-- Studyboard: the official sample flashcard sets, part 1 of 2. Published as @studyboard on studyboardapp.com/flashcards and in the
-- Course Library. Made by scripts/gen-seed-sets.js from seed-sets/*.json; don't edit by hand.
-- Before running: sign up in Studyboard with the account that should own them (support@studyboardapp.com below; change it if you use
-- another). Run supabase-schools.sql, supabase-usernames.sql and supabase-sharing.sql first. Then run every part, in order. Safe to run
-- again: it updates the same sets.
-- The cards are original, written for the topics in each course's published outline; no exam questions, slides or course files are copied.
-- To take them all down:  update public.shared_decks set published = false, listed = false where deck_id like 'seed:%';

do $$
declare owner uuid;
begin
  select id into owner from auth.users where lower(email) = lower('support@studyboardapp.com');
  if owner is null then raise exception 'Sign up in Studyboard with support@studyboardapp.com first (or change the address in this file).'; end if;
  -- "studyboard" is a reserved username, so only this account can have it (set here, not through the app)
  insert into public.study_profiles (user_id, display_name, username, username_set_at) values (owner, 'Studyboard', 'studyboard', now())
    on conflict (user_id) do update set username = 'studyboard', display_name = 'Studyboard';
end $$;

create or replace function pg_temp.sb_seed(p_id text, p_school text, p_code text, p_name text, p_data jsonb) returns void
language plpgsql as $f$
declare owner uuid; sn text; c text; n int := jsonb_array_length(p_data -> 'cards');
begin
  select id into owner from auth.users where lower(email) = lower('support@studyboardapp.com');
  select name into sn from public.schools where key = p_school;
  if sn is null then raise notice 'No school %, skipped %', p_school, p_id; return; end if;
  loop c := public.sbg_new_code(); exit when not exists (select 1 from public.shared_decks where code = c); end loop;
  insert into public.shared_decks (code, owner_id, deck_id, name, sharer_name, card_count, data, listed, listed_at, course_key, course_label, school_key, school_name, published, published_at)
    values (c, owner, p_id, p_name, 'Studyboard', n, p_data, true, now(), public.sbs_course_key(p_code), p_code, p_school, sn, true, now())
    on conflict (owner_id, deck_id) do update set name = excluded.name, data = excluded.data, card_count = excluded.card_count, sharer_name = 'Studyboard',
      listed = true, course_key = excluded.course_key, course_label = excluded.course_label, school_key = excluded.school_key, school_name = excluded.school_name,
      published = true, published_at = coalesce(public.shared_decks.published_at, now()), updated_at = now();
end $f$;

select pg_temp.sb_seed('seed:queensu-ca:psyc-100', 'queensu.ca', 'PSYC 100', 'PSYC 100 Midterm Review: Learning, Memory and Cognition', '{"v":1,"app":"studyboard","type":"deck","name":"PSYC 100 Midterm Review: Learning, Memory and Cognition","course":{"code":"PSYC 100","name":"Principles of Psychology"},"cards":[{"id":"psyc-100-1","front":"Classical conditioning: what is an unconditioned stimulus (US)?","back":"A stimulus that triggers a response automatically, without any prior learning. In Pavlov''s work, food in the mouth was the US that produced salivation (the unconditioned response)."},{"id":"psyc-100-2","front":"Classical conditioning: what is a conditioned stimulus (CS)?","back":"An originally neutral stimulus that, after being repeatedly paired with a US, comes to trigger a learned response (the conditioned response) on its own, such as the tone in Pavlov''s studies."},{"id":"psyc-100-3","front":"Extinction vs spontaneous recovery","back":"Extinction: the conditioned response weakens when the CS is repeatedly presented without the US. Spontaneous recovery: the extinguished response reappears after a rest period, showing extinction suppresses rather than erases learning."},{"id":"psyc-100-4","front":"Stimulus generalization vs stimulus discrimination","back":"Generalization: responding to stimuli similar to the original CS. Discrimination: learning to respond only to the specific CS and not to similar stimuli that were never paired with the US."},{"id":"psyc-100-5","front":"What did the Little Albert study (Watson and Rayner, 1920) demonstrate?","back":"That emotional responses such as fear can be classically conditioned. Pairing a white rat with a loud noise made an infant fear the rat, and the fear generalized to other furry objects. It is also a classic example of ethically problematic research."},{"id":"psyc-100-6","front":"Conditioned taste aversion (Garcia effect): why is it important?","back":"Animals learn to avoid a taste after a single pairing with illness, even with hours of delay. It shows biological preparedness: some stimulus-response associations are learned far more easily than others."},{"id":"psyc-100-7","front":"Thorndike''s law of effect","back":"Behaviours followed by satisfying consequences become more likely to be repeated, while those followed by unpleasant consequences become less likely. It is the foundation of operant conditioning."},{"id":"psyc-100-8","front":"Positive reinforcement vs negative reinforcement","back":"Both increase a behaviour. Positive reinforcement adds a pleasant stimulus (praise after studying). Negative reinforcement removes an unpleasant stimulus (taking a pill to stop a headache)."},{"id":"psyc-100-9","front":"Positive punishment vs negative punishment","back":"Both decrease a behaviour. Positive punishment adds an unpleasant stimulus (a scolding). Negative punishment removes a pleasant stimulus (losing phone privileges)."},{"id":"psyc-100-10","front":"Common pitfall: is negative reinforcement the same as punishment?","back":"No. Negative reinforcement increases a behaviour by removing something aversive. Punishment always decreases a behaviour."},{"id":"psyc-100-11","front":"Which reinforcement schedule produces high, steady responding that is most resistant to extinction?","back":"A variable-ratio schedule, where reinforcement comes after an unpredictable number of responses. Slot machines are the classic example."},{"id":"psyc-100-12","front":"Fixed-interval schedule: what response pattern does it produce?","back":"A scalloped pattern: responding is low right after reinforcement and speeds up as the end of the time interval approaches, like studying more as a scheduled exam gets closer."},{"id":"psyc-100-13","front":"Shaping","back":"Training a complex behaviour by reinforcing successive approximations of the target behaviour, gradually requiring closer matches before reinforcement is given."},{"id":"psyc-100-14","front":"What did Bandura''s Bobo doll studies show?","back":"Children who watched an adult behave aggressively toward a doll were more likely to imitate that aggression. This supports observational learning (modeling) without direct reinforcement."},{"id":"psyc-100-15","front":"Latent learning (Tolman)","back":"Learning that occurs without obvious reinforcement and is not shown until there is a reason to show it. Rats that explored a maze unrewarded ran it quickly once food was introduced, suggesting they had formed a cognitive map."},{"id":"psyc-100-16","front":"Atkinson-Shiffrin (multi-store) model of memory","back":"Information passes from sensory memory (very brief, large capacity) to short-term memory (limited, seconds) with attention, and into long-term memory (vast, lasting) through rehearsal and encoding."},{"id":"psyc-100-17","front":"Capacity and duration of short-term memory","back":"Miller estimated about 7 plus or minus 2 items; newer estimates are closer to 4 chunks. Without rehearsal, information fades in roughly 15 to 30 seconds."},{"id":"psyc-100-18","front":"Chunking","back":"Grouping individual items into larger meaningful units to fit more information into short-term memory, for example remembering 1-9-8-4 as the single year 1984."},{"id":"psyc-100-19","front":"Components of Baddeley''s working memory model","back":"Central executive (controls attention), phonological loop (verbal and auditory information), visuospatial sketchpad (visual and spatial information), and episodic buffer (integrates information and links to long-term memory)."},{"id":"psyc-100-20","front":"Explicit (declarative) vs implicit (nondeclarative) memory","back":"Explicit memory is consciously recalled: episodic (personal events) and semantic (facts). Implicit memory is expressed without awareness: procedural skills, priming and classically conditioned responses."},{"id":"psyc-100-21","front":"Levels of processing (Craik and Lockhart)","back":"How deeply information is processed affects retention. Deep, meaning-based (semantic) processing produces better memory than shallow processing of appearance or sound."},{"id":"psyc-100-22","front":"Serial position effect","back":"When recalling a list, items at the beginning (primacy effect, linked to long-term memory) and the end (recency effect, linked to short-term memory) are remembered better than items in the middle."},{"id":"psyc-100-23","front":"Proactive vs retroactive interference","back":"Proactive: old learning disrupts recall of new information (writing last year''s date). Retroactive: new learning disrupts recall of old information (a new password making you forget the old one)."},{"id":"psyc-100-24","front":"Encoding specificity and context-dependent memory","back":"Retrieval is best when the context at recall matches the context at encoding. Divers who learned words underwater recalled them better underwater than on land (Godden and Baddeley)."},{"id":"psyc-100-25","front":"Misinformation effect (Loftus and Palmer)","back":"Misleading information after an event can distort memory of it. Witnesses asked how fast cars smashed (vs hit) each other gave higher speed estimates and were more likely to falsely recall broken glass."},{"id":"psyc-100-26","front":"Patient H.M.: what did his case reveal?","back":"After removal of both medial temporal lobes, including the hippocampi, he could not form new explicit long-term memories but could still learn new motor skills. This showed the hippocampus is key for consolidating declarative memories."},{"id":"psyc-100-27","front":"Anterograde vs retrograde amnesia","back":"Anterograde: inability to form new memories after the injury. Retrograde: loss of memories formed before the injury."},{"id":"psyc-100-28","front":"Algorithm vs heuristic","back":"An algorithm is a step-by-step procedure that guarantees a solution but can be slow. A heuristic is a mental shortcut that is fast but can lead to errors."},{"id":"psyc-100-29","front":"Availability heuristic","back":"Judging how likely or frequent something is by how easily examples come to mind, such as overestimating plane crash risk after vivid news coverage."},{"id":"psyc-100-30","front":"Representativeness heuristic","back":"Judging probability by how closely something matches a prototype, often while ignoring base rates, such as assuming a quiet person who loves books is a librarian rather than a salesperson."},{"id":"psyc-100-31","front":"Confirmation bias","back":"The tendency to seek, interpret and remember information that supports one''s existing beliefs while ignoring or discounting contradictory evidence."},{"id":"psyc-100-32","front":"Functional fixedness","back":"A barrier to problem solving in which a person sees objects only in their usual function, such as failing to use a coin as a screwdriver."}],"quizzes":[],"seed":1,"look":{"color":"#9A4FD1","icon":"psych"}}'::jsonb);   -- https://queensu.ca/academic-calendar/search/?P=PSYC+100
select pg_temp.sb_seed('seed:queensu-ca:biol-102', 'queensu.ca', 'BIOL 102', 'BIOL 102 Midterm Review: Biomolecules, Metabolism and Molecular Genetics', '{"v":1,"app":"studyboard","type":"deck","name":"BIOL 102 Midterm Review: Biomolecules, Metabolism and Molecular Genetics","course":{"code":"BIOL 102","name":"Introductory Molecular and Cell Biology"},"cards":[{"id":"biol-102-1","front":"What are the four major classes of biological macromolecules?","back":"Carbohydrates, lipids, proteins and nucleic acids. All except lipids are true polymers built from repeating monomers."},{"id":"biol-102-2","front":"Dehydration synthesis vs hydrolysis","back":"Dehydration synthesis joins monomers by removing a water molecule, forming a covalent bond. Hydrolysis breaks the bond by adding water."},{"id":"biol-102-3","front":"Why is water such a good solvent for biological molecules?","back":"Water is polar and forms hydrogen bonds, so it surrounds and dissolves ions and other polar molecules. Nonpolar molecules are excluded, which drives hydrophobic interactions."},{"id":"biol-102-4","front":"The four levels of protein structure","back":"Primary: amino acid sequence. Secondary: alpha helices and beta sheets held by backbone hydrogen bonds. Tertiary: overall 3D fold from side-chain interactions. Quaternary: assembly of multiple polypeptide subunits."},{"id":"biol-102-5","front":"Phospholipid structure and why it forms bilayers","back":"A hydrophilic phosphate-containing head attached to two hydrophobic fatty acid tails. Being amphipathic, phospholipids in water arrange with heads facing out and tails tucked inward, forming a bilayer."},{"id":"biol-102-6","front":"Saturated vs unsaturated fatty acids","back":"Saturated fatty acids have no C=C double bonds, pack tightly and are solid at room temperature. Unsaturated fatty acids have one or more cis double bonds that kink the chain, so they pack loosely and are usually liquid."},{"id":"biol-102-7","front":"Three structural differences between DNA and RNA","back":"DNA uses deoxyribose sugar, RNA uses ribose. DNA uses thymine, RNA uses uracil. DNA is usually double-stranded, RNA is usually single-stranded."},{"id":"biol-102-8","front":"How do enzymes speed up reactions?","back":"They lower the activation energy by stabilizing the transition state. They do not change the overall free energy change (delta G) or the equilibrium position, and they are not consumed."},{"id":"biol-102-9","front":"Competitive vs noncompetitive inhibition","back":"A competitive inhibitor binds the active site and can be overcome by adding more substrate (Vmax unchanged, apparent Km rises). A noncompetitive inhibitor binds elsewhere, changes the enzyme''s shape and lowers Vmax."},{"id":"biol-102-10","front":"What does a negative delta G tell you about a reaction?","back":"The reaction is exergonic and spontaneous: it releases free energy. It says nothing about speed; a spontaneous reaction can still be very slow without a catalyst."},{"id":"biol-102-11","front":"How does ATP power endergonic reactions?","back":"Hydrolysis of ATP to ADP + phosphate releases free energy. Cells couple this to unfavourable reactions, often by transferring the phosphate to a reactant (phosphorylation) to make the overall process spontaneous."},{"id":"biol-102-12","front":"Overall equation for aerobic cellular respiration","back":"C6H12O6 + 6 O2 -> 6 CO2 + 6 H2O + energy (captured as ATP). Glucose is oxidized and oxygen is reduced."},{"id":"biol-102-13","front":"Glycolysis: location and net products per glucose","back":"Occurs in the cytosol and does not require oxygen. One glucose becomes 2 pyruvate, with a net gain of 2 ATP and 2 NADH."},{"id":"biol-102-14","front":"Pyruvate oxidation and the citric acid cycle: where and what?","back":"In the mitochondrial matrix. Pyruvate is converted to acetyl-CoA, which enters the citric acid cycle. Per glucose: CO2 is released and the cycle yields 2 ATP (or GTP), 6 NADH and 2 FADH2, plus 2 NADH from pyruvate oxidation."},{"id":"biol-102-15","front":"How does oxidative phosphorylation make ATP?","back":"The electron transport chain in the inner mitochondrial membrane uses electrons from NADH and FADH2 to pump H+ into the intermembrane space. H+ flows back through ATP synthase, driving ATP production (chemiosmosis). O2 is the final electron acceptor, forming water."},{"id":"biol-102-16","front":"What is the purpose of fermentation?","back":"To regenerate NAD+ from NADH so glycolysis can continue without oxygen. Animal muscle cells produce lactate; yeast produce ethanol and CO2. Only the 2 ATP from glycolysis are made."},{"id":"biol-102-17","front":"Photosynthesis: light reactions vs Calvin cycle","back":"Light reactions (thylakoid membranes) split water, release O2 and make ATP and NADPH. The Calvin cycle (stroma) uses that ATP and NADPH to fix CO2 into sugar, with rubisco catalyzing carbon fixation."},{"id":"biol-102-18","front":"State the central dogma of molecular biology","back":"Genetic information flows from DNA to RNA (transcription) to protein (translation). DNA is also copied to DNA during replication."},{"id":"biol-102-19","front":"What does semiconservative replication mean, and which experiment supported it?","back":"Each new DNA double helix contains one original strand and one newly made strand. Meselson and Stahl showed this using heavy (15N) and light (14N) nitrogen and density gradient centrifugation."},{"id":"biol-102-20","front":"Leading vs lagging strand","back":"DNA polymerase only adds nucleotides to a 3'' end, so it builds new DNA 5'' to 3''. The leading strand is made continuously toward the fork; the lagging strand is made in short Okazaki fragments that DNA ligase joins."},{"id":"biol-102-21","front":"Role of primase in DNA replication","back":"Primase makes a short RNA primer that provides the free 3'' OH group DNA polymerase needs to start synthesis. The primers are later removed and replaced with DNA."},{"id":"biol-102-22","front":"Transcription: what happens?","back":"RNA polymerase binds a promoter, unwinds the DNA and builds an RNA strand 5'' to 3'' that is complementary to the template strand. The RNA matches the coding strand, with U in place of T."},{"id":"biol-102-23","front":"Three processing steps for eukaryotic pre-mRNA","back":"Addition of a 5'' cap, addition of a 3'' poly-A tail, and splicing to remove introns and join exons. These steps occur in the nucleus before export."},{"id":"biol-102-24","front":"Start and stop codons","back":"Start codon: AUG, which codes for methionine. Stop codons: UAA, UAG and UGA, which code for no amino acid and end translation."},{"id":"biol-102-25","front":"Mini-problem: a template DNA strand reads 3''-TAC GGA-5''. What are the mRNA and amino acids?","back":"mRNA: 5''-AUG CCU-3''. This codes for methionine (AUG) then proline (CCU)."},{"id":"biol-102-26","front":"Silent vs missense vs nonsense mutations","back":"Silent: a base change that still codes for the same amino acid. Missense: codes for a different amino acid. Nonsense: creates a premature stop codon, usually producing a truncated protein."},{"id":"biol-102-27","front":"Why are frameshift mutations usually severe?","back":"Inserting or deleting a number of bases that is not a multiple of three shifts the reading frame, changing every codon downstream and often creating an early stop codon."},{"id":"biol-102-28","front":"Mitosis vs meiosis","back":"Mitosis: one division producing two genetically identical diploid cells, used for growth and repair. Meiosis: two divisions producing four genetically different haploid gametes, with crossing over and independent assortment."},{"id":"biol-102-29","front":"Mendel''s laws of segregation and independent assortment","back":"Segregation: the two alleles of a gene separate into different gametes. Independent assortment: alleles of different genes (on different chromosomes) sort into gametes independently of one another."},{"id":"biol-102-30","front":"Mini-problem: cross Aa x Aa where A is dominant. Expected ratios?","back":"Genotypes: 1 AA : 2 Aa : 1 aa. Phenotypes: 3 dominant : 1 recessive."},{"id":"biol-102-31","front":"What is a test cross?","back":"Crossing an individual with a dominant phenotype to a homozygous recessive individual. If any recessive offspring appear, the unknown parent must be heterozygous."}],"quizzes":[],"seed":1,"look":{"color":"#1E9E74","icon":"bio"}}'::jsonb);   -- https://queensu.ca/academic-calendar/search/?P=BIOL+102
select pg_temp.sb_seed('seed:queensu-ca:chem-112', 'queensu.ca', 'CHEM 112', 'CHEM 112 Final Review: Equilibrium, Acids and Bases, Electrochemistry and Kinetics', '{"v":1,"app":"studyboard","type":"deck","name":"CHEM 112 Final Review: Equilibrium, Acids and Bases, Electrochemistry and Kinetics","course":{"code":"CHEM 112","name":"General Chemistry"},"cards":[{"id":"chem-112-1","front":"Write the equilibrium constant expression for aA + bB <=> cC + dD","back":"K = [C]^c[D]^d / ([A]^a[B]^b). Pure solids and pure liquids are left out of the expression."},{"id":"chem-112-2","front":"Reaction quotient Q vs K: which way does the reaction shift?","back":"If Q < K, the reaction proceeds forward toward products. If Q > K, it shifts in reverse toward reactants. If Q = K, the system is at equilibrium."},{"id":"chem-112-3","front":"Le Chatelier''s principle: what happens if a reactant is added at equilibrium?","back":"The system shifts toward products to consume some of the added reactant. K itself does not change."},{"id":"chem-112-4","front":"Le Chatelier: effect of decreasing the volume of a gas-phase equilibrium","back":"Pressure increases, so the equilibrium shifts toward the side with fewer moles of gas. If both sides have equal moles of gas, there is no shift."},{"id":"chem-112-5","front":"What is the only change that alters the value of K?","back":"Temperature. For an exothermic reaction, raising the temperature decreases K; for an endothermic reaction, raising the temperature increases K."},{"id":"chem-112-6","front":"How does a catalyst affect an equilibrium?","back":"It speeds up the forward and reverse reactions equally, so equilibrium is reached faster, but the position of equilibrium and K are unchanged."},{"id":"chem-112-7","front":"Relationship between Kp and Kc","back":"Kp = Kc(RT)^(delta n), where delta n = moles of gaseous products minus moles of gaseous reactants, R = 0.08206 L·atm/(mol·K) and T is in kelvin."},{"id":"chem-112-8","front":"Bronsted-Lowry definitions of acid and base","back":"An acid is a proton (H+) donor and a base is a proton acceptor. After the transfer, the acid becomes its conjugate base and the base becomes its conjugate acid."},{"id":"chem-112-9","front":"Identify the conjugate pairs in NH3 + H2O <=> NH4+ + OH-","back":"NH3 (base) and NH4+ (its conjugate acid); H2O (acid) and OH- (its conjugate base)."},{"id":"chem-112-10","front":"pH, pOH and Kw at 25 degrees C","back":"pH = -log[H3O+], pOH = -log[OH-], Kw = [H3O+][OH-] = 1.0 x 10^-14, so pH + pOH = 14.00."},{"id":"chem-112-11","front":"Mini-problem: pH of 0.010 M HCl","back":"HCl is a strong acid and ionizes completely, so [H3O+] = 0.010 M and pH = -log(0.010) = 2.00."},{"id":"chem-112-12","front":"Weak acid pH shortcut and when it is valid","back":"[H3O+] is approximately sqrt(Ka x C). It is valid when the percent ionization is under about 5 percent (x much smaller than C)."},{"id":"chem-112-13","front":"Mini-problem: pH of 0.10 M weak acid with Ka = 1.0 x 10^-5","back":"[H3O+] = sqrt(1.0 x 10^-5 x 0.10) = 1.0 x 10^-3 M, so pH = 3.00. Ionization is 1 percent, so the approximation holds."},{"id":"chem-112-14","front":"Relationship between Ka and Kb for a conjugate acid-base pair","back":"Ka x Kb = Kw (1.0 x 10^-14 at 25 degrees C), so pKa + pKb = 14. The stronger the acid, the weaker its conjugate base."},{"id":"chem-112-15","front":"Henderson-Hasselbalch equation","back":"pH = pKa + log([A-]/[HA]), where [A-] is the conjugate base concentration and [HA] is the weak acid concentration. Used for buffer calculations."},{"id":"chem-112-16","front":"What is a buffer and when is it most effective?","back":"A solution of a weak acid and its conjugate base (or weak base and conjugate acid) that resists pH change when small amounts of acid or base are added. It works best when pH is within about 1 unit of the pKa."},{"id":"chem-112-17","front":"Weak acid titrated with strong base: pH at half-equivalence and equivalence","back":"At half-equivalence, [HA] = [A-] so pH = pKa. At the equivalence point the pH is above 7 because the conjugate base A- reacts with water to form OH-."},{"id":"chem-112-18","front":"Mini-problem: molar solubility of AgCl if Ksp = 1.8 x 10^-10","back":"AgCl(s) <=> Ag+ + Cl-, so Ksp = s^2 and s = sqrt(1.8 x 10^-10), about 1.3 x 10^-5 M."},{"id":"chem-112-19","front":"Common ion effect","back":"Adding an ion already present in an equilibrium shifts it away from that ion. For example, AgCl is less soluble in NaCl solution than in pure water."},{"id":"chem-112-20","front":"Oxidation vs reduction, and where each occurs in a galvanic cell","back":"Oxidation is loss of electrons and occurs at the anode. Reduction is gain of electrons and occurs at the cathode. Electrons flow through the wire from anode to cathode."},{"id":"chem-112-21","front":"How do you calculate the standard cell potential?","back":"E cell = E(cathode) - E(anode), using standard reduction potentials for both. A positive E cell means the reaction is spontaneous as written."},{"id":"chem-112-22","front":"Link between delta G, E cell and K","back":"delta G = -nFE cell and delta G standard = -RT ln K, where n is moles of electrons transferred and F = 96485 C/mol. Positive E means negative delta G and K greater than 1."},{"id":"chem-112-23","front":"Nernst equation","back":"E = E standard - (RT/nF) ln Q. At 25 degrees C this becomes E = E standard - (0.0592 V/n) log Q."},{"id":"chem-112-24","front":"Galvanic vs electrolytic cell","back":"A galvanic (voltaic) cell uses a spontaneous redox reaction to produce electricity. An electrolytic cell uses an external power source to drive a nonspontaneous reaction. Oxidation is at the anode in both."},{"id":"chem-112-25","front":"General form of a rate law","back":"Rate = k[A]^m[B]^n, where k is the rate constant and m and n are reaction orders. Orders must be determined experimentally, not from the balanced equation''s coefficients."},{"id":"chem-112-26","front":"Mini-problem: doubling [A] quadruples the rate. What is the order in A?","back":"Second order, since 2^m = 4 gives m = 2."},{"id":"chem-112-27","front":"First-order reactions: integrated rate law and half-life","back":"ln[A] = ln[A]0 - kt, and t(1/2) = 0.693/k. The half-life does not depend on starting concentration."},{"id":"chem-112-28","front":"Arrhenius equation","back":"k = A e^(-Ea/RT), where A is the frequency factor, Ea the activation energy, R = 8.314 J/(mol·K) and T the kelvin temperature. Higher T or lower Ea gives a larger k."},{"id":"chem-112-29","front":"What is the rate-determining step?","back":"The slowest elementary step in a reaction mechanism. It limits the overall rate, so the rate law follows from that step."},{"id":"chem-112-30","front":"Gibbs free energy and spontaneity","back":"delta G = delta H - T delta S. If delta H is negative and delta S is positive, the process is spontaneous at all temperatures; if delta H is positive and delta S negative, it is never spontaneous."},{"id":"chem-112-31","front":"Second law of thermodynamics","back":"For any spontaneous process, the total entropy of the universe (system plus surroundings) increases."}],"quizzes":[],"seed":1,"look":{"color":"#E0673B","icon":"chem"}}'::jsonb);   -- https://queensu.ca/academic-calendar/search/?P=CHEM+112
select pg_temp.sb_seed('seed:queensu-ca:econ-111', 'queensu.ca', 'ECON 111', 'ECON 111 Midterm Review: Supply, Demand, Elasticity and Market Efficiency', '{"v":1,"app":"studyboard","type":"deck","name":"ECON 111 Midterm Review: Supply, Demand, Elasticity and Market Efficiency","course":{"code":"ECON 111","name":"Introductory Microeconomics"},"cards":[{"id":"econ-111-1","front":"Opportunity cost","back":"The value of the next best alternative given up when a choice is made. For example, the opportunity cost of attending class may be the wages you could have earned working."},{"id":"econ-111-2","front":"Why is a production possibilities frontier usually bowed outward?","back":"Because of increasing opportunity cost: resources are not equally suited to producing both goods, so producing more of one good requires giving up ever larger amounts of the other."},{"id":"econ-111-3","front":"Absolute advantage vs comparative advantage","back":"Absolute advantage: producing more of a good with the same resources. Comparative advantage: producing a good at a lower opportunity cost. Trade gains come from comparative advantage."},{"id":"econ-111-4","front":"Mini-problem: In one hour, A makes 10 shirts or 5 hats; B makes 6 shirts or 2 hats. Who has comparative advantage in hats?","back":"A. A''s opportunity cost of a hat is 2 shirts, while B''s is 3 shirts. B has comparative advantage in shirts (1/3 hat per shirt vs A''s 1/2 hat)."},{"id":"econ-111-5","front":"Law of demand","back":"Other things equal, as the price of a good rises, the quantity demanded falls, giving a downward-sloping demand curve."},{"id":"econ-111-6","front":"Change in quantity demanded vs change in demand","back":"A change in the good''s own price causes a movement along the demand curve (change in quantity demanded). A change in any other factor shifts the whole curve (change in demand)."},{"id":"econ-111-7","front":"List the main factors that shift a demand curve","back":"Consumer income, prices of related goods (substitutes and complements), tastes, expectations about future prices, and the number of buyers (population)."},{"id":"econ-111-8","front":"Normal good vs inferior good","back":"Demand for a normal good rises when income rises. Demand for an inferior good falls when income rises, such as instant noodles or bus rides for some consumers."},{"id":"econ-111-9","front":"Substitutes vs complements","back":"Substitutes: a price rise in one increases demand for the other (coffee and tea). Complements: a price rise in one decreases demand for the other (printers and ink)."},{"id":"econ-111-10","front":"What happens when the price is above equilibrium? Below?","back":"Above equilibrium: quantity supplied exceeds quantity demanded, creating a surplus that pushes price down. Below: a shortage pushes price up."},{"id":"econ-111-11","front":"Demand and supply both increase. What happens to equilibrium price and quantity?","back":"Equilibrium quantity rises for sure. The effect on price is ambiguous: it depends on which curve shifts by more."},{"id":"econ-111-12","front":"Price elasticity of demand formula (midpoint method)","back":"Ed = (percent change in quantity demanded) / (percent change in price), using the average of the old and new values as the base for each percent change. Usually reported as an absolute value."},{"id":"econ-111-13","front":"Elastic vs inelastic demand and total revenue","back":"Elastic (Ed > 1): a price increase lowers total revenue. Inelastic (Ed < 1): a price increase raises total revenue. Unit elastic (Ed = 1): total revenue does not change."},{"id":"econ-111-14","front":"Mini-problem: price rises 10 percent and quantity demanded falls 20 percent. Elasticity and revenue effect?","back":"Ed = 20/10 = 2, so demand is elastic and total revenue falls."},{"id":"econ-111-15","front":"What makes demand more price elastic?","back":"Many close substitutes, the good being a luxury rather than a necessity, a large share of the budget, a narrowly defined market, and a longer time to adjust."},{"id":"econ-111-16","front":"Income elasticity of demand: what do the signs mean?","back":"Positive: normal good (greater than 1 is a luxury). Negative: inferior good. It equals percent change in quantity demanded divided by percent change in income."},{"id":"econ-111-17","front":"Cross-price elasticity of demand: what do the signs mean?","back":"Positive: the goods are substitutes. Negative: the goods are complements. Close to zero: unrelated goods."},{"id":"econ-111-18","front":"Consumer surplus","back":"The difference between what buyers are willing to pay and what they actually pay. On a graph, it is the area below the demand curve and above the price."},{"id":"econ-111-19","front":"Producer surplus","back":"The difference between the price sellers receive and their cost (the minimum they would accept). On a graph, it is the area above the supply curve and below the price."},{"id":"econ-111-20","front":"Effect of a binding price ceiling","back":"Set below equilibrium, it creates a shortage because quantity demanded exceeds quantity supplied. Rent control is the classic example, often leading to waiting lists and lower quality."},{"id":"econ-111-21","front":"Effect of a binding price floor","back":"Set above equilibrium, it creates a surplus because quantity supplied exceeds quantity demanded. A minimum wage above the market wage can create unemployment in that labour market."},{"id":"econ-111-22","front":"Deadweight loss","back":"The loss of total surplus when the quantity traded differs from the efficient quantity, for example due to a tax, price control or market power. It is the triangle between supply and demand over the lost units."},{"id":"econ-111-23","front":"Tax incidence: who bears more of a tax burden?","back":"Whichever side of the market is less elastic. The statutory payer does not matter; if demand is very inelastic, buyers bear most of the tax through a higher price."},{"id":"econ-111-24","front":"Utility-maximizing rule for a consumer","back":"Allocate the budget so that the marginal utility per dollar is equal across goods: MUx/Px = MUy/Py."},{"id":"econ-111-25","front":"Substitution effect vs income effect of a price fall","back":"Substitution effect: the good becomes relatively cheaper, so consumers buy more of it. Income effect: purchasing power rises, which increases demand for normal goods and decreases it for inferior goods."},{"id":"econ-111-26","front":"Positive vs normative statements","back":"Positive statements describe how the world is and can be tested with evidence. Normative statements say how the world should be and involve value judgments."},{"id":"econ-111-27","front":"Negative externality and a policy fix","back":"A cost imposed on third parties, such as pollution. The market overproduces because private cost is below social cost. A Pigouvian tax equal to the external cost can restore the efficient quantity."},{"id":"econ-111-28","front":"What defines a public good, and why is it underprovided by markets?","back":"It is non-rival (one person''s use does not reduce another''s) and non-excludable (people cannot be prevented from using it). Free riders can benefit without paying, so private firms underprovide it."},{"id":"econ-111-29","front":"When is a competitive market allocatively efficient?","back":"When it produces the quantity where marginal benefit (demand) equals marginal cost (supply), which maximizes total surplus."}],"quizzes":[],"seed":1,"look":{"color":"#C79A12","icon":"econ"}}'::jsonb);   -- https://queensu.ca/academic-calendar/search/?P=ECON+111
select pg_temp.sb_seed('seed:uottawa-ca:psy-1101', 'uottawa.ca', 'PSY 1101', 'PSY 1101 Midterm Review: Research Methods, Neuroscience, Sensation and Perception', '{"v":1,"app":"studyboard","type":"deck","name":"PSY 1101 Midterm Review: Research Methods, Neuroscience, Sensation and Perception","course":{"code":"PSY 1101","name":"Introduction to Psychology: Foundations"},"cards":[{"id":"psy-1101-1","front":"Hypothesis vs theory","back":"A hypothesis is a specific, testable prediction. A theory is a broader, well-supported explanation that organizes many observations and generates new hypotheses."},{"id":"psy-1101-2","front":"Operational definition","back":"A precise statement of how a variable will be measured or manipulated in a study, such as defining aggression as the number of times a child hits a doll in 10 minutes."},{"id":"psy-1101-3","front":"Independent vs dependent variable","back":"The independent variable is the factor the researcher manipulates. The dependent variable is the outcome that is measured to see whether it changed."},{"id":"psy-1101-4","front":"Why can experiments show causation when correlational studies cannot?","back":"Experiments manipulate the independent variable and use random assignment, which controls for other factors. Correlational studies only measure variables as they occur, so other explanations remain possible."},{"id":"psy-1101-5","front":"Interpreting a correlation coefficient (r)","back":"r ranges from -1 to +1. The sign gives direction and the absolute value gives strength, so r = -0.80 is a stronger relationship than r = +0.50."},{"id":"psy-1101-6","front":"Third-variable problem","back":"A correlation between two variables may be caused by an unmeasured third variable. Ice cream sales and drownings both rise in summer because of hot weather, not because one causes the other."},{"id":"psy-1101-7","front":"Random sampling vs random assignment","back":"Random sampling selects participants so the sample represents the population (helps generalize). Random assignment places participants into conditions by chance (helps establish causation)."},{"id":"psy-1101-8","front":"What is a double-blind procedure and why use it?","back":"Neither participants nor the researchers collecting data know who is in which condition. It reduces placebo effects and experimenter bias."},{"id":"psy-1101-9","front":"Reliability vs validity","back":"Reliability is consistency: the measure gives similar results across time or raters. Validity is accuracy: the measure actually assesses what it claims to. A measure can be reliable without being valid."},{"id":"psy-1101-10","front":"Main parts of a neuron and their roles","back":"Dendrites receive signals, the cell body (soma) integrates them, the axon conducts the action potential, the myelin sheath speeds conduction, and axon terminals release neurotransmitters."},{"id":"psy-1101-11","front":"Describe the action potential","back":"At rest the inside of the neuron is about -70 mV. When threshold is reached, Na+ channels open and Na+ rushes in (depolarization); then K+ flows out (repolarization). It is all-or-none: it fires fully or not at all."},{"id":"psy-1101-12","front":"What is the refractory period?","back":"A brief time after an action potential when the neuron cannot fire again (absolute) or needs stronger stimulation to fire (relative). It keeps signals moving in one direction and limits firing rate."},{"id":"psy-1101-13","front":"How is a signal passed across a synapse?","back":"The action potential triggers release of neurotransmitter into the synaptic cleft. It binds to receptors on the next neuron, producing excitatory or inhibitory effects, and is then cleared by reuptake or enzymes."},{"id":"psy-1101-14","front":"Match the neurotransmitters: dopamine, serotonin, acetylcholine, GABA, glutamate","back":"Dopamine: reward and movement. Serotonin: mood, sleep and appetite. Acetylcholine: muscle contraction and memory. GABA: main inhibitory transmitter. Glutamate: main excitatory transmitter."},{"id":"psy-1101-15","front":"Agonist vs antagonist","back":"An agonist mimics or enhances a neurotransmitter''s effect at its receptor. An antagonist blocks or reduces the neurotransmitter''s effect."},{"id":"psy-1101-16","front":"Sympathetic vs parasympathetic nervous system","back":"Both are parts of the autonomic nervous system. Sympathetic: fight or flight (raises heart rate, dilates pupils). Parasympathetic: rest and digest (slows heart rate, promotes digestion)."},{"id":"psy-1101-17","front":"Main functions of the four cerebral lobes","back":"Frontal: planning, decision making, movement (motor cortex). Parietal: touch and body position (somatosensory cortex), spatial attention. Temporal: hearing and language comprehension. Occipital: vision."},{"id":"psy-1101-18","front":"Broca''s area vs Wernicke''s area","back":"Broca''s area (left frontal lobe) supports speech production; damage causes slow, effortful speech. Wernicke''s area (left temporal lobe) supports comprehension; damage causes fluent but meaningless speech."},{"id":"psy-1101-19","front":"Roles of the hippocampus, amygdala and hypothalamus","back":"Hippocampus: forming new explicit memories. Amygdala: emotion, especially fear. Hypothalamus: regulating hunger, thirst, body temperature and hormones through the pituitary gland."},{"id":"psy-1101-20","front":"What did split-brain studies reveal?","back":"When the corpus callosum is cut, information shown only to the right hemisphere (left visual field) cannot be named aloud, because speech is usually controlled by the left hemisphere. The hemispheres can operate somewhat independently."},{"id":"psy-1101-21","front":"Sensation vs perception","back":"Sensation is detecting physical energy with sense receptors and converting it into neural signals (transduction). Perception is the brain organizing and interpreting those signals."},{"id":"psy-1101-22","front":"Absolute threshold vs difference threshold","back":"Absolute threshold: the minimum stimulus intensity detected 50 percent of the time. Difference threshold (just noticeable difference): the smallest change in a stimulus that can be detected 50 percent of the time."},{"id":"psy-1101-23","front":"Weber''s law","back":"The just noticeable difference is a constant proportion of the original stimulus, not a fixed amount. If you can detect 1 g added to 50 g, you would need about 2 g added to 100 g."},{"id":"psy-1101-24","front":"Signal detection theory","back":"Detecting a stimulus depends on both its strength and the observer''s decision criterion. Outcomes are hits, misses, false alarms and correct rejections."},{"id":"psy-1101-25","front":"Rods vs cones","back":"Rods are more numerous, very sensitive to dim light, concentrated in the periphery and do not detect colour. Cones work in bright light, detect colour and fine detail and are concentrated in the fovea."},{"id":"psy-1101-26","front":"Trichromatic vs opponent-process theory of colour vision","back":"Trichromatic: three cone types sensitive to short, medium and long wavelengths (roughly blue, green, red). Opponent-process: later neural channels code red vs green, blue vs yellow and black vs white, explaining afterimages."},{"id":"psy-1101-27","front":"Place theory vs frequency theory of pitch","back":"Place theory: different pitches stimulate different locations on the basilar membrane, best for high frequencies. Frequency theory: neurons fire at the rate of the sound wave, best for low frequencies."},{"id":"psy-1101-28","front":"Bottom-up vs top-down processing","back":"Bottom-up processing builds a perception from raw sensory features. Top-down processing uses expectations, knowledge and context to interpret sensory input."},{"id":"psy-1101-29","front":"Name four Gestalt grouping principles","back":"Proximity (near things group together), similarity (alike things group), continuity (smooth continuous patterns), and closure (we fill in gaps to see whole figures). Figure-ground separation is also basic."},{"id":"psy-1101-30","front":"Monocular vs binocular depth cues","back":"Binocular cues need both eyes: retinal disparity and convergence. Monocular cues work with one eye: linear perspective, relative size, interposition, texture gradient and motion parallax."},{"id":"psy-1101-31","front":"Circadian rhythm and REM sleep","back":"The circadian rhythm is a roughly 24-hour cycle regulated by the suprachiasmatic nucleus of the hypothalamus. REM sleep features rapid eye movements, vivid dreams, an active brain and near-paralysis of skeletal muscles."}],"quizzes":[],"seed":1,"look":{"color":"#4F46E5","icon":"psych"}}'::jsonb);   -- https://catalogue.uottawa.ca/en/courses/psy/
select pg_temp.sb_seed('seed:uottawa-ca:chm-1311', 'uottawa.ca', 'CHM 1311', 'CHM 1311 Midterm Review: Stoichiometry, Solutions, Gases and Thermochemistry', '{"v":1,"app":"studyboard","type":"deck","name":"CHM 1311 Midterm Review: Stoichiometry, Solutions, Gases and Thermochemistry","course":{"code":"CHM 1311","name":"Principles of Chemistry"},"cards":[{"id":"chm-1311-1","front":"What is a mole?","back":"The amount of substance containing Avogadro''s number of particles, 6.022 x 10^23. The mass of one mole in grams equals the formula mass in atomic mass units."},{"id":"chm-1311-2","front":"Mini-problem: how many moles are in 36.04 g of water?","back":"Molar mass of H2O = 2(1.008) + 16.00 = 18.02 g/mol, so 36.04 g / 18.02 g/mol = 2.000 mol."},{"id":"chm-1311-3","front":"Empirical formula vs molecular formula","back":"The empirical formula gives the simplest whole-number ratio of atoms. The molecular formula gives the actual number of each atom, a whole-number multiple of the empirical formula (glucose C6H12O6 has empirical formula CH2O)."},{"id":"chm-1311-4","front":"Mini-problem: a compound is 40.0% C, 6.7% H and 53.3% O by mass. Empirical formula?","back":"In 100 g: 40.0/12.01 = 3.33 mol C, 6.7/1.008 = 6.6 mol H, 53.3/16.00 = 3.33 mol O. Dividing by 3.33 gives a 1:2:1 ratio, so CH2O."},{"id":"chm-1311-5","front":"Limiting reactant","back":"The reactant that is completely used up first, which determines the maximum amount of product. Compare the mole ratio available to the ratio in the balanced equation."},{"id":"chm-1311-6","front":"Mini-problem: 2 H2 + O2 -> 2 H2O with 4.0 mol H2 and 3.0 mol O2. Limiting reactant and product?","back":"4.0 mol H2 needs only 2.0 mol O2, so H2 is limiting. It forms 4.0 mol H2O, with 1.0 mol O2 left over."},{"id":"chm-1311-7","front":"Percent yield formula","back":"Percent yield = (actual yield / theoretical yield) x 100. The theoretical yield is calculated from the limiting reactant."},{"id":"chm-1311-8","front":"Molarity and the dilution equation","back":"Molarity M = moles of solute / litres of solution. When diluting, moles of solute stay constant, so M1V1 = M2V2."},{"id":"chm-1311-9","front":"Mini-problem: 50.0 mL of 2.00 M NaCl is diluted to 250.0 mL. New concentration?","back":"M2 = (2.00 M x 50.0 mL) / 250.0 mL = 0.400 M."},{"id":"chm-1311-10","front":"Strong vs weak electrolytes","back":"Strong electrolytes dissociate completely in water (soluble ionic compounds, strong acids such as HCl). Weak electrolytes ionize only partly (weak acids such as acetic acid). Nonelectrolytes do not ionize (sugar)."},{"id":"chm-1311-11","front":"Net ionic equation for mixing AgNO3(aq) and NaCl(aq)","back":"Ag+(aq) + Cl-(aq) -> AgCl(s). Na+ and NO3- are spectator ions because they stay dissolved and unchanged."},{"id":"chm-1311-12","front":"Key oxidation number rules","back":"Elements alone are 0. Monatomic ions equal their charge. O is usually -2 (-1 in peroxides). H is +1 with nonmetals. The sum equals the overall charge of the molecule or ion."},{"id":"chm-1311-13","front":"Mini-problem: oxidation state of Mn in MnO4-","back":"x + 4(-2) = -1, so x = +7."},{"id":"chm-1311-14","front":"Ideal gas law and values of R","back":"PV = nRT, with T in kelvin. R = 0.08206 L·atm/(mol·K) or 8.314 J/(mol·K)."},{"id":"chm-1311-15","front":"Mini-problem: volume of 1.00 mol of ideal gas at 0 degrees C and 1.00 atm","back":"V = nRT/P = (1.00)(0.08206)(273.15)/1.00, about 22.4 L."},{"id":"chm-1311-16","front":"Dalton''s law of partial pressures","back":"The total pressure of a gas mixture equals the sum of the partial pressures of its components. Each partial pressure is P(i) = X(i) x P(total), where X(i) is the mole fraction."},{"id":"chm-1311-17","front":"Main assumptions of kinetic molecular theory","back":"Gas particles have negligible volume, move randomly in straight lines, have no attractions or repulsions, and collide elastically. Average kinetic energy is proportional to kelvin temperature."},{"id":"chm-1311-18","front":"Graham''s law of effusion","back":"rate1 / rate2 = sqrt(M2 / M1). Lighter gases effuse faster; for example, H2 effuses 4 times faster than O2 because sqrt(32/2) = 4."},{"id":"chm-1311-19","front":"When do real gases deviate most from ideal behaviour?","back":"At high pressure (particle volume matters) and low temperature (intermolecular attractions matter). The van der Waals equation corrects for both."},{"id":"chm-1311-20","front":"Heat equation for a temperature change","back":"q = m c delta T, where m is mass, c is specific heat capacity and delta T is the temperature change. For water, c = 4.184 J/(g·degree C)."},{"id":"chm-1311-21","front":"Mini-problem: heat needed to warm 100.0 g of water by 10.0 degrees C","back":"q = (100.0 g)(4.184 J/g·degree C)(10.0 degrees C) = 4184 J, or about 4.18 kJ."},{"id":"chm-1311-22","front":"Exothermic vs endothermic: sign of delta H","back":"Exothermic reactions release heat to the surroundings and delta H is negative. Endothermic reactions absorb heat and delta H is positive."},{"id":"chm-1311-23","front":"Hess''s law","back":"The enthalpy change of a reaction is the same whether it occurs in one step or several, so delta H values for steps can be added. Reversing a reaction flips the sign; multiplying it scales delta H."},{"id":"chm-1311-24","front":"Calculating delta H of reaction from enthalpies of formation","back":"delta H rxn = sum of n x delta Hf(products) - sum of n x delta Hf(reactants). The standard enthalpy of formation of an element in its standard state is zero."},{"id":"chm-1311-25","front":"Coffee-cup vs bomb calorimetry","back":"A coffee-cup calorimeter works at constant pressure and measures delta H. A bomb calorimeter works at constant volume and measures delta U (internal energy change)."},{"id":"chm-1311-26","front":"First law of thermodynamics and sign conventions","back":"delta U = q + w. q is positive when the system absorbs heat; w is positive when work is done on the system. Expansion work against constant pressure is w = -P delta V."},{"id":"chm-1311-27","front":"VSEPR shapes of CH4, NH3 and H2O","back":"All have four electron groups (tetrahedral electron geometry). CH4 is tetrahedral (109.5 degrees), NH3 is trigonal pyramidal (about 107 degrees), and H2O is bent (about 104.5 degrees) due to lone pairs."},{"id":"chm-1311-28","front":"Why is CO2 nonpolar while H2O is polar?","back":"Both have polar bonds, but CO2 is linear so the bond dipoles cancel. H2O is bent, so its bond dipoles add to give a net dipole."},{"id":"chm-1311-29","front":"Formal charge formula","back":"Formal charge = valence electrons - nonbonding electrons - (1/2) bonding electrons. The best Lewis structure keeps formal charges near zero, with negative charges on more electronegative atoms."}],"quizzes":[],"seed":1,"look":{"color":"#EA580C","icon":"chem"}}'::jsonb);   -- https://catalogue.uottawa.ca/en/courses/chm/
select pg_temp.sb_seed('seed:uottawa-ca:mat-1320', 'uottawa.ca', 'MAT 1320', 'MAT 1320 Final Review: Applications of Derivatives, Integration Techniques and Numerical Methods', '{"v":1,"app":"studyboard","type":"deck","name":"MAT 1320 Final Review: Applications of Derivatives, Integration Techniques and Numerical Methods","course":{"code":"MAT 1320","name":"Calculus I"},"cards":[{"id":"mat-1320-1","front":"State L''Hospital''s rule","back":"If lim f(x)/g(x) gives 0/0 or infinity/infinity, then lim f(x)/g(x) = lim f''(x)/g''(x), provided the second limit exists. Differentiate top and bottom separately, not as a quotient."},{"id":"mat-1320-2","front":"Mini-problem: lim as x -> 0 of (e^x - 1)/x","back":"It is 0/0, so apply L''Hospital: lim e^x / 1 = e^0 = 1."},{"id":"mat-1320-3","front":"Mini-problem: lim as x -> infinity of x/e^x","back":"It is infinity/infinity. L''Hospital gives lim 1/e^x = 0."},{"id":"mat-1320-4","front":"How do you handle the indeterminate form 0 x infinity?","back":"Rewrite the product as a quotient, for example f·g = f / (1/g), to get 0/0 or infinity/infinity, then apply L''Hospital''s rule."},{"id":"mat-1320-5","front":"Mean Value Theorem","back":"If f is continuous on [a, b] and differentiable on (a, b), there is some c in (a, b) with f''(c) = (f(b) - f(a)) / (b - a): the instantaneous rate equals the average rate somewhere."},{"id":"mat-1320-6","front":"Extreme Value Theorem","back":"A function continuous on a closed interval [a, b] attains both an absolute maximum and an absolute minimum there. Check critical points and endpoints to find them."},{"id":"mat-1320-7","front":"Critical point and the first derivative test","back":"A critical point is where f''(c) = 0 or f''(c) does not exist. If f'' changes from + to - at c, f has a local max; from - to +, a local min; no sign change, neither."},{"id":"mat-1320-8","front":"Second derivative test and inflection points","back":"If f''(c) = 0 and f''''(c) > 0, local min; if f''''(c) < 0, local max; if f''''(c) = 0, the test is inconclusive. An inflection point is where concavity changes sign."},{"id":"mat-1320-9","front":"Linear approximation formula and an example","back":"L(x) = f(a) + f''(a)(x - a). For sqrt(4.1) with a = 4: f(4) = 2 and f''(4) = 1/(2·2) = 1/4, so sqrt(4.1) is about 2 + 0.1/4 = 2.025."},{"id":"mat-1320-10","front":"Newton''s method formula","back":"x(n+1) = x(n) - f(x(n)) / f''(x(n)). It repeatedly uses tangent lines to approximate a root and can fail if f''(x(n)) is near zero or the starting guess is poor."},{"id":"mat-1320-11","front":"Mini-problem: a circle''s radius grows at 2 cm/s. How fast is area growing when r = 5 cm?","back":"A = pi r^2, so dA/dt = 2 pi r (dr/dt) = 2 pi (5)(2) = 20 pi cm^2/s, about 62.8 cm^2/s."},{"id":"mat-1320-12","front":"Mini-problem: find dy/dx for x^2 + y^2 = 25","back":"Differentiate implicitly: 2x + 2y (dy/dx) = 0, so dy/dx = -x/y."},{"id":"mat-1320-13","front":"Derivatives of ln x, arctan x and arcsin x","back":"d/dx [ln x] = 1/x. d/dx [arctan x] = 1/(1 + x^2). d/dx [arcsin x] = 1/sqrt(1 - x^2)."},{"id":"mat-1320-14","front":"Derivatives of a^x and log base a of x","back":"d/dx [a^x] = a^x ln a. d/dx [log_a x] = 1/(x ln a)."},{"id":"mat-1320-15","front":"Definite integral as a limit of Riemann sums","back":"The integral from a to b of f(x) dx = lim as n -> infinity of the sum of f(x_i*) delta x, where delta x = (b - a)/n. It gives net signed area."},{"id":"mat-1320-16","front":"Fundamental Theorem of Calculus, Part 1","back":"If F(x) = integral from a to x of f(t) dt, then F''(x) = f(x). With a variable upper limit g(x), the derivative is f(g(x))·g''(x)."},{"id":"mat-1320-17","front":"Fundamental Theorem of Calculus, Part 2","back":"If F is any antiderivative of a continuous f, then the integral from a to b of f(x) dx = F(b) - F(a)."},{"id":"mat-1320-18","front":"Mini-problem: integral from 0 to 2 of 3x^2 dx","back":"Antiderivative x^3, so 2^3 - 0^3 = 8."},{"id":"mat-1320-19","front":"Mini-problem: integral of 2x cos(x^2) dx","back":"Let u = x^2, du = 2x dx. The integral becomes integral of cos u du = sin(x^2) + C."},{"id":"mat-1320-20","front":"Integration by parts formula and a tip for choosing u","back":"Integral of u dv = uv - integral of v du. Choose u in the order LIATE: Logarithmic, Inverse trig, Algebraic, Trig, Exponential."},{"id":"mat-1320-21","front":"Mini-problem: integral of x e^x dx","back":"Let u = x and dv = e^x dx, so du = dx and v = e^x. Result: x e^x - e^x + C."},{"id":"mat-1320-22","front":"Mini-problem: integral of ln x dx","back":"Let u = ln x and dv = dx, so du = dx/x and v = x. Result: x ln x - x + C."},{"id":"mat-1320-23","front":"Mini-problem: integral of 1/(x(x + 1)) dx","back":"Partial fractions: 1/(x(x+1)) = 1/x - 1/(x+1). Result: ln|x| - ln|x + 1| + C."},{"id":"mat-1320-24","front":"Antiderivatives of 1/x and 1/(1 + x^2)","back":"Integral of 1/x dx = ln|x| + C. Integral of 1/(1 + x^2) dx = arctan x + C."},{"id":"mat-1320-25","front":"Trapezoidal rule","back":"Integral from a to b of f is about (delta x / 2)[f(x0) + 2f(x1) + 2f(x2) + ... + 2f(x(n-1)) + f(xn)], with delta x = (b - a)/n."},{"id":"mat-1320-26","front":"Simpson''s rule","back":"Requires n even: integral is about (delta x / 3)[f(x0) + 4f(x1) + 2f(x2) + 4f(x3) + ... + 4f(x(n-1)) + f(xn)]. It fits parabolas and is exact for cubics."},{"id":"mat-1320-27","front":"Error bounds for midpoint, trapezoidal and Simpson''s rules","back":"If |f''''| <= K: midpoint error <= K(b-a)^3/(24n^2), trapezoid error <= K(b-a)^3/(12n^2). If |f''''''''| <= K: Simpson error <= K(b-a)^5/(180n^4)."},{"id":"mat-1320-28","front":"Forward vs central difference approximations of f''(a)","back":"Forward: (f(a + h) - f(a)) / h, error proportional to h. Central: (f(a + h) - f(a - h)) / (2h), error proportional to h^2, so it is usually more accurate."},{"id":"mat-1320-29","front":"Mini-problem: a rectangle has perimeter 40. What dimensions maximize area?","back":"Area A = x(20 - x). A''(x) = 20 - 2x = 0 gives x = 10, so a 10 by 10 square with area 100."},{"id":"mat-1320-30","front":"Common pitfall with u-substitution in definite integrals","back":"When you substitute, either change the limits to u-values or convert back to x before evaluating. Mixing new integrand with old limits gives wrong answers."}],"quizzes":[],"seed":1,"look":{"color":"#3B6FE0","icon":"calc"}}'::jsonb);   -- https://catalogue.uottawa.ca/en/courses/mat/
select pg_temp.sb_seed('seed:uottawa-ca:bio-1141', 'uottawa.ca', 'BIO 1141', 'BIO 1141 Midterm Review: Cell Structure, Membrane Transport, Cytoskeleton and the Cell Cycle', '{"v":1,"app":"studyboard","type":"deck","name":"BIO 1141 Midterm Review: Cell Structure, Membrane Transport, Cytoskeleton and the Cell Cycle","course":{"code":"BIO 1141","name":"Introduction to Cell and Molecular Biology"},"cards":[{"id":"bio-1141-1","front":"Three tenets of cell theory","back":"All living things are made of one or more cells; the cell is the basic unit of life; and all cells arise from pre-existing cells."},{"id":"bio-1141-2","front":"What did the Miller-Urey experiment show?","back":"Passing electric sparks through a mixture of gases thought to resemble the early atmosphere (methane, ammonia, hydrogen, water vapour) produced amino acids, showing organic molecules can form from simple inorganic precursors."},{"id":"bio-1141-3","front":"RNA world hypothesis","back":"The idea that early life used RNA both to store genetic information and to catalyze reactions (ribozymes), before DNA and proteins took over those roles."},{"id":"bio-1141-4","front":"Evidence for the endosymbiotic origin of mitochondria and chloroplasts","back":"They have their own circular DNA, bacteria-like ribosomes, double membranes, and divide by a process like binary fission, consistent with descent from engulfed bacteria."},{"id":"bio-1141-5","front":"Prokaryotic vs eukaryotic cells","back":"Prokaryotes (bacteria and archaea) lack a nucleus and membrane-bound organelles and are usually smaller. Eukaryotes have a nucleus, membrane-bound organelles and an extensive cytoskeleton."},{"id":"bio-1141-6","front":"Rough ER vs smooth ER","back":"Rough ER has ribosomes and makes secreted, membrane and lysosomal proteins. Smooth ER lacks ribosomes and synthesizes lipids, detoxifies drugs and stores calcium."},{"id":"bio-1141-7","front":"Function of the Golgi apparatus","back":"It receives proteins and lipids from the ER, modifies them (for example by glycosylation), sorts them and packages them into vesicles for delivery to the membrane, lysosomes or secretion."},{"id":"bio-1141-8","front":"What do lysosomes do?","back":"They are acidic, membrane-bound compartments containing hydrolytic enzymes that digest macromolecules, worn-out organelles (autophagy) and material taken in by endocytosis."},{"id":"bio-1141-9","front":"Structure and roles of the nucleus","back":"A double-membrane nuclear envelope with nuclear pores encloses the DNA. The nucleolus makes ribosomal RNA and assembles ribosome subunits. Pores control traffic of RNA and proteins."},{"id":"bio-1141-10","front":"Fluid mosaic model of the plasma membrane","back":"The membrane is a fluid phospholipid bilayer in which proteins, cholesterol and carbohydrates are embedded or attached and can move laterally."},{"id":"bio-1141-11","front":"How does cholesterol affect membrane fluidity?","back":"It buffers fluidity: at warm temperatures it restrains phospholipid movement, and at cool temperatures it prevents tight packing that would make the membrane rigid."},{"id":"bio-1141-12","front":"Simple diffusion vs facilitated diffusion","back":"Both move substances down their concentration gradient without ATP. Simple diffusion goes directly through the bilayer (O2, CO2). Facilitated diffusion uses channel or carrier proteins (glucose, ions)."},{"id":"bio-1141-13","front":"What does the Na+/K+ pump do?","back":"It uses one ATP to pump 3 Na+ out of the cell and 2 K+ in, against their gradients. This primary active transport maintains the gradients and contributes to the membrane potential."},{"id":"bio-1141-14","front":"Secondary active transport","back":"Uses the energy of one ion moving down its gradient (often Na+, set up by the Na+/K+ pump) to move another substance against its gradient, as in the Na+/glucose symporter."},{"id":"bio-1141-15","front":"What happens to animal and plant cells in a hypotonic solution?","back":"Water enters by osmosis. Animal cells swell and may burst (lyse). Plant cells swell until the cell wall pushes back, becoming turgid, which is their healthy state."},{"id":"bio-1141-16","front":"Types of endocytosis","back":"Phagocytosis: engulfing large particles. Pinocytosis: taking in fluid. Receptor-mediated endocytosis: specific molecules bind receptors in clathrin-coated pits before uptake."},{"id":"bio-1141-17","front":"Three types of cytoskeletal filaments","back":"Microfilaments (actin, about 7 nm): cell shape, crawling, muscle contraction. Intermediate filaments (about 10 nm): mechanical strength. Microtubules (tubulin, about 25 nm): tracks for transport, spindle, cilia and flagella."},{"id":"bio-1141-18","front":"Kinesin vs dynein","back":"Both are motor proteins that walk along microtubules using ATP. Kinesin generally moves toward the plus end (outward), and dynein moves toward the minus end (inward). Myosin is the motor that moves along actin."},{"id":"bio-1141-19","front":"Structure of eukaryotic cilia and flagella","back":"A 9 + 2 arrangement: nine outer microtubule doublets around two central microtubules. Dynein arms cause doublets to slide, bending the structure. They are anchored by a basal body."},{"id":"bio-1141-20","front":"Sliding filament model of muscle contraction","back":"Ca2+ binds troponin, which moves tropomyosin and exposes binding sites on actin. Myosin heads bind actin, pull (power stroke) and release when ATP binds, so thin filaments slide past thick filaments."},{"id":"bio-1141-21","front":"Extracellular matrix and integrins","back":"The ECM is a network of proteins (such as collagen) and polysaccharides outside animal cells. Integrins are membrane proteins linking the ECM to the cytoskeleton and transmitting signals."},{"id":"bio-1141-22","front":"Tight junctions vs desmosomes vs gap junctions","back":"Tight junctions seal neighbouring cells to block leakage. Desmosomes anchor cells together for strength. Gap junctions form channels that let ions and small molecules pass between cells."},{"id":"bio-1141-23","front":"Phases of the eukaryotic cell cycle","back":"G1 (growth), S (DNA replication), G2 (preparation for division) and M phase (mitosis and cytokinesis). G1, S and G2 make up interphase. Non-dividing cells may exit to G0."},{"id":"bio-1141-24","front":"Stages of mitosis","back":"Prophase: chromosomes condense, spindle forms. Prometaphase: envelope breaks down, kinetochores attach. Metaphase: chromosomes line up. Anaphase: sister chromatids separate. Telophase: nuclei re-form."},{"id":"bio-1141-25","front":"How do cyclins and CDKs control the cell cycle?","back":"Cyclin-dependent kinases are active only when bound to cyclins, whose levels rise and fall during the cycle. Active cyclin-CDK complexes phosphorylate targets that push the cell past checkpoints."},{"id":"bio-1141-26","front":"Role of p53","back":"A tumour suppressor protein that responds to DNA damage by halting the cell cycle for repair or triggering apoptosis if the damage is too great. Mutations in p53 are common in cancers."},{"id":"bio-1141-27","front":"Cytokinesis in animal vs plant cells","back":"Animal cells form a cleavage furrow by a contractile ring of actin and myosin. Plant cells build a cell plate from Golgi-derived vesicles that becomes the new cell wall."},{"id":"bio-1141-28","front":"Key enzymes of DNA replication and their jobs","back":"Helicase unwinds the helix, topoisomerase relieves supercoiling, primase lays RNA primers, DNA polymerase adds nucleotides and proofreads, and ligase seals gaps between fragments."},{"id":"bio-1141-29","front":"Where do transcription and translation occur in eukaryotic cells?","back":"Transcription and mRNA processing happen in the nucleus. The mature mRNA is exported and translated by ribosomes in the cytosol or on the rough ER."},{"id":"bio-1141-30","front":"Roles of the ribosome''s A, P and E sites","back":"A site: accepts the incoming aminoacyl-tRNA. P site: holds the tRNA carrying the growing polypeptide. E site: where the empty tRNA exits."},{"id":"bio-1141-31","front":"How are secreted proteins directed to the ER?","back":"An N-terminal signal sequence is recognized by the signal recognition particle (SRP), which brings the ribosome to the ER membrane. The protein is threaded into the ER lumen as it is made."}],"quizzes":[],"seed":1,"look":{"color":"#0D9488","icon":"micro"}}'::jsonb);   -- https://catalogue.uottawa.ca/en/courses/bio/
select pg_temp.sb_seed('seed:mcgill-ca:psyc-100', 'mcgill.ca', 'PSYC 100', 'PSYC 100 Final Review: Development, Personality, Social Psychology and Mental Health', '{"v":1,"app":"studyboard","type":"deck","name":"PSYC 100 Final Review: Development, Personality, Social Psychology and Mental Health","course":{"code":"PSYC 100","name":"Introduction to Psychology"},"cards":[{"id":"psyc-100-1","front":"Ainsworth''s Strange Situation: main attachment styles","back":"Secure (upset when caregiver leaves, easily comforted on return), anxious-ambivalent or resistant (very distressed, hard to soothe), and avoidant (little distress, ignores caregiver). A disorganized style was added later."},{"id":"psyc-100-2","front":"What did Harlow''s infant monkey studies show?","back":"Infant monkeys preferred a soft cloth surrogate mother to a wire one that provided milk, especially when frightened. Contact comfort, not just feeding, is central to attachment."},{"id":"psyc-100-3","front":"Piaget''s four stages of cognitive development","back":"Sensorimotor (0-2 years, object permanence), preoperational (2-7, symbolic thought, egocentrism), concrete operational (7-11, conservation, logic about concrete things), formal operational (11+, abstract reasoning)."},{"id":"psyc-100-4","front":"Object permanence vs conservation","back":"Object permanence: knowing objects still exist when out of sight, developed in the sensorimotor stage. Conservation: knowing quantity stays the same despite changes in shape, mastered in the concrete operational stage."},{"id":"psyc-100-5","front":"Vygotsky''s zone of proximal development","back":"The gap between what a child can do alone and what they can do with guidance from a more skilled person. Support within this zone (scaffolding) drives learning."},{"id":"psyc-100-6","front":"Baumrind''s parenting styles","back":"Authoritative (warm, firm, explains rules), authoritarian (strict, low warmth, demands obedience), and permissive (warm, few demands). A neglectful (uninvolved) style was added later. Authoritative is linked to the best outcomes on average."},{"id":"psyc-100-7","front":"Erikson''s main crisis of adolescence","back":"Identity vs role confusion: teens explore roles and values to form a coherent sense of who they are."},{"id":"psyc-100-8","front":"The Big Five personality traits","back":"Openness to experience, Conscientiousness, Extraversion, Agreeableness and Neuroticism (OCEAN). They are relatively stable and partly heritable."},{"id":"psyc-100-9","front":"Freud''s id, ego and superego","back":"Id: unconscious drives seeking immediate pleasure. Superego: internalized moral standards. Ego: the mostly rational part that balances the id''s demands, the superego and reality."},{"id":"psyc-100-10","front":"Define projection, repression and displacement","back":"Projection: attributing your own unacceptable feelings to others. Repression: pushing threatening thoughts out of awareness. Displacement: redirecting impulses toward a safer target."},{"id":"psyc-100-11","front":"Person-situation debate","back":"Mischel argued that behaviour varies across situations more than trait theories predicted. The modern view is interactionist: traits predict average behaviour, while situations strongly shape specific actions."},{"id":"psyc-100-12","front":"How does personality tend to change across adulthood?","back":"On average, conscientiousness and agreeableness increase and neuroticism decreases from young adulthood to middle age, a pattern often called the maturity principle."},{"id":"psyc-100-13","front":"Fundamental attribution error","back":"Overestimating personality (dispositional) causes and underestimating situational causes when explaining other people''s behaviour."},{"id":"psyc-100-14","front":"Cognitive dissonance (Festinger and Carlsmith)","back":"Discomfort from holding conflicting beliefs and actions. Participants paid $1 to say a dull task was fun later rated it as more enjoyable than those paid $20, because they lacked a strong external justification."},{"id":"psyc-100-15","front":"What did Asch''s line studies show?","back":"Many people conformed to a clearly wrong group answer about line lengths on at least some trials. Conformity dropped sharply when even one other person gave the correct answer."},{"id":"psyc-100-16","front":"What did Milgram''s obedience study find?","back":"About 65 percent of participants obeyed an experimenter''s orders to deliver what they believed were the strongest shocks to another person. Obedience fell when the authority was less present or the victim was closer."},{"id":"psyc-100-17","front":"Bystander effect and diffusion of responsibility","back":"People are less likely to help in an emergency when others are present, because each person feels less personal responsibility to act (Darley and Latane)."},{"id":"psyc-100-18","front":"Social facilitation vs social loafing","back":"Social facilitation: the presence of others improves performance on easy or well-practiced tasks but impairs it on hard ones. Social loafing: people exert less effort in a group when individual contributions are not identifiable."},{"id":"psyc-100-19","front":"Groupthink","back":"A pattern in cohesive groups in which the desire for agreement overrides realistic evaluation of alternatives, leading to poor decisions. Dissent is suppressed and risks are underestimated."},{"id":"psyc-100-20","front":"Frustration-aggression hypothesis","back":"Being blocked from a goal creates frustration that increases the likelihood of aggression. It was later revised: frustration produces anger, which raises the readiness to aggress, especially with aggressive cues present."},{"id":"psyc-100-21","front":"Contact hypothesis for reducing prejudice","back":"Prejudice between groups decreases with contact under the right conditions: equal status, shared goals, cooperation and support from authorities."},{"id":"psyc-100-22","front":"Learned helplessness (Seligman) and its link to depression","back":"After repeated uncontrollable bad events, animals and people stop trying to escape even when escape becomes possible. It became a model for the hopelessness and passivity seen in depression."},{"id":"psyc-100-23","front":"Core features of major depressive disorder","back":"At least two weeks of depressed mood or loss of interest or pleasure, plus other symptoms such as sleep or appetite changes, fatigue, worthlessness, poor concentration or thoughts of death, causing significant impairment."},{"id":"psyc-100-24","front":"Beck''s cognitive triad","back":"Negative automatic thoughts about the self, the world and the future, which Beck proposed maintain depression."},{"id":"psyc-100-25","front":"Diathesis-stress model","back":"Psychological disorders arise from an interaction between a predisposition (diathesis, such as genetic vulnerability) and environmental stressors. Neither alone is usually sufficient."},{"id":"psyc-100-26","front":"Bipolar I vs bipolar II disorder","back":"Bipolar I involves at least one full manic episode. Bipolar II involves at least one hypomanic episode (milder, no severe impairment) and at least one major depressive episode, but no full mania."},{"id":"psyc-100-27","front":"Positive vs negative symptoms of schizophrenia","back":"Positive symptoms are added experiences: hallucinations, delusions, disorganized speech. Negative symptoms are reduced functions: flat affect, lack of motivation, reduced speech and social withdrawal."},{"id":"psyc-100-28","front":"Generalized anxiety disorder vs panic disorder","back":"GAD: persistent, hard-to-control worry about many things for at least six months. Panic disorder: recurrent unexpected panic attacks plus ongoing worry about future attacks or changes in behaviour to avoid them."},{"id":"psyc-100-29","front":"Cognitive-behavioural therapy vs psychodynamic therapy","back":"CBT targets current maladaptive thoughts and behaviours through structured techniques like cognitive restructuring and exposure. Psychodynamic therapy explores unconscious conflicts and past relationships to build insight."},{"id":"psyc-100-30","front":"How do SSRIs work?","back":"Selective serotonin reuptake inhibitors block reuptake of serotonin into the presynaptic neuron, increasing serotonin in the synapse. They are widely used for depression and anxiety disorders."},{"id":"psyc-100-31","front":"What does heritability mean, and what is a common misconception?","back":"Heritability is the proportion of variation in a trait within a population that is due to genetic differences. It does not describe how much of one individual''s trait is genetic, and it can change across environments."}],"quizzes":[],"seed":1,"look":{"color":"#D6386F","icon":"psych"}}'::jsonb);   -- https://coursecatalogue.mcgill.ca/courses/psyc-100/index.html
select pg_temp.sb_seed('seed:mcgill-ca:chem-110', 'mcgill.ca', 'CHEM 110', 'CHEM 110 Final Review: Atomic Structure, Nuclear Chemistry, Bonding and Metal Complexes', '{"v":1,"app":"studyboard","type":"deck","name":"CHEM 110 Final Review: Atomic Structure, Nuclear Chemistry, Bonding and Metal Complexes","course":{"code":"CHEM 110","name":"General Chemistry 1"},"cards":[{"id":"chem-110-1","front":"Energy of a photon","back":"E = h nu = hc / lambda, where h = 6.626 x 10^-34 J·s is Planck''s constant, nu is frequency, c = 3.00 x 10^8 m/s and lambda is wavelength."},{"id":"chem-110-2","front":"Mini-problem: energy of one photon of 500 nm light","back":"E = hc/lambda = (6.626 x 10^-34)(3.00 x 10^8) / (500 x 10^-9 m), about 3.98 x 10^-19 J."},{"id":"chem-110-3","front":"Photoelectric effect equation and its significance","back":"KE of ejected electron = h nu - work function. No electrons are ejected below a threshold frequency regardless of intensity, showing light comes in quanta (photons)."},{"id":"chem-110-4","front":"de Broglie wavelength","back":"lambda = h / (m v). All moving matter has wave properties; the effect is noticeable only for very small masses such as electrons."},{"id":"chem-110-5","front":"Bohr model energy levels for hydrogen","back":"E(n) = -2.18 x 10^-18 J (1/n^2). When an electron drops from a higher to a lower n, a photon is emitted with energy equal to the difference, giving line spectra."},{"id":"chem-110-6","front":"Heisenberg uncertainty principle","back":"It is impossible to know both the exact position and exact momentum of a particle at once: (delta x)(delta p) >= h/(4 pi). This is why electrons are described by orbitals (probability distributions)."},{"id":"chem-110-7","front":"The four quantum numbers","back":"n: principal (energy level, size). l: angular momentum (shape, 0 to n-1; s, p, d, f). ml: magnetic (orientation, -l to +l). ms: spin, +1/2 or -1/2."},{"id":"chem-110-8","front":"How many nodes does an orbital have?","back":"Total nodes = n - 1. Angular nodes = l. Radial nodes = n - l - 1. For example, a 3p orbital has 1 angular and 1 radial node."},{"id":"chem-110-9","front":"Aufbau principle, Pauli exclusion principle and Hund''s rule","back":"Aufbau: fill lowest-energy orbitals first. Pauli: no two electrons in an atom share all four quantum numbers, so at most two per orbital with opposite spins. Hund: fill degenerate orbitals singly with parallel spins before pairing."},{"id":"chem-110-10","front":"Electron configurations of Cr and Cu","back":"Cr is [Ar] 3d5 4s1 and Cu is [Ar] 3d10 4s1, exceptions caused by the extra stability of half-filled and filled d subshells."},{"id":"chem-110-11","front":"Trend in atomic radius and why","back":"Radius decreases across a period because effective nuclear charge increases while electrons enter the same shell. It increases down a group as electrons occupy higher shells."},{"id":"chem-110-12","front":"First ionization energy trend and two common exceptions","back":"Generally increases across a period and decreases down a group. Exceptions: B is lower than Be (removing a higher-energy 2p electron) and O is lower than N (electron pair repulsion in a 2p orbital)."},{"id":"chem-110-13","front":"Electronegativity trend","back":"Increases across a period and decreases down a group. Fluorine is the most electronegative element."},{"id":"chem-110-14","front":"Alpha, beta and gamma decay","back":"Alpha: emits a helium-4 nucleus, mass number drops by 4 and atomic number by 2. Beta (minus): a neutron becomes a proton and emits an electron, atomic number up by 1. Gamma: emits a high-energy photon with no change in mass or atomic number."},{"id":"chem-110-15","front":"Positron emission vs electron capture","back":"Both convert a proton into a neutron, lowering atomic number by 1 with no change in mass number. Positron emission releases a positron; electron capture absorbs an inner electron."},{"id":"chem-110-16","front":"Mini-problem: what forms when U-238 undergoes alpha decay?","back":"Th-234: mass number 238 - 4 = 234 and atomic number 92 - 2 = 90 (thorium), plus a helium-4 nucleus."},{"id":"chem-110-17","front":"Mini-problem: 80 g of an isotope decays for three half-lives. How much remains?","back":"80 -> 40 -> 20 -> 10 g, so 10 g remain."},{"id":"chem-110-18","front":"Mass defect and nuclear binding energy","back":"A nucleus has less mass than its separate protons and neutrons. The missing mass is the binding energy, E = delta m c^2. Iron-56 is near the peak of binding energy per nucleon, so it is among the most stable nuclei."},{"id":"chem-110-19","front":"Nuclear fission vs fusion","back":"Fission splits a heavy nucleus into smaller nuclei, releasing energy (nuclear reactors). Fusion combines light nuclei into a heavier one, releasing energy (stars). Both move toward higher binding energy per nucleon."},{"id":"chem-110-20","front":"Predicting decay from the neutron-to-proton ratio","back":"Nuclei with too many neutrons (above the band of stability) tend to undergo beta minus decay. Those with too few tend toward positron emission or electron capture. Very heavy nuclei often alpha decay."},{"id":"chem-110-21","front":"What is resonance in Lewis structures?","back":"When two or more valid Lewis structures differ only in electron placement, the real molecule is an average (resonance hybrid). For example, both O-O bonds in ozone are equal in length."},{"id":"chem-110-22","front":"VSEPR shapes for five and six electron groups with lone pairs","back":"Five groups: SF4 (1 lone pair) is seesaw, ClF3 (2) is T-shaped, XeF2 (3) is linear. Six groups: BrF5 (1 lone pair) is square pyramidal, XeF4 (2) is square planar."},{"id":"chem-110-23","front":"Hybridization from electron groups","back":"2 electron groups: sp (linear). 3: sp2 (trigonal planar). 4: sp3 (tetrahedral). 5: sp3d. 6: sp3d2."},{"id":"chem-110-24","front":"Sigma vs pi bonds","back":"A sigma bond forms from head-on orbital overlap and allows rotation. A pi bond forms from side-by-side p orbital overlap and restricts rotation. A double bond is 1 sigma + 1 pi; a triple bond is 1 sigma + 2 pi."},{"id":"chem-110-25","front":"Bond order formula in molecular orbital theory","back":"Bond order = (bonding electrons - antibonding electrons) / 2. Higher bond order means a stronger, shorter bond; bond order 0 means the molecule is not expected to exist (He2)."},{"id":"chem-110-26","front":"Why does MO theory explain that O2 is paramagnetic?","back":"O2 has two unpaired electrons in degenerate pi* antibonding orbitals, giving bond order (10 - 6)/2 = 2 and paramagnetism. A simple Lewis structure shows all electrons paired."},{"id":"chem-110-27","front":"Coordination complex vocabulary: ligand, coordination number, chelate","back":"A ligand is a Lewis base donating an electron pair to the metal. Coordination number is the number of donor atoms bonded to the metal. A chelating ligand binds through two or more donor atoms (ethylenediamine is bidentate)."},{"id":"chem-110-28","front":"Mini-problem: oxidation state of Co in [Co(NH3)5Cl]Cl2","back":"Two Cl- counter-ions mean the complex ion is 2+. NH3 is neutral and the bound Cl is -1, so Co + (-1) = +2 and Co is +3."},{"id":"chem-110-29","front":"Crystal field splitting in an octahedral complex","back":"The five d orbitals split into a lower-energy t2g set (dxy, dxz, dyz) and a higher-energy eg set (dz2, dx2-y2), which point at the ligands. The gap is delta o."},{"id":"chem-110-30","front":"High-spin vs low-spin complexes","back":"Weak-field ligands give a small delta o, so electrons occupy eg before pairing (high spin, more unpaired electrons). Strong-field ligands give a large delta o, so electrons pair in t2g first (low spin)."},{"id":"chem-110-31","front":"Spectrochemical series (selected ligands, weak to strong field)","back":"I- < Br- < Cl- < F- < OH- < H2O < NH3 < en < CN- < CO."},{"id":"chem-110-32","front":"Why are many transition metal complexes coloured?","back":"Electrons absorb visible light to jump from t2g to eg orbitals. The colour we see is complementary to the wavelength absorbed; larger delta o means absorption of shorter wavelengths."}],"quizzes":[],"seed":1,"look":{"color":"#DC2626","icon":"chem"}}'::jsonb);   -- https://coursecatalogue.mcgill.ca/courses/chem-110/index.html
select pg_temp.sb_seed('seed:mcgill-ca:math-140', 'mcgill.ca', 'MATH 140', 'MATH 140 Midterm Review: Functions, Limits, Continuity and Derivatives', '{"v":1,"app":"studyboard","type":"deck","name":"MATH 140 Midterm Review: Functions, Limits, Continuity and Derivatives","course":{"code":"MATH 140","name":"Calculus 1"},"cards":[{"id":"math-140-1","front":"What is the domain of a composite function f(g(x))?","back":"All x in the domain of g for which g(x) is in the domain of f. For f(x) = sqrt(x) and g(x) = x - 2, the domain of f(g(x)) is x >= 2."},{"id":"math-140-2","front":"When does a function have an inverse, and how do you find it?","back":"When it is one-to-one (passes the horizontal line test). Swap x and y and solve for y. The graph of the inverse is the reflection across y = x."},{"id":"math-140-3","front":"When does a two-sided limit exist?","back":"lim as x -> a of f(x) = L exists only if both one-sided limits exist and are equal to L. The function''s value at a does not matter."},{"id":"math-140-4","front":"Mini-problem: lim as x -> 3 of (x^2 - 9)/(x - 3)","back":"Factor: (x - 3)(x + 3)/(x - 3) = x + 3 for x not equal to 3, so the limit is 6."},{"id":"math-140-5","front":"Mini-problem: lim as x -> 0 of (sqrt(x + 4) - 2)/x","back":"Multiply by the conjugate: x / (x(sqrt(x + 4) + 2)) = 1/(sqrt(x + 4) + 2). As x -> 0 this gives 1/4."},{"id":"math-140-6","front":"Squeeze theorem","back":"If g(x) <= f(x) <= h(x) near a and lim g = lim h = L, then lim f = L. Example: -x^2 <= x^2 sin(1/x) <= x^2, so x^2 sin(1/x) -> 0 as x -> 0."},{"id":"math-140-7","front":"Important trigonometric limit","back":"lim as x -> 0 of sin(x)/x = 1 (x in radians). Also lim as x -> 0 of (1 - cos x)/x = 0."},{"id":"math-140-8","front":"Limits at infinity of rational functions","back":"Compare degrees. Numerator degree lower: limit 0. Equal degrees: ratio of leading coefficients. Numerator degree higher: no finite limit (grows without bound)."},{"id":"math-140-9","front":"Mini-problem: lim as x -> infinity of (3x^2 + 1)/(5x^2 - x)","back":"Equal degrees, so the limit is the ratio of leading coefficients: 3/5."},{"id":"math-140-10","front":"What is a vertical asymptote?","back":"x = a is a vertical asymptote if f(x) approaches positive or negative infinity as x approaches a from at least one side, often where a denominator is zero but the numerator is not."},{"id":"math-140-11","front":"Definition of continuity at a point","back":"f is continuous at a if f(a) is defined, lim as x -> a of f(x) exists, and the limit equals f(a)."},{"id":"math-140-12","front":"Removable vs jump vs infinite discontinuity","back":"Removable: the limit exists but differs from f(a) or f(a) is undefined (a hole). Jump: the one-sided limits exist but differ. Infinite: the function goes to infinity near the point."},{"id":"math-140-13","front":"Intermediate Value Theorem","back":"If f is continuous on [a, b] and N is between f(a) and f(b), then some c in (a, b) has f(c) = N. Often used to show an equation has a root."},{"id":"math-140-14","front":"Limit definition of the derivative","back":"f''(x) = lim as h -> 0 of (f(x + h) - f(x)) / h. It gives the slope of the tangent line and the instantaneous rate of change."},{"id":"math-140-15","front":"Does continuity imply differentiability?","back":"No. Differentiability implies continuity, but not the reverse. f(x) = |x| is continuous at 0 but not differentiable there because of the corner."},{"id":"math-140-16","front":"Power rule","back":"d/dx [x^n] = n·x^(n-1) for any real n. For example, d/dx [x^(-2)] = -2x^(-3)."},{"id":"math-140-17","front":"Product rule","back":"d/dx [f·g] = f''·g + f·g''."},{"id":"math-140-18","front":"Quotient rule","back":"d/dx [f/g] = (f''·g - f·g'') / g^2. Order matters in the numerator: derivative of the top times the bottom comes first."},{"id":"math-140-19","front":"Chain rule with an example","back":"d/dx [f(g(x))] = f''(g(x))·g''(x). Example: d/dx [sin(3x^2)] = cos(3x^2)·6x."},{"id":"math-140-20","front":"Derivatives of the six trig functions","back":"sin -> cos; cos -> -sin; tan -> sec^2; cot -> -csc^2; sec -> sec·tan; csc -> -csc·cot."},{"id":"math-140-21","front":"Derivatives of e^x and ln x","back":"d/dx [e^x] = e^x. d/dx [ln x] = 1/x for x > 0. With the chain rule, d/dx [e^(g(x))] = e^(g(x))·g''(x)."},{"id":"math-140-22","front":"Mini-problem: equation of the tangent line to y = x^2 at x = 3","back":"Point (3, 9), slope 2(3) = 6. Tangent line: y - 9 = 6(x - 3), so y = 6x - 9."},{"id":"math-140-23","front":"Logarithmic differentiation of y = x^x","back":"ln y = x ln x. Differentiate: y''/y = ln x + 1. So y'' = x^x (ln x + 1)."},{"id":"math-140-24","front":"Implicit differentiation: key idea","back":"Differentiate both sides with respect to x, treating y as a function of x, so every y term gets a factor of dy/dx by the chain rule. Then solve for dy/dx."},{"id":"math-140-25","front":"Position, velocity and acceleration","back":"If s(t) is position, velocity is v(t) = s''(t) and acceleration is a(t) = v''(t) = s''''(t). The object speeds up when v and a have the same sign."},{"id":"math-140-26","front":"What is an antiderivative?","back":"F is an antiderivative of f if F''(x) = f(x). All antiderivatives differ by a constant, so the general antiderivative of x^n (n not -1) is x^(n+1)/(n+1) + C."},{"id":"math-140-27","front":"Mini-problem: f''(x) = 6x and f(0) = 2. Find f(x).","back":"General antiderivative: f(x) = 3x^2 + C. Using f(0) = 2 gives C = 2, so f(x) = 3x^2 + 2."},{"id":"math-140-28","front":"Using f'' to find where f is increasing or decreasing","back":"f is increasing where f''(x) > 0 and decreasing where f''(x) < 0. Find critical points, then test the sign of f'' on each interval."},{"id":"math-140-29","front":"Using f'''' to find concavity","back":"f is concave up where f''''(x) > 0 and concave down where f''''(x) < 0. A point where concavity changes is an inflection point."},{"id":"math-140-30","front":"Common pitfall: derivative of a product","back":"The derivative of f·g is not f''·g''. Use the product rule f''g + fg''. Similarly, (f/g)'' is not f''/g''."}],"quizzes":[],"seed":1,"look":{"color":"#1D9BB8","icon":"calc"}}'::jsonb);   -- https://coursecatalogue.mcgill.ca/courses/math-140/index.html
select pg_temp.sb_seed('seed:mcgill-ca:econ-208', 'mcgill.ca', 'ECON 208', 'ECON 208 Final Review: Production, Costs, Market Structures and Factor Markets', '{"v":1,"app":"studyboard","type":"deck","name":"ECON 208 Final Review: Production, Costs, Market Structures and Factor Markets","course":{"code":"ECON 208","name":"Microeconomic Analysis and Applications"},"cards":[{"id":"econ-208-1","front":"Short run vs long run in production","back":"In the short run, at least one input (usually capital) is fixed. In the long run, all inputs are variable, so the firm can change its scale of operation."},{"id":"econ-208-2","front":"Total, average and marginal product; law of diminishing marginal returns","back":"TP is total output; AP = TP/L; MP = change in TP / change in L. Diminishing marginal returns: adding more of a variable input to a fixed input eventually makes MP fall."},{"id":"econ-208-3","front":"Fixed costs vs variable costs","back":"Fixed costs do not change with output in the short run (rent). Variable costs rise with output (raw materials, hourly labour). TC = TFC + TVC."},{"id":"econ-208-4","front":"Average and marginal cost formulas","back":"AFC = TFC/Q, AVC = TVC/Q, ATC = TC/Q = AFC + AVC. MC = change in TC / change in Q."},{"id":"econ-208-5","front":"Where does MC cross AVC and ATC?","back":"At their minimum points. When MC is below an average, the average falls; when MC is above it, the average rises."},{"id":"econ-208-6","front":"Mini-problem: total cost rises from $100 to $130 when output rises from 10 to 11 units. MC?","back":"MC = (130 - 100)/(11 - 10) = $30."},{"id":"econ-208-7","front":"Economies vs diseconomies of scale","back":"Economies of scale: long-run average cost falls as output expands (specialization, bulk buying). Diseconomies: LRAC rises at large scale (coordination problems). Minimum efficient scale is the smallest output at which LRAC is minimized."},{"id":"econ-208-8","front":"Accounting profit vs economic profit","back":"Accounting profit = revenue - explicit costs. Economic profit = revenue - explicit costs - implicit (opportunity) costs. Zero economic profit means a normal return on resources."},{"id":"econ-208-9","front":"Characteristics of perfect competition","back":"Many buyers and sellers, identical products, free entry and exit, and full information. Each firm is a price taker facing a horizontal demand curve at the market price."},{"id":"econ-208-10","front":"Profit-maximizing rule for any firm","back":"Produce where marginal revenue = marginal cost (MR = MC). For a perfectly competitive firm, MR = P, so it produces where P = MC."},{"id":"econ-208-11","front":"Short-run shutdown rule","back":"A firm should shut down if price is below minimum average variable cost, because it cannot cover variable costs. If P is between min AVC and min ATC, it operates at a loss to cover part of fixed costs."},{"id":"econ-208-12","front":"Long-run equilibrium in perfect competition","back":"Entry and exit drive economic profit to zero, so P = MC = minimum ATC. The outcome is both allocatively and productively efficient."},{"id":"econ-208-13","front":"Why is a monopolist''s marginal revenue below price?","back":"To sell an extra unit, a single-price monopolist must lower the price on all units sold. With linear demand P = a - bQ, MR = a - 2bQ, so MR has twice the slope of demand."},{"id":"econ-208-14","front":"Mini-problem: monopolist with demand P = 100 - 2Q and MC = 20. Profit-maximizing Q and P?","back":"MR = 100 - 4Q. Set MR = MC: 100 - 4Q = 20, so Q = 20. Price from demand: P = 100 - 40 = $60."},{"id":"econ-208-15","front":"Monopoly vs perfect competition outcomes","back":"Compared with competition, a monopoly charges a higher price and produces a lower quantity, creating deadweight loss. P > MC, so the outcome is allocatively inefficient."},{"id":"econ-208-16","front":"Natural monopoly and the regulation problem","back":"A natural monopoly has falling average costs over the relevant output range, so one firm can supply the market most cheaply. Marginal-cost pricing causes losses since P < ATC; average-cost pricing lets the firm break even."},{"id":"econ-208-17","front":"Conditions needed for price discrimination","back":"The firm must have market power, be able to identify groups with different willingness to pay or elasticities, and prevent resale between groups."},{"id":"econ-208-18","front":"Perfect (first-degree) price discrimination","back":"Each unit is sold at the buyer''s maximum willingness to pay. Output reaches the efficient level, so there is no deadweight loss, but the firm captures all consumer surplus."},{"id":"econ-208-19","front":"Long-run equilibrium in monopolistic competition","back":"Entry pushes economic profit to zero, so P = ATC, but the demand curve slopes down, so P > MC and firms produce below minimum ATC (excess capacity)."},{"id":"econ-208-20","front":"Prisoner''s dilemma in oligopoly","back":"Each firm has an incentive to cheat (cut price or raise output) whatever the other does, so the Nash equilibrium is for both to compete, even though both would earn more by cooperating."},{"id":"econ-208-21","front":"Dominant strategy vs Nash equilibrium","back":"A dominant strategy is best regardless of what rivals do. A Nash equilibrium is a set of strategies where no player can gain by changing strategy alone, given the others'' choices."},{"id":"econ-208-22","front":"Why are cartels unstable?","back":"Each member can raise its own profit by secretly producing more than its quota at the high cartel price. Cheating is hard to detect and punish, and collusion is illegal in many countries."},{"id":"econ-208-23","front":"Herfindahl-Hirschman Index (HHI)","back":"The sum of the squared market shares (in percent) of all firms. It ranges up to 10,000 for a pure monopoly; higher values mean a more concentrated industry."},{"id":"econ-208-24","front":"Why is the demand for labour a derived demand?","back":"Firms want labour not for itself but for the output it produces, so labour demand depends on demand for the final product and on labour''s productivity."},{"id":"econ-208-25","front":"How many workers does a profit-maximizing firm hire?","back":"It hires until the marginal revenue product of labour equals the wage: MRP = MR x MP = w. In a competitive output market, this is P x MP (value of marginal product) = w."},{"id":"econ-208-26","front":"What is a monopsony and how does it affect wages?","back":"A market with a single buyer of a factor, such as one employer in a town. It hires fewer workers and pays a lower wage than a competitive labour market would."},{"id":"econ-208-27","front":"Lorenz curve and Gini coefficient","back":"The Lorenz curve plots the cumulative share of income against the cumulative share of households. The Gini coefficient measures the gap from the line of perfect equality: 0 is perfect equality and 1 is maximum inequality."},{"id":"econ-208-28","front":"Economic rent in factor markets","back":"Payment to a factor above what is needed to keep it in its current use (its transfer earnings). A star athlete''s salary far above their next best job includes large economic rent."},{"id":"econ-208-29","front":"Allocative vs productive efficiency","back":"Allocative efficiency: producing the mix of goods society values most, where P = MC. Productive efficiency: producing at the lowest possible average cost (minimum ATC)."},{"id":"econ-208-30","front":"Should sunk costs affect business decisions?","back":"No. Sunk costs have already been paid and cannot be recovered, so only future marginal costs and benefits should guide decisions."}],"quizzes":[],"seed":1,"look":{"color":"#92400E","icon":"econ"}}'::jsonb);   -- https://coursecatalogue.mcgill.ca/courses/econ-208/index.html
select pg_temp.sb_seed('seed:uwaterloo-ca:psych-101', 'uwaterloo.ca', 'PSYCH 101', 'PSYCH 101 Exam Review: Research Methods, Biopsychology, Learning and Memory', '{"v":1,"app":"studyboard","type":"deck","name":"PSYCH 101 Exam Review: Research Methods, Biopsychology, Learning and Memory","course":{"code":"PSYCH 101","name":"Introductory Psychology"},"cards":[{"id":"psych-101-1","front":"What is the difference between an independent variable and a dependent variable?","back":"The independent variable is the factor the researcher manipulates; the dependent variable is the outcome that is measured to see whether it changed because of the manipulation."},{"id":"psych-101-2","front":"Why can a correlational study not establish causation?","back":"Two variables may be related because of a third variable, or the direction of influence may be reversed. Only an experiment with random assignment and controlled conditions supports causal claims."},{"id":"psych-101-3","front":"Random sampling vs random assignment","back":"Random sampling (choosing participants from a population by chance) improves generalizability. Random assignment (placing participants into conditions by chance) makes groups equivalent so differences can be attributed to the IV."},{"id":"psych-101-4","front":"What does a correlation coefficient of r = -0.80 tell you?","back":"A strong negative relationship: as one variable increases, the other tends to decrease. The sign gives direction and the absolute value (0 to 1) gives strength."},{"id":"psych-101-5","front":"What is a double-blind procedure and why use it?","back":"Neither participants nor the researchers collecting data know who is in which condition. It controls for both placebo effects and experimenter expectancy effects."},{"id":"psych-101-6","front":"Operational definition","back":"A precise statement of how a variable will be measured or manipulated in a study, e.g. defining ''aggression'' as the number of times a child hits a toy in 10 minutes."},{"id":"psych-101-7","front":"Reliability vs validity of a measure","back":"Reliability is consistency (the measure gives similar results each time). Validity is accuracy (it measures what it claims to measure). A measure can be reliable without being valid."},{"id":"psych-101-8","front":"What are the three main parts of a neuron and their roles?","back":"Dendrites receive signals, the cell body (soma) integrates them and holds the nucleus, and the axon carries the action potential to terminal buttons that release neurotransmitter."},{"id":"psych-101-9","front":"Describe the action potential in terms of ion movement.","back":"When the membrane reaches threshold, voltage-gated Na+ channels open and Na+ rushes in (depolarization); then K+ channels open and K+ flows out (repolarization), briefly overshooting (hyperpolarization)."},{"id":"psych-101-10","front":"What is the all-or-none law?","back":"A neuron either fires a full-strength action potential or does not fire at all. Stimulus intensity is coded by firing rate and number of neurons, not by the size of each spike."},{"id":"psych-101-11","front":"What role does the myelin sheath play?","back":"It insulates the axon and allows saltatory conduction, where the impulse jumps between nodes of Ranvier, greatly increasing conduction speed."},{"id":"psych-101-12","front":"Dopamine: main functions","back":"Involved in reward, motivation and voluntary movement. Loss of dopamine neurons is linked to Parkinson''s disease; excess dopamine activity is associated with positive symptoms of schizophrenia."},{"id":"psych-101-13","front":"Agonist vs antagonist drug","back":"An agonist mimics or enhances a neurotransmitter''s effect; an antagonist blocks or reduces it, often by occupying receptors without activating them."},{"id":"psych-101-14","front":"Sympathetic vs parasympathetic nervous system","back":"Both are branches of the autonomic nervous system. Sympathetic prepares the body for fight or flight (raises heart rate); parasympathetic supports rest and digest (conserves energy)."},{"id":"psych-101-15","front":"Which lobe contains the primary visual cortex?","back":"The occipital lobe, at the back of the brain."},{"id":"psych-101-16","front":"What did the case of Phineas Gage suggest about the frontal lobes?","back":"After an iron rod damaged his frontal lobe, his personality and self-control changed while basic intellect remained, suggesting the frontal lobes are important for planning, judgment and impulse control."},{"id":"psych-101-17","front":"Broca''s area vs Wernicke''s area","back":"Broca''s area (left frontal lobe) supports speech production; damage gives slow, effortful speech. Wernicke''s area (left temporal lobe) supports language comprehension; damage gives fluent but meaningless speech."},{"id":"psych-101-18","front":"Role of the hippocampus","back":"A limbic structure essential for forming new explicit (declarative) long-term memories. Damage, as in patient H.M., causes anterograde amnesia."},{"id":"psych-101-19","front":"Sensation vs perception","back":"Sensation is the detection of physical energy by sensory receptors; perception is the brain''s organization and interpretation of that input into meaningful experience."},{"id":"psych-101-20","front":"What is transduction?","back":"The conversion of physical stimulus energy (light, sound waves, pressure) into neural signals by sensory receptors."},{"id":"psych-101-21","front":"Rods vs cones","back":"Rods are very sensitive to dim light and do not code colour; they dominate the periphery. Cones need brighter light, code colour and detail, and are concentrated in the fovea."},{"id":"psych-101-22","front":"Weber''s law","back":"The just noticeable difference is a constant proportion of the original stimulus intensity. Example: if JND is 2% for weight, you notice 2 g added to 100 g but need 20 g added to 1000 g."},{"id":"psych-101-23","front":"In classical conditioning, identify the US, UR, CS and CR in Pavlov''s dogs.","back":"US = food, UR = salivation to food, CS = the tone (originally neutral), CR = salivation to the tone after pairing."},{"id":"psych-101-24","front":"Extinction vs spontaneous recovery","back":"Extinction is the weakening of a CR when the CS is repeatedly presented without the US. Spontaneous recovery is the reappearance of the weakened CR after a rest period."},{"id":"psych-101-25","front":"Negative reinforcement vs punishment","back":"Negative reinforcement removes an aversive stimulus to increase a behaviour (taking aspirin removes a headache). Punishment decreases a behaviour. Negative reinforcement is not punishment."},{"id":"psych-101-26","front":"Which reinforcement schedule produces the highest, most extinction-resistant response rates?","back":"Variable-ratio schedules, where reinforcement follows an unpredictable number of responses (e.g. slot machines)."},{"id":"psych-101-27","front":"What did Bandura''s Bobo doll study demonstrate?","back":"Children who watched an adult act aggressively toward a doll later imitated that aggression, showing observational learning without direct reinforcement."},{"id":"psych-101-28","front":"List the three stages of the Atkinson-Shiffrin memory model.","back":"Sensory memory (very brief, large capacity), short-term memory (about 7 plus or minus 2 items, roughly 20 seconds without rehearsal), and long-term memory (relatively permanent, vast capacity)."},{"id":"psych-101-29","front":"Explicit vs implicit memory","back":"Explicit (declarative) memory is consciously recalled facts (semantic) and events (episodic). Implicit memory shows up in performance without conscious recall, e.g. procedural skills and priming."},{"id":"psych-101-30","front":"Proactive vs retroactive interference","back":"Proactive: old learning disrupts recall of new information. Retroactive: new learning disrupts recall of old information."}],"quizzes":[],"seed":1,"look":{"color":"#9A4FD1","icon":"psych"}}'::jsonb);   -- https://academic-calendar-archive.uwaterloo.ca/undergraduate-studies/2017-2018/page/SCI-Psychology-Recommended-Course-Sequence1.html
select pg_temp.sb_seed('seed:uwaterloo-ca:biol-130', 'uwaterloo.ca', 'BIOL 130', 'BIOL 130 Exam Review: Cell Structure, Membranes, Cellular Energy and Division', '{"v":1,"app":"studyboard","type":"deck","name":"BIOL 130 Exam Review: Cell Structure, Membranes, Cellular Energy and Division","course":{"code":"BIOL 130","name":"Introductory Cell Biology"},"cards":[{"id":"biol-130-1","front":"Prokaryotic vs eukaryotic cells: key differences","back":"Prokaryotes lack a nucleus and membrane-bound organelles, have a circular chromosome and 70S ribosomes. Eukaryotes have a nucleus, internal membrane organelles, linear chromosomes and 80S cytoplasmic ribosomes."},{"id":"biol-130-2","front":"What are the main tenets of cell theory?","back":"All living things are made of one or more cells, the cell is the basic unit of life, and all cells come from pre-existing cells."},{"id":"biol-130-3","front":"Describe the fluid mosaic model of the plasma membrane.","back":"A phospholipid bilayer in which lipids and proteins move laterally, with integral and peripheral proteins, cholesterol and carbohydrate chains embedded in or attached to it."},{"id":"biol-130-4","front":"How does cholesterol affect membrane fluidity?","back":"It acts as a fluidity buffer: at high temperature it restrains phospholipid movement, and at low temperature it prevents tight packing, keeping the membrane from becoming too rigid."},{"id":"biol-130-5","front":"How do unsaturated fatty acid tails affect a membrane?","back":"Cis double bonds create kinks that prevent tight packing, increasing membrane fluidity and lowering the temperature at which the membrane solidifies."},{"id":"biol-130-6","front":"Which molecules cross a lipid bilayer easily without a transporter?","back":"Small nonpolar molecules such as O2, CO2 and N2, and to a lesser extent small uncharged polar molecules like water. Ions and large polar molecules need proteins."},{"id":"biol-130-7","front":"Passive vs active transport","back":"Passive transport moves solutes down their electrochemical gradient with no energy input (simple or facilitated diffusion). Active transport moves solutes against their gradient using ATP or another gradient."},{"id":"biol-130-8","front":"What does the Na+/K+ pump do per ATP hydrolyzed?","back":"It pumps 3 Na+ out of the cell and 2 K+ into the cell, contributing to the membrane potential and maintaining ion gradients."},{"id":"biol-130-9","front":"Secondary active transport (cotransport)","back":"A transporter uses the energy of an ion moving down its gradient (often Na+ or H+) to move another solute against its gradient, e.g. Na+/glucose symport."},{"id":"biol-130-10","front":"Function of the rough ER vs smooth ER","back":"Rough ER has ribosomes and makes secretory, membrane and lysosomal proteins. Smooth ER synthesizes lipids, detoxifies drugs and stores Ca2+."},{"id":"biol-130-11","front":"What does the Golgi apparatus do?","back":"It modifies (e.g. glycosylates), sorts and packages proteins and lipids received from the ER, sending them to the plasma membrane, lysosomes or secretion. Cargo enters the cis face and exits the trans face."},{"id":"biol-130-12","front":"Function of lysosomes","back":"Membrane-bound organelles with acid hydrolases (active at about pH 5) that digest macromolecules, worn-out organelles (autophagy) and engulfed material."},{"id":"biol-130-13","front":"What evidence supports the endosymbiotic origin of mitochondria and chloroplasts?","back":"They have double membranes, their own circular DNA, bacteria-like 70S ribosomes, and divide by a fission-like process."},{"id":"biol-130-14","front":"Name the three types of cytoskeletal filaments and a main role of each.","back":"Microfilaments (actin) for cell shape and movement; intermediate filaments for mechanical strength; microtubules (tubulin) for tracks for transport, the mitotic spindle, cilia and flagella."},{"id":"biol-130-15","front":"What are motor proteins kinesin and dynein used for?","back":"They walk along microtubules using ATP: kinesin generally moves cargo toward the plus end (cell periphery), dynein toward the minus end (cell centre); dynein also bends cilia and flagella."},{"id":"biol-130-16","front":"Write the overall equation for aerobic cellular respiration.","back":"C6H12O6 + 6 O2 -> 6 CO2 + 6 H2O + energy (ATP and heat)."},{"id":"biol-130-17","front":"Where does each stage of cellular respiration occur in eukaryotes?","back":"Glycolysis: cytosol. Pyruvate oxidation and citric acid cycle: mitochondrial matrix. Electron transport chain and ATP synthase: inner mitochondrial membrane."},{"id":"biol-130-18","front":"Net products of glycolysis per glucose","back":"2 pyruvate, 2 ATP (net) and 2 NADH."},{"id":"biol-130-19","front":"What is chemiosmosis?","back":"The electron transport chain pumps H+ into the intermembrane space; H+ then flows back into the matrix through ATP synthase, and that flow drives ATP synthesis."},{"id":"biol-130-20","front":"What is the final electron acceptor in aerobic respiration?","back":"Oxygen, which is reduced to water at the end of the electron transport chain."},{"id":"biol-130-21","front":"What does fermentation accomplish when oxygen is absent?","back":"It regenerates NAD+ from NADH (producing lactate or ethanol plus CO2) so glycolysis can continue to make a small amount of ATP."},{"id":"biol-130-22","front":"Competitive vs noncompetitive enzyme inhibition","back":"A competitive inhibitor binds the active site and can be overcome by more substrate (Km rises, Vmax unchanged). A noncompetitive inhibitor binds elsewhere and lowers Vmax."},{"id":"biol-130-23","front":"How do enzymes speed up reactions?","back":"They lower the activation energy by stabilizing the transition state. They do not change the overall free energy change (delta G) or the equilibrium position."},{"id":"biol-130-24","front":"List the phases of the eukaryotic cell cycle in order.","back":"G1, S (DNA replication), G2 (together called interphase), then M phase: mitosis (prophase, prometaphase, metaphase, anaphase, telophase) followed by cytokinesis."},{"id":"biol-130-25","front":"What happens in anaphase of mitosis?","back":"Cohesin holding sister chromatids together is cleaved, and the chromatids are pulled to opposite poles by shortening kinetochore microtubules."},{"id":"biol-130-26","front":"What is the role of cyclins and cyclin-dependent kinases (Cdks)?","back":"Cyclin levels rise and fall through the cycle; cyclin binding activates Cdks, which phosphorylate targets to drive the cell through checkpoints such as G1/S and G2/M."},{"id":"biol-130-27","front":"Mitosis vs meiosis outcomes","back":"Mitosis produces two genetically identical diploid daughter cells. Meiosis produces four genetically varied haploid cells through two divisions, crossing over and independent assortment."},{"id":"biol-130-28","front":"What is apoptosis?","back":"Programmed cell death carried out by caspases, in which the cell shrinks and fragments in a controlled way without causing inflammation."}],"quizzes":[],"seed":1,"look":{"color":"#1E9E74","icon":"bio"}}'::jsonb);   -- https://ucalendar.uwaterloo.ca/2223/COURSE/course-BIOL.html
select pg_temp.sb_seed('seed:uwaterloo-ca:math-137', 'uwaterloo.ca', 'MATH 137', 'MATH 137 Exam Review: Sequences, Limits, Continuity, Derivatives and Taylor Polynomials', '{"v":1,"app":"studyboard","type":"deck","name":"MATH 137 Exam Review: Sequences, Limits, Continuity, Derivatives and Taylor Polynomials","course":{"code":"MATH 137","name":"Calculus 1 for Honours Mathematics"},"cards":[{"id":"math-137-1","front":"Formal definition: a sequence {a_n} converges to L","back":"For every epsilon > 0 there exists N such that for all n > N, |a_n - L| < epsilon."},{"id":"math-137-2","front":"State the Monotone Convergence Theorem.","back":"Every bounded monotonic sequence converges. An increasing sequence bounded above converges to its least upper bound."},{"id":"math-137-3","front":"Does a_n = (-1)^n converge?","back":"No. The terms alternate between -1 and 1, so there is no single limit; the sequence is bounded but divergent."},{"id":"math-137-4","front":"Squeeze Theorem","back":"If g(x) <= f(x) <= h(x) near a and lim g(x) = lim h(x) = L as x -> a, then lim f(x) = L as x -> a."},{"id":"math-137-5","front":"Evaluate lim (x -> 0) of x^2 sin(1/x).","back":"0. Since -x^2 <= x^2 sin(1/x) <= x^2 and both bounds go to 0, the Squeeze Theorem gives 0."},{"id":"math-137-6","front":"Epsilon-delta definition of lim (x -> a) f(x) = L","back":"For every epsilon > 0 there exists delta > 0 such that 0 < |x - a| < delta implies |f(x) - L| < epsilon."},{"id":"math-137-7","front":"What is the fundamental trig limit?","back":"lim (x -> 0) sin(x)/x = 1 (x in radians)."},{"id":"math-137-8","front":"Evaluate lim (x -> 3) (x^2 - 9)/(x - 3).","back":"Factor: (x - 3)(x + 3)/(x - 3) = x + 3 for x not equal to 3, so the limit is 6."},{"id":"math-137-9","front":"Three conditions for f to be continuous at x = a","back":"f(a) is defined, lim (x -> a) f(x) exists, and the limit equals f(a)."},{"id":"math-137-10","front":"Name the three types of discontinuity.","back":"Removable (limit exists but differs from f(a) or f(a) undefined), jump (left and right limits exist but differ), and infinite/essential (a one-sided limit is infinite or does not exist)."},{"id":"math-137-11","front":"State the Intermediate Value Theorem.","back":"If f is continuous on [a, b] and k is any value between f(a) and f(b), then there is some c in [a, b] with f(c) = k."},{"id":"math-137-12","front":"How do you use the IVT to show x^3 + x - 1 = 0 has a root in [0, 1]?","back":"f(0) = -1 < 0 and f(1) = 1 > 0, and f is a continuous polynomial, so by the IVT there is c in (0, 1) with f(c) = 0."},{"id":"math-137-13","front":"Limit definition of the derivative","back":"f''(a) = lim (h -> 0) [f(a + h) - f(a)] / h, provided the limit exists."},{"id":"math-137-14","front":"Does differentiability imply continuity? Does the converse hold?","back":"Differentiable at a implies continuous at a. The converse is false: f(x) = |x| is continuous at 0 but not differentiable there."},{"id":"math-137-15","front":"Product rule and quotient rule","back":"(fg)'' = f''g + fg''. (f/g)'' = (f''g - fg'') / g^2, where g is not 0."},{"id":"math-137-16","front":"Chain rule; differentiate sin(x^3).","back":"d/dx f(g(x)) = f''(g(x))·g''(x). So d/dx sin(x^3) = cos(x^3)·3x^2."},{"id":"math-137-17","front":"Derivatives of e^x, ln x, a^x","back":"d/dx e^x = e^x; d/dx ln x = 1/x for x > 0; d/dx a^x = a^x·ln a."},{"id":"math-137-18","front":"Derivatives of tan x, arcsin x, arctan x","back":"d/dx tan x = sec^2 x; d/dx arcsin x = 1/sqrt(1 - x^2); d/dx arctan x = 1/(1 + x^2)."},{"id":"math-137-19","front":"Find dy/dx for x^2 + y^2 = 25 by implicit differentiation.","back":"2x + 2y·dy/dx = 0, so dy/dx = -x/y."},{"id":"math-137-20","front":"When should you use logarithmic differentiation? Differentiate y = x^x.","back":"When a variable is in both base and exponent, or for messy products. ln y = x ln x, so y''/y = ln x + 1, giving y'' = x^x (ln x + 1)."},{"id":"math-137-21","front":"Linear approximation of f near x = a","back":"L(x) = f(a) + f''(a)(x - a). Example: sqrt(4.1) is about 2 + (1/4)(0.1) = 2.025."},{"id":"math-137-22","front":"State the Mean Value Theorem.","back":"If f is continuous on [a, b] and differentiable on (a, b), there is c in (a, b) with f''(c) = [f(b) - f(a)] / (b - a)."},{"id":"math-137-23","front":"What is a consequence of the MVT about functions with zero derivative?","back":"If f''(x) = 0 for all x in an interval, then f is constant on that interval."},{"id":"math-137-24","front":"First derivative test for increasing/decreasing","back":"If f''(x) > 0 on an interval, f is increasing there; if f''(x) < 0, f is decreasing. A sign change of f'' at a critical point indicates a local max or min."},{"id":"math-137-25","front":"State L''Hospital''s Rule.","back":"If lim f(x)/g(x) is of the form 0/0 or infinity/infinity, then lim f(x)/g(x) = lim f''(x)/g''(x), provided the latter limit exists."},{"id":"math-137-26","front":"nth degree Taylor polynomial of f centred at a","back":"T_n(x) = sum from k = 0 to n of f^(k)(a)/k! · (x - a)^k."},{"id":"math-137-27","front":"Write the degree 3 Taylor polynomial of e^x and sin x centred at 0.","back":"e^x: 1 + x + x^2/2 + x^3/6. sin x: x - x^3/6."},{"id":"math-137-28","front":"Taylor''s Remainder Theorem (Lagrange form)","back":"f(x) - T_n(x) = f^(n+1)(c)/(n+1)! · (x - a)^(n+1) for some c between a and x; bounding f^(n+1) bounds the error."},{"id":"math-137-29","front":"Newton''s method iteration formula","back":"x_(n+1) = x_n - f(x_n)/f''(x_n). It approximates a root of f by following tangent lines; it may fail if f''(x_n) is near 0."}],"quizzes":[],"seed":1,"look":{"color":"#4F46E5","icon":"calc"}}'::jsonb);   -- https://academic-calendar-archive.uwaterloo.ca/undergraduate-studies/2017-2018/page/MATH-Mathematical-Studies.html
select pg_temp.sb_seed('seed:uwaterloo-ca:chem-120', 'uwaterloo.ca', 'CHEM 120', 'CHEM 120 Exam Review: Atomic Structure, Periodic Trends, Bonding and Gases', '{"v":1,"app":"studyboard","type":"deck","name":"CHEM 120 Exam Review: Atomic Structure, Periodic Trends, Bonding and Gases","course":{"code":"CHEM 120","name":"Physical and Chemical Properties of Matter"},"cards":[{"id":"chem-120-1","front":"Relationship between energy, frequency and wavelength of light","back":"E = h·nu and c = lambda·nu, so E = hc/lambda. h = 6.626 x 10^-34 J·s, c = 3.00 x 10^8 m/s. Shorter wavelength means higher energy."},{"id":"chem-120-2","front":"Energy of the hydrogen atom levels (Bohr)","back":"E_n = -2.18 x 10^-18 J / n^2. A photon emitted when an electron drops from n_i to n_f has energy equal to the difference E_i - E_f."},{"id":"chem-120-3","front":"What does the de Broglie relation state?","back":"Any moving particle has a wavelength lambda = h/(m·v), so electrons show wave behaviour such as diffraction."},{"id":"chem-120-4","front":"Heisenberg uncertainty principle","back":"Position and momentum cannot both be known exactly at the same time: delta x · delta p >= h/(4·pi)."},{"id":"chem-120-5","front":"Name the four quantum numbers and their allowed values.","back":"n = 1, 2, 3...; l = 0 to n-1 (s, p, d, f); m_l = -l to +l; m_s = +1/2 or -1/2."},{"id":"chem-120-6","front":"How many orbitals and electrons are in the n = 3 shell?","back":"n^2 = 9 orbitals (one 3s, three 3p, five 3d), holding up to 2n^2 = 18 electrons."},{"id":"chem-120-7","front":"State the Pauli exclusion principle and Hund''s rule.","back":"Pauli: no two electrons in an atom have the same four quantum numbers, so an orbital holds at most 2 electrons of opposite spin. Hund: degenerate orbitals fill singly with parallel spins before pairing."},{"id":"chem-120-8","front":"Write the ground-state electron configuration of Fe.","back":"[Ar] 4s^2 3d^6."},{"id":"chem-120-9","front":"Why are the configurations of Cr and Cu exceptions?","back":"A half-filled or filled d subshell is especially stable: Cr is [Ar] 4s^1 3d^5 and Cu is [Ar] 4s^1 3d^10."},{"id":"chem-120-10","front":"What is effective nuclear charge (Zeff) and how does it change across a period?","back":"Zeff = Z - S, the net positive charge felt by an electron after shielding. It increases across a period, pulling electrons closer."},{"id":"chem-120-11","front":"Trend in atomic radius on the periodic table","back":"Radius decreases across a period (Zeff rises) and increases down a group (more shells)."},{"id":"chem-120-12","front":"Trend in first ionization energy, and one exception","back":"Increases across a period and decreases down a group. Exception: O is lower than N because pairing in a 2p orbital adds repulsion (similarly B is lower than Be)."},{"id":"chem-120-13","front":"Ionic vs covalent bonding","back":"Ionic bonds form by electron transfer between atoms with a large electronegativity difference (often metal and nonmetal). Covalent bonds form by sharing electrons between nonmetals."},{"id":"chem-120-14","front":"How do you calculate formal charge?","back":"FC = (valence electrons) - (nonbonding electrons) - (1/2 x bonding electrons). The best Lewis structure minimizes formal charges and puts negative charge on the more electronegative atom."},{"id":"chem-120-15","front":"What are resonance structures?","back":"Two or more valid Lewis structures differing only in electron placement. The real molecule is a hybrid, e.g. all three C-O bonds in carbonate are equivalent."},{"id":"chem-120-16","front":"VSEPR: geometry of a molecule with 4 electron domains and 1 lone pair","back":"Electron geometry tetrahedral; molecular shape trigonal pyramidal (e.g. NH3), bond angle a bit less than 109.5 degrees."},{"id":"chem-120-17","front":"VSEPR: shape of SF4 and XeF4","back":"SF4 (5 domains, 1 lone pair) is seesaw. XeF4 (6 domains, 2 lone pairs) is square planar."},{"id":"chem-120-18","front":"What hybridization corresponds to 2, 3 and 4 electron domains?","back":"2 domains: sp (linear). 3 domains: sp2 (trigonal planar). 4 domains: sp3 (tetrahedral)."},{"id":"chem-120-19","front":"Sigma vs pi bonds","back":"A sigma bond forms by head-on overlap along the bond axis; a pi bond forms by side-on overlap of p orbitals. A double bond is 1 sigma + 1 pi; a triple bond is 1 sigma + 2 pi."},{"id":"chem-120-20","front":"How is bond order found from MO theory, and what does it predict for O2?","back":"Bond order = (bonding e- - antibonding e-)/2. O2 has bond order 2 and two unpaired electrons in pi* orbitals, so it is paramagnetic."},{"id":"chem-120-21","front":"When is a molecule with polar bonds nonpolar overall?","back":"When its geometry makes the bond dipoles cancel, e.g. CO2 (linear) and CCl4 (tetrahedral)."},{"id":"chem-120-22","front":"Ideal gas law","back":"PV = nRT, where P is pressure, V volume, n moles, T temperature in kelvin, and R = 8.314 J/(mol·K) or 0.08206 L·atm/(mol·K)."},{"id":"chem-120-23","front":"Mini-problem: what volume does 1.00 mol of ideal gas occupy at 273.15 K and 1.00 atm?","back":"V = nRT/P = (1.00)(0.08206)(273.15)/1.00 = 22.4 L."},{"id":"chem-120-24","front":"Dalton''s law of partial pressures","back":"P_total = P_A + P_B + ...; each partial pressure P_A = x_A·P_total, where x_A is the mole fraction."},{"id":"chem-120-25","front":"What does kinetic molecular theory say about average kinetic energy?","back":"The average kinetic energy of gas particles depends only on absolute temperature: KE_avg = (3/2)RT per mole. At the same T, lighter molecules move faster."},{"id":"chem-120-26","front":"Graham''s law of effusion","back":"rate_1/rate_2 = sqrt(M_2/M_1). Lighter gases effuse faster; H2 effuses 4 times faster than O2."},{"id":"chem-120-27","front":"When do real gases deviate most from ideal behaviour?","back":"At high pressure (molecular volume matters) and low temperature (intermolecular attractions matter). The van der Waals equation corrects with constants a (attraction) and b (volume)."}],"quizzes":[],"seed":1,"look":{"color":"#E0673B","icon":"chem"}}'::jsonb);   -- https://academic-calendar-archive.uwaterloo.ca/undergraduate-studies/2017-2018/page/SCI-Psychology-Recommended-Course-Sequence1.html
select pg_temp.sb_seed('seed:mcmaster-ca:psych-1x03', 'mcmaster.ca', 'PSYCH 1X03', 'PSYCH 1X03 Exam Review: Research Design, Learning, Cognition and Social Psychology', '{"v":1,"app":"studyboard","type":"deck","name":"PSYCH 1X03 Exam Review: Research Design, Learning, Cognition and Social Psychology","course":{"code":"PSYCH 1X03","name":"Introduction to Psychology, Neuroscience & Behaviour"},"cards":[{"id":"psych-1x03-1","front":"What is the third-variable problem?","back":"An unmeasured variable may cause both measured variables to change, creating a correlation without a direct causal link (e.g. heat raising both ice cream sales and drownings)."},{"id":"psych-1x03-2","front":"Between-subjects vs within-subjects design","back":"Between-subjects: each participant experiences only one condition. Within-subjects: each participant experiences all conditions, which needs fewer people but risks order effects."},{"id":"psych-1x03-3","front":"What is counterbalancing?","back":"Varying the order of conditions across participants in a within-subjects design so that practice, fatigue and other order effects are spread evenly across conditions."},{"id":"psych-1x03-4","front":"Internal vs external validity","back":"Internal validity is confidence that the IV caused the change in the DV. External validity is how well results generalize to other people, settings and times."},{"id":"psych-1x03-5","front":"What is a confound?","back":"A variable other than the IV that differs systematically between conditions, so it offers an alternative explanation for the results."},{"id":"psych-1x03-6","front":"Demand characteristics","back":"Cues in a study that hint at the hypothesis, which may lead participants to change their behaviour to fit what they think is expected."},{"id":"psych-1x03-7","front":"What is a statistically significant result, conventionally?","back":"A result with p < .05, meaning that if the null hypothesis were true, a result at least this extreme would occur less than 5% of the time."},{"id":"psych-1x03-8","front":"Mean, median and mode: which is least affected by outliers?","back":"The median (middle score). The mean is pulled toward extreme values, which is why income is often reported as a median."},{"id":"psych-1x03-9","front":"Habituation vs sensitization","back":"Habituation is a decrease in response to a repeated harmless stimulus. Sensitization is an increased response to a stimulus after exposure to an intense or noxious one."},{"id":"psych-1x03-10","front":"What is stimulus generalization in classical conditioning?","back":"Responding to stimuli similar to the CS, e.g. Little Albert fearing other furry objects after being conditioned to fear a white rat."},{"id":"psych-1x03-11","front":"Why is taste aversion learning a challenge for traditional conditioning theory?","back":"It can form after one pairing with a long delay between taste and illness, and it forms more readily with tastes than sounds, showing biological preparedness."},{"id":"psych-1x03-12","front":"Thorndike''s law of effect","back":"Behaviours followed by satisfying consequences become more likely to recur, and those followed by unpleasant consequences become less likely."},{"id":"psych-1x03-13","front":"What is shaping in operant conditioning?","back":"Reinforcing successive approximations of a target behaviour until the full behaviour is produced."},{"id":"psych-1x03-14","front":"Fixed-interval schedule: what response pattern does it produce?","back":"A scalloped pattern: responding slows right after reinforcement and speeds up as the time for the next available reinforcer approaches."},{"id":"psych-1x03-15","front":"What is latent learning (Tolman)?","back":"Learning that occurs without obvious reinforcement and is not shown until there is an incentive, e.g. rats that explored a maze quickly ran it once food was introduced, suggesting a cognitive map."},{"id":"psych-1x03-16","front":"Working memory components in Baddeley''s model","back":"The central executive (controls attention), phonological loop (verbal/auditory info), visuospatial sketchpad (visual and spatial info) and episodic buffer (integrates information)."},{"id":"psych-1x03-17","front":"Levels of processing theory","back":"Deeper, meaning-based (semantic) processing produces better long-term retention than shallow processing of physical or sound features."},{"id":"psych-1x03-18","front":"Serial position effect","back":"Items at the start (primacy, from transfer to long-term memory) and end (recency, still in short-term memory) of a list are recalled better than items in the middle."},{"id":"psych-1x03-19","front":"Encoding specificity principle","back":"Memory retrieval is best when cues present at retrieval match those present at encoding, including context (context-dependent memory) and internal state (state-dependent memory)."},{"id":"psych-1x03-20","front":"Availability heuristic vs representativeness heuristic","back":"Availability: judging likelihood by how easily examples come to mind. Representativeness: judging likelihood by how well something matches a prototype, often ignoring base rates."},{"id":"psych-1x03-21","front":"What is confirmation bias?","back":"The tendency to seek, notice and remember information that supports one''s existing beliefs while overlooking contradicting evidence."},{"id":"psych-1x03-22","front":"What is functional fixedness?","back":"A barrier to problem solving where a person can only see an object in its usual function, e.g. not thinking to use a coin as a screwdriver."},{"id":"psych-1x03-23","front":"Fundamental attribution error","back":"The tendency to overemphasize personality (dispositional) explanations and underestimate situational influences when explaining other people''s behaviour."},{"id":"psych-1x03-24","front":"Main finding of Asch''s line-judgment studies","back":"Many participants conformed at least once to a group''s obviously wrong answer, showing the power of normative social pressure; conformity dropped sharply when one other person dissented."},{"id":"psych-1x03-25","front":"Main finding of Milgram''s obedience study","back":"About 65% of participants obeyed an authority figure''s instructions to give what they believed were maximum-voltage shocks, showing strong situational pressure to obey."},{"id":"psych-1x03-26","front":"What is cognitive dissonance?","back":"Discomfort from holding inconsistent beliefs or acting against one''s attitudes, which people reduce by changing attitudes or justifying the behaviour (Festinger and Carlsmith''s $1 vs $20 study)."},{"id":"psych-1x03-27","front":"Bystander effect and diffusion of responsibility","back":"People are less likely to help in an emergency when others are present, partly because each person feels less personal responsibility to act."},{"id":"psych-1x03-28","front":"Social facilitation vs social loafing","back":"Social facilitation: the presence of others improves performance on simple or well-learned tasks (and worsens it on hard ones). Social loafing: people exert less effort when individual effort is pooled in a group."}],"quizzes":[],"seed":1,"look":{"color":"#D6386F","icon":"psych"}}'::jsonb);   -- https://academiccalendars.romcmaster.ca/preview_course_nopop.php?catoid=56&coid=279502
select pg_temp.sb_seed('seed:mcmaster-ca:biology-1a03', 'mcmaster.ca', 'BIOLOGY 1A03', 'BIOLOGY 1A03 Exam Review: Macromolecules, Membranes, Metabolism and Gene Expression', '{"v":1,"app":"studyboard","type":"deck","name":"BIOLOGY 1A03 Exam Review: Macromolecules, Membranes, Metabolism and Gene Expression","course":{"code":"BIOLOGY 1A03","name":"Cellular and Molecular Biology"},"cards":[{"id":"biology-1a03-1","front":"Name the four major classes of biological macromolecules and their monomers.","back":"Proteins (amino acids), nucleic acids (nucleotides), carbohydrates (monosaccharides) and lipids (not true polymers; fats are built from glycerol and fatty acids)."},{"id":"biology-1a03-2","front":"What type of bond links amino acids, and how is it formed?","back":"A peptide bond, formed by a dehydration (condensation) reaction between the carboxyl group of one amino acid and the amino group of the next."},{"id":"biology-1a03-3","front":"Four levels of protein structure","back":"Primary: amino acid sequence. Secondary: alpha helices and beta sheets held by backbone H-bonds. Tertiary: 3D fold from side-chain interactions. Quaternary: assembly of multiple polypeptides."},{"id":"biology-1a03-4","front":"Why does a protein denature at high temperature or extreme pH?","back":"Heat and pH disrupt the hydrogen bonds, ionic interactions and hydrophobic interactions that hold its shape, causing loss of function; the primary sequence is unchanged."},{"id":"biology-1a03-5","front":"DNA vs RNA structure","back":"DNA: deoxyribose, bases A, T, G, C, usually double-stranded. RNA: ribose (with 2'' OH), bases A, U, G, C, usually single-stranded."},{"id":"biology-1a03-6","front":"What does antiparallel mean for DNA strands?","back":"The two strands run in opposite directions: one 5'' to 3'', the other 3'' to 5''. A pairs with T (2 H-bonds) and G pairs with C (3 H-bonds)."},{"id":"biology-1a03-7","front":"What did the Meselson-Stahl experiment show?","back":"Using heavy (15N) and light (14N) nitrogen, they showed DNA replication is semiconservative: each new double helix has one parental and one new strand."},{"id":"biology-1a03-8","front":"Leading vs lagging strand synthesis","back":"DNA polymerase only adds nucleotides to a 3'' end. The leading strand is made continuously toward the fork; the lagging strand is made discontinuously as Okazaki fragments that ligase joins."},{"id":"biology-1a03-9","front":"Roles of helicase, primase and DNA ligase","back":"Helicase unwinds the double helix, primase lays down a short RNA primer to give a 3'' OH, and ligase seals nicks between Okazaki fragments."},{"id":"biology-1a03-10","front":"State the central dogma of molecular biology.","back":"Genetic information flows from DNA to RNA (transcription) to protein (translation). Reverse transcriptase in retroviruses is a notable exception (RNA to DNA)."},{"id":"biology-1a03-11","front":"Where does transcription start and what enzyme carries it out?","back":"RNA polymerase binds a promoter upstream of the gene (in eukaryotes with the help of transcription factors, e.g. at a TATA box) and synthesizes RNA 5'' to 3'' from the template strand."},{"id":"biology-1a03-12","front":"Three main eukaryotic pre-mRNA processing steps","back":"Adding a 5'' cap, adding a 3'' poly-A tail, and splicing out introns (joining exons) by the spliceosome."},{"id":"biology-1a03-13","front":"What is alternative splicing?","back":"Different combinations of exons are joined from the same pre-mRNA, allowing one gene to produce several different proteins."},{"id":"biology-1a03-14","front":"Mini-problem: the mRNA codon is 5''-AUG-3''. What is the tRNA anticodon?","back":"3''-UAC-5'' (usually written 5''-CAU-3''). AUG codes for methionine and is the start codon."},{"id":"biology-1a03-15","front":"Name the three stop codons.","back":"UAA, UAG and UGA. They are recognized by release factors, not tRNAs."},{"id":"biology-1a03-16","front":"What happens at the A, P and E sites of the ribosome?","back":"A site: incoming aminoacyl-tRNA binds. P site: holds the tRNA with the growing chain; peptide bond forms. E site: empty tRNA exits."},{"id":"biology-1a03-17","front":"What is the genetic code''s redundancy?","back":"Most amino acids are coded by more than one codon (64 codons for 20 amino acids), often differing at the third position (wobble), which reduces the impact of some mutations."},{"id":"biology-1a03-18","front":"Missense vs nonsense vs frameshift mutation","back":"Missense changes one amino acid. Nonsense creates a premature stop codon. Frameshift (insertion or deletion not a multiple of 3) shifts the reading frame and changes all downstream codons."},{"id":"biology-1a03-19","front":"How does the lac operon respond when lactose is present and glucose is absent?","back":"Allolactose binds the lac repressor so it leaves the operator, and high cAMP-CAP boosts RNA polymerase binding, so the lac genes are strongly transcribed."},{"id":"biology-1a03-20","front":"What is a signal sequence and what does it do?","back":"A short stretch of hydrophobic amino acids at the N-terminus that is recognized by SRP, which directs the ribosome to the rough ER so the protein enters the secretory pathway."},{"id":"biology-1a03-21","front":"Exergonic vs endergonic reactions","back":"Exergonic reactions release free energy (delta G < 0) and are spontaneous. Endergonic reactions require free energy input (delta G > 0) and are often coupled to ATP hydrolysis."},{"id":"biology-1a03-22","front":"Why is ATP called the energy currency of the cell?","back":"Hydrolysis of its terminal phosphate bond (ATP -> ADP + Pi) releases usable free energy that is coupled to endergonic reactions, often via phosphorylation of a substrate or protein."},{"id":"biology-1a03-23","front":"Oxidation vs reduction (OIL RIG)","back":"Oxidation is loss of electrons; reduction is gain. In respiration glucose is oxidized and O2 is reduced; NAD+ is reduced to NADH as it carries electrons."},{"id":"biology-1a03-24","front":"What is osmosis, and what happens to an animal cell in a hypotonic solution?","back":"Osmosis is diffusion of water across a selectively permeable membrane toward higher solute concentration. In a hypotonic solution water enters and an animal cell swells and may lyse."},{"id":"biology-1a03-25","front":"Light reactions vs Calvin cycle in photosynthesis","back":"Light reactions (thylakoid membranes) split water, release O2 and make ATP and NADPH. The Calvin cycle (stroma) uses that ATP and NADPH to fix CO2 into sugar via rubisco."},{"id":"biology-1a03-26","front":"What is a receptor tyrosine kinase?","back":"A membrane receptor that dimerizes when a signal binds, then phosphorylates tyrosines on itself, creating docking sites that start intracellular signalling cascades such as Ras/MAP kinase."},{"id":"biology-1a03-27","front":"What is a second messenger? Give an example.","back":"A small intracellular molecule that relays and amplifies a signal from a membrane receptor, e.g. cAMP made by adenylyl cyclase after G protein activation, or Ca2+."}],"quizzes":[],"seed":1,"look":{"color":"#16A34A","icon":"micro"}}'::jsonb);   -- https://academiccalendars.romcmaster.ca/preview_course_nopop.php?catoid=53&coid=265223
select pg_temp.sb_seed('seed:mcmaster-ca:chem-1a03', 'mcmaster.ca', 'CHEM 1A03', 'CHEM 1A03 Exam Review: Bonding, Molecular Structure, Intermolecular Forces and Phase Changes', '{"v":1,"app":"studyboard","type":"deck","name":"CHEM 1A03 Exam Review: Bonding, Molecular Structure, Intermolecular Forces and Phase Changes","course":{"code":"CHEM 1A03","name":"Introductory Chemistry I"},"cards":[{"id":"chem-1a03-1","front":"Mini-problem: how many moles are in 9.0 g of water (M = 18.0 g/mol)?","back":"n = m/M = 9.0 g / 18.0 g/mol = 0.50 mol."},{"id":"chem-1a03-2","front":"How do you find the limiting reagent?","back":"Convert each reactant to moles, divide by its stoichiometric coefficient, and the smallest result identifies the limiting reagent, which sets the maximum product."},{"id":"chem-1a03-3","front":"Define molarity and give a dilution formula.","back":"Molarity = moles of solute per litre of solution (mol/L). For dilution, C1V1 = C2V2."},{"id":"chem-1a03-4","front":"What is electronegativity and what is its periodic trend?","back":"The ability of an atom in a bond to attract shared electrons. It increases across a period and decreases down a group; fluorine is the most electronegative."},{"id":"chem-1a03-5","front":"Rank bond types by electronegativity difference.","back":"Roughly: below about 0.4 nonpolar covalent, about 0.4 to 1.8 polar covalent, and large differences (about 2 or more) mostly ionic. It is a continuum, not sharp cutoffs."},{"id":"chem-1a03-6","front":"What is lattice energy and what increases it?","back":"The energy released when gaseous ions form an ionic solid (or needed to separate it). It increases with higher ion charges and smaller ion sizes, e.g. MgO > NaCl."},{"id":"chem-1a03-7","front":"Exceptions to the octet rule","back":"Odd-electron species (NO), incomplete octets (BF3, boron with 6 electrons), and expanded octets for period 3 and below (SF6, PCl5)."},{"id":"chem-1a03-8","front":"Draw-in-words: the Lewis structure of CO2","back":"O=C=O: carbon double-bonded to each oxygen, each oxygen with two lone pairs, no lone pairs on carbon; linear, 180 degrees."},{"id":"chem-1a03-9","front":"VSEPR shape and bond angle of H2O","back":"4 electron domains (2 bonds, 2 lone pairs): tetrahedral electron geometry, bent molecular shape, angle about 104.5 degrees."},{"id":"chem-1a03-10","front":"Why does a lone pair compress bond angles?","back":"Lone pairs occupy more space near the central atom than bonding pairs, so they repel bonding pairs more strongly. Repulsion order: lone-lone > lone-bond > bond-bond."},{"id":"chem-1a03-11","front":"VSEPR: shape of PCl5 and of ClF3","back":"PCl5 (5 domains, no lone pairs) is trigonal bipyramidal. ClF3 (5 domains, 2 lone pairs in equatorial positions) is T-shaped."},{"id":"chem-1a03-12","front":"Hybridization of carbon in ethane, ethene and ethyne","back":"Ethane: sp3. Ethene: sp2 (one pi bond). Ethyne: sp (two pi bonds)."},{"id":"chem-1a03-13","front":"Bond length and bond energy vs bond order","back":"Higher bond order gives shorter and stronger bonds: C-C (longest, weakest) > C=C > C≡C (shortest, strongest)."},{"id":"chem-1a03-14","front":"Estimating delta H of reaction from bond enthalpies","back":"delta H is approximately the sum of bond energies broken minus the sum of bond energies formed. Breaking bonds costs energy; forming bonds releases energy."},{"id":"chem-1a03-15","front":"Name the intermolecular forces from usually weakest to strongest.","back":"London dispersion forces, dipole-dipole forces, hydrogen bonding (ion-dipole forces are stronger still, between ions and polar molecules)."},{"id":"chem-1a03-16","front":"What is required for hydrogen bonding?","back":"An H atom covalently bonded to N, O or F, attracted to a lone pair on another N, O or F atom."},{"id":"chem-1a03-17","front":"What determines the strength of London dispersion forces?","back":"Polarizability, which increases with the number of electrons (molar mass) and with more elongated shapes; e.g. n-pentane boils higher than neopentane."},{"id":"chem-1a03-18","front":"Why does water have an unusually high boiling point for its size?","back":"Each H2O molecule can form extensive hydrogen bonds with neighbours, which require more energy to overcome than dispersion forces in similar-sized molecules like H2S."},{"id":"chem-1a03-19","front":"Explain why ice floats.","back":"Hydrogen bonds lock ice into an open hexagonal lattice that is less dense than liquid water, where molecules pack more closely."},{"id":"chem-1a03-20","front":"Relationship between intermolecular forces and vapour pressure","back":"Stronger intermolecular forces mean fewer molecules escape to the gas phase, so vapour pressure is lower and the boiling point is higher."},{"id":"chem-1a03-21","front":"Define normal boiling point.","back":"The temperature at which a liquid''s vapour pressure equals 1 atm (101.325 kPa)."},{"id":"chem-1a03-22","front":"Heat for a temperature change vs a phase change","back":"Temperature change within one phase: q = m·c·delta T. Phase change at constant temperature: q = n·delta H (e.g. delta H_fus or delta H_vap)."},{"id":"chem-1a03-23","front":"Mini-problem: heat to warm 100 g of water from 20 C to 30 C (c = 4.18 J/g·C)?","back":"q = (100 g)(4.18 J/g·C)(10 C) = 4180 J = 4.18 kJ."},{"id":"chem-1a03-24","front":"On a heating curve, why is the temperature flat during melting?","back":"Added energy goes into overcoming intermolecular attractions (potential energy), not into raising kinetic energy, so temperature stays constant until the phase change is complete."},{"id":"chem-1a03-25","front":"What do the triple point and critical point on a phase diagram represent?","back":"Triple point: the T and P where solid, liquid and gas coexist. Critical point: beyond this T and P, liquid and gas become indistinguishable (supercritical fluid)."},{"id":"chem-1a03-26","front":"Why does the solid-liquid line on water''s phase diagram have a negative slope?","back":"Because ice is less dense than liquid water, increasing pressure favours the liquid, so the melting point decreases slightly as pressure rises."},{"id":"chem-1a03-27","front":"Clausius-Clapeyron equation (two-point form)","back":"ln(P2/P1) = -(delta H_vap/R)·(1/T2 - 1/T1), relating vapour pressure to temperature; T in kelvin and R = 8.314 J/(mol·K)."},{"id":"chem-1a03-28","front":"Is enthalpy of vaporization usually larger than enthalpy of fusion? Why?","back":"Yes. Vaporization must separate molecules almost completely, while melting only loosens the arrangement, so delta H_vap is much larger than delta H_fus."}],"quizzes":[],"seed":1,"look":{"color":"#EA580C","icon":"chem"}}'::jsonb);   -- https://academiccalendars.romcmaster.ca/preview_course_nopop.php?catoid=53&coid=265327
select pg_temp.sb_seed('seed:mcmaster-ca:econ-1b03', 'mcmaster.ca', 'ECON 1B03', 'ECON 1B03 Exam Review: Supply and Demand, Elasticity, Efficiency and Market Structures', '{"v":1,"app":"studyboard","type":"deck","name":"ECON 1B03 Exam Review: Supply and Demand, Elasticity, Efficiency and Market Structures","course":{"code":"ECON 1B03","name":"Introductory Microeconomics"},"cards":[{"id":"econ-1b03-1","front":"What is opportunity cost?","back":"The value of the next best alternative given up when making a choice. For example, the opportunity cost of attending class is what you would have earned working those hours."},{"id":"econ-1b03-2","front":"Absolute vs comparative advantage","back":"Absolute advantage: producing more output with the same resources. Comparative advantage: producing at a lower opportunity cost. Gains from trade come from comparative advantage."},{"id":"econ-1b03-3","front":"Mini-problem: A can make 10 shirts or 5 hats per hour; B can make 4 shirts or 4 hats. Who has the comparative advantage in hats?","back":"A''s cost of 1 hat = 2 shirts; B''s cost of 1 hat = 1 shirt. B has the lower opportunity cost, so B has the comparative advantage in hats and A in shirts."},{"id":"econ-1b03-4","front":"What does a bowed-out (concave) production possibilities frontier indicate?","back":"Increasing opportunity cost: resources are not equally suited to both goods, so producing more of one good requires giving up increasing amounts of the other."},{"id":"econ-1b03-5","front":"Change in quantity demanded vs change in demand","back":"A change in the good''s own price moves along the demand curve (change in quantity demanded). Changes in income, tastes, related prices, expectations or number of buyers shift the whole curve (change in demand)."},{"id":"econ-1b03-6","front":"Normal vs inferior goods","back":"Demand for a normal good rises when income rises; demand for an inferior good falls when income rises (e.g. instant noodles)."},{"id":"econ-1b03-7","front":"Substitutes vs complements","back":"Substitutes: a rise in the price of one increases demand for the other (coffee and tea). Complements: a rise in the price of one decreases demand for the other (printers and ink)."},{"id":"econ-1b03-8","front":"Effect on equilibrium: supply increases while demand is unchanged","back":"Equilibrium price falls and equilibrium quantity rises."},{"id":"econ-1b03-9","front":"If supply and demand both increase, what happens to price and quantity?","back":"Quantity definitely rises; the effect on price is ambiguous and depends on which shift is larger."},{"id":"econ-1b03-10","front":"Formula for price elasticity of demand (midpoint method)","back":"Ed = (% change in Qd)/(% change in P), where each % change = change/average of old and new values. Usually reported as an absolute value."},{"id":"econ-1b03-11","front":"Elastic vs inelastic demand and total revenue","back":"If |Ed| > 1 (elastic), a price cut raises total revenue. If |Ed| < 1 (inelastic), a price cut lowers total revenue. At |Ed| = 1, revenue is maximized."},{"id":"econ-1b03-12","front":"Determinants of price elasticity of demand","back":"More substitutes, a larger share of the budget, a longer time horizon and luxury status make demand more elastic; necessities with few substitutes are inelastic."},{"id":"econ-1b03-13","front":"What does a negative cross-price elasticity indicate?","back":"The goods are complements. A positive cross-price elasticity indicates substitutes."},{"id":"econ-1b03-14","front":"Consumer surplus and producer surplus","back":"Consumer surplus is willingness to pay minus price (area below demand, above price). Producer surplus is price minus marginal cost (area above supply, below price)."},{"id":"econ-1b03-15","front":"Effect of a binding price ceiling (e.g. rent control)","back":"Set below equilibrium, it creates a shortage (Qd > Qs), reduces quantity traded and causes deadweight loss, along with waiting lines or black markets."},{"id":"econ-1b03-16","front":"Effect of a binding price floor (e.g. a minimum wage above equilibrium)","back":"Set above equilibrium, it creates a surplus (Qs > Qd); in the labour market this surplus is unemployment."},{"id":"econ-1b03-17","front":"Who bears more of a tax burden?","back":"The side of the market that is more inelastic bears more of the tax, regardless of whether the tax is legally imposed on buyers or sellers."},{"id":"econ-1b03-18","front":"What is deadweight loss?","back":"The loss of total surplus from trades that would have been mutually beneficial but no longer occur, e.g. because of a tax, price control or monopoly."},{"id":"econ-1b03-19","front":"Negative externality and the efficient outcome","back":"When production imposes external costs (pollution), the market overproduces because marginal social cost exceeds marginal private cost. A Pigouvian tax equal to the external cost restores efficiency."},{"id":"econ-1b03-20","front":"Public good: two defining features","back":"Nonrival (one person''s use does not reduce another''s) and nonexcludable (people cannot easily be prevented from using it), which creates a free-rider problem."},{"id":"econ-1b03-21","front":"Accounting profit vs economic profit","back":"Accounting profit = revenue - explicit costs. Economic profit = revenue - explicit costs - implicit (opportunity) costs. Zero economic profit still means a normal return."},{"id":"econ-1b03-22","front":"What is the profit-maximizing rule for any firm?","back":"Produce where marginal revenue equals marginal cost (MR = MC)."},{"id":"econ-1b03-23","front":"When should a perfectly competitive firm shut down in the short run?","back":"When price is below minimum average variable cost (P < AVC), because revenue does not even cover variable costs."},{"id":"econ-1b03-24","front":"Long-run equilibrium in perfect competition","back":"Entry and exit drive economic profit to zero, so P = MC = minimum ATC; the market is both allocatively and productively efficient."},{"id":"econ-1b03-25","front":"Why is a monopolist''s marginal revenue below price?","back":"To sell an extra unit it must lower the price on all units sold (single-price monopoly), so MR < P and the MR curve lies below the demand curve."},{"id":"econ-1b03-26","front":"Monopoly outcome compared with perfect competition","back":"A monopoly produces less output at a higher price (where MR = MC and P > MC), creating deadweight loss."},{"id":"econ-1b03-27","front":"Prisoner''s dilemma in oligopoly","back":"Each firm has a dominant strategy to cheat (e.g. cut price), so both end up worse off than if they had cooperated; this explains why cartels tend to be unstable."}],"quizzes":[],"seed":1,"look":{"color":"#C79A12","icon":"econ"}}'::jsonb);   -- https://academiccalendars.romcmaster.ca/preview_course_nopop.php?catoid=58&coid=291530
select pg_temp.sb_seed('seed:uwo-ca:psychology-1002a-b', 'uwo.ca', 'Psychology 1002A/B', 'Psychology 1002 Exam Review: Biopsychology, Sensation and Perception, Learning and Cognition', '{"v":1,"app":"studyboard","type":"deck","name":"Psychology 1002 Exam Review: Biopsychology, Sensation and Perception, Learning and Cognition","course":{"code":"Psychology 1002A/B","name":"Psychology as a Natural Science"},"cards":[{"id":"psychology-1002a-b-1","front":"Structuralism vs functionalism","back":"Structuralism (Wundt, Titchener) used introspection to break consciousness into basic elements. Functionalism (James) studied the purpose of mental processes in helping organisms adapt."},{"id":"psychology-1002a-b-2","front":"What was behaviourism''s main claim about psychology?","back":"That psychology should study only observable behaviour and how the environment shapes it, not unobservable mental states (Watson, Skinner)."},{"id":"psychology-1002a-b-3","front":"Naturalistic observation: one strength and one weakness","back":"Strength: behaviour is seen in real settings, giving high external validity. Weakness: no control over variables, so causes cannot be identified, and observers may alter behaviour."},{"id":"psychology-1002a-b-4","front":"What is a placebo effect?","back":"An improvement caused by a person''s expectation of treatment rather than by the treatment itself, which is why control groups often receive an inert placebo."},{"id":"psychology-1002a-b-5","front":"Central vs peripheral nervous system","back":"The CNS is the brain and spinal cord. The PNS includes all nerves outside it, divided into the somatic (voluntary muscles, senses) and autonomic (internal organs) systems."},{"id":"psychology-1002a-b-6","front":"What is a resting potential and its approximate value?","back":"The voltage across a neuron''s membrane at rest, about -70 mV, maintained by unequal ion distribution and the sodium-potassium pump."},{"id":"psychology-1002a-b-7","front":"EPSP vs IPSP","back":"An excitatory postsynaptic potential depolarizes the membrane, making firing more likely; an inhibitory postsynaptic potential hyperpolarizes it, making firing less likely. The neuron sums them."},{"id":"psychology-1002a-b-8","front":"How is neurotransmitter action ended at the synapse?","back":"By reuptake into the presynaptic terminal, by enzymatic breakdown (e.g. acetylcholinesterase), or by diffusion away from the synapse."},{"id":"psychology-1002a-b-9","front":"Which neurotransmitter is the main inhibitory transmitter in the brain?","back":"GABA. Glutamate is the main excitatory neurotransmitter."},{"id":"psychology-1002a-b-10","front":"What do SSRIs do?","back":"Selective serotonin reuptake inhibitors block the reuptake of serotonin, leaving more of it in the synapse; they are used to treat depression."},{"id":"psychology-1002a-b-11","front":"Function of the cerebellum","back":"Coordinates movement, balance and timing, and supports motor learning."},{"id":"psychology-1002a-b-12","front":"Role of the hypothalamus","back":"Regulates hunger, thirst, body temperature and sexual behaviour, and controls the pituitary gland, linking the nervous and endocrine systems."},{"id":"psychology-1002a-b-13","front":"What did split-brain studies reveal?","back":"When the corpus callosum is cut, information shown only to the right hemisphere (left visual field) cannot be named aloud, because language is usually in the left hemisphere."},{"id":"psychology-1002a-b-14","front":"fMRI vs EEG","back":"fMRI measures blood-oxygen changes and gives good spatial resolution but poor timing. EEG measures electrical activity from the scalp and gives excellent timing but poor spatial resolution."},{"id":"psychology-1002a-b-15","front":"Monozygotic vs dizygotic twins in behavioural genetics","back":"MZ twins share about 100% of genes, DZ twins about 50%. If MZ twins are more similar on a trait than DZ twins, the trait has a genetic influence."},{"id":"psychology-1002a-b-16","front":"What does heritability mean, and what does it not mean?","back":"Heritability is the proportion of variation in a trait across a population that is due to genetic differences. It does not describe how much of one individual''s trait is caused by genes."},{"id":"psychology-1002a-b-17","front":"Absolute threshold","back":"The minimum stimulus intensity a person can detect 50% of the time."},{"id":"psychology-1002a-b-18","front":"What does signal detection theory add to threshold measurement?","back":"It separates sensitivity from response bias, classifying responses as hits, misses, false alarms and correct rejections, since detection also depends on expectations and motivation."},{"id":"psychology-1002a-b-19","front":"Trichromatic vs opponent-process theory of colour vision","back":"Trichromatic: three cone types (short, medium, long wavelengths) combine to code colour. Opponent-process: later neurons code red-green, blue-yellow and black-white pairs, explaining afterimages. Both are correct at different stages."},{"id":"psychology-1002a-b-20","front":"Place theory vs frequency theory of pitch","back":"Place theory: different pitches stimulate different places on the basilar membrane (best for high pitches). Frequency theory: neuron firing rate matches sound frequency (best for low pitches)."},{"id":"psychology-1002a-b-21","front":"Name three Gestalt grouping principles.","back":"Proximity (near items group together), similarity (alike items group), and closure (we fill in gaps to see whole figures); others include continuity and common fate."},{"id":"psychology-1002a-b-22","front":"Bottom-up vs top-down processing","back":"Bottom-up processing builds perception from sensory features. Top-down processing uses knowledge, expectations and context to interpret sensory input."},{"id":"psychology-1002a-b-23","front":"Binocular depth cues vs monocular depth cues","back":"Binocular cues need both eyes: retinal disparity and convergence. Monocular cues work with one eye: linear perspective, interposition, relative size, texture gradient."},{"id":"psychology-1002a-b-24","front":"Positive reinforcement vs negative punishment","back":"Positive reinforcement adds a pleasant stimulus to increase a behaviour (praise). Negative punishment removes a pleasant stimulus to decrease a behaviour (taking away a phone)."},{"id":"psychology-1002a-b-25","front":"What is learned helplessness (Seligman)?","back":"After repeated uncontrollable aversive events, animals or people stop trying to escape even when escape becomes possible; it has been linked to depression."},{"id":"psychology-1002a-b-26","front":"Drive-reduction theory of motivation","back":"Physiological needs create aversive drive states (e.g. hunger), and behaviour is motivated to reduce the drive and return the body to homeostasis."},{"id":"psychology-1002a-b-27","front":"Yerkes-Dodson law","back":"Performance increases with arousal up to a moderate level and then declines; the optimal arousal level is lower for complex tasks."},{"id":"psychology-1002a-b-28","front":"Algorithm vs heuristic","back":"An algorithm is a step-by-step procedure guaranteed to find a solution if followed. A heuristic is a mental shortcut that is faster but can lead to errors."},{"id":"psychology-1002a-b-29","front":"Retrograde vs anterograde amnesia","back":"Retrograde amnesia is loss of memories formed before an injury. Anterograde amnesia is inability to form new long-term memories after the injury."},{"id":"psychology-1002a-b-30","front":"What is the misinformation effect (Loftus)?","back":"Misleading information presented after an event can distort memory of it, e.g. using the word ''smashed'' led people to estimate higher speeds and falsely recall broken glass."}],"quizzes":[],"seed":1,"look":{"color":"#1D9BB8","icon":"psych"}}'::jsonb);   -- https://www.westerncalendar.uwo.ca/Courses.cfm?CourseAcadCalendarID=MAIN_029880_1&SelectedCalendar=Live
select pg_temp.sb_seed('seed:uwo-ca:biology-1001a', 'uwo.ca', 'Biology 1001A', 'Biology 1001A Exam Review: Inheritance, Evolution and Ecology', '{"v":1,"app":"studyboard","type":"deck","name":"Biology 1001A Exam Review: Inheritance, Evolution and Ecology","course":{"code":"Biology 1001A","name":"Biology for Science I"},"cards":[{"id":"biology-1001a-1","front":"Genotype vs phenotype","back":"Genotype is an organism''s genetic makeup (its alleles); phenotype is its observable traits, which result from the genotype interacting with the environment."},{"id":"biology-1001a-2","front":"State Mendel''s law of segregation.","back":"Each organism carries two alleles for a gene, and these separate during gamete formation so each gamete receives only one allele."},{"id":"biology-1001a-3","front":"State Mendel''s law of independent assortment and when it applies.","back":"Alleles of different genes assort independently into gametes. It holds for genes on different chromosomes or far apart on the same chromosome."},{"id":"biology-1001a-4","front":"Mini-problem: phenotypic ratio from a cross of Aa x Aa with complete dominance","back":"3 dominant : 1 recessive (genotypes 1 AA : 2 Aa : 1 aa)."},{"id":"biology-1001a-5","front":"Mini-problem: phenotypic ratio from a dihybrid cross AaBb x AaBb","back":"9 : 3 : 3 : 1, assuming complete dominance and independent assortment."},{"id":"biology-1001a-6","front":"What is a test cross?","back":"Crossing an individual with a dominant phenotype to a homozygous recessive individual. If any offspring show the recessive phenotype, the tested individual is heterozygous."},{"id":"biology-1001a-7","front":"Incomplete dominance vs codominance","back":"Incomplete dominance: heterozygote shows an intermediate phenotype (red x white snapdragons give pink). Codominance: both alleles fully expressed (AB blood type)."},{"id":"biology-1001a-8","front":"Why are X-linked recessive disorders more common in males?","back":"Males have one X chromosome (hemizygous), so a single recessive allele produces the phenotype, while females need two copies."},{"id":"biology-1001a-9","front":"How do crossing over and independent assortment create genetic variation in meiosis?","back":"Crossing over in prophase I exchanges segments between homologous chromosomes; independent assortment in metaphase I randomly orients homologous pairs, producing new allele combinations."},{"id":"biology-1001a-10","front":"What does a recombination frequency tell you about two genes?","back":"How far apart they are on a chromosome: higher frequency means farther apart. 1% recombination = 1 map unit (centimorgan); the maximum observed is 50% (unlinked)."},{"id":"biology-1001a-11","front":"What is nondisjunction?","back":"Failure of homologous chromosomes or sister chromatids to separate properly in meiosis, producing gametes with an abnormal chromosome number (e.g. trisomy 21)."},{"id":"biology-1001a-12","front":"Epistasis","back":"When one gene''s alleles mask or modify the expression of another gene, e.g. in Labrador coat colour, the E gene determines whether pigment from the B gene is deposited."},{"id":"biology-1001a-13","front":"Four conditions Darwin identified for natural selection","back":"Individuals vary in traits, some variation is heritable, more offspring are produced than can survive, and individuals with certain traits survive and reproduce more."},{"id":"biology-1001a-14","front":"What is evolutionary fitness?","back":"An individual''s relative reproductive success: the number of offspring it contributes to the next generation compared with others in the population."},{"id":"biology-1001a-15","front":"List the conditions for Hardy-Weinberg equilibrium.","back":"No mutation, no gene flow, very large population (no drift), random mating and no natural selection."},{"id":"biology-1001a-16","front":"Mini-problem: 16% of a population shows a recessive phenotype. Find p and q.","back":"q^2 = 0.16, so q = 0.4 and p = 1 - 0.4 = 0.6. Heterozygote frequency 2pq = 0.48."},{"id":"biology-1001a-17","front":"Genetic drift: bottleneck vs founder effect","back":"Both are random changes in allele frequency in small populations. A bottleneck follows a drastic population reduction; the founder effect occurs when a few individuals start a new population."},{"id":"biology-1001a-18","front":"Directional vs stabilizing vs disruptive selection","back":"Directional favours one extreme, stabilizing favours intermediate phenotypes, and disruptive favours both extremes over the middle."},{"id":"biology-1001a-19","front":"What is sexual selection?","back":"Selection for traits that improve mating success, through competition within a sex (intrasexual) or choice by the other sex (intersexual), e.g. a peacock''s tail."},{"id":"biology-1001a-20","front":"Biological species concept and one limitation","back":"A species is a group of populations that can interbreed and produce fertile offspring in nature. It cannot be applied to asexual organisms or fossils."},{"id":"biology-1001a-21","front":"Allopatric vs sympatric speciation","back":"Allopatric: a geographic barrier splits a population, which diverges. Sympatric: new species arise in the same area, e.g. by polyploidy in plants or habitat specialization."},{"id":"biology-1001a-22","front":"Prezygotic vs postzygotic reproductive barriers","back":"Prezygotic barriers prevent fertilization (habitat, temporal, behavioural, mechanical, gametic isolation). Postzygotic barriers act after (hybrid inviability, sterility, breakdown)."},{"id":"biology-1001a-23","front":"Homologous vs analogous structures","back":"Homologous structures share ancestry though function may differ (human arm, bat wing). Analogous structures have similar function from convergent evolution, not common ancestry (bird and insect wings)."},{"id":"biology-1001a-24","front":"Exponential vs logistic population growth","back":"Exponential: dN/dt = rN, unlimited J-shaped growth. Logistic: dN/dt = rN(K - N)/K, growth slows as N approaches carrying capacity K, giving an S-shaped curve."},{"id":"biology-1001a-25","front":"r-selected vs K-selected species","back":"r-selected: many small offspring, little parental care, rapid growth (insects, weeds). K-selected: few large offspring, high parental care, populations near carrying capacity (elephants)."},{"id":"biology-1001a-26","front":"Density-dependent vs density-independent factors","back":"Density-dependent factors (competition, disease, predation) have stronger effects as population density rises. Density-independent factors (weather, fire) act regardless of density."},{"id":"biology-1001a-27","front":"Competitive exclusion principle","back":"Two species competing for exactly the same limiting resources cannot coexist indefinitely; one will be excluded unless they partition resources (niche differentiation)."},{"id":"biology-1001a-28","front":"Mutualism vs commensalism vs parasitism","back":"Mutualism: both benefit (+/+). Commensalism: one benefits, the other unaffected (+/0). Parasitism: one benefits at the other''s expense (+/-)."},{"id":"biology-1001a-29","front":"What is a keystone species?","back":"A species with a disproportionately large effect on community structure relative to its abundance, e.g. sea otters controlling sea urchins and protecting kelp forests."},{"id":"biology-1001a-30","front":"Why is only about 10% of energy transferred between trophic levels?","back":"Most energy is lost as heat from metabolism, or is not eaten or not digested, so food chains are usually limited to a few levels."}],"quizzes":[],"seed":1,"look":{"color":"#65A30D","icon":"bio"}}'::jsonb);   -- https://www.westerncalendar.uwo.ca/Courses.cfm?CourseAcadCalendarID=MAIN_023016_1
select pg_temp.sb_seed('seed:uwo-ca:economics-1021a-b', 'uwo.ca', 'Economics 1021A/B', 'Economics 1021 Exam Review: Consumer Choice, Costs, Competition, Monopoly and Factor Markets', '{"v":1,"app":"studyboard","type":"deck","name":"Economics 1021 Exam Review: Consumer Choice, Costs, Competition, Monopoly and Factor Markets","course":{"code":"Economics 1021A/B","name":"Principles of Microeconomics"},"cards":[{"id":"economics-1021a-b-1","front":"What is the fundamental economic problem?","back":"Scarcity: wants exceed the limited resources available, so people and societies must make choices and face trade-offs."},{"id":"economics-1021a-b-2","front":"Positive vs normative statements","back":"Positive statements describe what is and can be tested (a minimum wage rise reduces teen employment). Normative statements are value judgments about what ought to be."},{"id":"economics-1021a-b-3","front":"What does a point inside the production possibilities frontier represent?","back":"An inefficient use of resources (unemployment or misallocation); more of one good could be produced without giving up any of the other."},{"id":"economics-1021a-b-4","front":"What does the law of demand state, and why does it hold?","back":"Other things equal, a higher price lowers quantity demanded. It holds because of the substitution effect and the income effect."},{"id":"economics-1021a-b-5","front":"What shifts the supply curve?","back":"Changes in input prices, technology, prices of related goods in production, expected future prices, number of sellers, and natural events. The good''s own price does not shift supply."},{"id":"economics-1021a-b-6","front":"Mini-problem: Qd = 100 - 2P and Qs = 20 + 2P. Find equilibrium.","back":"Set 100 - 2P = 20 + 2P, so 4P = 80 and P = 20. Q = 100 - 40 = 60."},{"id":"economics-1021a-b-7","front":"Income elasticity of demand: what do the signs mean?","back":"Positive means a normal good (above 1 is a luxury, between 0 and 1 a necessity). Negative means an inferior good."},{"id":"economics-1021a-b-8","front":"Price elasticity of supply and its main determinant","back":"Es = % change in Qs / % change in P. Supply is more elastic with more time to adjust and when inputs can easily be shifted into production."},{"id":"economics-1021a-b-9","front":"Write the budget constraint and give its slope.","back":"Px·X + Py·Y = Income. With X on the horizontal axis the slope is -Px/Py, the market rate at which Y trades for X."},{"id":"economics-1021a-b-10","front":"What does an indifference curve show, and why does it slope downward?","back":"All bundles giving the consumer the same utility. It slopes down because to stay equally well off, getting more of one good requires giving up some of the other."},{"id":"economics-1021a-b-11","front":"Marginal rate of substitution (MRS)","back":"The rate at which a consumer is willing to give up Y for one more X while keeping utility constant; it equals the absolute slope of the indifference curve and usually diminishes."},{"id":"economics-1021a-b-12","front":"Condition for the consumer''s best affordable bundle","back":"The indifference curve is tangent to the budget line: MRS = Px/Py, or equivalently MUx/Px = MUy/Py (equal marginal utility per dollar)."},{"id":"economics-1021a-b-13","front":"Substitution effect vs income effect of a price fall","back":"Substitution effect: the good is relatively cheaper, so buy more of it. Income effect: real income rises, so buy more if the good is normal, less if it is inferior."},{"id":"economics-1021a-b-14","front":"What is the law of diminishing marginal returns?","back":"In the short run, adding more of a variable input (labour) to a fixed input (capital) eventually causes the marginal product of each extra unit to fall."},{"id":"economics-1021a-b-15","front":"How are AFC, AVC, ATC and MC defined?","back":"AFC = TFC/Q, AVC = TVC/Q, ATC = TC/Q = AFC + AVC, MC = change in TC / change in Q."},{"id":"economics-1021a-b-16","front":"Why does the MC curve cross ATC and AVC at their minimum points?","back":"When marginal cost is below an average, it pulls the average down; when above, it pulls it up. So MC intersects each average curve at its lowest point."},{"id":"economics-1021a-b-17","front":"Economies of scale vs diseconomies of scale","back":"Economies of scale: long-run average cost falls as output rises (specialization). Diseconomies of scale: LRAC rises at large output (management and coordination problems)."},{"id":"economics-1021a-b-18","front":"Short run vs long run in production","back":"In the short run at least one input (usually plant size) is fixed. In the long run all inputs are variable, including the number of firms."},{"id":"economics-1021a-b-19","front":"Four characteristics of perfect competition","back":"Many firms and buyers, identical products, no barriers to entry or exit, and full information; each firm is a price taker with horizontal demand at the market price."},{"id":"economics-1021a-b-20","front":"Which part of the cost curve is a competitive firm''s short-run supply curve?","back":"The portion of the marginal cost curve above the minimum of average variable cost."},{"id":"economics-1021a-b-21","front":"Mini-problem: a competitive firm sells at P = $10 where MC = $10, ATC = $8, and Q = 50. Find profit.","back":"Profit = (P - ATC) x Q = (10 - 8) x 50 = $100 in economic profit, which will attract entry in the long run."},{"id":"economics-1021a-b-22","front":"Sources of monopoly power (barriers to entry)","back":"Natural barriers (economies of scale making a natural monopoly, control of a key resource), legal barriers (patents, copyrights, licences, public franchises)."},{"id":"economics-1021a-b-23","front":"What is price discrimination, and what conditions are needed?","back":"Charging different customers different prices for the same good, not based on cost differences. The firm needs market power, the ability to identify groups with different willingness to pay, and to prevent resale."},{"id":"economics-1021a-b-24","front":"Monopolistic competition in the long run","back":"Free entry drives economic profit to zero, but because demand slopes down, firms produce where P = ATC above minimum ATC, so there is excess capacity and a markup over MC."},{"id":"economics-1021a-b-25","front":"How does a competitive firm decide how much labour to hire?","back":"Hire until the value of the marginal product of labour (P x MPL) equals the wage rate."},{"id":"economics-1021a-b-26","front":"Why might income be unequally distributed in a market economy?","back":"Differences in skills and human capital, wealth and inherited assets, compensating wage differentials, discrimination and market power."},{"id":"economics-1021a-b-27","front":"What does the Lorenz curve show?","back":"The cumulative share of income received by cumulative shares of households. The further it bows from the 45-degree line of perfect equality, the greater the inequality (the Gini coefficient measures this gap)."}],"quizzes":[],"seed":1,"look":{"color":"#0D9488","icon":"econ"}}'::jsonb);   -- https://westerncalendar.uwo.ca/Courses.cfm?ArchiveID=&CourseAcadCalendarID=HURON_022072_5&SelectedCalendar=Live
select pg_temp.sb_seed('seed:uwo-ca:calculus-1000a-b', 'uwo.ca', 'Calculus 1000A/B', 'Calculus 1000 Exam Review: Derivatives, L''Hospital''s Rule, Definite Integrals and Applications', '{"v":1,"app":"studyboard","type":"deck","name":"Calculus 1000 Exam Review: Derivatives, L''Hospital''s Rule, Definite Integrals and Applications","course":{"code":"Calculus 1000A/B","name":"Calculus I"},"cards":[{"id":"calculus-1000a-b-1","front":"Evaluate lim (x -> infinity) (3x^2 + 1)/(5x^2 - x).","back":"Divide by x^2: (3 + 1/x^2)/(5 - 1/x) -> 3/5."},{"id":"calculus-1000a-b-2","front":"Evaluate lim (x -> 0) (e^x - 1)/x.","back":"1. It is 0/0, and L''Hospital''s Rule gives lim e^x/1 = 1."},{"id":"calculus-1000a-b-3","front":"Derivative of ln(x^2 + 1)","back":"2x/(x^2 + 1), by the chain rule."},{"id":"calculus-1000a-b-4","front":"Derivative of e^(3x) · x^2","back":"Product rule: 3e^(3x)·x^2 + 2x·e^(3x) = x·e^(3x)(3x + 2)."},{"id":"calculus-1000a-b-5","front":"Derivative of log base b of x","back":"1/(x ln b)."},{"id":"calculus-1000a-b-6","front":"Derivatives of sin x, cos x and sec x","back":"d/dx sin x = cos x; d/dx cos x = -sin x; d/dx sec x = sec x tan x."},{"id":"calculus-1000a-b-7","front":"Derivative of arccos x","back":"-1/sqrt(1 - x^2), for -1 < x < 1."},{"id":"calculus-1000a-b-8","front":"What are the domain and range of arcsin x and arctan x?","back":"arcsin: domain [-1, 1], range [-pi/2, pi/2]. arctan: domain all reals, range (-pi/2, pi/2)."},{"id":"calculus-1000a-b-9","front":"Evaluate arcsin(1/2) and arctan(1).","back":"arcsin(1/2) = pi/6; arctan(1) = pi/4."},{"id":"calculus-1000a-b-10","front":"Mini-problem: differentiate y = arctan(2x).","back":"y'' = 2/(1 + 4x^2)."},{"id":"calculus-1000a-b-11","front":"Which indeterminate forms can L''Hospital''s Rule be applied to directly?","back":"Only 0/0 and infinity/infinity. Other forms (0·infinity, infinity - infinity, 1^infinity, 0^0, infinity^0) must first be rewritten as a quotient."},{"id":"calculus-1000a-b-12","front":"How do you evaluate a 1^infinity limit like lim (x -> infinity) (1 + 1/x)^x?","back":"Let y = (1 + 1/x)^x, so ln y = x ln(1 + 1/x) = ln(1 + 1/x)/(1/x), a 0/0 form that tends to 1. So y -> e^1 = e."},{"id":"calculus-1000a-b-13","front":"Evaluate lim (x -> 0+) x ln x.","back":"Rewrite as ln x/(1/x) (infinity/infinity form). L''Hospital: (1/x)/(-1/x^2) = -x -> 0."},{"id":"calculus-1000a-b-14","front":"Common L''Hospital pitfall","back":"Applying it when the limit is not indeterminate, or using the quotient rule on f/g instead of differentiating numerator and denominator separately."},{"id":"calculus-1000a-b-15","front":"Riemann sum definition of the definite integral","back":"Integral from a to b of f(x) dx = lim (n -> infinity) of sum from i = 1 to n of f(x_i*)·delta x, where delta x = (b - a)/n."},{"id":"calculus-1000a-b-16","front":"Fundamental Theorem of Calculus, Part 1","back":"If F(x) = integral from a to x of f(t) dt with f continuous, then F''(x) = f(x)."},{"id":"calculus-1000a-b-17","front":"Mini-problem: find d/dx of the integral from 0 to x^2 of cos(t) dt.","back":"By FTC Part 1 and the chain rule: cos(x^2)·2x."},{"id":"calculus-1000a-b-18","front":"Fundamental Theorem of Calculus, Part 2","back":"If F is any antiderivative of a continuous f on [a, b], then the integral from a to b of f(x) dx = F(b) - F(a)."},{"id":"calculus-1000a-b-19","front":"Evaluate the integral from 0 to pi of sin x dx.","back":"[-cos x] from 0 to pi = -cos(pi) + cos(0) = 1 + 1 = 2."},{"id":"calculus-1000a-b-20","front":"Basic antiderivatives: x^n, 1/x, e^x","back":"x^(n+1)/(n+1) + C for n not equal to -1; ln|x| + C; e^x + C."},{"id":"calculus-1000a-b-21","front":"Antiderivatives of 1/(1 + x^2) and 1/sqrt(1 - x^2)","back":"arctan x + C and arcsin x + C."},{"id":"calculus-1000a-b-22","front":"How does u-substitution work? Integrate 2x·cos(x^2) dx.","back":"Let u = x^2, du = 2x dx, so the integral becomes integral of cos u du = sin u + C = sin(x^2) + C."},{"id":"calculus-1000a-b-23","front":"When changing variables in a definite integral, what must you do with the limits?","back":"Either convert the limits to u-values (u(a) and u(b)) or substitute back to x before evaluating with the original limits. Do not mix the two."},{"id":"calculus-1000a-b-24","front":"Area between two curves","back":"Area = integral from a to b of [top function - bottom function] dx, where a and b are often the intersection points; split the integral if the curves cross."},{"id":"calculus-1000a-b-25","front":"Mini-problem: area between y = x and y = x^2 on [0, 1]","back":"Integral from 0 to 1 of (x - x^2) dx = 1/2 - 1/3 = 1/6."},{"id":"calculus-1000a-b-26","front":"Disk method formula for volume of revolution about the x-axis","back":"V = pi · integral from a to b of [f(x)]^2 dx."},{"id":"calculus-1000a-b-27","front":"Washer method formula","back":"V = pi · integral from a to b of ([R(x)]^2 - [r(x)]^2) dx, where R is the outer radius and r the inner radius."},{"id":"calculus-1000a-b-28","front":"Mini-problem: volume when y = sqrt(x) on [0, 4] is rotated about the x-axis","back":"V = pi · integral from 0 to 4 of x dx = pi · (16/2) = 8·pi."},{"id":"calculus-1000a-b-29","front":"Does the integral of f from a to b always equal area?","back":"No. It gives net signed area: regions below the x-axis count as negative. Use |f(x)| to get total area."}],"quizzes":[],"seed":1,"look":{"color":"#3B6FE0","icon":"calc"}}'::jsonb);   -- https://www.westerncalendar.uwo.ca/Courses.cfm?CourseAcadCalendarID=MAIN_013890_1
select pg_temp.sb_seed('seed:ualberta-ca:biol-107', 'ualberta.ca', 'BIOL 107', 'BIOL 107 Midterm and Final Review: Cell Structure, Metabolism and Gene Expression', '{"v":1,"app":"studyboard","type":"deck","name":"BIOL 107 Midterm and Final Review: Cell Structure, Metabolism and Gene Expression","course":{"code":"BIOL 107","name":"Introduction to Cell Biology"},"cards":[{"id":"biol-107-1","front":"Prokaryotic vs eukaryotic cells: what is the key structural difference?","back":"Prokaryotes (bacteria and archaea) have no nucleus or membrane-bound organelles; their DNA sits in a nucleoid region and they have 70S ribosomes. Eukaryotes have a nucleus, an endomembrane system, mitochondria and 80S cytosolic ribosomes."},{"id":"biol-107-2","front":"Name the four major classes of biological macromolecules and their building blocks.","back":"Proteins (amino acids), nucleic acids (nucleotides), carbohydrates (monosaccharides) and lipids. Lipids are not true polymers; a triglyceride is glycerol plus three fatty acids."},{"id":"biol-107-3","front":"Dehydration synthesis vs hydrolysis","back":"Dehydration synthesis joins monomers by removing a water molecule to form a covalent bond. Hydrolysis breaks that bond by adding water. Polymers are built by dehydration and digested by hydrolysis."},{"id":"biol-107-4","front":"What are the four levels of protein structure?","back":"Primary: amino acid sequence. Secondary: alpha helices and beta sheets held by backbone hydrogen bonds. Tertiary: overall 3D fold from R-group interactions. Quaternary: assembly of two or more polypeptide subunits."},{"id":"biol-107-5","front":"What determines whether an amino acid is nonpolar, polar, acidic or basic?","back":"Its R group (side chain). The amino and carboxyl groups are common to all amino acids, so only the side chain changes the chemical properties."},{"id":"biol-107-6","front":"Saturated vs unsaturated fatty acids","back":"Saturated fatty acids have no C=C double bonds, pack tightly and are solid at room temperature. Unsaturated fatty acids have one or more cis double bonds that kink the chain, so they pack loosely and tend to be liquid."},{"id":"biol-107-7","front":"Why do phospholipids spontaneously form a bilayer in water?","back":"They are amphipathic: a hydrophilic phosphate head and two hydrophobic fatty acid tails. In water the tails cluster away from water and the heads face the aqueous surroundings on both sides."},{"id":"biol-107-8","front":"What does the fluid mosaic model describe?","back":"A membrane is a fluid phospholipid bilayer in which proteins, cholesterol and glycolipids are embedded or attached and can move laterally, forming a mosaic of components."},{"id":"biol-107-9","front":"What factors increase membrane fluidity?","back":"Higher temperature and more unsaturated (kinked) or shorter fatty acid tails. Cholesterol acts as a buffer: it reduces fluidity at warm temperatures and prevents tight packing at cold temperatures."},{"id":"biol-107-10","front":"Simple diffusion vs facilitated diffusion vs active transport","back":"Simple diffusion: small nonpolar molecules cross the bilayer down their gradient. Facilitated diffusion: channel or carrier proteins move solutes down their gradient with no energy input. Active transport: pumps move solutes against their gradient using energy such as ATP."},{"id":"biol-107-11","front":"An animal cell is placed in a hypertonic solution. What happens?","back":"Water leaves the cell by osmosis toward the higher solute concentration, so the cell shrinks (crenates). In a hypotonic solution an animal cell swells and may lyse, while a plant cell becomes turgid."},{"id":"biol-107-12","front":"What evidence supports the endosymbiotic origin of mitochondria and chloroplasts?","back":"They have double membranes, their own circular DNA, 70S bacteria-like ribosomes, divide by binary fission, and their genes are most similar to those of bacteria."},{"id":"biol-107-13","front":"Rough ER vs smooth ER","back":"Rough ER is studded with ribosomes and makes secreted and membrane proteins. Smooth ER lacks ribosomes and synthesizes lipids, detoxifies drugs, and stores calcium ions."},{"id":"biol-107-14","front":"What is the function of the Golgi apparatus?","back":"It receives proteins and lipids from the ER, modifies them (for example by adding or trimming carbohydrates), sorts them and packages them in vesicles for delivery to the plasma membrane, lysosomes or secretion."},{"id":"biol-107-15","front":"What do lysosomes do?","back":"They are acidic, membrane-bound compartments containing hydrolytic enzymes that digest macromolecules, worn-out organelles (autophagy) and material taken in by phagocytosis."},{"id":"biol-107-16","front":"What does a negative delta G tell you about a reaction?","back":"The reaction is exergonic and spontaneous: it releases free energy. It says nothing about speed; a spontaneous reaction can still be very slow without a catalyst."},{"id":"biol-107-17","front":"How do enzymes speed up reactions?","back":"They lower the activation energy by stabilizing the transition state. They do not change delta G or the equilibrium position, and they are not consumed by the reaction."},{"id":"biol-107-18","front":"Competitive vs noncompetitive inhibition","back":"A competitive inhibitor binds the active site and can be outcompeted by adding more substrate. A noncompetitive inhibitor binds elsewhere on the enzyme and changes its shape, lowering activity no matter how much substrate is present."},{"id":"biol-107-19","front":"How do cells use ATP to drive endergonic reactions?","back":"Through energy coupling: the exergonic hydrolysis of ATP is linked to the endergonic reaction, often by transferring a phosphate group to a reactant (phosphorylation) so the overall delta G is negative."},{"id":"biol-107-20","front":"Glycolysis: location, input and net output","back":"It takes place in the cytosol. One glucose is split into 2 pyruvate, with a net gain of 2 ATP and 2 NADH. It does not need oxygen."},{"id":"biol-107-21","front":"Pyruvate oxidation and the citric acid cycle: where do they occur and what do they make per glucose?","back":"Both occur in the mitochondrial matrix. Per glucose they make 2 acetyl CoA, 8 NADH, 2 FADH2, 2 ATP (or GTP) and 6 CO2 in total."},{"id":"biol-107-22","front":"How does chemiosmosis produce ATP?","back":"The electron transport chain in the inner mitochondrial membrane pumps H+ into the intermembrane space. The H+ flow back into the matrix through ATP synthase, which uses that energy to make ATP. O2 is the final electron acceptor and forms water."},{"id":"biol-107-23","front":"Why do cells carry out fermentation when oxygen is absent?","back":"To regenerate NAD+ from NADH so glycolysis can continue making ATP. Pyruvate is reduced to lactate (in animals) or to ethanol and CO2 (in yeast)."},{"id":"biol-107-24","front":"Light reactions vs Calvin cycle","back":"The light reactions occur in the thylakoid membranes: they split water, release O2 and make ATP and NADPH. The Calvin cycle occurs in the stroma and uses that ATP and NADPH to fix CO2 into sugar (G3P)."},{"id":"biol-107-25","front":"What does rubisco do?","back":"Rubisco is the Calvin cycle enzyme that fixes CO2 by attaching it to ribulose bisphosphate (RuBP). It is thought to be the most abundant protein on Earth."},{"id":"biol-107-26","front":"What are the phases of the eukaryotic cell cycle, and when is DNA replicated?","back":"Interphase (G1, S, G2) followed by M phase (mitosis and cytokinesis). DNA is replicated during S phase."},{"id":"biol-107-27","front":"Mitosis vs meiosis","back":"Mitosis: one division that produces 2 genetically identical diploid cells, used for growth and repair. Meiosis: two divisions that produce 4 genetically different haploid gametes."},{"id":"biol-107-28","front":"What two events in meiosis generate genetic variation?","back":"Crossing over between homologous chromosomes in prophase I, and independent assortment of homologous pairs at metaphase I. Random fertilization adds further variation."},{"id":"biol-107-29","front":"What did the Meselson-Stahl experiment show?","back":"That DNA replication is semiconservative: each new double helix has one parental strand and one new strand. They showed this by growing bacteria in heavy 15N and then light 14N medium and separating the DNA by density."},{"id":"biol-107-30","front":"Leading vs lagging strand","back":"DNA polymerase adds nucleotides only in the 5'' to 3'' direction. The leading strand is made continuously toward the fork; the lagging strand is made discontinuously as Okazaki fragments that are later joined."},{"id":"biol-107-31","front":"State the roles of helicase, primase, DNA ligase and topoisomerase.","back":"Helicase unwinds the double helix. Primase lays down RNA primers. DNA ligase seals the nicks between Okazaki fragments. Topoisomerase relieves the supercoiling that builds up ahead of the fork."},{"id":"biol-107-32","front":"How does transcription differ from DNA replication in its requirements?","back":"RNA polymerase does not need a primer. It reads the template strand 3'' to 5'', makes RNA 5'' to 3'' using U instead of T, and copies only one gene or region, not the whole genome."},{"id":"biol-107-33","front":"Name three ways eukaryotic pre-mRNA is processed before it leaves the nucleus.","back":"A 5'' methylguanosine cap is added, a 3'' poly-A tail is added, and introns are removed by splicing so that the exons are joined together."},{"id":"biol-107-34","front":"In translation, what happens at the A, P and E sites of the ribosome?","back":"The A site accepts the incoming aminoacyl-tRNA, the P site holds the tRNA carrying the growing polypeptide, and the E site is where the empty tRNA exits."},{"id":"biol-107-35","front":"A template DNA strand reads 3''-TACGGA-5''. Give the mRNA and the amino acids it encodes.","back":"The mRNA is 5''-AUGCCU-3'', which encodes Met-Pro. AUG is also the start codon."}],"quizzes":[],"seed":1,"look":{"color":"#1E9E74","icon":"bio"}}'::jsonb);   -- https://apps.ualberta.ca/catalogue/course/biol/107
select pg_temp.sb_seed('seed:ualberta-ca:chem-101', 'ualberta.ca', 'CHEM 101', 'CHEM 101 Exam Review: Atomic Structure, Bonding, Gases and States of Matter', '{"v":1,"app":"studyboard","type":"deck","name":"CHEM 101 Exam Review: Atomic Structure, Bonding, Gases and States of Matter","course":{"code":"CHEM 101","name":"Introductory University Chemistry I"},"cards":[{"id":"chem-101-1","front":"Photon energy formula and what each symbol means","back":"E = h·v = h·c/λ. E is the photon energy in J, h is Planck''s constant (6.626 x 10^-34 J·s), v is the frequency in s^-1, c is the speed of light (3.00 x 10^8 m/s) and λ is the wavelength in m."},{"id":"chem-101-2","front":"What key observation of the photoelectric effect supports the particle nature of light?","back":"Electrons are ejected only when the light''s frequency is above a threshold, no matter how intense it is. Raising the intensity raises the number of electrons, not their kinetic energy."},{"id":"chem-101-3","front":"de Broglie wavelength formula","back":"λ = h/(m·v), where m is the mass in kg and v is the velocity in m/s. It is only significant for very small particles such as electrons."},{"id":"chem-101-4","front":"Energy levels of the hydrogen atom in the Bohr model","back":"E_n = -2.18 x 10^-18 J (1/n^2). When an electron drops from a higher n to a lower n, a photon is emitted whose energy equals the difference between the two levels."},{"id":"chem-101-5","front":"List the four quantum numbers and their allowed values.","back":"n = 1, 2, 3... (shell and size); l = 0 to n-1 (subshell shape: s, p, d, f); ml = -l to +l (orbital orientation); ms = +1/2 or -1/2 (electron spin)."},{"id":"chem-101-6","front":"How many orbitals and how many electrons can the n = 3 shell hold?","back":"It has n^2 = 9 orbitals (one 3s, three 3p and five 3d), so it can hold 2n^2 = 18 electrons."},{"id":"chem-101-7","front":"Aufbau principle, Pauli exclusion principle and Hund''s rule","back":"Aufbau: fill the lowest-energy orbitals first. Pauli: no two electrons in an atom share all four quantum numbers, so each orbital holds at most 2 electrons of opposite spin. Hund: in degenerate orbitals, electrons occupy separate orbitals with parallel spins before pairing."},{"id":"chem-101-8","front":"Write the electron configurations of Fe and Fe3+.","back":"Fe: [Ar] 4s2 3d6. Fe3+: [Ar] 3d5. Transition metals lose their 4s electrons before their 3d electrons."},{"id":"chem-101-9","front":"Which two common first-row transition metals have exceptional electron configurations?","back":"Cr is [Ar] 4s1 3d5 and Cu is [Ar] 4s1 3d10. A half-filled or filled d subshell gives them extra stability."},{"id":"chem-101-10","front":"What is effective nuclear charge, and how does it change across a period?","back":"Zeff = Z - S: the nuclear charge an electron actually feels after shielding by inner electrons. It increases across a period because protons are added while shielding by same-shell electrons is weak."},{"id":"chem-101-11","front":"Periodic trend in atomic radius","back":"Radius decreases from left to right across a period (higher Zeff pulls the electrons in) and increases going down a group (electrons occupy higher shells)."},{"id":"chem-101-12","front":"Periodic trend in first ionization energy, and the main exceptions","back":"It generally increases across a period and decreases down a group. Exceptions: group 13 is lower than group 2 (for example B < Be, because a p electron is removed) and group 16 is lower than group 15 (O < N, because of pairing repulsion)."},{"id":"chem-101-13","front":"Rank O2-, F-, Na+ and Mg2+ by size.","back":"O2- > F- > Na+ > Mg2+. They are isoelectronic (10 electrons each), so the ion with the most protons pulls the electrons in most tightly and is smallest."},{"id":"chem-101-14","front":"How does electronegativity difference predict bond type?","back":"Little or no difference (under about 0.4) gives a nonpolar covalent bond. A moderate difference gives a polar covalent bond. A large difference (roughly above 1.7 to 2) gives a mostly ionic bond. The cutoffs are approximate."},{"id":"chem-101-15","front":"Formal charge formula","back":"Formal charge = (valence electrons) - (nonbonding electrons) - (1/2)(bonding electrons). The best Lewis structure keeps formal charges near zero, with any negative charge on the more electronegative atom."},{"id":"chem-101-16","front":"What are resonance structures?","back":"Two or more valid Lewis structures that differ only in where the electrons are placed. The real molecule is a hybrid of them; for example, both O-O bonds in ozone are identical, with a bond order of 1.5."},{"id":"chem-101-17","front":"Which atoms can have an expanded octet?","back":"Atoms from period 3 and below, such as P, S, Cl and Xe, which can hold more than 8 valence electrons (for example PCl5, SF6 and XeF4). Period 2 atoms such as C, N and O cannot."},{"id":"chem-101-18","front":"VSEPR: geometry of a molecule with 4 electron domains, 2 of them lone pairs (for example H2O)","back":"The electron-domain geometry is tetrahedral and the molecular shape is bent. The angle is about 104.5°, smaller than 109.5° because lone pairs repel more strongly."},{"id":"chem-101-19","front":"What is the molecular shape of SF4?","back":"Seesaw. S has 5 electron domains (trigonal bipyramidal) with one lone pair, which sits in an equatorial position."},{"id":"chem-101-20","front":"What is the molecular shape of XeF4?","back":"Square planar. Xe has 6 electron domains (octahedral) with two lone pairs placed opposite each other."},{"id":"chem-101-21","front":"Why is CO2 nonpolar even though its C=O bonds are polar?","back":"It is linear, so the two equal bond dipoles point in opposite directions and cancel, giving no net dipole moment."},{"id":"chem-101-22","front":"How do you match hybridization to electron domains, and what are sigma and pi bonds?","back":"2 domains: sp; 3: sp2; 4: sp3. A single bond is one sigma bond. A double bond is one sigma and one pi bond. A triple bond is one sigma and two pi bonds."},{"id":"chem-101-23","front":"Molecular orbital bond order, and why O2 is paramagnetic","back":"Bond order = (bonding electrons - antibonding electrons)/2. O2 has a bond order of 2 and two unpaired electrons in degenerate pi* orbitals, so it is attracted to a magnetic field."},{"id":"chem-101-24","front":"Ideal gas law and the units to use","back":"PV = nRT. Use R = 0.08206 L·atm/(mol·K) with P in atm and V in L, or R = 8.314 J/(mol·K) with SI units. T must always be in kelvin."},{"id":"chem-101-25","front":"What is the pressure of 2.00 mol of an ideal gas at 300 K in a 10.0 L container?","back":"P = nRT/V = (2.00)(0.08206)(300)/10.0 = 4.92 atm."},{"id":"chem-101-26","front":"Dalton''s law of partial pressures","back":"P_total = P1 + P2 + ... The partial pressure of each gas equals its mole fraction times the total pressure: P_i = x_i · P_total."},{"id":"chem-101-27","front":"Kinetic molecular theory: what does temperature tell you about gas particles?","back":"Average kinetic energy is proportional to absolute temperature. Root-mean-square speed is u_rms = sqrt(3RT/M), where R = 8.314 J/(mol·K) and M is the molar mass in kg/mol, so lighter gases move faster."},{"id":"chem-101-28","front":"Graham''s law of effusion","back":"rate1/rate2 = sqrt(M2/M1). For example, H2 (2 g/mol) effuses about 4 times faster than O2 (32 g/mol), because sqrt(32/2) = 4."},{"id":"chem-101-29","front":"When do real gases deviate most from ideal behaviour, and what do the van der Waals constants represent?","back":"At high pressure and low temperature. The constant a corrects for attractions between molecules (which lower the pressure) and b corrects for the volume the molecules themselves occupy."},{"id":"chem-101-30","front":"Name the main intermolecular forces from generally weakest to strongest.","back":"London dispersion forces (present in all molecules), dipole-dipole forces (polar molecules) and hydrogen bonding (H bonded to N, O or F interacting with a lone pair on N, O or F). Ion-dipole forces are stronger still."},{"id":"chem-101-31","front":"Why do boiling points increase going down the noble gases from He to Xe?","back":"Larger atoms have bigger, more polarizable electron clouds, so London dispersion forces get stronger and more energy is needed to separate the atoms."},{"id":"chem-101-32","front":"Phase diagram: what are the triple point and the critical point?","back":"At the triple point, solid, liquid and gas coexist in equilibrium. Above the critical temperature and pressure, liquid and gas can no longer be told apart and the substance is a supercritical fluid."},{"id":"chem-101-33","front":"When does a liquid boil?","back":"When its vapour pressure equals the external pressure. That is why water boils below 100 °C at high altitude, where the air pressure is lower."},{"id":"chem-101-34","front":"Four types of solids and an example of each","back":"Ionic (NaCl: brittle, high melting point), molecular (ice, dry ice: low melting point), covalent network (diamond, quartz: very hard, very high melting point) and metallic (Cu: conductive, malleable)."},{"id":"chem-101-35","front":"Why are alkali metals so reactive?","back":"They have a single ns1 valence electron and a very low first ionization energy, so they readily form +1 ions. They react with water to form a hydroxide and H2 gas, and reactivity increases down the group."}],"quizzes":[],"seed":1,"look":{"color":"#E0673B","icon":"chem"}}'::jsonb);   -- https://apps.ualberta.ca/catalogue/course/chem/101
select pg_temp.sb_seed('seed:ualberta-ca:psych-104', 'ualberta.ca', 'PSYCH 104', 'PSYCH 104 Exam Review: Research Methods, Brain, Sensation, Learning and Memory', '{"v":1,"app":"studyboard","type":"deck","name":"PSYCH 104 Exam Review: Research Methods, Brain, Sensation, Learning and Memory","course":{"code":"PSYCH 104","name":"Basic Psychological Processes"},"cards":[{"id":"psych-104-1","front":"Independent variable vs dependent variable","back":"The independent variable is what the researcher manipulates (for example, hours of sleep). The dependent variable is the outcome that is measured (for example, test score)."},{"id":"psych-104-2","front":"Why doesn''t correlation prove causation?","back":"A third variable could cause both (the third-variable problem), and the direction of the effect may be unclear (the directionality problem). Only a true experiment with random assignment supports a causal claim."},{"id":"psych-104-3","front":"What does a correlation coefficient (r) tell you?","back":"r runs from -1 to +1. The sign gives the direction (positive or negative) and the absolute value gives the strength; r = 0 means no linear relationship. For example, r = -0.8 is stronger than r = +0.3."},{"id":"psych-104-4","front":"Random sampling vs random assignment","back":"Random sampling picks participants from a population so that results generalize (external validity). Random assignment places participants into conditions by chance so that groups are equivalent and causal conclusions are valid (internal validity)."},{"id":"psych-104-5","front":"What is an operational definition?","back":"A precise statement of how a variable will be measured or manipulated in a study, for example defining aggression as the number of times a child hits a doll in 10 minutes."},{"id":"psych-104-6","front":"What is a double-blind study for?","back":"Neither participants nor the researchers who interact with them know who is in which condition. This controls for placebo effects and for experimenter expectancy bias."},{"id":"psych-104-7","front":"Name the main parts of a neuron and what each does.","back":"Dendrites receive signals, the soma (cell body) integrates them, the axon carries the action potential away, and the axon terminals release neurotransmitter into the synapse."},{"id":"psych-104-8","front":"What happens during an action potential?","back":"When the membrane reaches threshold, Na+ channels open and Na+ rushes in (depolarization). K+ channels then open and K+ flows out (repolarization). It is all-or-none: a stronger stimulus raises the firing rate, not the size of each spike."},{"id":"psych-104-9","front":"What does myelin do, and what happens when it is damaged?","back":"Myelin insulates axons so the action potential jumps between the nodes of Ranvier (saltatory conduction), which speeds transmission. Its loss, as in multiple sclerosis, slows or blocks signals."},{"id":"psych-104-10","front":"Match these neurotransmitters to their main roles: dopamine, serotonin, acetylcholine, GABA, glutamate.","back":"Dopamine: reward and movement (lost in Parkinson''s). Serotonin: mood, sleep and appetite. Acetylcholine: muscle contraction and memory (reduced in Alzheimer''s). GABA: main inhibitory transmitter. Glutamate: main excitatory transmitter."},{"id":"psych-104-11","front":"Agonist vs antagonist drugs","back":"An agonist mimics or enhances a neurotransmitter''s effect (for example, morphine at opioid receptors). An antagonist blocks a neurotransmitter''s effect (for example, curare blocks acetylcholine receptors)."},{"id":"psych-104-12","front":"Give the main functions of the four cerebral lobes.","back":"Frontal: planning, decision making and voluntary movement (motor cortex). Parietal: touch and body sense (somatosensory cortex) and spatial processing. Temporal: hearing, language comprehension and memory. Occipital: vision."},{"id":"psych-104-13","front":"Broca''s aphasia vs Wernicke''s aphasia","back":"Broca''s area (left frontal) damage causes slow, effortful, broken speech with comprehension largely intact. Wernicke''s area (left temporal) damage causes fluent but meaningless speech and poor comprehension."},{"id":"psych-104-14","front":"What did split-brain studies reveal?","back":"When the corpus callosum is cut, an image shown only to the right hemisphere (left visual field) cannot be named aloud, because language is usually in the left hemisphere, yet the left hand can pick out the object."},{"id":"psych-104-15","front":"Sensation vs perception, and what is transduction?","back":"Sensation is the detection of physical stimuli by sense receptors. Perception is the brain''s organization and interpretation of that input. Transduction is the conversion of stimulus energy into neural signals."},{"id":"psych-104-16","front":"Absolute threshold vs difference threshold, and Weber''s law","back":"The absolute threshold is the minimum stimulus detected 50% of the time. The difference threshold (JND) is the smallest detectable change. Weber''s law: the JND is a constant proportion of the original stimulus (ΔI/I = k)."},{"id":"psych-104-17","front":"What does signal detection theory add to the idea of thresholds?","back":"Detection depends on both sensitivity and the observer''s decision criterion. Outcomes are hits, misses, false alarms and correct rejections, so motivation and expectations shift responses."},{"id":"psych-104-18","front":"Rods vs cones","back":"Rods are concentrated in the periphery, are very sensitive in dim light and do not code colour. Cones are concentrated in the fovea, need brighter light and support colour vision and fine detail."},{"id":"psych-104-19","front":"Trichromatic theory vs opponent-process theory of colour vision","back":"Trichromatic: three cone types (short, medium and long wavelength, roughly blue, green and red) combine to code colour. Opponent-process: later neurons work in opposing pairs (red-green, blue-yellow, black-white), which explains afterimages. Both are correct at different stages."},{"id":"psych-104-20","front":"Place theory vs frequency theory of pitch","back":"Place theory: different frequencies maximally vibrate different locations on the basilar membrane, which best explains high pitches. Frequency theory: neural firing rate matches the sound frequency, which explains low pitches."},{"id":"psych-104-21","front":"Name four Gestalt grouping principles.","back":"Proximity (nearby items group together), similarity (alike items group), continuity (we see smooth, continuous lines) and closure (we fill gaps to see whole figures). Figure-ground separation is also basic."},{"id":"psych-104-22","front":"Bottom-up vs top-down processing","back":"Bottom-up processing builds perception from raw sensory features. Top-down processing uses expectations, knowledge and context to interpret input, for example reading a messy word correctly from the rest of the sentence."},{"id":"psych-104-23","front":"Give examples of binocular and monocular depth cues.","back":"Binocular: retinal disparity and convergence. Monocular: relative size, linear perspective, interposition (overlap), texture gradient, relative height and motion parallax."},{"id":"psych-104-24","front":"In Pavlov''s experiments, identify the UCS, UCR, CS and CR.","back":"UCS: food. UCR: salivation to food. CS: the tone, once it has been paired with food. CR: salivation to the tone alone."},{"id":"psych-104-25","front":"Define extinction, spontaneous recovery, generalization and discrimination in classical conditioning.","back":"Extinction: the CR fades when the CS is presented without the UCS. Spontaneous recovery: the CR reappears after a rest. Generalization: the CR occurs to stimuli similar to the CS. Discrimination: responding only to the CS and not to similar stimuli."},{"id":"psych-104-26","front":"Positive and negative reinforcement vs positive and negative punishment","back":"Reinforcement increases a behaviour and punishment decreases it. Positive means something is added and negative means something is removed. Taking away a nagging noise when a seatbelt is buckled is negative reinforcement."},{"id":"psych-104-27","front":"Which reinforcement schedule produces high response rates and the most resistance to extinction?","back":"A variable-ratio schedule (reward after an unpredictable number of responses, as with slot machines). Fixed-interval schedules produce a scalloped pattern with a pause after each reward."},{"id":"psych-104-28","front":"What did Bandura''s Bobo doll study show?","back":"Children who watched an adult act aggressively toward a doll later imitated that aggression, showing observational learning (modelling) without any direct reinforcement."},{"id":"psych-104-29","front":"Atkinson-Shiffrin model: name the three memory stores and their limits.","back":"Sensory memory: large capacity, lasts under a second (iconic) to a few seconds (echoic). Short-term memory: about 7 plus or minus 2 items, about 20 to 30 seconds without rehearsal. Long-term memory: essentially unlimited and durable."},{"id":"psych-104-30","front":"What does the levels-of-processing framework predict?","back":"Deeper, meaning-based (semantic) encoding produces better retention than shallow encoding based on appearance (structural) or sound (phonemic)."},{"id":"psych-104-31","front":"Proactive interference vs retroactive interference","back":"Proactive: old information disrupts recall of new information (your old password intrudes). Retroactive: new information disrupts recall of old information (you learn Spanish and forget French vocabulary)."},{"id":"psych-104-32","front":"Explicit vs implicit memory, and what patient H.M. showed","back":"Explicit memory is conscious recall of facts and events. Implicit memory shows up in skills and priming. After removal of H.M.''s hippocampal regions he could not form new explicit memories (anterograde amnesia) but could still learn motor skills."},{"id":"psych-104-33","front":"Availability heuristic vs representativeness heuristic","back":"Availability: judging how likely something is by how easily examples come to mind (fearing plane crashes after news coverage). Representativeness: judging by similarity to a prototype while ignoring base rates."},{"id":"psych-104-34","front":"Drive-reduction theory vs the Yerkes-Dodson law","back":"Drive-reduction: physiological needs create drives that motivate behaviour to restore homeostasis. Yerkes-Dodson: performance is best at moderate arousal, and the optimal level is lower for difficult tasks."},{"id":"psych-104-35","front":"James-Lange, Cannon-Bard and Schachter-Singer theories of emotion","back":"James-Lange: bodily arousal comes first and the emotion is our perception of it. Cannon-Bard: arousal and emotion happen at the same time and independently. Schachter-Singer (two-factor): arousal plus a cognitive label produces the emotion."}],"quizzes":[],"seed":1,"look":{"color":"#9A4FD1","icon":"psych"}}'::jsonb);   -- https://apps.ualberta.ca/catalogue/course/psych/104
select pg_temp.sb_seed('seed:ualberta-ca:econ-101', 'ualberta.ca', 'ECON 101', 'ECON 101 Exam Review: Supply and Demand, Elasticity, Costs and Market Structures', '{"v":1,"app":"studyboard","type":"deck","name":"ECON 101 Exam Review: Supply and Demand, Elasticity, Costs and Market Structures","course":{"code":"ECON 101","name":"Introduction to Microeconomics"},"cards":[{"id":"econ-101-1","front":"What is opportunity cost?","back":"The value of the next best alternative you give up when you make a choice. The opportunity cost of a year of university includes the wages you could have earned working, not just tuition."},{"id":"econ-101-2","front":"What does a production possibilities frontier (PPF) that bows outward imply?","back":"Increasing opportunity cost: resources are not equally suited to every good, so each extra unit of one good costs more and more units of the other. Points inside the PPF are inefficient and points outside are unattainable."},{"id":"econ-101-3","front":"Absolute advantage vs comparative advantage","back":"Absolute advantage: producing more output with the same resources. Comparative advantage: producing at a lower opportunity cost. Trade gains come from comparative advantage, even when one side has an absolute advantage in everything."},{"id":"econ-101-4","front":"A worker in A can make 10 wheat or 5 cloth; a worker in B can make 6 wheat or 6 cloth. Who has the comparative advantage in cloth?","back":"B. One cloth costs A 2 wheat but costs B only 1 wheat. A has the comparative advantage in wheat (1 wheat costs A 0.5 cloth vs 1 cloth for B)."},{"id":"econ-101-5","front":"Change in quantity demanded vs change in demand","back":"A change in the good''s own price causes a movement along the demand curve (a change in quantity demanded). A change in any other factor shifts the whole demand curve (a change in demand)."},{"id":"econ-101-6","front":"What shifts the demand curve?","back":"Income, prices of related goods (substitutes and complements), tastes, expectations about future prices or income, and the number of buyers."},{"id":"econ-101-7","front":"Normal good vs inferior good","back":"Demand for a normal good rises when income rises. Demand for an inferior good falls when income rises (for example instant noodles or bus rides as people switch to alternatives)."},{"id":"econ-101-8","front":"Substitutes vs complements","back":"Substitutes: a higher price of one raises demand for the other (coffee and tea). Complements: a higher price of one lowers demand for the other (printers and ink)."},{"id":"econ-101-9","front":"What shifts the supply curve?","back":"Input prices, technology, prices of other goods the firm could produce, expectations, the number of sellers, and taxes or subsidies on production."},{"id":"econ-101-10","front":"What happens when the price is above or below equilibrium?","back":"Above equilibrium, quantity supplied exceeds quantity demanded (a surplus) and the price tends to fall. Below equilibrium there is a shortage and the price tends to rise."},{"id":"econ-101-11","front":"Demand and supply both increase. What happens to equilibrium price and quantity?","back":"Quantity definitely rises. The price change is ambiguous: it depends on which curve shifts more."},{"id":"econ-101-12","front":"Midpoint formula for price elasticity of demand","back":"Ed = [(Q2 - Q1)/((Q1 + Q2)/2)] / [(P2 - P1)/((P1 + P2)/2)]. It is usually reported as an absolute value: above 1 is elastic, below 1 is inelastic, exactly 1 is unit elastic."},{"id":"econ-101-13","front":"Price rises from $4 to $6 and quantity demanded falls from 120 to 80. Find the elasticity (midpoint method).","back":"%ΔQ = -40/100 = -40% and %ΔP = 2/5 = +40%, so |Ed| = 1. Demand is unit elastic over this range."},{"id":"econ-101-14","front":"How does a price increase affect total revenue?","back":"If demand is elastic, total revenue falls. If demand is inelastic, total revenue rises. If demand is unit elastic, total revenue is unchanged."},{"id":"econ-101-15","front":"What makes demand more price elastic?","back":"Many close substitutes, a narrowly defined market, a large share of the budget, the good being a luxury, and a longer time to adjust."},{"id":"econ-101-16","front":"Signs of income elasticity and cross-price elasticity","back":"Income elasticity is positive for normal goods and negative for inferior goods (above 1 means a luxury). Cross-price elasticity is positive for substitutes and negative for complements."},{"id":"econ-101-17","front":"Consumer surplus vs producer surplus","back":"Consumer surplus is willingness to pay minus price paid: the area below demand and above price. Producer surplus is price received minus cost: the area above supply and below price."},{"id":"econ-101-18","front":"Effect of a binding price ceiling (for example rent control)","back":"It is set below equilibrium, so quantity demanded exceeds quantity supplied, causing a shortage. Other effects include deadweight loss, waiting lists and lower quality."},{"id":"econ-101-19","front":"Effect of a binding price floor (for example a minimum wage)","back":"It is set above equilibrium, so quantity supplied exceeds quantity demanded, causing a surplus. In the labour market that surplus is unemployment. It also creates deadweight loss."},{"id":"econ-101-20","front":"Who bears the burden of a per-unit tax?","back":"Whichever side of the market is less elastic (more inelastic) bears more of the burden, no matter who legally pays. The tax shrinks the quantity traded and creates deadweight loss."},{"id":"econ-101-21","front":"Utility-maximizing rule for two goods","back":"Spend your budget so that MUx/Px = MUy/Py: the last dollar spent on each good gives the same marginal utility."},{"id":"econ-101-22","front":"Short run vs long run in production","back":"In the short run at least one input (usually capital) is fixed. In the long run all inputs are variable and firms can enter or exit the industry."},{"id":"econ-101-23","front":"Law of diminishing marginal returns","back":"In the short run, as more of a variable input is added to a fixed input, the marginal product of the variable input eventually falls."},{"id":"econ-101-24","front":"Define TC, ATC, AVC and MC.","back":"TC = TFC + TVC. ATC = TC/Q. AVC = TVC/Q. MC = ΔTC/ΔQ, the cost of producing one more unit."},{"id":"econ-101-25","front":"Where does the MC curve cross the ATC and AVC curves?","back":"At their minimum points. When MC is below the average, it pulls the average down; when MC is above the average, it pulls it up."},{"id":"econ-101-26","front":"Accounting profit vs economic profit","back":"Accounting profit = revenue - explicit costs. Economic profit = revenue - explicit costs - implicit costs (opportunity costs). Zero economic profit means the firm earns a normal return."},{"id":"econ-101-27","front":"What are the features of perfect competition?","back":"Many buyers and sellers, identical products, free entry and exit, and full information. Each firm is a price taker, so P = MR and the firm''s demand curve is horizontal."},{"id":"econ-101-28","front":"Profit-maximizing rule and shutdown rule in the short run","back":"Produce where MR = MC. In the short run, shut down if P is below minimum AVC, because operating would lose more than the fixed costs."},{"id":"econ-101-29","front":"Long-run equilibrium in perfect competition","back":"Entry and exit drive economic profit to zero, so P = MC = minimum ATC. This outcome is both allocatively and productively efficient."},{"id":"econ-101-30","front":"How does a monopoly choose price and quantity?","back":"Because MR is below price, it produces where MR = MC and then charges the highest price the demand curve allows at that quantity. Output is lower and price higher than under competition, which creates deadweight loss."},{"id":"econ-101-31","front":"What conditions are needed for price discrimination?","back":"The firm must have market power, be able to identify or separate groups with different price elasticities, and prevent resale between groups."},{"id":"econ-101-32","front":"Long-run outcome in monopolistic competition","back":"Free entry drives economic profit to zero, but P = ATC above minimum ATC, so firms have excess capacity and P > MC."},{"id":"econ-101-33","front":"What is the prisoner''s dilemma, and why does it matter for oligopoly?","back":"Each player has a dominant strategy (for example, cheating on a collusive agreement) that leads to a Nash equilibrium worse for both than cooperating. It explains why cartels are unstable."},{"id":"econ-101-34","front":"Negative externality: market outcome and policy fix","back":"When there are external costs such as pollution, the market overproduces because private cost is below social cost. A Pigouvian tax equal to the marginal external cost can restore the efficient quantity."},{"id":"econ-101-35","front":"What makes something a public good, and what is the free-rider problem?","back":"A public good is non-rival and non-excludable (for example national defence). People can benefit without paying, so private markets underprovide it."}],"quizzes":[],"seed":1,"look":{"color":"#C79A12","icon":"econ"}}'::jsonb);   -- https://apps.ualberta.ca/catalogue/course/econ/101
select pg_temp.sb_seed('seed:ucalgary-ca:psyc-200', 'ucalgary.ca', 'PSYC 200', 'PSYC 200 Final Review: Neuroscience, Perception, Cognition, Memory and Language', '{"v":1,"app":"studyboard","type":"deck","name":"PSYC 200 Final Review: Neuroscience, Perception, Cognition, Memory and Language","course":{"code":"PSYC 200","name":"Principles of Psychology I"},"cards":[{"id":"psyc-200-1","front":"Central vs peripheral nervous system, and somatic vs autonomic divisions","back":"The CNS is the brain and spinal cord; the PNS is all the nerves outside them. The PNS divides into the somatic system (voluntary movement and sensory input) and the autonomic system (involuntary control of organs and glands)."},{"id":"psyc-200-2","front":"Sympathetic vs parasympathetic nervous system","back":"The sympathetic system drives fight-or-flight: it raises heart rate, dilates the pupils and slows digestion. The parasympathetic system drives rest-and-digest: it slows the heart, stimulates digestion and conserves energy."},{"id":"psyc-200-3","front":"What maintains a neuron''s resting potential of about -70 mV?","back":"The sodium-potassium pump (moving 3 Na+ out for every 2 K+ in) and K+ leak channels that let positive charge escape. The inside of the cell ends up negative relative to the outside."},{"id":"psyc-200-4","front":"What is the absolute refractory period?","back":"A brief period right after an action potential when the neuron cannot fire again, because the Na+ channels are inactivated. It limits the maximum firing rate and keeps signals moving in one direction."},{"id":"psyc-200-5","front":"EPSP vs IPSP, and how does a neuron decide to fire?","back":"An EPSP depolarizes the membrane (making firing more likely) and an IPSP hyperpolarizes it (making firing less likely). The neuron sums these inputs over space and time, and fires if the axon hillock reaches threshold."},{"id":"psyc-200-6","front":"What is reuptake, and how do SSRIs work?","back":"Reuptake is the presynaptic neuron reabsorbing its released neurotransmitter, which ends the signal. SSRIs block serotonin reuptake, so serotonin stays in the synapse longer; they are used to treat depression."},{"id":"psyc-200-7","front":"What is the hippocampus mainly responsible for?","back":"Forming new explicit (declarative) long-term memories and spatial memory. Damage to it causes anterograde amnesia, while older memories and motor skills are largely spared."},{"id":"psyc-200-8","front":"What is the amygdala''s main role?","back":"Processing emotion, especially fear and threat detection, and attaching emotional significance to memories. Damage reduces fear responses and fear conditioning."},{"id":"psyc-200-9","front":"What does the hypothalamus regulate?","back":"Homeostatic drives such as hunger, thirst, body temperature and sexual behaviour. It also controls the pituitary gland, linking the nervous system to the endocrine system."},{"id":"psyc-200-10","front":"What does the cerebellum do?","back":"It coordinates smooth, timed movement, balance and posture, and it supports motor learning. Damage produces clumsy, uncoordinated movement (ataxia)."},{"id":"psyc-200-11","front":"What is the role of the thalamus, and which sense bypasses it?","back":"The thalamus is a relay station that routes incoming sensory information to the correct cortical areas. Smell (olfaction) is the main sense that does not relay through the thalamus first."},{"id":"psyc-200-12","front":"EEG vs fMRI: what is each best at?","back":"EEG records electrical activity at the scalp with excellent timing resolution (milliseconds) but poor spatial resolution. fMRI measures blood-oxygen changes (the BOLD signal) with good spatial detail but slower timing."},{"id":"psyc-200-13","front":"What is neuroplasticity?","back":"The brain''s ability to change its structure and function with experience, learning or injury, for example by strengthening synapses or reorganizing cortical maps after damage. It is greatest in childhood."},{"id":"psyc-200-14","front":"Trace the path of light to the optic nerve.","back":"Light passes through the cornea, pupil and lens to the retina. There photoreceptors (rods and cones) signal bipolar cells, which signal ganglion cells. Ganglion cell axons form the optic nerve, and where they exit there are no receptors (the blind spot)."},{"id":"psyc-200-15","front":"What did Hubel and Wiesel discover?","back":"Feature detector neurons in the visual cortex that respond selectively to particular features such as lines at specific orientations, movement or edges. This showed that visual perception is built up hierarchically."},{"id":"psyc-200-16","front":"Dorsal stream vs ventral stream in vision","back":"The dorsal (\"where/how\") stream runs to the parietal lobe and processes location, motion and visually guided action. The ventral (\"what\") stream runs to the temporal lobe and processes object identity and recognition."},{"id":"psyc-200-17","front":"How does the ear code pitch and loudness?","back":"Frequency corresponds to pitch and amplitude to loudness. Sound vibrations move fluid in the cochlea, bending hair cells on the basilar membrane, which transduce the motion into neural signals."},{"id":"psyc-200-18","front":"What is the gate control theory of pain?","back":"Neural \"gates\" in the spinal cord can block or let through pain signals going to the brain. Input from touch fibres (for example rubbing an injury) and signals coming down from the brain can close the gate and reduce pain."},{"id":"psyc-200-19","front":"What is perceptual constancy?","back":"Perceiving objects as having a stable size, shape, colour and brightness even when the image on the retina changes. For example, a door still looks rectangular as it swings open."},{"id":"psyc-200-20","front":"What did Garcia''s taste aversion research show?","back":"Rats learned to avoid a taste after a single pairing with illness, even with a long delay, but not to avoid lights or sounds paired with illness. This showed biological preparedness: some associations are learned more easily."},{"id":"psyc-200-21","front":"What is latent learning (Tolman)?","back":"Learning that happens without reinforcement and is not shown until there is a reason to show it. Rats that explored a maze without reward ran it quickly once food was added, suggesting they had formed cognitive maps."},{"id":"psyc-200-22","front":"Name the components of Baddeley''s working memory model.","back":"The central executive (controls attention), the phonological loop (verbal and auditory information), the visuospatial sketchpad (visual and spatial information) and the episodic buffer (combines information and links it to long-term memory)."},{"id":"psyc-200-23","front":"What is the serial position effect?","back":"Better recall of the first items in a list (the primacy effect, due to more rehearsal and transfer to long-term memory) and of the last items (the recency effect, because they are still in short-term memory)."},{"id":"psyc-200-24","front":"What is encoding specificity, and what is a classic example?","back":"Recall is best when the cues at retrieval match the conditions at encoding. Divers who learned words underwater recalled them better underwater than on land, and the reverse was also true (context-dependent memory)."},{"id":"psyc-200-25","front":"What is the misinformation effect (Loftus)?","back":"Misleading information given after an event changes later memory of it. Asking how fast cars were going when they \"smashed\" rather than \"hit\" led to higher speed estimates and false reports of broken glass."},{"id":"psyc-200-26","front":"Episodic vs semantic vs procedural memory","back":"Episodic: personal events tied to a time and place. Semantic: general facts and knowledge. Procedural: skills and habits, shown through performance (implicit). The first two are both explicit (declarative)."},{"id":"psyc-200-27","front":"What does prototype theory say about how we form concepts?","back":"We categorize items by comparing them to a prototype, the most typical example of a category. A robin is judged to be a bird faster than a penguin because it is closer to the prototype."},{"id":"psyc-200-28","front":"Functional fixedness vs mental set","back":"Functional fixedness: seeing an object only in terms of its usual function (not thinking of a coin as a screwdriver). Mental set: sticking with a problem-solving approach that worked before, even when a better one exists."},{"id":"psyc-200-29","front":"Algorithm vs heuristic","back":"An algorithm is a step-by-step procedure that guarantees a solution but can be slow. A heuristic is a mental shortcut that is fast but can lead to errors."},{"id":"psyc-200-30","front":"Confirmation bias vs framing effect","back":"Confirmation bias: seeking or favouring evidence that supports what we already believe. Framing effect: decisions change with how options are worded, for example a 90% survival rate versus a 10% death rate."},{"id":"psyc-200-31","front":"Define phoneme, morpheme, syntax and semantics.","back":"A phoneme is the smallest unit of sound. A morpheme is the smallest unit of meaning (for example \"un-\" or \"dog\"). Syntax is the rules for combining words into sentences. Semantics is the meaning of words and sentences."},{"id":"psyc-200-32","front":"Chomsky vs Skinner on language acquisition","back":"Skinner argued that language is learned through reinforcement and imitation. Chomsky argued for an innate language acquisition device and a universal grammar, pointing to rapid learning and novel errors such as \"goed\"."},{"id":"psyc-200-33","front":"What is the linguistic relativity (Whorfian) hypothesis?","back":"The idea that the language we speak shapes how we think and perceive. The strong version (language determines thought) is largely rejected; weaker effects, for example on colour categorization, have some support."}],"quizzes":[],"seed":1,"look":{"color":"#C026D3","icon":"psych"}}'::jsonb);   -- https://ucalgary.ca/pubs/calendar/archives/2023/psychology.html
select pg_temp.sb_seed('seed:ucalgary-ca:biol-241', 'ucalgary.ca', 'BIOL 241', 'BIOL 241 Exam Review: Bioenergetics, Respiration, Photosynthesis and Ecosystem Energy Flow', '{"v":1,"app":"studyboard","type":"deck","name":"BIOL 241 Exam Review: Bioenergetics, Respiration, Photosynthesis and Ecosystem Energy Flow","course":{"code":"BIOL 241","name":"Energy Flow in Biological Systems"},"cards":[{"id":"biol-241-1","front":"State the first law of thermodynamics and what it means for organisms.","back":"Energy cannot be created or destroyed, only converted from one form to another. Organisms do not make energy; they convert light or chemical energy into ATP, work and heat."},{"id":"biol-241-2","front":"State the second law of thermodynamics and what it means for living systems.","back":"Every energy conversion increases the total entropy of the universe, and some energy is lost as heat. Organisms stay highly ordered only by taking in energy constantly and releasing heat and disorder to their surroundings."},{"id":"biol-241-3","front":"Gibbs free energy equation and its symbols","back":"ΔG = ΔH - TΔS. ΔG is the change in free energy, ΔH the change in enthalpy (heat content), T the absolute temperature in kelvin and ΔS the change in entropy. A negative ΔG means the reaction is spontaneous."},{"id":"biol-241-4","front":"How does ΔG differ from the standard value ΔG°''?","back":"ΔG°'' applies under standard conditions (1 M concentrations, pH 7). The actual ΔG = ΔG°'' + RT ln Q depends on cell concentrations, so a reaction with a positive ΔG°'' can still proceed if products are kept low."},{"id":"biol-241-5","front":"How do cells drive endergonic reactions?","back":"By coupling them to exergonic reactions, usually ATP hydrolysis, so the combined ΔG is negative. Often a phosphate is transferred from ATP to a reactant, creating a more reactive intermediate."},{"id":"biol-241-6","front":"Why is ATP a useful energy currency?","back":"Hydrolysis of its terminal phosphoanhydride bond releases a convenient amount of free energy (ΔG°'' about -30.5 kJ/mol). ATP is quickly regenerated from ADP + Pi by respiration or photosynthesis."},{"id":"biol-241-7","front":"Define oxidation and reduction, and give the role of NAD+.","back":"Oxidation is loss of electrons and reduction is gain of electrons (OIL RIG). NAD+ is reduced to NADH by accepting electrons (with H+) from food molecules, then carries those electrons to the electron transport chain."},{"id":"biol-241-8","front":"What is the induced fit model of enzyme action?","back":"When the substrate binds, the active site changes shape slightly to grip it more tightly. This strains bonds and stabilizes the transition state, lowering the activation energy."},{"id":"biol-241-9","front":"What does Km mean in Michaelis-Menten kinetics?","back":"Km is the substrate concentration at which the reaction rate is half of Vmax. A low Km means high affinity: the enzyme reaches half speed at a low substrate concentration."},{"id":"biol-241-10","front":"What is feedback inhibition? Give a respiration example.","back":"The end product of a pathway inhibits an earlier enzyme, often allosterically, to prevent overproduction. High ATP and citrate inhibit phosphofructokinase (PFK), the key regulatory enzyme of glycolysis."},{"id":"biol-241-11","front":"How do temperature and pH affect enzyme activity?","back":"Activity rises with temperature up to an optimum, then drops sharply as the enzyme denatures. Each enzyme also has an optimal pH; values far from it change the charges on R groups and disrupt the enzyme''s shape."},{"id":"biol-241-12","front":"Describe the two phases of glycolysis.","back":"Energy investment phase: 2 ATP are used to phosphorylate glucose and split it into two 3-carbon sugars. Payoff phase: 4 ATP and 2 NADH are produced, for a net gain of 2 ATP per glucose."},{"id":"biol-241-13","front":"Substrate-level phosphorylation vs oxidative phosphorylation","back":"Substrate-level: an enzyme transfers a phosphate directly from a substrate to ADP (in glycolysis and the citric acid cycle). Oxidative: ATP synthase makes ATP using the proton gradient produced by the electron transport chain."},{"id":"biol-241-14","front":"About how many ATP does aerobic respiration yield per glucose, and where do most come from?","back":"About 30 to 32 ATP. Most come from oxidative phosphorylation powered by NADH and FADH2 (about 2.5 ATP per NADH and 1.5 per FADH2)."},{"id":"biol-241-15","front":"Why is oxygen essential for aerobic respiration, and how does cyanide kill?","back":"O2 is the final electron acceptor at the end of the electron transport chain, forming water. Cyanide blocks complex IV (cytochrome c oxidase), so electron flow, proton pumping and ATP synthesis stop."},{"id":"biol-241-16","front":"What do uncoupling proteins do, for example in brown fat?","back":"They let H+ leak back across the inner mitochondrial membrane without passing through ATP synthase. The gradient''s energy is released as heat instead of making ATP, which is how brown fat produces heat (non-shivering thermogenesis)."},{"id":"biol-241-17","front":"Anaerobic respiration vs fermentation","back":"Anaerobic respiration still uses an electron transport chain but with a final electron acceptor other than O2 (for example sulfate or nitrate). Fermentation uses no electron transport chain; it only regenerates NAD+ and makes 2 ATP per glucose."},{"id":"biol-241-18","front":"How are fats used for energy, and why do they store so much?","back":"Triglycerides are broken into glycerol and fatty acids; beta-oxidation cuts the fatty acids into acetyl CoA for the citric acid cycle. Fats are highly reduced, so they yield about 9 kcal/g compared with about 4 kcal/g for carbohydrate or protein."},{"id":"biol-241-19","front":"Photoautotroph vs chemoautotroph vs heterotroph","back":"Photoautotrophs make organic molecules from CO2 using light. Chemoautotrophs make them from CO2 using energy from oxidizing inorganic chemicals (such as H2S at deep-sea vents). Heterotrophs get both energy and carbon by eating organic matter."},{"id":"biol-241-20","front":"Why do plants look green, and what does an action spectrum show?","back":"Chlorophyll absorbs mainly blue and red light and reflects green. An action spectrum plots photosynthetic rate against wavelength, showing which wavelengths actually drive photosynthesis."},{"id":"biol-241-21","front":"What are the roles of photosystem II and photosystem I in the light reactions?","back":"PSII uses light to energize electrons, replacing them by splitting water, which releases O2. Its electrons pass down a transport chain that pumps H+ for ATP. PSI re-energizes the electrons to reduce NADP+ to NADPH."},{"id":"biol-241-22","front":"What is cyclic electron flow, and why do chloroplasts use it?","back":"Electrons from PSI cycle back to the electron transport chain instead of reducing NADP+. This makes extra ATP but no NADPH and no O2, balancing the Calvin cycle''s higher demand for ATP."},{"id":"biol-241-23","front":"Calvin cycle: what does it take to make one G3P?","back":"Three turns, fixing 3 CO2, use 9 ATP and 6 NADPH and produce one net G3P (a 3-carbon sugar). The cycle has three stages: carbon fixation by rubisco, reduction, and regeneration of RuBP."},{"id":"biol-241-24","front":"What is photorespiration, and when does it occur?","back":"Rubisco binds O2 instead of CO2, which wastes energy and releases fixed carbon as CO2. It increases in hot, dry conditions, when stomata close and the O2:CO2 ratio inside the leaf rises."},{"id":"biol-241-25","front":"C4 vs CAM plants","back":"Both fix CO2 first with PEP carboxylase, which does not bind O2, to reduce photorespiration. C4 plants (such as corn) separate the steps in space between mesophyll and bundle sheath cells. CAM plants (such as cacti) separate them in time: they open stomata at night and run the Calvin cycle by day."},{"id":"biol-241-26","front":"Gross vs net primary productivity","back":"GPP is the total rate at which producers capture energy by photosynthesis. NPP = GPP - the energy producers use in their own respiration. NPP is the energy available to consumers."},{"id":"biol-241-27","front":"Roughly what fraction of energy passes from one trophic level to the next, and why?","back":"About 10%, though it ranges from about 5 to 20%. Most energy is lost as heat from respiration, or is never eaten, digested or assimilated."},{"id":"biol-241-28","front":"Why are food chains usually short, and why is a pyramid of energy never inverted?","back":"With only about 10% transferred at each step, too little energy remains to support more than about 4 or 5 trophic levels. Each level must have less energy than the level below it, so energy pyramids always narrow upward."},{"id":"biol-241-29","front":"Endotherm vs ectotherm","back":"Endotherms (mammals, birds) keep body temperature high mainly with metabolic heat, which needs high energy intake. Ectotherms (most reptiles, fish, invertebrates) rely mainly on external heat, so they need much less food for their size."},{"id":"biol-241-30","front":"How does metabolic rate scale with body mass?","back":"Basal metabolic rate scales roughly with M^0.75 (Kleiber''s law). So mass-specific metabolic rate (per gram) falls as body size rises: a mouse burns far more energy per gram than an elephant."},{"id":"biol-241-31","front":"Why do small animals lose heat faster for their size?","back":"They have a higher surface area to volume ratio, so more surface is available for heat loss relative to the tissue that produces heat."},{"id":"biol-241-32","front":"Write the basic energy budget of an animal.","back":"Ingested energy = egested energy (feces) + assimilated energy. Assimilated energy = energy used in respiration (maintenance and activity, lost as heat) + production (growth and reproduction)."}],"quizzes":[],"seed":1,"look":{"color":"#16A34A","icon":"bio"}}'::jsonb);   -- https://ucalgary.ca/pubs/calendar/archives/2023/biology.html
select pg_temp.sb_seed('seed:ucalgary-ca:chem-201', 'ucalgary.ca', 'CHEM 201', 'CHEM 201 Exam Review: Electronic Structure, Lewis Structures, VSEPR and Molecular Interactions', '{"v":1,"app":"studyboard","type":"deck","name":"CHEM 201 Exam Review: Electronic Structure, Lewis Structures, VSEPR and Molecular Interactions","course":{"code":"CHEM 201","name":"General Chemistry: Structure and Bonding"},"cards":[{"id":"chem-201-1","front":"How are wavelength, frequency and energy of light related?","back":"c = λ·v and E = h·v. Higher frequency means shorter wavelength and higher photon energy, so UV photons carry more energy than visible photons, and visible more than infrared."},{"id":"chem-201-2","front":"What is the energy of a single photon of 500 nm light?","back":"E = hc/λ = (6.626 x 10^-34 J·s)(3.00 x 10^8 m/s)/(500 x 10^-9 m) = 3.98 x 10^-19 J."},{"id":"chem-201-3","front":"Rydberg equation for hydrogen emission lines","back":"1/λ = R_H (1/n1^2 - 1/n2^2), where n2 > n1 and R_H = 1.097 x 10^7 m^-1. Transitions down to n1 = 2 give the visible Balmer series."},{"id":"chem-201-4","front":"Why do atoms give line spectra instead of continuous spectra?","back":"Electron energies are quantized, so only specific energy differences between levels are possible. Each transition emits or absorbs a photon of one specific wavelength."},{"id":"chem-201-5","front":"How do you count the nodes in an atomic orbital? Apply it to a 3p orbital.","back":"Total nodes = n - 1, angular nodes = l, radial nodes = n - l - 1. A 3p orbital (n = 3, l = 1) has 2 nodes in total: 1 angular and 1 radial."},{"id":"chem-201-6","front":"What ml values are allowed for l = 2, and how many d orbitals is that?","back":"ml = -2, -1, 0, +1, +2, so there are 5 d orbitals in any shell with n ≥ 3."},{"id":"chem-201-7","front":"Is the quantum number set n = 2, l = 2 allowed?","back":"No. l must range from 0 to n - 1, so for n = 2 only l = 0 (2s) or l = 1 (2p) is allowed. A 2d subshell does not exist."},{"id":"chem-201-8","front":"Why is 2s lower in energy than 2p in multi-electron atoms?","back":"A 2s electron penetrates closer to the nucleus than a 2p electron, so it is less shielded and feels a higher effective nuclear charge. In hydrogen, with one electron, they are degenerate."},{"id":"chem-201-9","front":"Paramagnetic vs diamagnetic: classify a ground-state N atom.","back":"Paramagnetic species have unpaired electrons and are attracted to a magnetic field; diamagnetic species have all electrons paired. N (1s2 2s2 2p3) has 3 unpaired 2p electrons, so it is paramagnetic."},{"id":"chem-201-10","front":"What is electron affinity, and what is its general periodic trend?","back":"The energy change when a gaseous atom gains an electron. It generally becomes more negative (more favourable) from left to right across a period, with halogens the most favourable. Noble gases and group 2 have unfavourable values."},{"id":"chem-201-11","front":"Steps for drawing a Lewis structure","back":"Count total valence electrons (adjusting for charge), put the least electronegative atom in the centre (never H), connect atoms with single bonds, complete outer octets, place leftover electrons on the central atom, then form multiple bonds if the central atom lacks an octet."},{"id":"chem-201-12","front":"What is the formal charge on N in NH4+?","back":"FC = 5 valence - 0 nonbonding - (1/2)(8 bonding) = +1. This accounts for the overall +1 charge of the ion."},{"id":"chem-201-13","front":"How are bond order, bond length and bond energy related?","back":"A higher bond order means a shorter, stronger bond. For carbon-carbon bonds, C≡C is shorter and stronger than C=C, which is shorter and stronger than C-C."},{"id":"chem-201-14","front":"What is the C-O bond order in the carbonate ion, and why are all three bonds the same?","back":"CO3^2- has three equivalent resonance structures, each with one C=O and two C-O bonds. The real ion is their average, so each bond has a bond order of 4/3 and all three are identical."},{"id":"chem-201-15","front":"Electron-domain geometry vs molecular geometry, using NH3","back":"Electron-domain geometry counts all bonding and lone-pair domains; molecular geometry describes only the positions of the atoms. NH3 has a tetrahedral electron geometry but a trigonal pyramidal shape, with angles of about 107°."},{"id":"chem-201-16","front":"Give the molecular shapes of ClF3, BrF5 and I3-.","back":"ClF3: T-shaped (5 domains, 2 lone pairs). BrF5: square pyramidal (6 domains, 1 lone pair). I3-: linear (5 domains, 3 equatorial lone pairs)."},{"id":"chem-201-17","front":"Why is CH2Cl2 polar while CCl4 is nonpolar?","back":"Both are tetrahedral. In CCl4 the four identical C-Cl dipoles cancel. In CH2Cl2 the C-H and C-Cl bonds have different polarities, so the dipoles do not cancel and there is a net dipole moment."},{"id":"chem-201-18","front":"Sigma vs pi bonds in valence bond theory","back":"A sigma bond forms by head-on orbital overlap along the line between the nuclei and allows free rotation. A pi bond forms by side-by-side overlap of p orbitals above and below that line and prevents rotation."},{"id":"chem-201-19","front":"What is the hybridization of carbon in methane, ethene and ethyne?","back":"Methane: sp3 (tetrahedral, 109.5°). Ethene: sp2 (trigonal planar, 120°, one pi bond). Ethyne: sp (linear, 180°, two pi bonds)."},{"id":"chem-201-20","front":"How many sigma and pi bonds are in acetonitrile, CH3CN?","back":"5 sigma bonds (three C-H, one C-C and one in the C≡N) and 2 pi bonds (both in the C≡N triple bond)."},{"id":"chem-201-21","front":"Use MO theory to explain why He2 does not exist.","back":"He2 would have 2 electrons in sigma1s (bonding) and 2 in sigma*1s (antibonding), so bond order = (2 - 2)/2 = 0 and no stable bond forms."},{"id":"chem-201-22","front":"Compare N2, O2 and O2+ using MO theory.","back":"N2: bond order 3, all electrons paired (diamagnetic). O2: bond order 2, two unpaired pi* electrons (paramagnetic). O2+: one pi* electron removed, so bond order 2.5 and a shorter, stronger bond than O2."},{"id":"chem-201-23","front":"Why does the MO energy ordering differ for B2, C2 and N2 compared with O2 and F2?","back":"In the lighter molecules, mixing between 2s and 2p orbitals (s-p mixing) pushes sigma2p above pi2p. In O2 and F2 the 2s-2p energy gap is larger, so sigma2p lies below pi2p."},{"id":"chem-201-24","front":"Constitutional isomers vs stereoisomers, with a cis/trans example","back":"Constitutional isomers differ in how the atoms are connected (butane vs isobutane). Stereoisomers have the same connectivity but a different 3D arrangement. Cis- and trans-2-butene exist because the C=C pi bond prevents rotation."},{"id":"chem-201-25","front":"Aldehyde vs ketone","back":"Both contain a carbonyl group (C=O). In an aldehyde the carbonyl carbon is bonded to at least one H, so it sits at the end of a chain (R-CHO). In a ketone the carbonyl carbon is bonded to two carbon groups (R-CO-R'')."},{"id":"chem-201-26","front":"Why does ethanol boil far higher than dimethyl ether, even though both are C2H6O?","back":"Ethanol has an O-H group, so its molecules hydrogen bond with one another. Dimethyl ether has no H bonded to O, so it has only dipole-dipole and dispersion forces. Ethanol boils at about 78 °C; dimethyl ether at about -24 °C."},{"id":"chem-201-27","front":"What forces let NaCl dissolve in water?","back":"Ion-dipole attractions: the partially negative O ends of water surround Na+ and the partially positive H ends surround Cl-. Together with the gain in entropy, this offsets the lattice energy."},{"id":"chem-201-28","front":"Why does n-pentane boil higher than neopentane, its isomer with the same molar mass?","back":"The long, straight n-pentane molecule has more surface contact with its neighbours, so its London dispersion forces are stronger than those of compact, nearly spherical neopentane."},{"id":"chem-201-29","front":"What does \"like dissolves like\" mean?","back":"Polar and ionic substances dissolve well in polar solvents (for example sugar in water). Nonpolar substances dissolve in nonpolar solvents (for example oil in hexane). Solubility is favoured when solute and solvent have similar intermolecular forces."},{"id":"chem-201-30","front":"What controls lattice energy? Compare MgO and NaCl.","back":"By Coulomb''s law, lattice energy is proportional to (q1·q2)/r. MgO (charges +2 and -2, small ions) has a much larger lattice energy than NaCl (charges +1 and -1), so it has a much higher melting point."},{"id":"chem-201-31","front":"How does band theory distinguish conductors, semiconductors and insulators?","back":"In metals the valence band and conduction band overlap or the valence band is partly filled, so electrons move freely. Semiconductors have a small band gap that electrons can cross with heat or doping. Insulators have a large band gap."},{"id":"chem-201-32","front":"Diamond vs graphite","back":"Both are pure carbon. Diamond is a 3D network of sp3 carbons: very hard and an electrical insulator. Graphite is layers of sp2 carbons with delocalized pi electrons: soft and slippery, and it conducts electricity along its layers."}],"quizzes":[],"seed":1,"look":{"color":"#DC2626","icon":"chem"}}'::jsonb);   -- https://calendar.ucalgary.ca/courses/1047931
select pg_temp.sb_seed('seed:utoronto-ca:psy100h1', 'utoronto.ca', 'PSY100H1', 'PSY100 Final Review: Development, Personality, Psychological Disorders and Social Psychology', '{"v":1,"app":"studyboard","type":"deck","name":"PSY100 Final Review: Development, Personality, Psychological Disorders and Social Psychology","course":{"code":"PSY100H1","name":"Introductory Psychology"},"cards":[{"id":"psy100h1-1","front":"List Piaget''s four stages of cognitive development with approximate ages.","back":"Sensorimotor (0 to 2 years), preoperational (2 to 7), concrete operational (7 to 11) and formal operational (11 and up)."},{"id":"psy100h1-2","front":"What is object permanence, and when does it develop?","back":"Understanding that objects continue to exist when they are out of sight. Piaget placed it in the sensorimotor stage, developing in the first year or two; later research suggests infants show signs of it earlier."},{"id":"psy100h1-3","front":"What are conservation and egocentrism, and which stage are they tied to?","back":"Conservation: knowing that a quantity stays the same when its shape changes (for example water poured into a taller glass). Preoperational children lack it and are egocentric, meaning they struggle to take another person''s perspective."},{"id":"psy100h1-4","front":"What is Vygotsky''s zone of proximal development?","back":"The gap between what a child can do alone and what they can do with guidance from a more skilled person. Learning is most effective in this zone, with support (scaffolding) that is gradually withdrawn."},{"id":"psy100h1-5","front":"What did Harlow''s monkey studies show about attachment?","back":"Infant monkeys preferred a soft cloth mother over a wire mother that provided milk, especially when frightened. Attachment depends on contact comfort, not just feeding."},{"id":"psy100h1-6","front":"Describe the attachment styles identified with Ainsworth''s Strange Situation.","back":"Secure: upset when the caregiver leaves and easily comforted on return. Insecure-avoidant: little distress and avoids the caregiver on return. Insecure-resistant (ambivalent): very distressed and hard to soothe, clinging and angry. A disorganized style was added later."},{"id":"psy100h1-7","front":"What are Kohlberg''s three levels of moral reasoning?","back":"Preconventional: avoid punishment and gain rewards. Conventional: follow rules and social approval. Postconventional: reason from abstract principles and rights. The levels are based on the reasoning given, not on the decision itself."},{"id":"psy100h1-8","front":"What is Erikson''s main psychosocial crisis of adolescence?","back":"Identity vs role confusion: teenagers try out roles and values to form a coherent sense of who they are. It is one of Erikson''s eight lifespan stages, such as trust vs mistrust in infancy."},{"id":"psy100h1-9","front":"Fluid intelligence vs crystallized intelligence","back":"Fluid intelligence is the ability to reason and solve new problems; it peaks in early adulthood and then declines. Crystallized intelligence is accumulated knowledge and vocabulary; it stays stable or grows into later adulthood."},{"id":"psy100h1-10","front":"What does heritability mean, and what is a common misreading of it?","back":"The proportion of variation in a trait within a particular population that is due to genetic differences. It does not describe how much of one person''s trait is genetic, and it can change when environments change."},{"id":"psy100h1-11","front":"How are twin studies used to estimate genetic influence?","back":"Identical (monozygotic) twins share about 100% of their genes and fraternal (dizygotic) twins about 50%. If identical twins are much more similar on a trait, the trait has a substantial genetic component."},{"id":"psy100h1-12","front":"Name the Big Five personality traits.","back":"OCEAN: Openness to experience, Conscientiousness, Extraversion, Agreeableness and Neuroticism. Each is a continuous dimension, fairly stable in adulthood and partly heritable."},{"id":"psy100h1-13","front":"Freud''s id, ego and superego","back":"The id seeks immediate pleasure (the pleasure principle). The superego holds internalized moral standards. The ego mediates between them and reality (the reality principle)."},{"id":"psy100h1-14","front":"Projection vs displacement as defence mechanisms","back":"Projection: attributing your own unacceptable feelings to others (\"he hates me\" when you dislike him). Displacement: redirecting an impulse toward a safer target (yelling at your sibling after a boss criticizes you)."},{"id":"psy100h1-15","front":"What is Carl Rogers'' humanistic view of personality?","back":"People strive toward self-actualization. Healthy growth needs unconditional positive regard, acceptance that is not tied to meeting conditions; conditions of worth create a gap between the real self and the ideal self."},{"id":"psy100h1-16","front":"What did Bandura mean by reciprocal determinism and self-efficacy?","back":"Reciprocal determinism: behaviour, personal factors (thoughts) and the environment all influence one another. Self-efficacy: belief in your ability to succeed at a task, which predicts effort and persistence."},{"id":"psy100h1-17","front":"What is the fundamental attribution error?","back":"Overestimating personality (dispositional) causes and underestimating situational causes when explaining other people''s behaviour. For example, assuming a driver who cuts you off is a jerk rather than rushing to the hospital."},{"id":"psy100h1-18","front":"What did Festinger and Carlsmith''s cognitive dissonance study find?","back":"After a boring task, participants paid $1 to tell others it was fun later rated it as more enjoyable than those paid $20. With too little external justification, they changed their attitude to reduce dissonance."},{"id":"psy100h1-19","front":"What did Asch''s line judgment studies show?","back":"Many people gave an obviously wrong answer to match a unanimous group: about 75% conformed at least once. Conformity dropped sharply when even one other person disagreed with the group."},{"id":"psy100h1-20","front":"What did Milgram''s obedience studies find?","back":"About 65% of participants obeyed an authority figure and gave what they believed were maximum 450-volt shocks to another person. Obedience fell when the experimenter was absent or the victim was closer."},{"id":"psy100h1-21","front":"What is the bystander effect, and what explains it?","back":"People are less likely to help in an emergency when others are present. Diffusion of responsibility (each person feels less personally responsible) and pluralistic ignorance (taking others'' inaction as a sign that nothing is wrong) explain it (Darley and Latané)."},{"id":"psy100h1-22","front":"Social facilitation vs social loafing","back":"Social facilitation: the presence of others improves performance on simple or well-learned tasks and impairs it on hard or new ones. Social loafing: people put in less effort when individual contributions in a group are not identifiable."},{"id":"psy100h1-23","front":"What is groupthink?","back":"A cohesive group''s drive for agreement overrides realistic evaluation of alternatives, leading to poor decisions. Contributing factors include strong directive leaders, isolation and self-censorship of doubts."},{"id":"psy100h1-24","front":"What is the mere exposure effect?","back":"Repeated exposure to a stimulus (a face, a song, a brand) tends to increase how much we like it, even without conscious recognition."},{"id":"psy100h1-25","front":"What criteria help define a psychological disorder?","back":"Patterns of thought, emotion or behaviour that are deviant (unusual in context), distressing to the person and dysfunctional (they interfere with daily life). Diagnosis uses systems such as the DSM-5."},{"id":"psy100h1-26","front":"What are the core features of major depressive disorder?","back":"At least 2 weeks of depressed mood or loss of interest or pleasure (anhedonia), plus other symptoms such as sleep or appetite change, fatigue, worthlessness, poor concentration or suicidal thoughts, causing significant impairment."},{"id":"psy100h1-27","front":"Bipolar I vs bipolar II disorder","back":"Bipolar I requires at least one full manic episode (elevated mood, little need for sleep, grandiosity, risky behaviour). Bipolar II involves hypomanic episodes, which are milder and less impairing, plus major depressive episodes."},{"id":"psy100h1-28","front":"Positive vs negative symptoms of schizophrenia","back":"Positive symptoms are excesses added to normal experience: hallucinations, delusions, disorganized speech. Negative symptoms are deficits: flat affect, reduced speech, lack of motivation and social withdrawal."},{"id":"psy100h1-29","front":"What is the dopamine hypothesis of schizophrenia?","back":"Excess dopamine activity, especially in certain pathways, contributes to positive symptoms. It is supported by antipsychotics that block D2 receptors and by stimulants that can trigger psychosis. It is incomplete, since glutamate and brain structure are also involved."},{"id":"psy100h1-30","front":"Generalized anxiety disorder vs panic disorder vs specific phobia","back":"GAD: persistent, excessive worry about many things for at least 6 months. Panic disorder: recurrent unexpected panic attacks plus fear of future attacks. Specific phobia: intense, irrational fear of a particular object or situation, leading to avoidance."},{"id":"psy100h1-31","front":"Obsessions vs compulsions in OCD","back":"Obsessions are intrusive, unwanted thoughts or urges that cause anxiety (for example fear of germs). Compulsions are repetitive behaviours or mental acts performed to reduce that anxiety (for example repeated handwashing)."},{"id":"psy100h1-32","front":"How does cognitive behavioural therapy differ from psychodynamic therapy?","back":"CBT is structured and present-focused: it identifies and challenges distorted thoughts and changes behaviour, for example through exposure. Psychodynamic therapy explores unconscious conflicts and past experiences to build insight."},{"id":"psy100h1-33","front":"What is the diathesis-stress model?","back":"Psychological disorders arise from an interaction between a predisposition or vulnerability (the diathesis, such as genetic risk) and environmental stressors. Neither alone is usually enough."},{"id":"psy100h1-34","front":"What are the three stages of Selye''s general adaptation syndrome?","back":"Alarm (the initial fight-or-flight reaction), resistance (sustained physiological effort to cope) and exhaustion (resources become depleted, increasing vulnerability to illness)."}],"quizzes":[],"seed":1,"look":{"color":"#4F46E5","icon":"psych"}}'::jsonb);   -- https://artsci.calendar.utoronto.ca/course/psy100h1
select pg_temp.sb_seed('seed:utoronto-ca:bio130h1', 'utoronto.ca', 'BIO130H1', 'BIO130 Exam Review: Gene Expression, Membranes, Protein Sorting, Cytoskeleton and Cell Cycle', '{"v":1,"app":"studyboard","type":"deck","name":"BIO130 Exam Review: Gene Expression, Membranes, Protein Sorting, Cytoskeleton and Cell Cycle","course":{"code":"BIO130H1","name":"Molecular and Cell Biology"},"cards":[{"id":"bio130h1-1","front":"State the central dogma and its best-known exception.","back":"Information flows from DNA to RNA (transcription) to protein (translation). Retroviruses such as HIV use reverse transcriptase to copy RNA back into DNA."},{"id":"bio130h1-2","front":"How does DNA differ from RNA chemically?","back":"DNA has deoxyribose (no 2'' OH), uses thymine and is usually double-stranded. RNA has ribose (with a 2'' OH), uses uracil in place of thymine and is usually single-stranded and less stable."},{"id":"bio130h1-3","front":"If a DNA sample is 30% adenine, what are the percentages of T, G and C?","back":"By Chargaff''s rules A = T and G = C. So T = 30%, leaving 40% for G + C: G = 20% and C = 20%."},{"id":"bio130h1-4","front":"What does it mean that the two DNA strands are antiparallel?","back":"They run in opposite directions: one strand runs 5'' to 3'' and its partner 3'' to 5''. The 5'' end has a free phosphate and the 3'' end a free OH, where new nucleotides are added."},{"id":"bio130h1-5","front":"What is the end-replication problem, and how does telomerase address it?","back":"When the final primer at a linear chromosome end is removed, the lagging strand cannot be completed, so chromosomes shorten each round. Telomerase uses its own RNA template to extend the repetitive telomere DNA, mainly in germ cells, stem cells and many cancers."},{"id":"bio130h1-6","front":"How do cells keep DNA replication accurate?","back":"DNA polymerase has 3'' to 5'' exonuclease proofreading that removes mispaired nucleotides as it goes. Mismatch repair then fixes errors that escape proofreading by recognizing the newly made strand."},{"id":"bio130h1-7","front":"What is a nucleosome, and how does euchromatin differ from heterochromatin?","back":"A nucleosome is about 147 bp of DNA wrapped around a histone octamer (two copies each of H2A, H2B, H3 and H4). Euchromatin is loosely packed and transcriptionally active. Heterochromatin is densely packed and mostly silent."},{"id":"bio130h1-8","front":"How do histone acetylation and DNA methylation affect transcription?","back":"Acetylation of histone lysines neutralizes their positive charge, loosening chromatin and generally increasing transcription. Methylation of cytosines at CpG sites in promoters generally silences genes."},{"id":"bio130h1-9","front":"What is needed to start transcription of a eukaryotic protein-coding gene?","back":"RNA polymerase II plus general transcription factors assemble at the promoter, often recognizing the TATA box through TFIID (TATA-binding protein), to form the preinitiation complex."},{"id":"bio130h1-10","front":"How can an enhancer far from a gene increase its transcription?","back":"Activator proteins bind the enhancer, and the DNA loops so the activators can contact the promoter complex, often through the Mediator complex and coactivators, which recruit or stabilize RNA polymerase II."},{"id":"bio130h1-11","front":"When is the lac operon expressed at high levels in E. coli, and why?","back":"When lactose is present and glucose is low. Allolactose binds the lac repressor so it releases the operator, and the low glucose raises cAMP, so CAP-cAMP binds and strongly stimulates RNA polymerase."},{"id":"bio130h1-12","front":"What is alternative splicing?","back":"Different combinations of exons from the same pre-mRNA are joined by the spliceosome (snRNPs), so one gene can encode several protein isoforms."},{"id":"bio130h1-13","front":"What are the key features of the genetic code?","back":"Codons are triplets, read without gaps and without overlap. The code is degenerate (most amino acids have several codons) and nearly universal. AUG is the start codon (Met); UAA, UAG and UGA are stop codons."},{"id":"bio130h1-14","front":"What do aminoacyl-tRNA synthetases do, and why are they crucial?","back":"Each one attaches the correct amino acid to its matching tRNAs, using ATP. They make the actual connection between codon and amino acid, so their accuracy determines translation accuracy."},{"id":"bio130h1-15","front":"Silent vs missense vs nonsense vs frameshift mutations","back":"Silent: the codon changes but the amino acid does not. Missense: a different amino acid. Nonsense: an early stop codon. Frameshift: an insertion or deletion not in multiples of 3 shifts the reading frame and usually ruins the protein."},{"id":"bio130h1-16","front":"How do secreted proteins enter the ER?","back":"An N-terminal signal sequence is bound by the signal recognition particle (SRP) as it emerges from the ribosome. SRP pauses translation and brings the ribosome to the SRP receptor on the ER, where the protein is threaded through a translocon as it is made (cotranslationally)."},{"id":"bio130h1-17","front":"How do proteins get into the nucleus?","back":"A nuclear localization signal (NLS) is recognized by importin, which carries the protein through the nuclear pore complex. Ran-GTP in the nucleus releases the cargo, which keeps import one-way."},{"id":"bio130h1-18","front":"Where are proteins glycosylated as they pass through the secretory pathway?","back":"N-linked glycosylation starts in the ER, where a preformed oligosaccharide is added to asparagine. The Golgi then trims and modifies the sugars as the protein moves from the cis face to the trans face."},{"id":"bio130h1-19","front":"How are enzymes targeted to the lysosome?","back":"In the Golgi they are tagged with mannose-6-phosphate. M6P receptors in the trans-Golgi network package them into vesicles bound for endosomes and lysosomes, where the low pH releases them."},{"id":"bio130h1-20","front":"Constitutive vs regulated secretion","back":"Constitutive secretion happens continuously in all cells, for example releasing extracellular matrix proteins. Regulated secretion stores cargo in secretory vesicles until a signal, such as a rise in Ca2+, triggers release (for example insulin or neurotransmitters)."},{"id":"bio130h1-21","front":"What is receptor-mediated endocytosis? Give an example.","back":"Ligands bind specific surface receptors that cluster in clathrin-coated pits, which pinch off as vesicles (with the help of dynamin). Cells take up LDL cholesterol this way."},{"id":"bio130h1-22","front":"Integral vs peripheral membrane proteins","back":"Integral proteins are embedded in the bilayer, often spanning it with hydrophobic alpha helices of about 20 amino acids; detergents are needed to remove them. Peripheral proteins attach loosely to the surface or to integral proteins."},{"id":"bio130h1-23","front":"Channels vs transporters (carriers)","back":"Channels form a pore that lets specific ions flow rapidly down their gradient, often gated. Transporters bind their solute and change shape to move it across; this is slower and is needed for active transport."},{"id":"bio130h1-24","front":"What does the Na+/K+ ATPase do, and why is it important?","back":"Each ATP hydrolyzed pumps 3 Na+ out of the cell and 2 K+ in. It maintains the ion gradients and membrane potential that power secondary transport, control cell volume and allow nerve signalling."},{"id":"bio130h1-25","front":"Give an example of secondary active transport.","back":"The Na+/glucose symporter in intestinal cells uses Na+ flowing into the cell down its gradient (set up by the Na+/K+ ATPase) to bring glucose in against its own concentration gradient."},{"id":"bio130h1-26","front":"Compare the three cytoskeletal filament types.","back":"Microfilaments (actin, about 7 nm): cell shape, crawling and muscle contraction. Microtubules (tubulin, about 25 nm): tracks for transport, the mitotic spindle, cilia. Intermediate filaments (for example keratins and lamins, about 10 nm): mechanical strength."},{"id":"bio130h1-27","front":"Kinesin vs dynein vs myosin","back":"Kinesins mostly walk toward the plus end of microtubules (outward toward the cell periphery). Dyneins walk toward the minus end (toward the centrosome). Myosins move along actin filaments. All use ATP hydrolysis."},{"id":"bio130h1-28","front":"What is dynamic instability of microtubules?","back":"Microtubules switch between growing and rapidly shrinking. A GTP-tubulin cap at the plus end stabilizes growth; if GTP is hydrolyzed faster than new subunits are added, the cap is lost and the microtubule shrinks (catastrophe)."},{"id":"bio130h1-29","front":"How do cyclins and Cdks drive the cell cycle?","back":"Cyclin-dependent kinases (Cdks) are active only when bound to a cyclin. Cyclin levels rise and fall through the cycle, so different cyclin-Cdk complexes phosphorylate targets that trigger S phase or mitosis. Cyclins are then destroyed by ubiquitin-mediated proteolysis."},{"id":"bio130h1-30","front":"What does the spindle assembly checkpoint monitor?","back":"It delays anaphase until every kinetochore is properly attached to spindle microtubules. Only then is the APC/C activated to trigger separation of the sister chromatids."},{"id":"bio130h1-31","front":"Proto-oncogenes vs tumour suppressor genes","back":"Proto-oncogenes (such as Ras) promote growth; a gain-of-function mutation in one copy can drive cancer. Tumour suppressors (such as p53 and Rb) restrain growth; usually both copies must be lost. p53 halts the cycle or triggers apoptosis after DNA damage."},{"id":"bio130h1-32","front":"What is apoptosis, and which enzymes carry it out?","back":"Programmed cell death that orderly dismantles a cell without inflammation. Caspases (cysteine proteases) are activated in a cascade, for example after cytochrome c is released from mitochondria."},{"id":"bio130h1-33","front":"Outline G protein-coupled receptor (GPCR) signalling through cAMP.","back":"A ligand binds the GPCR, which makes the G alpha subunit swap GDP for GTP. G alpha s activates adenylyl cyclase to make cAMP, which activates protein kinase A (PKA). The signal ends when G alpha hydrolyzes GTP."},{"id":"bio130h1-34","front":"Outline receptor tyrosine kinase signalling to the MAP kinase pathway.","back":"Ligand binding makes the receptors pair up and phosphorylate each other''s tyrosines. Adaptor proteins recruit a GEF that activates Ras (GDP to GTP). Ras starts a kinase cascade (Raf, then MEK, then ERK) that changes gene expression and promotes proliferation."}],"quizzes":[],"seed":1,"look":{"color":"#0D9488","icon":"bio"}}'::jsonb);   -- https://artsci.calendar.utoronto.ca/course/bio130h1
select pg_temp.sb_seed('seed:utoronto-ca:mat135h1', 'utoronto.ca', 'MAT135H1', 'MAT135 Exam Review: Limits, Derivatives, Optimization and Differential Equations', '{"v":1,"app":"studyboard","type":"deck","name":"MAT135 Exam Review: Limits, Derivatives, Optimization and Differential Equations","course":{"code":"MAT135H1","name":"Calculus I"},"cards":[{"id":"mat135h1-1","front":"When does lim (x→a) f(x) exist?","back":"When the left-hand limit and the right-hand limit both exist and are equal. The value of f(a) itself does not matter; f need not even be defined at a."},{"id":"mat135h1-2","front":"Evaluate lim (x→2) (x^2 - 4)/(x - 2).","back":"Factor: (x - 2)(x + 2)/(x - 2) = x + 2 for x ≠ 2, so the limit is 4."},{"id":"mat135h1-3","front":"What is lim (x→0) sin(x)/x?","back":"1, with x in radians. This standard limit is used to derive that d/dx [sin x] = cos x."},{"id":"mat135h1-4","front":"What three conditions make f continuous at x = a?","back":"f(a) is defined, lim (x→a) f(x) exists, and lim (x→a) f(x) = f(a)."},{"id":"mat135h1-5","front":"State the Intermediate Value Theorem.","back":"If f is continuous on [a, b] and N is between f(a) and f(b), then f(c) = N for some c in (a, b). It is often used to show an equation has a root, for example when f(a) < 0 < f(b)."},{"id":"mat135h1-6","front":"Find the horizontal asymptote of f(x) = (3x^2 + 1)/(2x^2 - 5).","back":"The degrees of the top and bottom are equal, so the asymptote is the ratio of the leading coefficients: y = 3/2."},{"id":"mat135h1-7","front":"State the limit definition of the derivative.","back":"f''(x) = lim (h→0) [f(x + h) - f(x)]/h. It is the slope of the tangent line, or the instantaneous rate of change of f at x."},{"id":"mat135h1-8","front":"Does differentiable imply continuous? Does continuous imply differentiable?","back":"Differentiable implies continuous. The converse is false: f(x) = |x| is continuous at 0 but not differentiable there, because it has a corner."},{"id":"mat135h1-9","front":"Basic derivative rules: x^n, e^x, ln x, a^x","back":"d/dx [x^n] = n·x^(n-1). d/dx [e^x] = e^x. d/dx [ln x] = 1/x. d/dx [a^x] = a^x·ln a."},{"id":"mat135h1-10","front":"State the product rule and the quotient rule.","back":"(fg)'' = f''g + fg''. (f/g)'' = (f''g - fg'')/g^2. A common mistake is writing (fg)'' = f''·g'', which is wrong."},{"id":"mat135h1-11","front":"State the chain rule and find d/dx [sin(x^3)].","back":"d/dx [f(g(x))] = f''(g(x))·g''(x). So d/dx [sin(x^3)] = cos(x^3)·3x^2."},{"id":"mat135h1-12","front":"Derivatives of sin x, cos x and tan x","back":"d/dx [sin x] = cos x. d/dx [cos x] = -sin x. d/dx [tan x] = sec^2 x."},{"id":"mat135h1-13","front":"Use implicit differentiation to find dy/dx for x^2 + y^2 = 25.","back":"Differentiate both sides: 2x + 2y·(dy/dx) = 0, so dy/dx = -x/y."},{"id":"mat135h1-14","front":"Differentiate y = x^x.","back":"Take logs: ln y = x·ln x. Differentiate: y''/y = ln x + 1. So y'' = x^x·(ln x + 1)."},{"id":"mat135h1-15","front":"A circle''s radius grows at 2 cm/s. How fast is its area growing when r = 5 cm?","back":"A = πr^2, so dA/dt = 2πr·(dr/dt) = 2π(5)(2) = 20π cm^2/s, about 62.8 cm^2/s."},{"id":"mat135h1-16","front":"Linear approximation formula; use it to estimate sqrt(4.1).","back":"L(x) = f(a) + f''(a)(x - a). With f(x) = sqrt(x) and a = 4: f''(4) = 1/(2·2) = 1/4, so sqrt(4.1) ≈ 2 + (1/4)(0.1) = 2.025."},{"id":"mat135h1-17","front":"What is a critical point?","back":"A point c in the domain of f where f''(c) = 0 or f''(c) does not exist. Local maxima and minima can occur only at critical points (or at the endpoints of an interval)."},{"id":"mat135h1-18","front":"First derivative test","back":"If f'' changes from + to - at c, f has a local maximum at c. If f'' changes from - to +, it has a local minimum. If f'' does not change sign, c is not a local extremum."},{"id":"mat135h1-19","front":"What does f'''' tell you, and what is an inflection point?","back":"If f'''' > 0, f is concave up; if f'''' < 0, f is concave down. An inflection point is where the concavity changes. For example, f(x) = x^3 has one at x = 0."},{"id":"mat135h1-20","front":"How do you find the absolute max and min of a continuous function on [a, b]?","back":"By the Extreme Value Theorem both exist. Evaluate f at every critical point inside (a, b) and at both endpoints; the largest value is the absolute max and the smallest is the absolute min."},{"id":"mat135h1-21","front":"State the Mean Value Theorem.","back":"If f is continuous on [a, b] and differentiable on (a, b), then f''(c) = [f(b) - f(a)]/(b - a) for some c in (a, b). So at some instant, the instantaneous rate equals the average rate."},{"id":"mat135h1-22","front":"A rectangle has perimeter 40. What dimensions maximize its area?","back":"With width x and length 20 - x, A(x) = x(20 - x). Then A''(x) = 20 - 2x = 0 gives x = 10. A 10 x 10 square gives the maximum area of 100."},{"id":"mat135h1-23","front":"State L''Hôpital''s rule.","back":"If lim f(x)/g(x) has the form 0/0 or ∞/∞, it equals lim f''(x)/g''(x) when that limit exists. For example, lim (x→0) (e^x - 1)/x = lim e^x/1 = 1."},{"id":"mat135h1-24","front":"How do you check whether a function solves a differential equation?","back":"Substitute the function and its derivatives into the equation and confirm both sides are equal for all t. For example, y = e^(3t) solves y'' = 3y because y'' = 3e^(3t) = 3y."},{"id":"mat135h1-25","front":"Solve dy/dt = ky with y(0) = y0.","back":"y(t) = y0·e^(kt). If k > 0 the solution grows exponentially; if k < 0 it decays exponentially."},{"id":"mat135h1-26","front":"How do you find doubling time and half-life for exponential models?","back":"For growth y = y0·e^(kt), the doubling time is ln(2)/k. For decay y = y0·e^(-kt), the half-life is ln(2)/k."},{"id":"mat135h1-27","front":"Find and classify the equilibria of dy/dt = y(3 - y).","back":"Set dy/dt = 0: y = 0 and y = 3. Near y = 0 the solution moves away (unstable). Near y = 3, dy/dt > 0 just below and < 0 just above, so solutions move toward 3 (stable)."},{"id":"mat135h1-28","front":"What is a slope field?","back":"A grid of short line segments whose slope at each point (t, y) equals dy/dt given by the differential equation. Solution curves follow the segments, which shows their behaviour without solving the equation."},{"id":"mat135h1-29","front":"Euler''s method: give the formula and apply two steps to dy/dt = y, y(0) = 1, h = 0.5.","back":"y_(n+1) = y_n + h·f(t_n, y_n). Step 1: 1 + 0.5(1) = 1.5. Step 2: 1.5 + 0.5(1.5) = 2.25. So y(1) ≈ 2.25, while the exact value is e ≈ 2.718. Euler''s method underestimates here because the solution is concave up."},{"id":"mat135h1-30","front":"Logistic equation: what do r and K mean, and when is growth fastest?","back":"dP/dt = rP(1 - P/K). r is the intrinsic growth rate and K is the carrying capacity, a stable equilibrium. Growth is fastest at P = K/2."},{"id":"mat135h1-31","front":"Newton''s law of cooling","back":"dT/dt = -k(T - Ta), where k > 0 and Ta is the ambient temperature. The solution is T(t) = Ta + (T0 - Ta)e^(-kt), so the temperature approaches Ta exponentially."},{"id":"mat135h1-32","front":"Find d/dx [e^(2x)] and d/dx [ln(5x)].","back":"d/dx [e^(2x)] = 2e^(2x), by the chain rule. d/dx [ln(5x)] = 5/(5x) = 1/x."}],"quizzes":[],"seed":1,"look":{"color":"#3B6FE0","icon":"calc"}}'::jsonb);   -- https://artsci.calendar.utoronto.ca/course/mat135h1
select pg_temp.sb_seed('seed:utoronto-ca:eco101h1', 'utoronto.ca', 'ECO101H1', 'ECO101 Exam Review: Market Equilibrium, Elasticity, Welfare, Costs and Market Power', '{"v":1,"app":"studyboard","type":"deck","name":"ECO101 Exam Review: Market Equilibrium, Elasticity, Welfare, Costs and Market Power","course":{"code":"ECO101H1","name":"Principles of Microeconomics"},"cards":[{"id":"eco101h1-1","front":"Positive vs normative statements","back":"A positive statement describes how the economy works and can be tested (\"a higher minimum wage reduces teen employment\"). A normative statement is a value judgment about what ought to be (\"the minimum wage should be raised\")."},{"id":"eco101h1-2","front":"What is the marginal principle, and why should sunk costs be ignored?","back":"Do an activity up to the point where marginal benefit equals marginal cost. Sunk costs cannot be recovered whatever you choose, so they should not affect forward-looking decisions."},{"id":"eco101h1-3","front":"Demand is Qd = 100 - 2P and supply is Qs = -20 + 2P. Find the equilibrium.","back":"Set 100 - 2P = -20 + 2P, so 4P = 120 and P = 30. Then Q = 100 - 60 = 40."},{"id":"eco101h1-4","front":"With Qd = 100 - 2P and Qs = -20 + 2P, find consumer and producer surplus at equilibrium (P = 30, Q = 40).","back":"The demand choke price is 50 and the supply intercept price is 10. CS = 0.5 x 40 x (50 - 30) = 400. PS = 0.5 x 40 x (30 - 10) = 400."},{"id":"eco101h1-5","front":"In the same market (Qd = 100 - 2P, Qs = -20 + 2P), a $4 per-unit tax is placed on sellers. Find the new outcome.","back":"Supply becomes Qs = -20 + 2(P - 4). Setting 100 - 2P = -28 + 2P gives P = 32 and Q = 36. Buyers pay $32 and sellers keep $28, so the burden is split equally. Revenue = 4 x 36 = 144. DWL = 0.5 x 4 x 4 = 8."},{"id":"eco101h1-6","front":"How does price elasticity change along a straight-line demand curve?","back":"Demand is elastic on the upper (high-price) part, unit elastic at the midpoint and inelastic on the lower part. Slope is constant, but elasticity is not."},{"id":"eco101h1-7","front":"Perfectly inelastic vs perfectly elastic demand","back":"Perfectly inelastic (elasticity 0): vertical curve; quantity does not respond to price. Perfectly elastic (infinite elasticity): horizontal curve; any price rise drops quantity to zero, as for a single competitive firm''s demand."},{"id":"eco101h1-8","front":"Income rises 10% and the quantity demanded of a good falls 5%. What is the income elasticity, and what kind of good is it?","back":"Income elasticity = -5%/10% = -0.5. A negative value means it is an inferior good."},{"id":"eco101h1-9","front":"The price of good B rises 20% and the quantity demanded of good A rises 10%. Find the cross-price elasticity and the relationship.","back":"Cross-price elasticity = 10%/20% = +0.5. A positive value means A and B are substitutes."},{"id":"eco101h1-10","front":"What makes supply more price elastic?","back":"More time to adjust, spare production capacity, inputs that are easy to obtain, and goods that can be stored. Supply is usually more elastic in the long run."},{"id":"eco101h1-11","front":"Why is a competitive market equilibrium efficient?","back":"At the equilibrium quantity, the marginal benefit to buyers (demand) equals the marginal cost to sellers (supply), so total surplus is maximized. Producing more or less creates deadweight loss."},{"id":"eco101h1-12","front":"What are the effects of an import quota?","back":"It limits imports, raising the domestic price and lowering consumer surplus. Domestic producers gain. Whoever holds the import licences collects quota rents, and there is deadweight loss from inefficient domestic production and lost consumption."},{"id":"eco101h1-13","front":"Effects of a tariff on a small open economy","back":"The domestic price rises by the tariff. Domestic production rises, consumption and imports fall, and the government collects tariff revenue. There are two deadweight loss triangles: one from production and one from consumption."},{"id":"eco101h1-14","front":"Budget constraint: equation and slope","back":"Px·X + Py·Y = I. Plotted with Y on the vertical axis, the slope is -Px/Py. A change in income shifts the line in parallel; a change in one price rotates it."},{"id":"eco101h1-15","front":"What is the consumer''s optimum with indifference curves?","back":"The point where an indifference curve is tangent to the budget line: MRS = MUx/MUy = Px/Py. The rate at which the consumer is willing to trade goods equals the rate the market allows."},{"id":"eco101h1-16","front":"Substitution effect vs income effect of a price decrease","back":"Substitution effect: the good is now relatively cheaper, so people buy more of it. Income effect: purchasing power rises, which increases quantity for a normal good and decreases it for an inferior good."},{"id":"eco101h1-17","front":"Marginal product vs average product of labour","back":"MPL = ΔQ/ΔL, the extra output from one more worker. APL = Q/L. When MPL is above APL, the average rises; when MPL is below APL, the average falls."},{"id":"eco101h1-18","front":"TFC = $100, TVC = $200 and Q = 10. Find AFC, AVC and ATC.","back":"AFC = 100/10 = $10. AVC = 200/10 = $20. ATC = 300/10 = $30, which also equals AFC + AVC."},{"id":"eco101h1-19","front":"Economies vs diseconomies of scale","back":"Economies of scale: long-run average cost falls as output rises (from specialization or spreading large fixed costs). Diseconomies: LRAC rises at very large sizes (coordination problems). Minimum efficient scale is where LRAC first reaches its lowest level."},{"id":"eco101h1-20","front":"What is a perfectly competitive firm''s short-run supply curve?","back":"Its marginal cost curve above the minimum of average variable cost. Below that price the firm shuts down and produces nothing."},{"id":"eco101h1-21","front":"A perfectly competitive industry faces a permanent increase in demand. What happens in the long run?","back":"In the short run, price rises and firms earn economic profit. That profit attracts entry, which shifts industry supply right until price falls back to minimum ATC (in a constant-cost industry) and profit returns to zero."},{"id":"eco101h1-22","front":"A monopolist faces P = 100 - Q with MC = 20. Find Q, P and the deadweight loss.","back":"MR = 100 - 2Q. Setting MR = MC gives Q = 40 and P = 60. A competitive market would produce Q = 80, where P = MC. DWL = 0.5 x (60 - 20) x (80 - 40) = 800."},{"id":"eco101h1-23","front":"What are common barriers to entry that sustain a monopoly?","back":"Control of a key resource, government protection (patents, licences), economies of scale large enough to create a natural monopoly, network effects, and high startup costs."},{"id":"eco101h1-24","front":"Why is regulating a natural monopoly at P = MC a problem, and what is the alternative?","back":"For a natural monopoly ATC is falling, so MC is below ATC and pricing at MC causes losses that require a subsidy. Average-cost pricing (P = ATC) lets the firm break even at the cost of some inefficiency."},{"id":"eco101h1-25","front":"What happens under perfect (first-degree) price discrimination?","back":"Each buyer pays their maximum willingness to pay. Output reaches the efficient level, so there is no deadweight loss, but the firm captures all the surplus and consumer surplus is zero."},{"id":"eco101h1-26","front":"What is a dominant strategy, and how does it differ from a Nash equilibrium?","back":"A dominant strategy is a player''s best choice whatever the others do. A Nash equilibrium is a set of strategies in which no player can do better by changing their own strategy alone. If every player has a dominant strategy, those strategies form a Nash equilibrium."},{"id":"eco101h1-27","front":"Why are cartels hard to sustain?","back":"Each member gains by secretly producing more than its quota at the high cartel price, so cheating is individually rational. That is a prisoner''s dilemma. Cartels are also illegal under competition law in Canada and many other countries."},{"id":"eco101h1-28","front":"What does the Coase theorem say?","back":"If property rights are clearly defined and bargaining costs are low, private parties can negotiate an efficient outcome to an externality, whoever is initially given the right."},{"id":"eco101h1-29","front":"Positive externality: market outcome and policy fix","back":"When there are external benefits, such as vaccination or education, social benefit exceeds private benefit, so the market underproduces. A subsidy equal to the marginal external benefit can raise output to the efficient level."},{"id":"eco101h1-30","front":"What is the tragedy of the commons?","back":"Common resources are rival but non-excludable, so each user ignores the cost their use imposes on others, leading to overuse (for example overfishing). Fixes include quotas, tradable permits and property rights."},{"id":"eco101h1-31","front":"How many workers does a competitive firm hire?","back":"Labour demand is derived from output demand. The firm hires until the marginal revenue product of labour, MRPL = MPL x P, equals the wage."}],"quizzes":[],"seed":1,"look":{"color":"#EA580C","icon":"econ"}}'::jsonb);   -- https://artsci.calendar.utoronto.ca/course/eco101h1
select pg_temp.sb_seed('seed:bcit-ca:bhsc-1200', 'bcit.ca', 'BHSC 1200', 'BHSC 1200 Exam Review: Cells, Tissues and Organ Systems in Homeostasis', '{"v":1,"app":"studyboard","type":"deck","name":"BHSC 1200 Exam Review: Cells, Tissues and Organ Systems in Homeostasis","course":{"code":"BHSC 1200","name":"Human Anatomy and Physiology"},"cards":[{"id":"bhsc-1200-1","front":"Describe anatomical position and the paired terms proximal/distal and medial/lateral.","back":"Standing upright, facing forward, arms at the sides, palms forward. Proximal/distal: closer to or farther from where a limb attaches. Medial/lateral: toward or away from the body''s midline."},{"id":"bhsc-1200-2","front":"Sagittal vs frontal (coronal) vs transverse planes","back":"Sagittal divides the body into left and right parts. Frontal (coronal) divides it into front (anterior) and back (posterior). Transverse divides it into upper (superior) and lower (inferior) parts."},{"id":"bhsc-1200-3","front":"What are the three components of a negative feedback loop? Give an example.","back":"A receptor detects a change, a control centre compares it to the set point, and an effector reverses the change. Example: when body temperature rises, the hypothalamus triggers sweating and skin vasodilation."},{"id":"bhsc-1200-4","front":"Give two examples of positive feedback in the body.","back":"Childbirth (stretching of the cervix triggers more oxytocin and stronger contractions) and blood clotting (activated platelets recruit more platelets). Positive feedback amplifies a change until an endpoint is reached."},{"id":"bhsc-1200-5","front":"What are the four primary tissue types?","back":"Epithelial (covers surfaces and lines cavities), connective (supports and binds, includes bone and blood), muscle (contracts) and nervous (conducts signals)."},{"id":"bhsc-1200-6","front":"Where is simple squamous epithelium found, and why does it suit those sites?","back":"In the air sacs of the lungs (alveoli) and the lining of capillaries. A single thin layer of flat cells allows rapid diffusion of gases and nutrients."},{"id":"bhsc-1200-7","front":"Functions of the mitochondria, ribosomes, rough ER, Golgi and lysosomes","back":"Mitochondria make most ATP. Ribosomes build proteins. Rough ER folds and processes proteins. Golgi modifies, sorts and packages them. Lysosomes digest worn-out parts and debris with enzymes."},{"id":"bhsc-1200-8","front":"Mitosis vs meiosis","back":"Mitosis makes two genetically identical diploid cells for growth and repair. Meiosis makes four genetically different haploid gametes, with two divisions and crossing over."},{"id":"bhsc-1200-9","front":"What happens in the stratum basale, and what do melanocytes do?","back":"The stratum basale is the deepest layer of the epidermis, where cells divide to replace those shed at the surface. Melanocytes there make melanin, which absorbs UV light and protects cell DNA."},{"id":"bhsc-1200-10","front":"Osteoblasts vs osteoclasts vs osteocytes","back":"Osteoblasts build new bone matrix. Osteoclasts break down bone, releasing calcium. Osteocytes are mature bone cells trapped in the matrix that maintain it."},{"id":"bhsc-1200-11","front":"How do PTH and calcitonin regulate blood calcium?","back":"Parathyroid hormone raises blood Ca2+ by stimulating osteoclasts, increasing kidney reabsorption and activating vitamin D. Calcitonin from the thyroid lowers blood Ca2+ by inhibiting osteoclasts."},{"id":"bhsc-1200-12","front":"Axial vs appendicular skeleton","back":"Axial: skull, vertebral column, ribs and sternum, which protect and support the body''s core. Appendicular: the limbs plus the pectoral and pelvic girdles that attach them."},{"id":"bhsc-1200-13","front":"Summarize the sliding filament mechanism of skeletal muscle contraction.","back":"Ca2+ released from the sarcoplasmic reticulum binds troponin, which moves tropomyosin off actin''s binding sites. Myosin heads bind actin and pull (power stroke); ATP binding releases the myosin head so the cycle repeats."},{"id":"bhsc-1200-14","front":"Central vs peripheral nervous system, and somatic vs autonomic","back":"CNS: brain and spinal cord. PNS: all nerves outside it. Somatic: voluntary control of skeletal muscle. Autonomic: involuntary control of heart, smooth muscle and glands."},{"id":"bhsc-1200-15","front":"Sympathetic vs parasympathetic effects","back":"Sympathetic (fight or flight): faster heart rate, dilated pupils and airways, slower digestion. Parasympathetic (rest and digest): slower heart rate, constricted pupils, increased digestion."},{"id":"bhsc-1200-16","front":"List the parts of a reflex arc in order.","back":"Receptor, sensory (afferent) neuron, integration centre in the CNS (often an interneuron), motor (efferent) neuron, effector (muscle or gland)."},{"id":"bhsc-1200-17","front":"Steroid hormones vs peptide hormones","back":"Steroids (e.g., cortisol, estrogen) are lipid-soluble, cross the membrane and bind receptors inside the cell to change gene expression. Peptides (e.g., insulin) bind surface receptors and act through second messengers."},{"id":"bhsc-1200-18","front":"Insulin vs glucagon","back":"Both come from the pancreatic islets. Insulin (beta cells) lowers blood glucose by promoting uptake and storage as glycogen. Glucagon (alpha cells) raises blood glucose by breaking down glycogen."},{"id":"bhsc-1200-19","front":"Trace blood flow through the heart starting at the venae cavae.","back":"Venae cavae → right atrium → tricuspid valve → right ventricle → pulmonary valve → pulmonary arteries → lungs → pulmonary veins → left atrium → mitral valve → left ventricle → aortic valve → aorta."},{"id":"bhsc-1200-20","front":"Order of the cardiac conduction system","back":"SA node (pacemaker) → AV node (brief delay so the ventricles can fill) → bundle of His → right and left bundle branches → Purkinje fibres."},{"id":"bhsc-1200-21","front":"What do the P wave, QRS complex and T wave of an ECG represent?","back":"P wave: atrial depolarization. QRS complex: ventricular depolarization (atrial repolarization is hidden within it). T wave: ventricular repolarization."},{"id":"bhsc-1200-22","front":"Calculate cardiac output when heart rate is 70 beats/min and stroke volume is 70 mL.","back":"Cardiac output = HR × SV = 70 × 70 mL = 4900 mL/min, or about 4.9 L/min."},{"id":"bhsc-1200-23","front":"Main formed elements of blood and their functions","back":"Red blood cells carry O2 bound to hemoglobin. White blood cells defend against infection. Platelets (cell fragments) help form clots."},{"id":"bhsc-1200-24","front":"Innate vs adaptive immunity","back":"Innate immunity is fast and non-specific (skin, inflammation, phagocytes). Adaptive immunity is slower at first but specific and has memory: B cells make antibodies, and T cells kill infected cells or coordinate the response."},{"id":"bhsc-1200-25","front":"What are the cardinal signs of inflammation?","back":"Redness, heat, swelling and pain, sometimes with loss of function. Vasodilation and leaky capillaries bring more blood, fluid and white blood cells to the injured area."},{"id":"bhsc-1200-26","front":"Name three functions of the lymphatic system.","back":"Returns excess tissue fluid to the blood, absorbs dietary fats from the small intestine (through lacteals), and filters lymph through lymph nodes as part of immune defence."},{"id":"bhsc-1200-27","front":"Explain inspiration using Boyle''s law.","back":"The diaphragm and external intercostals contract, increasing thoracic volume. As volume rises, pressure in the lungs falls below atmospheric pressure, so air flows in."},{"id":"bhsc-1200-28","front":"How is most CO2 carried in the blood?","back":"About 70% travels as bicarbonate (HCO3−) in plasma, formed in red blood cells by carbonic anhydrase. The rest is bound to hemoglobin or dissolved."},{"id":"bhsc-1200-29","front":"What is the main chemical stimulus driving breathing rate?","back":"Rising CO2 (and the falling pH it causes), detected mainly by central chemoreceptors in the medulla. Low O2 becomes a strong stimulus only when it falls a lot."},{"id":"bhsc-1200-30","front":"Match each digestive enzyme or secretion to its target: salivary amylase, pepsin, pancreatic lipase, bile.","back":"Salivary amylase: starch. Pepsin (stomach): proteins. Pancreatic lipase: fats (triglycerides). Bile (liver, stored in the gallbladder) has no enzymes; it emulsifies fats."},{"id":"bhsc-1200-31","front":"Why is the small intestine so effective at absorption?","back":"Circular folds, villi and microvilli give it a huge surface area, and it is long. Most nutrient absorption occurs there."},{"id":"bhsc-1200-32","front":"What happens at each part of the nephron?","back":"Glomerulus: filtration of plasma. Proximal tubule: reabsorbs most water, glucose and salts. Loop of Henle: concentrates the medulla. Distal tubule and collecting duct: hormone-controlled fine-tuning."},{"id":"bhsc-1200-33","front":"ADH vs aldosterone","back":"ADH (from the posterior pituitary) makes the collecting ducts more permeable to water, giving concentrated urine. Aldosterone (adrenal cortex) increases Na+ reabsorption and K+ secretion; water follows the sodium."},{"id":"bhsc-1200-34","front":"Outline the renin-angiotensin-aldosterone system.","back":"Low blood pressure leads the kidneys to release renin, which leads to angiotensin II. Angiotensin II constricts blood vessels and triggers aldosterone release and thirst, raising blood volume and pressure."},{"id":"bhsc-1200-35","front":"Which hormone surge triggers ovulation?","back":"A mid-cycle surge of luteinizing hormone (LH) from the anterior pituitary, triggered by rising estrogen."}],"quizzes":[],"seed":1,"look":{"color":"#DC2626","icon":"med"}}'::jsonb);   -- https://www.bcit.ca/courses/human-anatomy-and-physiology-bhsc-1200/
select pg_temp.sb_seed('seed:bcit-ca:comp-1510', 'bcit.ca', 'COMP 1510', 'COMP 1510 Exam Review: Programming Fundamentals, Testing, Error Handling and OOP Design', '{"v":1,"app":"studyboard","type":"deck","name":"COMP 1510 Exam Review: Programming Fundamentals, Testing, Error Handling and OOP Design","course":{"code":"COMP 1510","name":"Programming Methods"},"cards":[{"id":"comp-1510-1","front":"Name the three basic control structures every algorithm can be built from.","back":"Sequence (steps run in order), selection (if/else decisions) and iteration (loops)."},{"id":"comp-1510-2","front":"What is a variable''s scope?","back":"The region of the program where the name can be used. A variable declared inside a function or block is usually not accessible outside it."},{"id":"comp-1510-3","front":"What is a common pitfall with dividing two integers?","back":"In many languages (e.g., Java, C), integer / integer truncates: 7 / 2 gives 3, not 3.5. Convert one operand to floating point if you need the fractional part."},{"id":"comp-1510-4","front":"Primitive values vs references to objects","back":"A primitive variable stores the value itself (e.g., an int). A reference variable stores the address of an object, so two variables can refer to the same object and both see changes to it."},{"id":"comp-1510-5","front":"Identity vs equality when comparing objects","back":"Identity asks whether two references point to the same object. Equality asks whether two objects have the same contents. Two separate strings can be equal in content but not identical."},{"id":"comp-1510-6","front":"What is decomposition?","back":"Breaking a large problem into smaller, independent pieces (functions, classes, modules), each with a clear purpose and interface, that can be built and tested separately."},{"id":"comp-1510-7","front":"What is encapsulation?","back":"Bundling an object''s data together with the methods that operate on it, so the data is managed through those methods instead of being changed directly from outside."},{"id":"comp-1510-8","front":"What is information hiding, and why does it help?","back":"Keeping internal details private and exposing only a public interface. Callers depend only on the interface, so the internals can change without breaking other code."},{"id":"comp-1510-9","front":"What is message passing in object-oriented programming?","back":"Objects interact by calling each other''s public methods (sending messages) instead of reaching into each other''s data."},{"id":"comp-1510-10","front":"Class vs object","back":"A class is a blueprint defining data (fields or attributes) and behaviour (methods). An object is a specific instance created from that class, with its own values."},{"id":"comp-1510-11","front":"What is a constructor?","back":"A special method that runs when an object is created. It sets the object''s initial state, typically by assigning its fields from the arguments."},{"id":"comp-1510-12","front":"Instance variables vs class (static) variables","back":"Each object has its own copy of an instance variable. A class variable is shared by all instances of the class, e.g., a counter of how many objects have been created."},{"id":"comp-1510-13","front":"Accessor vs mutator methods","back":"An accessor (getter) returns information about an object''s state without changing it. A mutator (setter) changes the state, ideally validating the new value first."},{"id":"comp-1510-14","front":"What is an API, and why is it valuable?","back":"An application programming interface is the set of documented operations a module or library offers. It lets you use code without knowing how it works inside, which supports reuse and teamwork."},{"id":"comp-1510-15","front":"What are preconditions and postconditions?","back":"A precondition is what must be true before a function is called (e.g., the list is not empty). A postcondition is what the function guarantees afterwards if the precondition held."},{"id":"comp-1510-16","front":"Why write automated unit tests?","back":"They check small pieces of code in isolation, run quickly and repeatably, catch regressions when code changes, and document the expected behaviour."},{"id":"comp-1510-17","front":"A function accepts whole numbers from 1 to 100. Which inputs should you test?","back":"A typical value (e.g., 50), the boundaries (1 and 100), just outside them (0 and 101), and invalid input of the wrong type or format. Bugs cluster at boundaries."},{"id":"comp-1510-18","front":"Describe the test-driven development cycle.","back":"Red: write a failing test for the next small behaviour. Green: write just enough code to make it pass. Refactor: clean up the code while keeping all tests passing."},{"id":"comp-1510-19","front":"Why use exceptions instead of special error return values?","back":"Exceptions separate error-handling code from normal logic, cannot be silently ignored the way an unchecked return code can, and carry information about what went wrong."},{"id":"comp-1510-20","front":"What is the role of a finally block (or equivalent cleanup)?","back":"Its code runs whether or not an exception occurred. It is used to release resources such as open files or network connections."},{"id":"comp-1510-21","front":"What is a common mistake when handling exceptions?","back":"Catching every exception and doing nothing (swallowing it). The program keeps running in a bad state and the real cause becomes hard to find. Catch only what you can handle."},{"id":"comp-1510-22","front":"An array has n elements. What are the valid indices, and what happens outside them?","back":"0 to n − 1 with zero-based indexing. Accessing index n or a negative index (where not supported) raises an out-of-bounds or index error."},{"id":"comp-1510-23","front":"What does it mean that strings are immutable in languages like Java and Python?","back":"A string object''s characters cannot be changed. Operations like concatenation or replace create a new string, which also makes repeated concatenation in a loop inefficient."},{"id":"comp-1510-24","front":"Why design before coding?","back":"Planning with pseudocode, diagrams or test cases clarifies requirements and structure first, which reduces wasted effort and costly rewrites."},{"id":"comp-1510-25","front":"Syntax error vs runtime error vs logic error","back":"Syntax: code violates the language rules and won''t compile or run. Runtime: it crashes while executing (e.g., division by zero). Logic: it runs but produces wrong results."},{"id":"comp-1510-26","front":"Name a systematic debugging process.","back":"Reproduce the bug reliably, narrow down where it happens (prints, breakpoints, stepping through), form a hypothesis, fix it, then add a test so it doesn''t come back."},{"id":"comp-1510-27","front":"What usually causes an infinite loop?","back":"The loop condition never becomes false, often because the loop variable is never updated or is updated in the wrong direction."},{"id":"comp-1510-28","front":"What is an off-by-one error? Give an example.","back":"A boundary mistake that makes a loop run one time too many or too few, such as looping i from 0 through n inclusive over an array of length n."},{"id":"comp-1510-29","front":"What is a side effect, and why prefer functions without unnecessary ones?","back":"A side effect is any change outside the function''s return value (changing globals, printing, modifying arguments). Functions without them are easier to reason about and test."},{"id":"comp-1510-30","front":"What does the DRY principle mean?","back":"Don''t Repeat Yourself: put each piece of logic in one place, such as a function, instead of copying it, so a fix or change is made once."},{"id":"comp-1510-31","front":"High cohesion and low coupling","back":"Cohesion: how focused a module is on a single job (aim high). Coupling: how much modules depend on each other''s internals (aim low). Together they make code easier to change and test."},{"id":"comp-1510-32","front":"Trace: total = 0; for i from 1 to 5 inclusive: total = total + i. What is total?","back":"15, since 1 + 2 + 3 + 4 + 5 = 15."}],"quizzes":[],"seed":1,"look":{"color":"#0D9488","icon":"code"}}'::jsonb);   -- https://www.bcit.ca/courses/comp1510
select pg_temp.sb_seed('seed:bcit-ca:fmgt-1105', 'bcit.ca', 'FMGT 1105', 'FMGT 1105 Final Review: Transactions, Adjusting Entries, Financial Statements and Merchandising', '{"v":1,"app":"studyboard","type":"deck","name":"FMGT 1105 Final Review: Transactions, Adjusting Entries, Financial Statements and Merchandising","course":{"code":"FMGT 1105","name":"Accounting 1 for Financial Management"},"cards":[{"id":"fmgt-1105-1","front":"State the basic accounting equation.","back":"Assets = Liabilities + Equity. Every transaction keeps the equation in balance."},{"id":"fmgt-1105-2","front":"Which account types increase with a debit and which with a credit?","back":"Debits increase assets, expenses and drawings (or dividends). Credits increase liabilities, equity (capital or share capital) and revenues."},{"id":"fmgt-1105-3","front":"What is an account''s normal balance?","back":"The side on which it increases: debit for assets, expenses and drawings or dividends; credit for liabilities, equity and revenues. Accumulated depreciation, a contra-asset, has a credit normal balance."},{"id":"fmgt-1105-4","front":"Journalize: the owner invests $10,000 cash in a proprietorship.","back":"Debit Cash 10,000; credit Owner''s Capital 10,000. For a corporation issuing shares, the credit is to Common Shares (share capital)."},{"id":"fmgt-1105-5","front":"Journalize: supplies are bought on account for $500.","back":"Debit Supplies 500; credit Accounts Payable 500. No expense is recorded until the supplies are used."},{"id":"fmgt-1105-6","front":"When is revenue recognized under accrual accounting?","back":"When it is earned, meaning the goods or services have been provided to the customer, regardless of when cash is received."},{"id":"fmgt-1105-7","front":"What is the expense recognition (matching) principle?","back":"Expenses are recorded in the same period as the revenues they helped generate, not necessarily when cash is paid."},{"id":"fmgt-1105-8","front":"Accrual basis vs cash basis accounting","back":"Accrual basis records revenues when earned and expenses when incurred. Cash basis records them only when cash changes hands. ASPE requires the accrual basis."},{"id":"fmgt-1105-9","front":"Name the four main types of adjusting entries.","back":"Prepaid expenses (and depreciation), unearned revenues, accrued revenues and accrued expenses. Adjusting entries never involve the Cash account."},{"id":"fmgt-1105-10","front":"On Oct 1 a company pays $1,200 for 12 months of insurance. Give the Dec 31 adjusting entry.","back":"Three months have expired: 3/12 × 1,200 = 300. Debit Insurance Expense 300; credit Prepaid Insurance 300."},{"id":"fmgt-1105-11","front":"A customer paid $6,000 in advance for 6 months of service; 2 months are now done. Adjusting entry?","back":"2/6 × 6,000 = 4,000 earned. Debit Unearned Revenue 4,000; credit Service Revenue 4,000."},{"id":"fmgt-1105-12","front":"Employees earned $2,000 of wages by year-end that will be paid next month. Adjusting entry?","back":"Debit Salaries (Wages) Expense 2,000; credit Salaries (Wages) Payable 2,000. This is an accrued expense."},{"id":"fmgt-1105-13","front":"Straight-line depreciation: equipment costs $50,000, residual value $5,000, life 5 years. Annual depreciation?","back":"(50,000 − 5,000) / 5 = 9,000 per year. Debit Depreciation Expense 9,000; credit Accumulated Depreciation 9,000."},{"id":"fmgt-1105-14","front":"What is book value (carrying amount)?","back":"Cost minus accumulated depreciation. It is not the asset''s market value."},{"id":"fmgt-1105-15","front":"What does a trial balance prove, and what can''t it detect?","back":"It shows total debits equal total credits. It won''t catch a transaction that was never recorded, an entry posted to the wrong account on the correct side, or equal offsetting errors."},{"id":"fmgt-1105-16","front":"In what order are the financial statements prepared, and why?","back":"Income statement first (gives net income), then the statement of owner''s equity or retained earnings (uses net income), then the balance sheet (uses ending equity)."},{"id":"fmgt-1105-17","front":"What are closing entries for?","back":"They reset temporary accounts (revenues, expenses, and drawings or dividends) to zero and transfer their balances, through Income Summary, to Owner''s Capital or Retained Earnings."},{"id":"fmgt-1105-18","front":"Temporary vs permanent accounts","back":"Temporary (nominal) accounts are closed each period: revenues, expenses, drawings or dividends. Permanent (real) accounts carry their balances forward: assets, liabilities and equity."},{"id":"fmgt-1105-19","front":"What appears on a post-closing trial balance?","back":"Only permanent accounts (assets, liabilities and equity), because every temporary account now has a zero balance."},{"id":"fmgt-1105-20","front":"List the main steps of the accounting cycle.","back":"Analyze transactions, journalize, post to the ledger, prepare a trial balance, journalize and post adjusting entries, prepare an adjusted trial balance, prepare financial statements, close the books, prepare a post-closing trial balance."},{"id":"fmgt-1105-21","front":"What is the purpose of a worksheet?","back":"An optional working tool that lays out the trial balance, adjustments and adjusted trial balance in columns, then sorts amounts into income statement and balance sheet columns to help prepare statements."},{"id":"fmgt-1105-22","front":"Current vs non-current assets and liabilities","back":"Current items are expected to be converted to cash, used up or paid within one year or the operating cycle, whichever is longer. Everything else is non-current, e.g., equipment or a 5-year loan."},{"id":"fmgt-1105-23","front":"Perpetual vs periodic inventory systems","back":"Perpetual systems update Inventory and Cost of Goods Sold with every purchase and sale. Periodic systems record purchases in a Purchases account and work out COGS only at period end from a physical count."},{"id":"fmgt-1105-24","front":"Under a perpetual system, journalize a $1,000 credit sale of goods that cost $600.","back":"Debit Accounts Receivable 1,000; credit Sales 1,000. Also debit Cost of Goods Sold 600; credit Inventory 600."},{"id":"fmgt-1105-25","front":"How are net sales and gross profit calculated?","back":"Net sales = Sales − Sales returns and allowances − Sales discounts. Gross profit = Net sales − Cost of goods sold."},{"id":"fmgt-1105-26","front":"Terms 2/10, n/30 on a $1,000 invoice: how much does the buyer pay if paying within 10 days?","back":"The buyer takes a 2% discount and pays $980. Otherwise the full $1,000 is due within 30 days."},{"id":"fmgt-1105-27","front":"FOB shipping point vs FOB destination","back":"FOB shipping point: the buyer owns the goods and pays freight once they leave the seller. FOB destination: the seller owns them and pays freight until they reach the buyer."},{"id":"fmgt-1105-28","front":"Periodic system: how is cost of goods sold calculated?","back":"COGS = Beginning inventory + Cost of goods purchased − Ending inventory. Cost of goods purchased = Net purchases + Freight in."},{"id":"fmgt-1105-29","front":"Compare proprietorships, partnerships and corporations.","back":"A proprietorship has one owner and a partnership two or more, and the owners usually have unlimited personal liability. A corporation is a separate legal entity owned by shareholders, who have limited liability."},{"id":"fmgt-1105-30","front":"Name four principles of internal control.","back":"Establishing responsibility, segregation of duties, documentation procedures, physical controls, independent checks of performance and human resource controls (any four)."},{"id":"fmgt-1105-31","front":"Economic entity, going concern and monetary unit assumptions","back":"Economic entity: business records are kept separate from the owner''s personal affairs. Going concern: the business is assumed to continue operating. Monetary unit: only items measurable in money are recorded."},{"id":"fmgt-1105-32","front":"What are the two fundamental qualitative characteristics of useful financial information?","back":"Relevance (it can make a difference to decisions) and faithful representation (it is complete, neutral and free from material error)."}],"quizzes":[],"seed":1,"look":{"color":"#C79A12","icon":"acct"}}'::jsonb);   -- https://www.bcit.ca/courses/accounting-1-for-financial-management-fmgt-1105
select pg_temp.sb_seed('seed:ubc-ca:psyc-101', 'ubc.ca', 'PSYC 101', 'PSYC 101 Midterm Review: Research Methods, Biopsychology, Learning, Perception and Memory', '{"v":1,"app":"studyboard","type":"deck","name":"PSYC 101 Midterm Review: Research Methods, Biopsychology, Learning, Perception and Memory","course":{"code":"PSYC 101","name":"Introduction to Biological and Cognitive Psychology"},"cards":[{"id":"psyc-101-1","front":"Independent variable vs dependent variable","back":"The independent variable is what the experimenter deliberately manipulates; the dependent variable is what is measured to see whether it changed as a result."},{"id":"psyc-101-2","front":"Why does random assignment allow a causal conclusion in an experiment?","back":"It makes the groups equivalent on average on all pre-existing characteristics, so a difference in the dependent variable can be attributed to the manipulation rather than to confounds."},{"id":"psyc-101-3","front":"Random sampling vs random assignment","back":"Random sampling chooses who is in the study, which supports generalizing to the population (external validity). Random assignment decides which condition each participant gets, which supports causal inference (internal validity)."},{"id":"psyc-101-4","front":"What is a confounding variable?","back":"A variable other than the independent variable that changes systematically along with it, providing an alternative explanation for any difference in the dependent variable."},{"id":"psyc-101-5","front":"What does a correlation coefficient (r) tell you?","back":"r ranges from −1 to +1. The sign gives the direction of the linear relationship and the absolute value gives its strength; r = 0 means no linear relationship."},{"id":"psyc-101-6","front":"Give two reasons a correlation between X and Y does not prove X causes Y.","back":"Directionality: Y might cause X. Third variable: some other factor Z might cause both (e.g., hot weather raises both ice cream sales and drownings)."},{"id":"psyc-101-7","front":"What is an operational definition?","back":"A concrete statement of exactly how a variable will be measured or manipulated, e.g., defining aggression as the number of times a child hits a doll in 10 minutes."},{"id":"psyc-101-8","front":"Reliability vs validity","back":"Reliability is consistency of a measure across time, raters or items. Validity is whether it measures what it claims to measure. A measure can be reliable but not valid, but it cannot be valid without being reliable."},{"id":"psyc-101-9","front":"What problems does a double-blind design control for?","back":"Because neither participants nor the researchers who interact with them know who is in which condition, it controls for placebo effects and experimenter expectancy effects."},{"id":"psyc-101-10","front":"Which measure of central tendency is least affected by extreme scores?","back":"The median, the middle score when values are ordered. The mean is pulled toward outliers, which is why median income is usually reported instead of mean income."},{"id":"psyc-101-11","front":"In a normal distribution, what percentage of scores fall within 1 and 2 standard deviations of the mean?","back":"About 68% fall within ±1 SD and about 95% fall within ±2 SD."},{"id":"psyc-101-12","front":"What does p < .05 mean, and what does it NOT mean?","back":"If the null hypothesis were true, results at least this extreme would occur less than 5% of the time. It does not mean the effect is large or important, or that the hypothesis is 95% likely to be true."},{"id":"psyc-101-13","front":"Trace the path of a signal through a single neuron.","back":"Dendrites receive input, the cell body (soma) integrates it, the axon carries the action potential away from the soma, and the axon terminals release neurotransmitter into the synapse."},{"id":"psyc-101-14","front":"Describe the ion movements during an action potential.","back":"At threshold, voltage-gated Na+ channels open and Na+ rushes in (depolarization). Then K+ channels open and K+ flows out (repolarization), with a brief hyperpolarization and refractory period."},{"id":"psyc-101-15","front":"What is the resting membrane potential and what maintains it?","back":"About −70 mV inside relative to outside. It is maintained by the sodium-potassium pump (3 Na+ out, 2 K+ in) and the membrane''s greater permeability to K+ than Na+."},{"id":"psyc-101-16","front":"What does the all-or-none principle say about action potentials?","back":"A neuron either fires a full-size action potential or does not fire at all. Stimulus intensity is coded by firing rate and by the number of neurons firing, not by the size of each spike."},{"id":"psyc-101-17","front":"What does myelin do?","back":"It insulates the axon so the action potential jumps between gaps called nodes of Ranvier (saltatory conduction), greatly speeding transmission. Myelin loss in multiple sclerosis slows or disrupts signals."},{"id":"psyc-101-18","front":"Agonist vs antagonist drugs","back":"An agonist mimics or enhances a neurotransmitter''s effect; an antagonist blocks or reduces it. SSRIs, for example, increase serotonin''s action by blocking its reuptake."},{"id":"psyc-101-19","front":"Broca''s aphasia vs Wernicke''s aphasia","back":"Broca''s (left frontal lobe): slow, effortful, non-fluent speech with relatively good comprehension. Wernicke''s (left temporal lobe): fluent but meaningless speech with poor comprehension."},{"id":"psyc-101-20","front":"A split-brain patient sees a word flashed only to the left visual field. What happens?","back":"The word reaches the right hemisphere, which usually lacks speech, so the patient cannot say it, but can pick out the named object with the left hand (controlled by the right hemisphere)."},{"id":"psyc-101-21","front":"In Pavlov''s experiments, identify the US, UR, CS and CR.","back":"Food is the unconditioned stimulus (US) causing salivation, the unconditioned response (UR). After pairing, the tone becomes a conditioned stimulus (CS) that triggers salivation, now the conditioned response (CR)."},{"id":"psyc-101-22","front":"Extinction vs spontaneous recovery in classical conditioning","back":"Extinction: the CR weakens when the CS is repeatedly presented without the US. Spontaneous recovery: after a rest period, the extinguished CR briefly reappears, showing the learning was suppressed, not erased."},{"id":"psyc-101-23","front":"Negative reinforcement vs punishment","back":"Negative reinforcement removes an unpleasant stimulus to INCREASE a behaviour (taking aspirin removes a headache). Punishment DECREASES a behaviour. A common mistake is treating negative reinforcement as punishment."},{"id":"psyc-101-24","front":"Which reinforcement schedule produces high, steady responding and the most resistance to extinction?","back":"Variable ratio, where reinforcement comes after an unpredictable number of responses, as with slot machines."},{"id":"psyc-101-25","front":"What did Bandura''s Bobo doll study show?","back":"Children who watched an adult act aggressively toward a doll were more likely to copy that aggression. This showed observational learning (modelling) without direct reinforcement."},{"id":"psyc-101-26","front":"Sensation vs perception, and what is transduction?","back":"Sensation is the detection of physical energy by sensory receptors; perception is the brain organizing and interpreting it. Transduction is converting that energy into neural signals."},{"id":"psyc-101-27","front":"State Weber''s law.","back":"The just noticeable difference is a constant proportion of the original stimulus: ΔI / I = k. A larger standard stimulus needs a larger change before the difference is noticed."},{"id":"psyc-101-28","front":"What does signal detection theory separate?","back":"It separates sensitivity (how well signal is told apart from noise) from response bias (the criterion for saying ''yes''), using hits, misses, false alarms and correct rejections."},{"id":"psyc-101-29","front":"Rods vs cones","back":"Rods are more numerous, very sensitive in dim light, absent from the fovea, and do not code colour. Cones are packed in the fovea, need more light, and support colour vision and fine detail."},{"id":"psyc-101-30","front":"Describe the Atkinson-Shiffrin (modal) model of memory.","back":"Information passes from sensory memory (very brief) to short-term memory (limited capacity, about 7 ± 2 items, roughly 20 to 30 s without rehearsal) and, with encoding, into long-term memory."},{"id":"psyc-101-31","front":"What is the encoding specificity principle?","back":"Retrieval is best when the cues or context at retrieval match those present at encoding. Example: divers recalled word lists better in the same setting (underwater or on land) where they learned them."},{"id":"psyc-101-32","front":"Proactive vs retroactive interference","back":"Proactive: old learning interferes with recalling new information. Retroactive: new learning interferes with recalling old information."},{"id":"psyc-101-33","front":"What is the serial position effect?","back":"In free recall of a list, items at the beginning (primacy, via long-term memory) and end (recency, still in short-term memory) are remembered better than items in the middle."},{"id":"psyc-101-34","front":"Availability heuristic vs representativeness heuristic","back":"Availability: judging how likely something is by how easily examples come to mind. Representativeness: judging probability by how closely something matches a prototype, often ignoring base rates."}],"quizzes":[],"seed":1,"look":{"color":"#9A4FD1","icon":"psych"}}'::jsonb);   -- https://vancouver.calendar.ubc.ca/course-descriptions/subject/psycv
select pg_temp.sb_seed('seed:ubc-ca:econ-101', 'ubc.ca', 'ECON 101', 'ECON 101 Final Review: Consumer Choice, Market Equilibrium, Welfare and Market Power', '{"v":1,"app":"studyboard","type":"deck","name":"ECON 101 Final Review: Consumer Choice, Market Equilibrium, Welfare and Market Power","course":{"code":"ECON 101","name":"Principles of Microeconomics"},"cards":[{"id":"econ-101-1","front":"What is opportunity cost?","back":"The value of the next best alternative given up when a choice is made. Example: the opportunity cost of a year in school includes the wages you could have earned working."},{"id":"econ-101-2","front":"Movement along a demand curve vs a shift of the curve","back":"A change in the good''s own price causes a movement along the curve (change in quantity demanded). A change in any other factor shifts the whole curve (change in demand)."},{"id":"econ-101-3","front":"List the main factors that shift a demand curve.","back":"Consumer income, prices of related goods (substitutes and complements), tastes, expectations about future prices or income, and the number of buyers."},{"id":"econ-101-4","front":"Normal good vs inferior good","back":"Demand for a normal good rises when income rises; demand for an inferior good falls when income rises (e.g., instant noodles or bus travel for some consumers)."},{"id":"econ-101-5","front":"How does cross-price elasticity identify substitutes and complements?","back":"Cross-price elasticity = %ΔQ of good A / %ΔP of good B. Positive means substitutes (coffee and tea); negative means complements (printers and ink)."},{"id":"econ-101-6","front":"Price elasticity of demand using the midpoint method","back":"E = (ΔQ / average Q) / (ΔP / average P). If |E| > 1 demand is elastic, if |E| < 1 inelastic, and if |E| = 1 unit elastic."},{"id":"econ-101-7","front":"Mini-problem: price rises from $4 to $6 and quantity falls from 120 to 80. Find the midpoint elasticity.","back":"%ΔQ = −40/100 = −0.4 and %ΔP = 2/5 = 0.4, so E = −1. Demand is unit elastic over this range and total revenue stays the same ($480)."},{"id":"econ-101-8","front":"If demand is elastic, what happens to total revenue when price rises?","back":"Total revenue falls, because the percentage drop in quantity is larger than the percentage rise in price. With inelastic demand, a price rise increases total revenue."},{"id":"econ-101-9","front":"Define consumer surplus and producer surplus.","back":"Consumer surplus is willingness to pay minus price paid (area below demand, above price). Producer surplus is price received minus marginal cost (area above supply, below price)."},{"id":"econ-101-10","front":"Supply and demand both increase. What happens to equilibrium price and quantity?","back":"Quantity definitely rises, but the price change is ambiguous: it depends on which curve shifts by more."},{"id":"econ-101-11","front":"What happens with a binding price ceiling?","back":"Set below equilibrium, it creates a shortage (quantity demanded exceeds quantity supplied), lowers the quantity traded and causes a deadweight loss. Rent control is a classic example."},{"id":"econ-101-12","front":"Who bears more of the burden of a per-unit tax?","back":"The side of the market that is less elastic. Tax incidence does not depend on whether the government collects the tax from buyers or from sellers."},{"id":"econ-101-13","front":"What is deadweight loss?","back":"The loss of total surplus when the quantity traded differs from the efficient quantity, for example due to taxes, price controls, monopoly or externalities."},{"id":"econ-101-14","front":"State the consumer''s optimal choice condition for two goods.","back":"Spend the budget so that MUx / Px = MUy / Py. Graphically, the indifference curve is tangent to the budget line: MRS = Px / Py."},{"id":"econ-101-15","front":"What is the slope of the budget line, and how does an income increase change it?","back":"With good X on the horizontal axis, the slope is −Px / Py. An increase in income shifts the line outward in parallel; a price change rotates it."},{"id":"econ-101-16","front":"Substitution effect vs income effect of a price decrease","back":"Substitution effect: the good is now relatively cheaper, so you buy more of it. Income effect: your purchasing power rises, which raises consumption of normal goods and lowers it for inferior goods."},{"id":"econ-101-17","front":"What is the law of diminishing marginal returns?","back":"In the short run, as more of a variable input (like labour) is added to a fixed input (like capital), the extra output from each additional unit eventually falls."},{"id":"econ-101-18","front":"Where does marginal cost cross the average cost curves?","back":"The MC curve crosses both the average variable cost and average total cost curves at their minimum points."},{"id":"econ-101-19","front":"Economic profit vs accounting profit","back":"Accounting profit = revenue − explicit costs. Economic profit = revenue − explicit costs − implicit (opportunity) costs. Zero economic profit means the firm earns a normal return."},{"id":"econ-101-20","front":"Profit-maximizing rule and short-run shutdown rule for a perfectly competitive firm","back":"Produce where P = MC. In the short run, shut down if price is below the minimum of average variable cost."},{"id":"econ-101-21","front":"What is long-run equilibrium in a perfectly competitive industry?","back":"Free entry and exit push price to the minimum of average total cost, so firms earn zero economic profit and P = MC = min ATC."},{"id":"econ-101-22","front":"Why is marginal revenue less than price for a monopolist?","back":"To sell one more unit, a single-price monopolist must lower the price on all units, so the extra revenue is less than the price of the extra unit."},{"id":"econ-101-23","front":"Mini-problem: a monopolist faces P = 100 − 2Q with MC = 20. Find Q and P.","back":"MR = 100 − 4Q. Set MR = MC: 100 − 4Q = 20, so Q = 20. Price comes from demand: P = 100 − 2(20) = 60."},{"id":"econ-101-24","front":"Compare monopoly and perfect competition outcomes.","back":"A monopoly produces less and charges more (P > MC), creating a deadweight loss. Perfect competition produces where P = MC, which is allocatively efficient."},{"id":"econ-101-25","front":"What is perfect (first-degree) price discrimination?","back":"Charging each buyer their maximum willingness to pay. The firm captures all consumer surplus and, unusually, produces the efficient quantity, so there is no deadweight loss."},{"id":"econ-101-26","front":"What is a dominant strategy?","back":"A strategy that gives a player a better payoff than the alternatives no matter what the other players do."},{"id":"econ-101-27","front":"Define a Nash equilibrium.","back":"A set of strategies where no player can improve their payoff by changing their own strategy, given the strategies of the others."},{"id":"econ-101-28","front":"How does the prisoner''s dilemma explain why cartels are unstable?","back":"Each firm''s dominant strategy is to cheat (produce more), even though both would earn more by cooperating. The Nash equilibrium is mutual cheating, which is worse for both."},{"id":"econ-101-29","front":"Negative externality and the Pigouvian tax","back":"A negative externality is a cost imposed on third parties (e.g., pollution), so the market overproduces. A per-unit tax equal to the marginal external cost moves output to the socially efficient level."},{"id":"econ-101-30","front":"What does Pareto efficiency mean?","back":"An allocation where no one can be made better off without making someone else worse off. A competitive equilibrium without market failures is Pareto efficient."}],"quizzes":[],"seed":1,"look":{"color":"#1E9E74","icon":"econ"}}'::jsonb);   -- https://vancouver.calendar.ubc.ca/course-descriptions/subject/econv
select pg_temp.sb_seed('seed:ubc-ca:biol-112', 'ubc.ca', 'BIOL 112', 'BIOL 112 Midterm Review: Cell Structure, Membranes, Gene Expression and Energy Metabolism', '{"v":1,"app":"studyboard","type":"deck","name":"BIOL 112 Midterm Review: Cell Structure, Membranes, Gene Expression and Energy Metabolism","course":{"code":"BIOL 112","name":"Biology of the Cell"},"cards":[{"id":"biol-112-1","front":"Prokaryotic vs eukaryotic cells","back":"Prokaryotes (bacteria, archaea) lack a nucleus and membrane-bound organelles and are usually smaller. Eukaryotes have a nucleus, an endomembrane system and organelles such as mitochondria."},{"id":"biol-112-2","front":"Why do phospholipids spontaneously form a bilayer in water?","back":"They are amphipathic: hydrophilic phosphate heads face the water on both sides while hydrophobic fatty acid tails cluster together inside, away from water."},{"id":"biol-112-3","front":"Simple diffusion vs facilitated diffusion vs active transport","back":"Simple diffusion: small nonpolar molecules cross the bilayer down their gradient. Facilitated diffusion: channels or carriers move solutes down their gradient. Active transport uses energy (often ATP) to move solutes against their gradient."},{"id":"biol-112-4","front":"What happens to an animal cell placed in a hypertonic solution?","back":"Water leaves the cell by osmosis toward the higher solute concentration outside, so the cell shrinks (crenates). In a hypotonic solution it swells and may lyse."},{"id":"biol-112-5","front":"What does the Na+/K+ ATPase do?","back":"Using one ATP per cycle, it pumps 3 Na+ out and 2 K+ in, building gradients that power secondary active transport and contribute to the membrane potential."},{"id":"biol-112-6","front":"Trace the path of a secreted protein from synthesis to export.","back":"Translation begins on a free ribosome, which docks on the rough ER; the protein enters the ER lumen, travels in vesicles to the Golgi for processing, then leaves in secretory vesicles by exocytosis."},{"id":"biol-112-7","front":"How is a protein targeted to the ER?","back":"An N-terminal signal sequence is recognized by the signal recognition particle (SRP), which pauses translation and brings the ribosome to an SRP receptor and translocon on the ER membrane."},{"id":"biol-112-8","front":"Give evidence for the endosymbiotic origin of mitochondria and chloroplasts.","back":"They have double membranes, their own circular DNA, bacteria-like 70S ribosomes, and divide by a fission-like process."},{"id":"biol-112-9","front":"Key structural features of DNA","back":"Two antiparallel strands in a double helix with a sugar-phosphate backbone. A pairs with T (2 hydrogen bonds) and G pairs with C (3 hydrogen bonds)."},{"id":"biol-112-10","front":"What did the Meselson-Stahl experiment show?","back":"Using heavy (15N) and light (14N) nitrogen, they showed DNA replication is semiconservative: each new double helix has one parental strand and one new strand."},{"id":"biol-112-11","front":"Leading strand vs lagging strand synthesis","back":"DNA polymerase only adds nucleotides 5'' to 3''. The leading strand is made continuously; the lagging strand is made in short Okazaki fragments, each starting from an RNA primer, later joined by DNA ligase."},{"id":"biol-112-12","front":"State the central dogma of molecular biology.","back":"Genetic information flows from DNA to RNA (transcription) to protein (translation). Reverse transcription in retroviruses is a notable exception to the DNA-first direction."},{"id":"biol-112-13","front":"How does transcription start in bacteria, and which way is RNA made?","back":"Sigma factor helps RNA polymerase bind the promoter. The polymerase reads the template strand 3'' to 5'' and builds RNA 5'' to 3'', with no primer needed."},{"id":"biol-112-14","front":"Name three processing steps for eukaryotic pre-mRNA.","back":"Addition of a 5'' cap, addition of a 3'' poly-A tail, and splicing by the spliceosome to remove introns and join exons."},{"id":"biol-112-15","front":"What happens at the A, P and E sites of the ribosome?","back":"A site: incoming aminoacyl-tRNA binds. P site: holds the tRNA with the growing polypeptide. E site: the empty tRNA exits."},{"id":"biol-112-16","front":"What are the start and stop codons?","back":"Start: AUG, which codes for methionine. Stop: UAA, UAG and UGA, which are recognized by release factors rather than tRNAs."},{"id":"biol-112-17","front":"Silent vs missense vs nonsense vs frameshift mutations","back":"Silent: same amino acid. Missense: a different amino acid. Nonsense: creates a premature stop codon. Frameshift: an insertion or deletion not divisible by 3 shifts the reading frame."},{"id":"biol-112-18","front":"How is the lac operon regulated when lactose is absent vs present?","back":"Lactose absent: the lac repressor binds the operator and blocks transcription. Lactose present: allolactose binds the repressor and releases it from the operator, so the genes can be transcribed."},{"id":"biol-112-19","front":"What role do cAMP and CAP play in the lac operon?","back":"When glucose is low, cAMP rises and binds CAP. CAP-cAMP binds near the promoter and boosts RNA polymerase binding, a form of positive control."},{"id":"biol-112-20","front":"How do enzymes speed up reactions?","back":"They lower the activation energy by stabilizing the transition state. They do not change the overall ΔG or the equilibrium position, and they are not used up."},{"id":"biol-112-21","front":"Competitive vs noncompetitive (allosteric) inhibition","back":"A competitive inhibitor binds the active site and can be overcome with more substrate. A noncompetitive inhibitor binds elsewhere and changes the enzyme''s shape, lowering Vmax regardless of substrate level."},{"id":"biol-112-22","front":"How does ATP drive unfavourable reactions?","back":"ATP hydrolysis is strongly exergonic. Cells couple it to endergonic reactions, often by transferring a phosphate to a reactant, so the combined reaction has a negative ΔG."},{"id":"biol-112-23","front":"Where does each stage of cellular respiration occur in a eukaryotic cell?","back":"Glycolysis: cytosol. Pyruvate oxidation and the citric acid cycle: mitochondrial matrix. Electron transport chain and ATP synthase: inner mitochondrial membrane."},{"id":"biol-112-24","front":"Explain chemiosmosis in mitochondria.","back":"The electron transport chain pumps H+ into the intermembrane space. H+ flows back into the matrix through ATP synthase, which uses that energy to make ATP. O2 is the final electron acceptor, forming water."},{"id":"biol-112-25","front":"What is the purpose of fermentation?","back":"To regenerate NAD+ from NADH so glycolysis can keep producing ATP when oxygen is absent. Lactic acid or ethanol is produced as a by-product."},{"id":"biol-112-26","front":"Light reactions vs the Calvin cycle","back":"Light reactions (thylakoid membranes) use light to split water, release O2 and make ATP and NADPH. The Calvin cycle (stroma) uses that ATP and NADPH to fix CO2 into sugar, with rubisco catalyzing carbon fixation."},{"id":"biol-112-27","front":"Name the three cytoskeleton filaments and a main role of each.","back":"Microtubules (tubulin): tracks for transport, spindle, cilia and flagella. Actin microfilaments: cell shape, crawling, muscle contraction. Intermediate filaments: mechanical strength."},{"id":"biol-112-28","front":"How does a G protein-coupled receptor pathway amplify a signal?","back":"One ligand-bound receptor activates many G proteins, which activate adenylyl cyclase to make many cAMP molecules; cAMP activates protein kinase A, which phosphorylates many targets."},{"id":"biol-112-29","front":"Gram-positive vs Gram-negative bacterial cell walls","back":"Gram-positive: thick peptidoglycan layer that retains crystal violet (stains purple). Gram-negative: thin peptidoglycan between two membranes, with an outer membrane containing lipopolysaccharide (stains pink)."},{"id":"biol-112-30","front":"Describe the four levels of protein structure.","back":"Primary: amino acid sequence. Secondary: alpha helices and beta sheets held by backbone hydrogen bonds. Tertiary: overall 3D fold from side-chain interactions. Quaternary: assembly of multiple subunits."}],"quizzes":[],"seed":1,"look":{"color":"#16A34A","icon":"bio"}}'::jsonb);   -- https://vancouver.calendar.ubc.ca/course-descriptions/subject/biolv
select pg_temp.sb_seed('seed:ubc-ca:math-100', 'ubc.ca', 'MATH 100', 'MATH 100 Final Review: Limits, Derivative Rules, Optimization and Approximation', '{"v":1,"app":"studyboard","type":"deck","name":"MATH 100 Final Review: Limits, Derivative Rules, Optimization and Approximation","course":{"code":"MATH 100","name":"Differential Calculus with Applications"},"cards":[{"id":"math-100-1","front":"Limit definition of the derivative","back":"f''(a) = lim as h→0 of [f(a + h) − f(a)] / h, the slope of the tangent line at x = a and the instantaneous rate of change."},{"id":"math-100-2","front":"Three conditions for f to be continuous at x = a","back":"f(a) is defined, the limit of f(x) as x→a exists, and that limit equals f(a)."},{"id":"math-100-3","front":"Does continuity imply differentiability?","back":"No. Differentiable implies continuous, but not the reverse. Example: f(x) = |x| is continuous at 0 but has a corner there, so f''(0) does not exist."},{"id":"math-100-4","front":"Power rule","back":"d/dx [x^n] = n·x^(n−1) for any real n. Example: d/dx [x^(1/2)] = (1/2)x^(−1/2)."},{"id":"math-100-5","front":"Product rule","back":"d/dx [f·g] = f''·g + f·g''."},{"id":"math-100-6","front":"Quotient rule","back":"d/dx [f/g] = (f''·g − f·g'') / g^2. Order matters in the numerator: derivative of the top times the bottom comes first."},{"id":"math-100-7","front":"Chain rule","back":"d/dx [f(g(x))] = f''(g(x))·g''(x). Example: d/dx [(3x + 1)^5] = 5(3x + 1)^4·3 = 15(3x + 1)^4."},{"id":"math-100-8","front":"Derivatives of sin x, cos x and tan x","back":"d/dx sin x = cos x; d/dx cos x = −sin x; d/dx tan x = sec^2 x. These hold only when x is in radians."},{"id":"math-100-9","front":"Derivatives of e^x, a^x and ln x","back":"d/dx e^x = e^x; d/dx a^x = a^x·ln a; d/dx ln x = 1/x for x > 0."},{"id":"math-100-10","front":"Derivatives of arcsin x and arctan x","back":"d/dx arcsin x = 1 / √(1 − x^2); d/dx arctan x = 1 / (1 + x^2)."},{"id":"math-100-11","front":"Evaluate lim as x→0 of sin(x)/x.","back":"The limit is 1 (with x in radians). It is the key limit used to prove that d/dx sin x = cos x."},{"id":"math-100-12","front":"Use implicit differentiation on x^2 + y^2 = 25 to find dy/dx.","back":"Differentiate both sides: 2x + 2y·(dy/dx) = 0, so dy/dx = −x/y. At (3, 4) the slope is −3/4."},{"id":"math-100-13","front":"Differentiate y = x^x.","back":"Take logs: ln y = x·ln x. Differentiate: y''/y = ln x + 1, so y'' = x^x·(ln x + 1)."},{"id":"math-100-14","front":"Equation of the tangent line to y = f(x) at x = a","back":"y = f(a) + f''(a)(x − a)."},{"id":"math-100-15","front":"Use a linear approximation to estimate √4.1.","back":"With f(x) = √x at a = 4: f(4) = 2 and f''(4) = 1/4. So √4.1 ≈ 2 + (1/4)(0.1) = 2.025 (actual ≈ 2.0248)."},{"id":"math-100-16","front":"Related rates: how is dV/dt related to dr/dt for a sphere?","back":"V = (4/3)πr^3, so dV/dt = 4πr^2·(dr/dt). Differentiate with respect to time before substituting the values at the given instant."},{"id":"math-100-17","front":"What is a critical point?","back":"A point c in the domain of f where f''(c) = 0 or f''(c) does not exist. Local extrema can only occur at critical points (or endpoints)."},{"id":"math-100-18","front":"First derivative test","back":"If f'' changes from + to − at a critical point, it is a local maximum; from − to +, a local minimum; if f'' does not change sign, it is neither."},{"id":"math-100-19","front":"Second derivative test","back":"If f''(c) = 0 and f''''(c) > 0, f has a local minimum at c; if f''''(c) < 0, a local maximum. If f''''(c) = 0 the test is inconclusive."},{"id":"math-100-20","front":"What is an inflection point?","back":"A point on the graph where the concavity changes (f'''' changes sign). f''''(c) = 0 alone is not enough: f(x) = x^4 has f''''(0) = 0 but no inflection point."},{"id":"math-100-21","front":"How do you find absolute extrema of a continuous f on a closed interval [a, b]?","back":"Evaluate f at every critical point inside (a, b) and at both endpoints; the largest value is the absolute max and the smallest is the absolute min (guaranteed by the Extreme Value Theorem)."},{"id":"math-100-22","front":"State the Mean Value Theorem.","back":"If f is continuous on [a, b] and differentiable on (a, b), there is some c in (a, b) with f''(c) = [f(b) − f(a)] / (b − a)."},{"id":"math-100-23","front":"State the Intermediate Value Theorem.","back":"If f is continuous on [a, b] and N is between f(a) and f(b), then f(c) = N for some c in [a, b]. It is often used to show an equation has a root."},{"id":"math-100-24","front":"When can L''Hôpital''s rule be used?","back":"For limits of the indeterminate form 0/0 or ∞/∞: then lim f/g = lim f''/g'', if the latter exists. Other forms like 0·∞ must first be rewritten as a quotient."},{"id":"math-100-25","front":"Solve dy/dt = ky and give the doubling time.","back":"y(t) = y0·e^(kt), where y0 = y(0). For k > 0 the doubling time is ln 2 / k."},{"id":"math-100-26","front":"Newton''s method formula","back":"x_(n+1) = x_n − f(x_n) / f''(x_n). Each step follows the tangent line to where it hits the x-axis. It fails if f''(x_n) = 0."},{"id":"math-100-27","front":"Taylor polynomial of degree n for f about x = a","back":"T_n(x) = sum for k = 0 to n of f^(k)(a)/k! · (x − a)^k. Example: about 0, e^x ≈ 1 + x + x^2/2 + x^3/6."},{"id":"math-100-28","front":"Find lim as x→∞ of (3x^2 + 1)/(5x^2 − x).","back":"Divide top and bottom by x^2: the limit is 3/5. When the degrees are equal, the limit is the ratio of leading coefficients, giving the horizontal asymptote y = 3/5."},{"id":"math-100-29","front":"Use the squeeze theorem to find lim as x→0 of x^2·sin(1/x).","back":"Since −x^2 ≤ x^2·sin(1/x) ≤ x^2 and both bounds → 0, the limit is 0."},{"id":"math-100-30","front":"Optimization: a rectangle has perimeter 40. What dimensions maximize its area?","back":"With sides x and 20 − x, A = x(20 − x). A'' = 20 − 2x = 0 gives x = 10. A 10 by 10 square gives the maximum area of 100."},{"id":"math-100-31","front":"Common pitfall: what is d/dx [e^(x^2)]?","back":"By the chain rule it is 2x·e^(x^2). It is NOT x^2·e^(x^2 − 1); the power rule does not apply when the variable is in the exponent."}],"quizzes":[],"seed":1,"look":{"color":"#3B6FE0","icon":"calc"}}'::jsonb);   -- https://vancouver.calendar.ubc.ca/course-descriptions/subject/mathv
select pg_temp.sb_seed('seed:sfu-ca:psyc-100', 'sfu.ca', 'PSYC 100', 'PSYC 100 Exam Review: History, Research Design, the Brain, Perception, Learning and Motivation', '{"v":1,"app":"studyboard","type":"deck","name":"PSYC 100 Exam Review: History, Research Design, the Brain, Perception, Learning and Motivation","course":{"code":"PSYC 100","name":"Introduction to Psychology I"},"cards":[{"id":"psyc-100-1","front":"Who founded the first psychology laboratory, and when?","back":"Wilhelm Wundt, in Leipzig, Germany, in 1879. That date is usually treated as the start of psychology as a separate experimental science."},{"id":"psyc-100-2","front":"Structuralism vs functionalism","back":"Structuralism (Wundt, Titchener) used trained introspection to break conscious experience into basic elements. Functionalism (William James), influenced by Darwin, asked what purpose mental processes serve in adapting to the environment."},{"id":"psyc-100-3","front":"What was the core claim of behaviourism?","back":"Psychology should study only observable behaviour and how the environment shapes it, not inner mental states. Key figures were John B. Watson and B. F. Skinner."},{"id":"psyc-100-4","front":"What is the main idea of Gestalt psychology?","back":"The whole is different from the sum of its parts: we perceive organized patterns rather than isolated sensations. Max Wertheimer was a founder."},{"id":"psyc-100-5","front":"Psychoanalytic vs humanistic perspectives","back":"Psychoanalytic (Freud): behaviour is driven by unconscious conflicts and early childhood experiences. Humanistic (Maslow, Rogers): people are basically good and motivated toward growth and self-actualization."},{"id":"psyc-100-6","front":"What was the cognitive revolution?","back":"A shift in the 1950s and 1960s back toward studying mental processes such as memory, language and problem solving, often using the computer as a model of information processing."},{"id":"psyc-100-7","front":"How do twin studies estimate the role of genes?","back":"They compare identical (monozygotic) twins, who share nearly all their genes, with fraternal (dizygotic) twins, who share about half. Greater similarity in identical twins suggests a genetic contribution."},{"id":"psyc-100-8","front":"Name three descriptive research methods and one weakness they share.","back":"Naturalistic observation, case studies and surveys. None of them manipulates variables, so none can establish cause and effect."},{"id":"psyc-100-9","front":"Hypothesis vs theory","back":"A theory is a broad, well-supported explanation that ties together many findings. A hypothesis is a specific, testable prediction, often derived from a theory."},{"id":"psyc-100-10","front":"What does it mean for a claim to be falsifiable?","back":"It is possible, at least in principle, to describe evidence that would show the claim is wrong. Scientific claims must be falsifiable."},{"id":"psyc-100-11","front":"Within-subjects vs between-subjects designs","back":"Within-subjects: every participant experiences all conditions, which needs fewer people but risks order effects. Between-subjects: each participant gets only one condition."},{"id":"psyc-100-12","front":"How is counterbalancing used?","back":"In a within-subjects design, the order of conditions is varied across participants (e.g., half get A then B, half get B then A) so practice or fatigue effects do not favour one condition."},{"id":"psyc-100-13","front":"What are demand characteristics?","back":"Cues in a study that suggest to participants what the researcher expects, which can lead them to change their behaviour to fit (or defy) the hypothesis."},{"id":"psyc-100-14","front":"Name three core ethical requirements for research with human participants.","back":"Informed consent, the right to withdraw without penalty, and debriefing after the study (especially if deception was used). Studies are reviewed by a research ethics board."},{"id":"psyc-100-15","front":"Main functions of the four cerebral lobes","back":"Frontal: planning, decision making, voluntary movement. Parietal: touch and body sensation, spatial processing. Temporal: hearing, language comprehension, memory. Occipital: vision."},{"id":"psyc-100-16","front":"Hippocampus vs amygdala vs hypothalamus","back":"Hippocampus: forming new long-term memories. Amygdala: fear and emotional responses. Hypothalamus: regulates hunger, thirst, temperature and controls the pituitary gland."},{"id":"psyc-100-17","front":"What does the cerebellum do?","back":"It coordinates fine movement, balance and timing, and supports motor learning. Damage produces clumsy, uncoordinated movement."},{"id":"psyc-100-18","front":"EEG vs fMRI","back":"EEG records electrical activity from the scalp, with excellent timing (milliseconds) but poor spatial detail. fMRI tracks blood oxygen changes (the BOLD signal), with good spatial detail but slower timing."},{"id":"psyc-100-19","front":"Match each neurotransmitter to a key role: dopamine, serotonin, acetylcholine, GABA, glutamate.","back":"Dopamine: reward and movement (lost in Parkinson''s). Serotonin: mood, sleep, appetite. Acetylcholine: muscle action and memory. GABA: main inhibitory. Glutamate: main excitatory."},{"id":"psyc-100-20","front":"Why is the pituitary called the master gland, and what controls it?","back":"Its hormones regulate many other endocrine glands (thyroid, adrenals, gonads). It is itself controlled by the hypothalamus."},{"id":"psyc-100-21","front":"What did the case of Phineas Gage suggest?","back":"After an iron rod damaged his frontal lobe in 1848, he survived but reportedly became impulsive and less reliable, suggesting the frontal lobes are involved in personality and self-control."},{"id":"psyc-100-22","front":"Bottom-up vs top-down processing","back":"Bottom-up processing builds perception from raw sensory features. Top-down processing uses knowledge, expectations and context to interpret input, which is why context helps you read messy handwriting."},{"id":"psyc-100-23","front":"Name four Gestalt grouping principles.","back":"Proximity (near items group), similarity (alike items group), closure (we fill gaps to see whole shapes) and continuity (we see smooth continuous lines)."},{"id":"psyc-100-24","front":"Binocular vs monocular depth cues","back":"Binocular cues need both eyes: retinal disparity and convergence. Monocular cues work with one eye: linear perspective, interposition (overlap), relative size, texture gradient, shading."},{"id":"psyc-100-25","front":"What is perceptual constancy?","back":"Perceiving an object''s size, shape, colour or brightness as stable even though the image on the retina changes, e.g., a door still looks rectangular as it swings open."},{"id":"psyc-100-26","front":"Trichromatic theory vs opponent-process theory of colour","back":"Trichromatic: three cone types (short, medium, long wavelength) explain colour at the retina. Opponent-process: red-green, blue-yellow and black-white channels explain afterimages. Both are correct at different stages."},{"id":"psyc-100-27","front":"Place theory vs frequency theory of pitch","back":"Place theory: different pitches excite different locations on the basilar membrane, which explains high pitches best. Frequency theory: neural firing rate matches sound frequency, which explains low pitches best."},{"id":"psyc-100-28","front":"What is Thorndike''s law of effect?","back":"Behaviours followed by satisfying consequences become more likely, and those followed by unpleasant consequences become less likely. It came from his puzzle box studies with cats."},{"id":"psyc-100-29","front":"What is shaping in operant conditioning?","back":"Reinforcing successive approximations, closer and closer steps toward a target behaviour, until the full behaviour appears."},{"id":"psyc-100-30","front":"What did Garcia''s taste aversion research show?","back":"Rats learned to avoid a taste after a single pairing with illness, even hours later, but did not link illness with lights or sounds. Learning is constrained by biological preparedness."},{"id":"psyc-100-31","front":"What is latent learning?","back":"Learning that happens without obvious reinforcement and is shown only when a reason appears. Tolman''s rats explored a maze and later ran it quickly once food was added, suggesting a cognitive map."},{"id":"psyc-100-32","front":"Drive-reduction theory vs arousal theory of motivation","back":"Drive reduction: biological needs create drives that push us to restore homeostasis. Arousal theory: we seek an optimal level of arousal, which explains curiosity and thrill seeking."},{"id":"psyc-100-33","front":"What is the Yerkes-Dodson law?","back":"Performance is best at a moderate level of arousal. For difficult tasks the ideal level is lower; for easy tasks it is higher."},{"id":"psyc-100-34","front":"Describe Maslow''s hierarchy of needs.","back":"From bottom to top: physiological, safety, belonging and love, esteem, and self-actualization. Lower needs generally must be met before higher ones motivate behaviour."},{"id":"psyc-100-35","front":"Intrinsic vs extrinsic motivation, and the overjustification effect","back":"Intrinsic: doing something for its own sake. Extrinsic: doing it for external rewards. The overjustification effect is when rewarding an already enjoyable activity reduces intrinsic interest in it."}],"quizzes":[],"seed":1,"look":{"color":"#C026D3","icon":"psych"}}'::jsonb);   -- https://www.sfu.ca/students/calendar/2026/fall/courses/psyc/100.html
select pg_temp.sb_seed('seed:sfu-ca:cmpt-120', 'sfu.ca', 'CMPT 120', 'CMPT 120 Final Review: Python Basics, Control Flow, Recursion, Files and Algorithms', '{"v":1,"app":"studyboard","type":"deck","name":"CMPT 120 Final Review: Python Basics, Control Flow, Recursion, Files and Algorithms","course":{"code":"CMPT 120","name":"Introduction to Computing Science and Programming I"},"cards":[{"id":"cmpt-120-1","front":"In Python 3, what are 7 / 2, 7 // 2 and 7 % 2?","back":"7 / 2 = 3.5 (true division always gives a float), 7 // 2 = 3 (floor division) and 7 % 2 = 1 (remainder)."},{"id":"cmpt-120-2","front":"What is −7 // 2 in Python, and why?","back":"−4. Floor division rounds down toward negative infinity, not toward zero."},{"id":"cmpt-120-3","front":"Evaluate 2 + 3 * 4 ** 2.","back":"50. Exponentiation first (4 ** 2 = 16), then multiplication (3 * 16 = 48), then addition (2 + 48 = 50)."},{"id":"cmpt-120-4","front":"Mutable vs immutable types in Python","back":"Mutable objects can be changed in place: lists, dictionaries, sets. Immutable objects cannot: int, float, str, tuple. ''Changing'' a string really creates a new string."},{"id":"cmpt-120-5","front":"What is the difference between = and == ?","back":"= assigns a value to a variable. == compares two values and gives True or False."},{"id":"cmpt-120-6","front":"What happens with ''5'' + 2, and how do you fix it?","back":"It raises a TypeError because a str and an int cannot be added. Convert first: int(''5'') + 2 gives 7, or ''5'' + str(2) gives ''52''."},{"id":"cmpt-120-7","front":"For s = ''python'', what are s[1:4], s[-1] and s[::-1]?","back":"s[1:4] = ''yth'' (index 1 up to but not including 4), s[-1] = ''n'' (last character), s[::-1] = ''nohtyp'' (the reversed string)."},{"id":"cmpt-120-8","front":"What values does range(2, 10, 3) produce?","back":"2, 5, 8. It starts at 2, steps by 3, and stops before reaching 10."},{"id":"cmpt-120-9","front":"When is a while loop a better choice than a for loop?","back":"When you don''t know ahead of time how many iterations you need, such as repeating until the user enters valid input. A for loop suits iterating over a known sequence or range."},{"id":"cmpt-120-10","front":"break vs continue","back":"break exits the nearest enclosing loop immediately. continue skips the rest of the current iteration and goes on to the next one."},{"id":"cmpt-120-11","front":"What is short-circuit evaluation?","back":"In A and B, B is not evaluated if A is False; in A or B, B is not evaluated if A is True. This lets you write guards like: x != 0 and 10 / x > 1."},{"id":"cmpt-120-12","front":"return vs print in a function","back":"return sends a value back to the caller so it can be stored or used. print only displays text. A function with no return statement returns None."},{"id":"cmpt-120-13","front":"Local vs global scope","back":"A variable assigned inside a function is local to that function and disappears when it returns. Global variables are defined at module level; assigning to one inside a function requires the global keyword."},{"id":"cmpt-120-14","front":"a = [1, 2]; b = a; b.append(3). What is a now, and why?","back":"[1, 2, 3]. b = a makes b another name (alias) for the same list. To copy instead, use b = a[:] or b = list(a)."},{"id":"cmpt-120-15","front":"list.append vs list.extend","back":"append adds its argument as a single element: [1, 2].append([3, 4]) gives [1, 2, [3, 4]]. extend adds each element of an iterable: it gives [1, 2, 3, 4]."},{"id":"cmpt-120-16","front":"Key facts about Python dictionaries","back":"They map keys to values. Keys must be immutable (hashable), such as str, int or tuple. d[k] raises KeyError if k is missing, while d.get(k, default) returns the default instead."},{"id":"cmpt-120-17","front":"What two parts does every correct recursive function need?","back":"A base case that returns without recursing, and a recursive case that calls the function on a smaller problem moving toward the base case. Without a reachable base case you get a RecursionError."},{"id":"cmpt-120-18","front":"Trace fact(4) where fact(n) returns 1 if n == 0, else n * fact(n − 1).","back":"fact(4) = 4 * fact(3) = 4 * 3 * fact(2) = 4 * 3 * 2 * fact(1) = 4 * 3 * 2 * 1 * fact(0) = 24."},{"id":"cmpt-120-19","front":"Linear search vs binary search","back":"Linear search checks items one by one: O(n), works on any list. Binary search repeatedly halves a SORTED list: O(log n)."},{"id":"cmpt-120-20","front":"About how many comparisons does binary search need for a sorted list of 1,000,000 items?","back":"About 20 in the worst case, since 2^20 ≈ 1,000,000. Linear search could need up to 1,000,000."},{"id":"cmpt-120-21","front":"What is the Big-O running time of two nested loops that each run n times?","back":"O(n^2), because the inner body runs n × n times. Doubling n roughly quadruples the running time."},{"id":"cmpt-120-22","front":"Running time of selection sort and insertion sort","back":"Both are O(n^2) in the worst case. Insertion sort is O(n) on an already sorted list, while selection sort is always O(n^2)."},{"id":"cmpt-120-23","front":"Why use ''with open(name) as f:'' to read a file?","back":"It automatically closes the file when the block ends, even if an error occurs. Each line read includes its trailing newline, so use line.strip() or rstrip() before processing."},{"id":"cmpt-120-24","front":"File modes ''r'', ''w'' and ''a''","back":"''r'' reads (the file must exist). ''w'' writes, creating the file or erasing existing contents. ''a'' appends to the end without erasing."},{"id":"cmpt-120-25","front":"Syntax error vs runtime error vs logic error","back":"Syntax error: the code breaks Python''s grammar and won''t run. Runtime error: it crashes while running (e.g., ZeroDivisionError). Logic error: it runs but produces the wrong answer."},{"id":"cmpt-120-26","front":"What does a try / except block do?","back":"Code in try runs normally; if a matching exception is raised, control jumps to the except block instead of crashing. Catch specific exceptions (e.g., ValueError) rather than everything."},{"id":"cmpt-120-27","front":"What is pseudocode and why write it?","back":"An informal, language-independent description of an algorithm''s steps. It lets you plan the logic before worrying about exact syntax."},{"id":"cmpt-120-28","front":"Convert decimal 13 to binary.","back":"1101, since 13 = 8 + 4 + 0 + 1. A bit is one binary digit; a byte is 8 bits, giving 256 possible values."},{"id":"cmpt-120-29","front":"What do the shell commands pwd, ls, cd and mkdir do?","back":"pwd prints the current directory, ls lists its contents, cd changes directory (cd .. goes up one level) and mkdir creates a new directory."},{"id":"cmpt-120-30","front":"What is an off-by-one error?","back":"A loop or index that goes one step too far or stops one step short, e.g., using range(1, n) when you meant 1 through n inclusive, which needs range(1, n + 1)."},{"id":"cmpt-120-31","front":"Why is 0.1 + 0.2 == 0.3 False in Python?","back":"Floats are stored in binary, which cannot represent 0.1 exactly, so the sum is 0.30000000000000004. Compare floats with a tolerance, e.g., abs(a − b) < 1e-9."},{"id":"cmpt-120-32","front":"What does [x * x for x in range(4)] produce?","back":"[0, 1, 4, 9]. A list comprehension builds a new list by applying the expression to each item."}],"quizzes":[],"seed":1,"look":{"color":"#4F46E5","icon":"code"}}'::jsonb);   -- https://www.sfu.ca/students/calendar/2026/fall/courses/cmpt/120.html
select pg_temp.sb_seed('seed:sfu-ca:chem-121', 'sfu.ca', 'CHEM 121', 'CHEM 121 Midterm Review: Atomic Structure, Bonding, Stoichiometry, Gases and Thermochemistry', '{"v":1,"app":"studyboard","type":"deck","name":"CHEM 121 Midterm Review: Atomic Structure, Bonding, Stoichiometry, Gases and Thermochemistry","course":{"code":"CHEM 121","name":"General Chemistry and Laboratory I"},"cards":[{"id":"chem-121-1","front":"How does atomic radius change across a period and down a group?","back":"It decreases left to right across a period (more protons, similar shielding, higher effective nuclear charge) and increases down a group (electrons occupy higher shells)."},{"id":"chem-121-2","front":"General trend in first ionization energy, and two common exceptions","back":"It increases across a period and decreases down a group. Exceptions: B is lower than Be (removing a 2p electron) and O is lower than N (pairing repulsion in a 2p orbital)."},{"id":"chem-121-3","front":"Electronegativity trend","back":"It increases toward the top right of the periodic table (excluding noble gases). Fluorine is the most electronegative element."},{"id":"chem-121-4","front":"What are the four quantum numbers and their allowed values?","back":"n = 1, 2, 3...; l = 0 to n − 1 (s, p, d, f); ml = −l to +l; ms = +1/2 or −1/2."},{"id":"chem-121-5","front":"Aufbau principle, Pauli exclusion principle and Hund''s rule","back":"Aufbau: fill lower-energy orbitals first. Pauli: no two electrons in an atom share all four quantum numbers, so at most 2 per orbital with opposite spins. Hund: fill degenerate orbitals singly before pairing."},{"id":"chem-121-6","front":"Write the electron configurations of Fe and Fe3+.","back":"Fe: [Ar] 4s2 3d6. Fe3+: [Ar] 3d5. When transition metals form cations, the 4s electrons are removed before the 3d electrons."},{"id":"chem-121-7","front":"Why are Cr and Cu exceptions to the expected configurations?","back":"Cr is [Ar] 4s1 3d5 and Cu is [Ar] 4s1 3d10, because half-filled and completely filled d subshells are especially stable."},{"id":"chem-121-8","front":"Relate the energy of a photon to its frequency and wavelength.","back":"E = hν = hc/λ, where h = 6.626 × 10^−34 J·s and c = 3.00 × 10^8 m/s. Shorter wavelength means higher energy."},{"id":"chem-121-9","front":"Rank the isoelectronic species O2−, F−, Na+, Mg2+ by size.","back":"O2− > F− > Na+ > Mg2+. They all have 10 electrons, so the ion with more protons pulls them in more tightly and is smaller."},{"id":"chem-121-10","front":"Formula for formal charge","back":"Formal charge = (valence electrons) − (nonbonding electrons) − (bonding electrons / 2). The best Lewis structure keeps formal charges small, with negative charge on the more electronegative atoms."},{"id":"chem-121-11","front":"VSEPR shapes of H2O and NH3","back":"Both have 4 electron domains (tetrahedral arrangement). H2O has 2 lone pairs, so it is bent (about 104.5°); NH3 has 1 lone pair, so it is trigonal pyramidal (about 107°)."},{"id":"chem-121-12","front":"Why is CO2 nonpolar while H2O is polar?","back":"Both have polar bonds, but CO2 is linear so its bond dipoles cancel. H2O is bent, so its bond dipoles add up to a net dipole."},{"id":"chem-121-13","front":"Match hybridization to electron geometry: sp, sp2, sp3.","back":"sp: 2 domains, linear, 180°. sp2: 3 domains, trigonal planar, 120°. sp3: 4 domains, tetrahedral, 109.5°."},{"id":"chem-121-14","front":"How many sigma and pi bonds are in a double bond and a triple bond?","back":"A double bond has 1 sigma and 1 pi bond; a triple bond has 1 sigma and 2 pi bonds. Every single bond is a sigma bond."},{"id":"chem-121-15","front":"Rank the main intermolecular forces and their effect on boiling point.","back":"London dispersion forces (all molecules, stronger with more electrons), then dipole-dipole, then hydrogen bonding (H bonded to N, O or F). Stronger forces give higher boiling points."},{"id":"chem-121-16","front":"What is a mole, and how do you convert grams to moles?","back":"One mole is 6.022 × 10^23 particles (Avogadro''s number). Moles = mass in grams / molar mass in g/mol."},{"id":"chem-121-17","front":"2 H2 + O2 → 2 H2O. With 4 mol H2 and 3 mol O2, what is the limiting reactant and how much water forms?","back":"4 mol H2 needs only 2 mol O2, so H2 is limiting. It makes 4 mol H2O, and 1 mol O2 is left over."},{"id":"chem-121-18","front":"How is percent yield calculated?","back":"Percent yield = (actual yield / theoretical yield) × 100%. The theoretical yield comes from the limiting reactant."},{"id":"chem-121-19","front":"What is the empirical formula of glucose, C6H12O6?","back":"CH2O, the simplest whole-number ratio of atoms. The molecular formula is a whole-number multiple of it (here 6)."},{"id":"chem-121-20","front":"Define molarity and give the dilution equation.","back":"Molarity M = moles of solute / litres of solution. For dilution, M1V1 = M2V2, because the moles of solute stay the same."},{"id":"chem-121-21","front":"Ideal gas law and the two common values of R","back":"PV = nRT, with T in kelvin. R = 0.08206 L·atm/(mol·K) or 8.314 J/(mol·K)."},{"id":"chem-121-22","front":"What volume does 1 mol of ideal gas occupy at 0 °C and 1 atm?","back":"About 22.4 L. This only applies at those conditions; at other conditions use PV = nRT."},{"id":"chem-121-23","front":"State Dalton''s law of partial pressures.","back":"Total pressure is the sum of the partial pressures: P_total = P1 + P2 + ... Each gas''s partial pressure equals its mole fraction times P_total."},{"id":"chem-121-24","front":"State Graham''s law of effusion.","back":"Rate of effusion is inversely proportional to the square root of molar mass: rate1/rate2 = √(M2/M1). H2 effuses 4 times faster than O2 because √(32/2) = 4."},{"id":"chem-121-25","front":"When do real gases deviate most from ideal behaviour?","back":"At high pressure and low temperature, when molecular volume and intermolecular attractions become significant."},{"id":"chem-121-26","front":"Sign of ΔH for exothermic and endothermic reactions","back":"Exothermic reactions release heat to the surroundings, so ΔH < 0. Endothermic reactions absorb heat, so ΔH > 0."},{"id":"chem-121-27","front":"Mini-problem: how much heat raises 100 g of water from 20 °C to 30 °C? (c = 4.184 J/g·°C)","back":"q = m·c·ΔT = 100 × 4.184 × 10 = 4184 J, or about 4.18 kJ."},{"id":"chem-121-28","front":"What does Hess''s law state?","back":"The enthalpy change of a reaction is the same whether it happens in one step or many, so ΔH values of steps can be added. Reversing a reaction flips the sign of ΔH; multiplying it scales ΔH."},{"id":"chem-121-29","front":"How do you calculate ΔH°rxn from standard enthalpies of formation?","back":"ΔH°rxn = Σ n·ΔH°f(products) − Σ n·ΔH°f(reactants). ΔH°f of an element in its standard state (e.g., O2 gas) is zero."},{"id":"chem-121-30","front":"Estimating ΔH from bond enthalpies","back":"ΔH ≈ Σ(bonds broken) − Σ(bonds formed). Breaking bonds costs energy; forming bonds releases it."},{"id":"chem-121-31","front":"What makes lattice energy larger?","back":"Higher ion charges and smaller ions. MgO (2+ and 2−) has a much larger lattice energy than NaCl (1+ and 1−)."},{"id":"chem-121-32","front":"Compare ionic, molecular, covalent network and metallic solids.","back":"Ionic: high melting, brittle, conduct when molten. Molecular: low melting. Covalent network (diamond): very high melting and hard. Metallic: conduct as solids, malleable."}],"quizzes":[],"seed":1,"look":{"color":"#E0673B","icon":"chem"}}'::jsonb);   -- https://www.sfu.ca/students/calendar/2026/fall/courses/chem/121.html
select pg_temp.sb_seed('seed:ucla-edu:lifesci-7a', 'ucla.edu', 'LIFESCI 7A', 'LIFESCI 7A Midterm Review: Biomolecules, Enzymes, Cellular Respiration and Gene Expression', '{"v":1,"app":"studyboard","type":"deck","name":"LIFESCI 7A Midterm Review: Biomolecules, Enzymes, Cellular Respiration and Gene Expression","course":{"code":"LIFESCI 7A","name":"Cell and Molecular Biology"},"cards":[{"id":"lifesci-7a-1","front":"Why is water such a good solvent for ions and polar molecules?","back":"Water is polar: its partially negative oxygen and partially positive hydrogens form hydrogen bonds with polar solutes and surround ions in hydration shells, stabilizing them in solution."},{"id":"lifesci-7a-2","front":"What is the hydrophobic effect?","back":"Nonpolar molecules cluster together in water because this reduces the ordered cage of water molecules around them, increasing water''s entropy. It drives lipid bilayer formation and helps proteins fold with nonpolar side chains buried inside."},{"id":"lifesci-7a-3","front":"Describe the four levels of protein structure.","back":"Primary: amino acid sequence. Secondary: alpha helices and beta sheets held by backbone hydrogen bonds. Tertiary: overall 3D fold from side chain interactions. Quaternary: assembly of two or more polypeptide subunits."},{"id":"lifesci-7a-4","front":"How is a peptide bond formed?","back":"By a condensation (dehydration) reaction between the carboxyl group of one amino acid and the amino group of the next, releasing water. The chain has a free amino N-terminus and a free carboxyl C-terminus."},{"id":"lifesci-7a-5","front":"Saturated vs unsaturated fatty acids","back":"Saturated fatty acids have no C=C double bonds, so straight chains pack tightly (solid fats). Unsaturated fatty acids have cis double bonds that kink the chain, lowering packing and melting point and increasing membrane fluidity."},{"id":"lifesci-7a-6","front":"Name three structural differences between DNA and RNA.","back":"DNA uses deoxyribose (no 2'' OH), thymine, and is usually double-stranded. RNA uses ribose (has a 2'' OH), uracil instead of thymine, and is usually single-stranded, often folding into complex shapes."},{"id":"lifesci-7a-7","front":"What does it mean that the two strands of DNA are antiparallel, and how do bases pair?","back":"One strand runs 5'' to 3'' while its partner runs 3'' to 5''. A pairs with T by 2 hydrogen bonds and G pairs with C by 3 hydrogen bonds, so GC-rich DNA is harder to melt."},{"id":"lifesci-7a-8","front":"What does the sign of ΔG tell you, and what is the equation?","back":"ΔG = ΔH − TΔS. Negative ΔG means exergonic and spontaneous (but not necessarily fast); positive ΔG means endergonic and requires an energy input to proceed."},{"id":"lifesci-7a-9","front":"How do enzymes speed up reactions? What do they NOT change?","back":"They lower the activation energy, mainly by stabilizing the transition state. They do not change ΔG or the equilibrium constant; they only help the reaction reach equilibrium faster."},{"id":"lifesci-7a-10","front":"Competitive vs noncompetitive inhibition: effect on Km and Vmax","back":"Competitive inhibitors bind the active site: apparent Km rises, Vmax unchanged, overcome by more substrate. Pure noncompetitive inhibitors bind elsewhere: Vmax falls, Km unchanged, not overcome by more substrate."},{"id":"lifesci-7a-11","front":"What is Km in Michaelis-Menten kinetics?","back":"The substrate concentration at which the reaction rate is half of Vmax. A lower Km means the enzyme reaches half-maximal rate at lower substrate concentration (higher apparent affinity)."},{"id":"lifesci-7a-12","front":"What is feedback inhibition?","back":"The end product of a metabolic pathway binds an allosteric site on an enzyme early in the pathway and inhibits it, so the cell stops making product when it already has enough."},{"id":"lifesci-7a-13","front":"How does ATP drive endergonic reactions?","back":"ATP hydrolysis to ADP + Pi is strongly exergonic (about −30.5 kJ/mol under standard conditions). The cell couples it to unfavorable reactions, often by transferring the phosphate to a substrate or protein, making the overall ΔG negative."},{"id":"lifesci-7a-14","front":"Define oxidation and reduction. What happens to NAD+ in metabolism?","back":"Oxidation is loss of electrons; reduction is gain of electrons (OIL RIG). NAD+ is reduced to NADH when it accepts two electrons and a proton from a fuel molecule being oxidized."},{"id":"lifesci-7a-15","front":"Glycolysis: location, inputs, and net products per glucose","back":"Occurs in the cytosol and needs no oxygen. One glucose becomes 2 pyruvate, with a net gain of 2 ATP (by substrate-level phosphorylation) and 2 NADH."},{"id":"lifesci-7a-16","front":"Pyruvate oxidation and the citric acid cycle: location and products","back":"Both occur in the mitochondrial matrix. Each pyruvate becomes acetyl-CoA, releasing CO2 and making NADH. Each turn of the cycle releases 2 CO2 and makes 3 NADH, 1 FADH2 and 1 ATP (or GTP)."},{"id":"lifesci-7a-17","front":"How do the electron transport chain and ATP synthase make ATP?","back":"Electrons from NADH and FADH2 pass through inner-membrane complexes to O2, the final acceptor, forming water. The energy pumps H+ into the intermembrane space; H+ flowing back through ATP synthase into the matrix powers ATP synthesis (chemiosmosis)."},{"id":"lifesci-7a-18","front":"What is the purpose of fermentation?","back":"To regenerate NAD+ from NADH so glycolysis can keep making ATP without oxygen. Animals make lactate; yeast make ethanol and CO2. No extra ATP is made beyond glycolysis."},{"id":"lifesci-7a-19","front":"What happens to a cell treated with an uncoupler that makes the inner mitochondrial membrane leaky to H+?","back":"Electron transport and O2 consumption continue or even increase, but the proton gradient collapses, so ATP synthase makes little ATP. The energy is released as heat."},{"id":"lifesci-7a-20","front":"What did the Meselson-Stahl experiment show?","back":"DNA replication is semiconservative. Bacteria grown in heavy 15N were moved to 14N: after one generation all DNA had hybrid density; after two generations there were hybrid and light bands, ruling out conservative and dispersive models."},{"id":"lifesci-7a-21","front":"Leading vs lagging strand synthesis","back":"DNA polymerase only adds nucleotides to a 3'' end (builds 5'' to 3''). The leading strand is made continuously toward the fork; the lagging strand is made away from the fork in short Okazaki fragments, each started by an RNA primer."},{"id":"lifesci-7a-22","front":"Match the replication enzyme to its job: helicase, primase, DNA polymerase, ligase, topoisomerase","back":"Helicase unwinds the double helix. Primase lays down RNA primers. DNA polymerase extends primers and proofreads. Ligase seals nicks between fragments. Topoisomerase relieves supercoiling ahead of the fork."},{"id":"lifesci-7a-23","front":"How does transcription differ from DNA replication in terms of direction and primers?","back":"RNA polymerase reads the template strand 3'' to 5'' and builds RNA 5'' to 3'', like DNA polymerase, but it needs no primer. It starts at a promoter and only copies one gene-sized region rather than the whole genome."},{"id":"lifesci-7a-24","front":"What three processing steps convert a eukaryotic pre-mRNA into mature mRNA?","back":"Addition of a 5'' cap, addition of a 3'' poly-A tail, and splicing, in which the spliceosome removes introns and joins exons. Alternative splicing lets one gene encode several proteins."},{"id":"lifesci-7a-25","front":"Outline translation at the ribosome.","back":"tRNA anticodons pair with mRNA codons. Initiation begins at AUG (methionine). The ribosome moves through the A, P and E sites, forming peptide bonds. A stop codon (UAA, UAG, UGA) is bound by a release factor, freeing the polypeptide."},{"id":"lifesci-7a-26","front":"Key properties of the genetic code","back":"Triplet codons read without overlap; redundant (several codons can code the same amino acid); unambiguous (each codon specifies one amino acid); and nearly universal across organisms."},{"id":"lifesci-7a-27","front":"Silent vs missense vs nonsense vs frameshift mutations","back":"Silent: codon changes but same amino acid. Missense: one amino acid replaced by another. Nonsense: codon becomes a stop codon, truncating the protein. Frameshift: insertion or deletion not a multiple of 3 shifts every downstream codon."},{"id":"lifesci-7a-28","front":"How is the lac operon regulated?","back":"Without lactose, the lac repressor binds the operator and blocks transcription. Allolactose binds the repressor and releases it. Strong transcription also needs low glucose, when cAMP-CAP binds near the promoter and recruits RNA polymerase."},{"id":"lifesci-7a-29","front":"Inducible vs repressible operons: lac vs trp","back":"The lac operon is inducible: normally off, turned on when lactose is present. The trp operon is repressible: normally on, and tryptophan acts as a corepressor that activates the repressor to shut it off."},{"id":"lifesci-7a-30","front":"How do chromatin modifications affect eukaryotic gene expression?","back":"Histone acetylation loosens chromatin and generally promotes transcription. DNA methylation (often at CpG sites) and histone deacetylation generally condense chromatin and silence genes."},{"id":"lifesci-7a-31","front":"A DNA template strand reads 3''-TAC GGA-5''. What is the mRNA and the encoded dipeptide?","back":"The mRNA is 5''-AUG CCU-3'', which encodes Met-Pro. The mRNA is complementary and antiparallel to the template, with U in place of T."}],"quizzes":[],"seed":1,"look":{"color":"#1E9E74","icon":"bio"}}'::jsonb);   -- https://mimg.ucla.edu/education/undergraduate/life-sciences-core-major-preparation
select pg_temp.sb_seed('seed:ucla-edu:chem-14a', 'ucla.edu', 'CHEM 14A', 'CHEM 14A Exam Review: Quantum Atom, Periodic Trends, Chemical Bonding and Acids and Bases', '{"v":1,"app":"studyboard","type":"deck","name":"CHEM 14A Exam Review: Quantum Atom, Periodic Trends, Chemical Bonding and Acids and Bases","course":{"code":"CHEM 14A","name":"General Chemistry for Life Scientists I"},"cards":[{"id":"chem-14a-1","front":"Energy of a photon: formula and constants","back":"E = hν = hc/λ, where h = 6.626×10^−34 J·s (Planck''s constant), ν is frequency, c = 3.00×10^8 m/s, and λ is wavelength. Shorter wavelength means higher energy."},{"id":"chem-14a-2","front":"What did the photoelectric effect show, and what is its equation?","back":"Electrons are ejected only if the light''s frequency exceeds a threshold, regardless of intensity, showing light comes in photons. KE of ejected electron = hν − Φ, where Φ is the metal''s work function."},{"id":"chem-14a-3","front":"In the photoelectric effect, what happens if you increase light intensity at a fixed frequency above threshold?","back":"More electrons are ejected per second, but each electron''s maximum kinetic energy stays the same, because KE depends only on photon frequency."},{"id":"chem-14a-4","front":"de Broglie wavelength formula","back":"λ = h/(mv), where m is mass and v is speed. Matter has wave properties, noticeable only for very small masses like electrons."},{"id":"chem-14a-5","front":"State the Heisenberg uncertainty principle.","back":"Δx·Δp ≥ h/(4π). The more precisely a particle''s position is known, the less precisely its momentum can be known, so electrons are described by orbitals (probability distributions), not exact paths."},{"id":"chem-14a-6","front":"Energy levels of the hydrogen atom","back":"E_n = −hR/n^2, with R = 3.29×10^15 Hz (equivalently −2.18×10^−18 J/n^2). A photon is emitted when the electron drops to lower n and absorbed when it rises to higher n."},{"id":"chem-14a-7","front":"List the four quantum numbers and their allowed values.","back":"n = 1, 2, 3, ... (shell, size). l = 0 to n−1 (subshell shape: s, p, d, f). ml = −l to +l (orientation). ms = +1/2 or −1/2 (spin)."},{"id":"chem-14a-8","front":"How many orbitals are in a subshell and in a shell?","back":"A subshell with quantum number l has 2l + 1 orbitals (s 1, p 3, d 5, f 7). Shell n has n^2 orbitals and can hold 2n^2 electrons."},{"id":"chem-14a-9","front":"State the Pauli exclusion principle and Hund''s rule.","back":"Pauli: no two electrons in an atom share all four quantum numbers, so an orbital holds at most 2 electrons of opposite spin. Hund: degenerate orbitals fill singly with parallel spins before any pairing."},{"id":"chem-14a-10","front":"Ground-state electron configurations of Cr and Cu","back":"Cr is [Ar]3d5 4s1 and Cu is [Ar]3d10 4s1. A half-filled or filled d subshell is extra stable, so one 4s electron moves into 3d."},{"id":"chem-14a-11","front":"What is effective nuclear charge and how does it explain atomic radius trends?","back":"Zeff is the nuclear charge felt by an electron after shielding by inner electrons. Zeff rises across a period, pulling electrons closer, so radius decreases left to right; radius increases down a group as electrons occupy higher n shells."},{"id":"chem-14a-12","front":"General ionization energy trend and its two common exceptions","back":"IE increases up a group and left to right across a period. Exceptions: B is lower than Be (removing a higher-energy 2p electron) and O is lower than N (removing a paired 2p electron with extra repulsion)."},{"id":"chem-14a-13","front":"Electronegativity trend","back":"Electronegativity increases toward the upper right of the periodic table (excluding noble gases). Fluorine is the most electronegative element, about 4.0 on the Pauling scale."},{"id":"chem-14a-14","front":"Formal charge formula and how to use it","back":"FC = V − (L + B/2), where V = valence electrons of the free atom, L = lone-pair electrons, B = bonding electrons. Prefer structures with formal charges closest to zero and any negative charge on the more electronegative atom."},{"id":"chem-14a-15","front":"What is resonance? Use carbonate as an example.","back":"When several valid Lewis structures differ only in electron placement, the real molecule is a hybrid with delocalized electrons. In CO3^2−, all three C–O bonds are identical with bond order 4/3."},{"id":"chem-14a-16","front":"Which atoms can have an expanded octet, and why?","back":"Atoms in period 3 and below (such as P in PCl5, S in SF6, Xe in XeF4). They are larger and have more room around them for more than 8 valence electrons; period 2 atoms like C, N, O, F cannot."},{"id":"chem-14a-17","front":"VSEPR electron geometries for 2, 3, 4, 5 and 6 electron domains","back":"2 linear (180°), 3 trigonal planar (120°), 4 tetrahedral (109.5°), 5 trigonal bipyramidal (90° and 120°), 6 octahedral (90°)."},{"id":"chem-14a-18","front":"Molecular shapes of NH3, H2O, SF4, ClF3 and XeF4","back":"NH3 trigonal pyramidal (~107°), H2O bent (~104.5°), SF4 seesaw, ClF3 T-shaped, XeF4 square planar. Lone pairs repel more than bonding pairs and compress bond angles."},{"id":"chem-14a-19","front":"When is a molecule polar? Compare CO2 and H2O.","back":"It needs polar bonds arranged so their dipoles do not cancel. Linear CO2 has polar bonds that cancel, so it is nonpolar. Bent H2O has dipoles that add, so it is polar."},{"id":"chem-14a-20","front":"Match steric number to hybridization.","back":"Steric number 2: sp. 3: sp2. 4: sp3. 5: sp3d. 6: sp3d2. Steric number = number of atoms bonded to the central atom plus its lone pairs."},{"id":"chem-14a-21","front":"Sigma vs pi bonds in single, double and triple bonds","back":"A single bond is 1 σ. A double bond is 1 σ + 1 π. A triple bond is 1 σ + 2 π. Pi bonds come from side-on p-orbital overlap and prevent rotation around the bond."},{"id":"chem-14a-22","front":"Bond order from molecular orbital theory, and why O2 is paramagnetic","back":"Bond order = (bonding electrons − antibonding electrons)/2. O2 has bond order 2 and two unpaired electrons in degenerate π* orbitals, so it is attracted to a magnetic field, which Lewis structures fail to predict."},{"id":"chem-14a-23","front":"Why does He2 not exist as a stable molecule?","back":"Its 4 electrons fill both σ1s (bonding) and σ*1s (antibonding), giving bond order (2 − 2)/2 = 0, so there is no net bond."},{"id":"chem-14a-24","front":"What is a coordination compound? Define ligand, coordination number and chelate.","back":"A central metal ion bonded to ligands, which are Lewis bases donating lone pairs. Coordination number is the number of donor atoms bonded to the metal. A chelating ligand, like ethylenediamine, binds through two or more donor atoms."},{"id":"chem-14a-25","front":"Brønsted-Lowry vs Lewis acids and bases","back":"Brønsted-Lowry: acid donates H+, base accepts H+. Lewis: acid accepts an electron pair, base donates an electron pair. Every Brønsted base is a Lewis base, but Lewis acids include species without H, like BF3 or metal ions."},{"id":"chem-14a-26","front":"How are Ka and Kb of a conjugate pair related?","back":"Ka × Kb = Kw = 1.0×10^−14 at 25 °C (pKa + pKb = 14). The stronger the acid, the weaker its conjugate base."},{"id":"chem-14a-27","front":"List the common strong acids.","back":"HCl, HBr, HI, HNO3, H2SO4 (first proton), HClO4 and HClO3. They ionize essentially completely in water, so [H3O+] equals the acid concentration."},{"id":"chem-14a-28","front":"What makes one oxoacid stronger than another? Rank HClO, HClO2, HClO3, HClO4.","back":"More oxygens (more electronegative atoms) pull electron density away and stabilize the conjugate base by delocalizing charge. Strength: HClO4 > HClO3 > HClO2 > HClO."},{"id":"chem-14a-29","front":"Why is HI a stronger acid than HF?","back":"For binary acids in the same group, bond strength dominates. The H–I bond is much longer and weaker than H–F, so HI ionizes more easily, even though F is more electronegative."},{"id":"chem-14a-30","front":"Mini-problem: pH of 0.10 M acetic acid (Ka = 1.8×10^−5)","back":"[H3O+] ≈ sqrt(Ka × C) = sqrt(1.8×10^−6) ≈ 1.3×10^−3 M, so pH ≈ 2.87. The approximation is valid because x is under 5% of 0.10 M."},{"id":"chem-14a-31","front":"Henderson-Hasselbalch equation and the effective range of a buffer","back":"pH = pKa + log([A−]/[HA]). A buffer works best within about pKa ± 1, and has pH = pKa when [A−] = [HA]."},{"id":"chem-14a-32","front":"Weak acid titrated with strong base: pH at the half-equivalence and equivalence points","back":"At half-equivalence, [HA] = [A−], so pH = pKa. At equivalence, only the conjugate base remains, so the pH is above 7."}],"quizzes":[],"seed":1,"look":{"color":"#E0673B","icon":"chem"}}'::jsonb);   -- https://summer.chem.ucla.edu/ucla-curriculum-3-1
select pg_temp.sb_seed('seed:ucla-edu:econ-1', 'ucla.edu', 'ECON 1', 'ECON 1 Midterm Review: Trade, Supply and Demand, Elasticity, Welfare and Costs of Production', '{"v":1,"app":"studyboard","type":"deck","name":"ECON 1 Midterm Review: Trade, Supply and Demand, Elasticity, Welfare and Costs of Production","course":{"code":"ECON 1","name":"Principles of Economics"},"cards":[{"id":"econ-1-1","front":"What is opportunity cost?","back":"The value of the next best alternative you give up when making a choice. For example, the opportunity cost of college includes forgone wages, not just tuition."},{"id":"econ-1-2","front":"What does it mean to think at the margin?","back":"Rational decision-makers compare the marginal benefit and marginal cost of one more unit of an activity and keep going as long as marginal benefit is at least marginal cost."},{"id":"econ-1-3","front":"Production possibilities frontier: what do the curve''s shape and points mean?","back":"The PPF shows the maximum output combinations given resources and technology. Points inside are inefficient, points outside are unattainable. Its bowed-out shape reflects increasing opportunity cost; growth shifts it outward."},{"id":"econ-1-4","front":"Absolute vs comparative advantage","back":"Absolute advantage: producing a good using fewer inputs than another producer. Comparative advantage: producing a good at a lower opportunity cost. Gains from trade depend on comparative advantage."},{"id":"econ-1-5","front":"Mini-problem: In an hour Ana makes 4 shirts or 2 hats; Ben makes 3 shirts or 3 hats. Who has comparative advantage in hats?","back":"Ben. Ana''s opportunity cost of 1 hat is 2 shirts; Ben''s is 1 shirt. Ana has comparative advantage in shirts (1/2 hat per shirt vs Ben''s 1 hat per shirt)."},{"id":"econ-1-6","front":"For trade to benefit both parties, where must the price (terms of trade) fall?","back":"Between the two producers'' opportunity costs of the good. For example, if hats cost Ben 1 shirt and Ana 2 shirts, a price between 1 and 2 shirts per hat benefits both."},{"id":"econ-1-7","front":"Change in quantity demanded vs change in demand","back":"A change in the good''s own price causes a movement along the demand curve (change in quantity demanded). A change in any other determinant shifts the entire demand curve (change in demand)."},{"id":"econ-1-8","front":"What shifts the demand curve?","back":"Income, prices of related goods (substitutes and complements), tastes, expectations about the future, and the number of buyers."},{"id":"econ-1-9","front":"Normal vs inferior goods","back":"For a normal good, demand rises when income rises. For an inferior good (such as bus rides or instant noodles for many people), demand falls when income rises."},{"id":"econ-1-10","front":"Substitutes vs complements","back":"Substitutes: a rise in the price of one increases demand for the other (coffee and tea). Complements: a rise in the price of one decreases demand for the other (cars and gasoline)."},{"id":"econ-1-11","front":"What shifts the supply curve?","back":"Input prices, technology, expectations about the future, and the number of sellers. A cost increase shifts supply left; a technology improvement shifts it right."},{"id":"econ-1-12","front":"What happens when price is above or below equilibrium?","back":"Above equilibrium, quantity supplied exceeds quantity demanded (surplus), pushing price down. Below, quantity demanded exceeds quantity supplied (shortage), pushing price up."},{"id":"econ-1-13","front":"If supply and demand both increase, what happens to equilibrium price and quantity?","back":"Equilibrium quantity rises. The price change is ambiguous: it rises if demand shifts more than supply and falls if supply shifts more."},{"id":"econ-1-14","front":"Price elasticity of demand using the midpoint method","back":"Elasticity = (percent change in Qd)/(percent change in P), where percent change = (new − old)/average of the two values. Report the absolute value."},{"id":"econ-1-15","front":"How does total revenue respond to a price increase when demand is elastic vs inelastic?","back":"Elastic (elasticity > 1): total revenue falls when price rises. Inelastic (< 1): total revenue rises. Unit elastic (= 1): total revenue unchanged."},{"id":"econ-1-16","front":"What makes demand more price elastic?","back":"Close substitutes available, the good is a luxury rather than a necessity, the market is narrowly defined, and a longer time horizon to adjust."},{"id":"econ-1-17","front":"Interpret the signs of income elasticity and cross-price elasticity.","back":"Income elasticity > 0 means a normal good, < 0 an inferior good. Cross-price elasticity > 0 means substitutes, < 0 means complements."},{"id":"econ-1-18","front":"What does a binding price ceiling do? Give an example.","back":"A legal maximum price set below equilibrium creates a shortage (Qd > Qs), possibly with waiting lines, lower quality or black markets. Rent control is a classic example."},{"id":"econ-1-19","front":"What does a binding price floor do? Give an example.","back":"A legal minimum price set above equilibrium creates a surplus (Qs > Qd). A minimum wage above the equilibrium wage can create unemployment, especially among less-skilled workers."},{"id":"econ-1-20","front":"Who bears the burden of a tax?","back":"The side of the market that is less elastic bears more of the burden, regardless of whether the tax is legally collected from buyers or sellers."},{"id":"econ-1-21","front":"Define consumer surplus and producer surplus.","back":"Consumer surplus is buyers'' willingness to pay minus the price paid (area below demand, above price). Producer surplus is price received minus sellers'' cost (area above supply, below price)."},{"id":"econ-1-22","front":"Mini-problem: Demand is P = 10 − Q and the price is 4. What is consumer surplus?","back":"At P = 4, Q = 6. Consumer surplus = 1/2 × 6 × (10 − 4) = 18."},{"id":"econ-1-23","front":"What is deadweight loss from a tax, and how does it scale?","back":"The lost total surplus from trades that no longer happen because the tax drives a wedge between buyer and seller prices. It is larger with more elastic supply or demand and grows with the square of the tax: doubling a tax roughly quadruples DWL."},{"id":"econ-1-24","front":"When a country opens to trade and the world price is below its domestic price, who gains and who loses?","back":"The country imports. Domestic consumers gain, domestic producers lose, and total surplus rises because consumers'' gains exceed producers'' losses."},{"id":"econ-1-25","front":"What does a tariff on imports do?","back":"It raises the domestic price, increasing domestic production and reducing imports and consumption. Producers and the government gain, consumers lose more, so a deadweight loss results."},{"id":"econ-1-26","front":"Negative externality: market outcome and a standard fix","back":"When production imposes uncompensated costs on others (like pollution), the market produces more than the socially optimal quantity. A Pigovian tax equal to the external cost per unit can correct it."},{"id":"econ-1-27","front":"State the Coase theorem.","back":"If private parties can bargain at negligible cost, they can reach an efficient outcome on externalities on their own, regardless of the initial allocation of property rights."},{"id":"econ-1-28","front":"Public goods vs common resources","back":"Public goods are nonexcludable and nonrival (national defense), leading to free riding and underprovision. Common resources are rival but nonexcludable (ocean fish), leading to overuse, the tragedy of the commons."},{"id":"econ-1-29","front":"Accounting profit vs economic profit","back":"Accounting profit = revenue − explicit costs. Economic profit = revenue − explicit costs − implicit costs (opportunity costs such as the owner''s forgone wages), so it is usually smaller."},{"id":"econ-1-30","front":"Why does the marginal cost curve cross average total cost at its minimum?","back":"When MC is below ATC, each extra unit pulls the average down; when MC is above ATC, it pulls the average up. So ATC is at its lowest exactly where MC = ATC."},{"id":"econ-1-31","front":"How are total, fixed, variable and average costs related?","back":"TC = FC + VC. ATC = TC/Q = AFC + AVC. Fixed costs do not vary with output in the short run; AFC falls steadily as Q rises."},{"id":"econ-1-32","front":"What is diminishing marginal product?","back":"As more of a variable input (like workers) is added to a fixed input (like a factory), each additional unit eventually adds less output. This makes marginal cost rise as output increases."}],"quizzes":[],"seed":1,"look":{"color":"#C79A12","icon":"econ"}}'::jsonb);   -- https://economics.ucla.edu/summer/virtual
select pg_temp.sb_seed('seed:umich-edu:psych-111', 'umich.edu', 'PSYCH 111', 'PSYCH 111 Exam Review: Research Methods, Biopsychology, Sensation and Learning', '{"v":1,"app":"studyboard","type":"deck","name":"PSYCH 111 Exam Review: Research Methods, Biopsychology, Sensation and Learning","course":{"code":"PSYCH 111","name":"Introduction to Psychology"},"cards":[{"id":"psych-111-1","front":"Independent vs dependent variable","back":"The independent variable is what the researcher manipulates; the dependent variable is the outcome measured to see whether it changed because of the manipulation."},{"id":"psych-111-2","front":"Why doesn''t correlation imply causation?","back":"A third variable might cause both (third-variable problem), or the causal direction might be reversed (directionality problem). Only experiments with random assignment support causal conclusions."},{"id":"psych-111-3","front":"What does a correlation coefficient (r) tell you?","back":"r ranges from −1 to +1. The sign shows direction (positive or negative relationship) and the absolute value shows strength; r = 0 means no linear relationship."},{"id":"psych-111-4","front":"Random sampling vs random assignment","back":"Random sampling selects participants so the sample represents the population (helps generalization). Random assignment places participants into conditions by chance so groups are equivalent (supports causal claims)."},{"id":"psych-111-5","front":"What is an operational definition?","back":"A precise description of how a variable will be measured or manipulated in a study, such as defining aggression as the number of times a child hits a doll in 10 minutes."},{"id":"psych-111-6","front":"What is a double-blind study, and what problems does it prevent?","back":"Neither participants nor the researchers interacting with them know who is in which condition. It controls placebo effects and experimenter bias."},{"id":"psych-111-7","front":"What is a confounding variable?","back":"A variable other than the independent variable that differs systematically between conditions, so it offers an alternative explanation for the results."},{"id":"psych-111-8","front":"Reliability vs validity","back":"Reliability is consistency: the measure gives similar results across time or raters. Validity is accuracy: it measures what it claims to measure. A measure can be reliable without being valid."},{"id":"psych-111-9","front":"Main parts of a neuron and their functions","back":"Dendrites receive signals; the cell body (soma) integrates them; the axon carries the action potential; the myelin sheath speeds conduction; axon terminals release neurotransmitter."},{"id":"psych-111-10","front":"Describe the action potential.","back":"Resting potential is about −70 mV. When stimulation reaches threshold (about −55 mV), Na+ channels open and Na+ rushes in (depolarization), then K+ flows out (repolarization). It is all-or-none: intensity is coded by firing rate."},{"id":"psych-111-11","front":"What happens at a chemical synapse?","back":"The action potential triggers release of neurotransmitter into the synaptic cleft. It binds receptors on the postsynaptic cell, producing excitatory or inhibitory effects, and is cleared by reuptake or enzymatic breakdown."},{"id":"psych-111-12","front":"Key functions of dopamine, serotonin, acetylcholine, GABA and glutamate","back":"Dopamine: reward and movement (loss in Parkinson''s). Serotonin: mood, sleep, appetite. Acetylcholine: muscle contraction and memory (reduced in Alzheimer''s). GABA: main inhibitory. Glutamate: main excitatory."},{"id":"psych-111-13","front":"Agonist vs antagonist drugs","back":"An agonist mimics or enhances a neurotransmitter''s effect. An antagonist blocks or reduces it, for example by occupying receptors without activating them."},{"id":"psych-111-14","front":"Sympathetic vs parasympathetic nervous system","back":"Sympathetic: fight or flight, raising heart rate, dilating pupils, slowing digestion. Parasympathetic: rest and digest, calming the body and conserving energy."},{"id":"psych-111-15","front":"Main function of each cerebral lobe","back":"Frontal: planning, decision making, motor control. Parietal: touch and spatial processing. Occipital: vision. Temporal: hearing, language comprehension, and memory (with nearby medial structures)."},{"id":"psych-111-16","front":"Broca''s vs Wernicke''s aphasia","back":"Broca''s area damage (left frontal) causes halting, effortful speech with relatively intact comprehension. Wernicke''s area damage (left temporal) causes fluent but meaningless speech and poor comprehension."},{"id":"psych-111-17","front":"Roles of the hippocampus, amygdala and hypothalamus","back":"Hippocampus: forming new explicit memories. Amygdala: fear and emotional responses. Hypothalamus: hunger, thirst, temperature, and control of the pituitary gland."},{"id":"psych-111-18","front":"What did split-brain studies (Sperry and Gazzaniga) reveal?","back":"With the corpus callosum cut, an object shown only to the right hemisphere (left visual field) could not be named aloud but could be picked out by the left hand, showing the left hemisphere''s dominance for language in most people."},{"id":"psych-111-19","front":"Sensation vs perception, and what is transduction?","back":"Sensation is detecting physical energy with sense receptors; perception is organizing and interpreting it. Transduction is converting stimulus energy into neural signals."},{"id":"psych-111-20","front":"Absolute threshold vs difference threshold, and Weber''s law","back":"Absolute threshold: the minimum stimulus detected 50% of the time. Difference threshold (JND): the smallest detectable change. Weber''s law: the JND is a constant proportion of the original stimulus."},{"id":"psych-111-21","front":"What does signal detection theory add to the idea of thresholds?","back":"Detection depends on both sensitivity and the observer''s response bias (criterion). Outcomes are hits, misses, false alarms and correct rejections."},{"id":"psych-111-22","front":"Rods vs cones","back":"Rods are very sensitive to dim light, more numerous in the periphery, and do not detect color. Cones work in bright light, are concentrated in the fovea, and support color and fine detail."},{"id":"psych-111-23","front":"Trichromatic vs opponent-process theory of color","back":"Trichromatic: three cone types (short, medium, long wavelength) explain color at the receptor level. Opponent-process: red-green, blue-yellow and black-white channels later in processing explain afterimages."},{"id":"psych-111-24","front":"Define UCS, UCR, CS and CR in classical conditioning using Pavlov''s dogs.","back":"Food is the UCS, which naturally produces salivation (UCR). A tone (initially neutral) paired with food becomes the CS, and salivation to the tone alone is the CR."},{"id":"psych-111-25","front":"Extinction vs spontaneous recovery","back":"Extinction: the CR weakens when the CS is repeatedly presented without the UCS. Spontaneous recovery: after a rest period, the extinguished CR briefly reappears."},{"id":"psych-111-26","front":"Positive vs negative reinforcement and punishment","back":"Reinforcement increases behavior; punishment decreases it. Positive means adding a stimulus; negative means removing one. Removing a headache by taking aspirin is negative reinforcement."},{"id":"psych-111-27","front":"Which schedule of reinforcement produces high, steady responding that is most resistant to extinction?","back":"Variable ratio, which reinforces after an unpredictable number of responses, like a slot machine."},{"id":"psych-111-28","front":"What did Bandura''s Bobo doll study show?","back":"Children who watched an adult behave aggressively toward a doll were more likely to imitate the aggression, demonstrating observational learning without direct reinforcement."},{"id":"psych-111-29","front":"Stimulus generalization vs discrimination, using Little Albert","back":"After a white rat was paired with a loud noise, Albert also feared similar white furry objects (generalization). Discrimination is learning to respond only to the specific CS and not similar stimuli."},{"id":"psych-111-30","front":"Binocular vs monocular depth cues","back":"Binocular cues need both eyes: retinal disparity and convergence. Monocular cues work with one eye: relative size, interposition, linear perspective, texture gradient and motion parallax."}],"quizzes":[],"seed":1,"look":{"color":"#9A4FD1","icon":"psych"}}'::jsonb);   -- https://prod.lsa.umich.edu/content/dam/psychassets/psychdocuments/MajorInBCNPsych/PsychologyWSFa21_Stats%20update.pdf
select pg_temp.sb_seed('seed:umich-edu:chem-130', 'umich.edu', 'CHEM 130', 'CHEM 130 Exam Review: Stoichiometry, Gases, Thermochemistry and Chemical Equilibrium', '{"v":1,"app":"studyboard","type":"deck","name":"CHEM 130 Exam Review: Stoichiometry, Gases, Thermochemistry and Chemical Equilibrium","course":{"code":"CHEM 130","name":"General Chemistry: Macroscopic Investigations and Reaction Principles"},"cards":[{"id":"chem-130-1","front":"What is a mole?","back":"An amount containing 6.022×10^23 particles (Avogadro''s number). The mass of one mole of a substance in grams equals its formula mass in atomic mass units."},{"id":"chem-130-2","front":"Mini-problem: How many moles are in 36.0 g of water?","back":"Molar mass of H2O = 2(1.008) + 16.00 = 18.02 g/mol, so 36.0 g ÷ 18.02 g/mol ≈ 2.00 mol."},{"id":"chem-130-3","front":"Mini-problem: 2H2 + O2 → 2H2O with 4 mol H2 and 3 mol O2. Which is limiting, and how much water forms?","back":"4 mol H2 needs only 2 mol O2, so H2 is limiting. 4 mol H2O forms and 1 mol O2 is left over."},{"id":"chem-130-4","front":"Percent yield formula","back":"Percent yield = (actual yield ÷ theoretical yield) × 100%. Theoretical yield is calculated from the limiting reactant."},{"id":"chem-130-5","front":"Empirical vs molecular formula","back":"The empirical formula is the simplest whole-number ratio of atoms; the molecular formula is the actual number. Glucose is C6H12O6 with empirical formula CH2O."},{"id":"chem-130-6","front":"Molarity and the dilution equation","back":"Molarity M = moles of solute ÷ liters of solution. When diluting, moles of solute stay constant: M1V1 = M2V2."},{"id":"chem-130-7","front":"Write the net ionic equation for mixing AgNO3(aq) and NaCl(aq).","back":"Ag+(aq) + Cl−(aq) → AgCl(s). Na+ and NO3− are spectator ions and are left out."},{"id":"chem-130-8","front":"How do you identify oxidation and reduction in a reaction using oxidation numbers?","back":"The species whose oxidation number increases is oxidized (it is the reducing agent); the species whose oxidation number decreases is reduced (it is the oxidizing agent)."},{"id":"chem-130-9","front":"Ideal gas law and the two common values of R","back":"PV = nRT. R = 0.08206 L·atm/(mol·K) when using liters and atmospheres, or 8.314 J/(mol·K) for energy units. Temperature must be in kelvin."},{"id":"chem-130-10","front":"Molar volume of an ideal gas at STP","back":"At STP (0 °C = 273.15 K and 1 atm), one mole of an ideal gas occupies about 22.4 L."},{"id":"chem-130-11","front":"Dalton''s law of partial pressures","back":"P_total = P1 + P2 + ... and each partial pressure Pi = xi × P_total, where xi is the mole fraction of gas i."},{"id":"chem-130-12","front":"What does kinetic molecular theory say about temperature and molecular speed?","back":"Average kinetic energy is proportional to absolute temperature. Root-mean-square speed = sqrt(3RT/M), with M in kg/mol, so at the same temperature lighter gases move faster."},{"id":"chem-130-13","front":"Graham''s law of effusion","back":"rate1/rate2 = sqrt(M2/M1). For example, H2 (2 g/mol) effuses about 4 times faster than O2 (32 g/mol)."},{"id":"chem-130-14","front":"When do real gases deviate most from ideal behavior, and why?","back":"At high pressure and low temperature, when molecules are close together: their own volume and intermolecular attractions are no longer negligible."},{"id":"chem-130-15","front":"Sign of ΔH for exothermic vs endothermic processes","back":"Exothermic: heat flows from system to surroundings, ΔH < 0, surroundings warm up. Endothermic: heat flows into the system, ΔH > 0, surroundings cool down."},{"id":"chem-130-16","front":"Heat equation for a temperature change, and the specific heat of water","back":"q = m·c·ΔT, where m is mass, c is specific heat capacity and ΔT is the temperature change. For liquid water, c = 4.184 J/(g·°C)."},{"id":"chem-130-17","front":"Mini-problem: How much heat raises 50.0 g of water from 20.0 °C to 30.0 °C?","back":"q = (50.0 g)(4.184 J/g·°C)(10.0 °C) = 2092 J ≈ 2.09 kJ."},{"id":"chem-130-18","front":"State Hess''s law.","back":"Because enthalpy is a state function, ΔH for an overall reaction equals the sum of ΔH values for any series of steps that add up to it. Reversing a step flips the sign; multiplying a step multiplies ΔH."},{"id":"chem-130-19","front":"How do you calculate ΔH°rxn from standard enthalpies of formation?","back":"ΔH°rxn = Σ n·ΔH°f(products) − Σ n·ΔH°f(reactants). ΔH°f of an element in its standard state (like O2(g) or C(graphite)) is zero."},{"id":"chem-130-20","front":"How do you estimate ΔH from bond enthalpies?","back":"ΔH ≈ Σ (bond enthalpies of bonds broken) − Σ (bond enthalpies of bonds formed). Breaking bonds costs energy; forming bonds releases it."},{"id":"chem-130-21","front":"Coffee-cup vs bomb calorimeter","back":"A coffee-cup calorimeter works at constant pressure and measures ΔH. A bomb calorimeter works at constant volume and measures ΔU (ΔE), often for combustion."},{"id":"chem-130-22","front":"Write the equilibrium expression rules. What is left out?","back":"K = [products]^coefficients ÷ [reactants]^coefficients. Pure solids and pure liquids are left out because their activity is 1."},{"id":"chem-130-23","front":"Reaction quotient Q vs K: which way does the reaction shift?","back":"If Q < K, the reaction proceeds forward toward products. If Q > K, it proceeds in reverse toward reactants. If Q = K, the system is at equilibrium."},{"id":"chem-130-24","front":"Le Châtelier: effect of decreasing the volume of a gaseous equilibrium","back":"Pressure increases, and the equilibrium shifts toward the side with fewer moles of gas. Adding an inert gas at constant volume causes no shift."},{"id":"chem-130-25","front":"How does raising temperature affect K for an exothermic reaction?","back":"K decreases, because heat acts like a product; the equilibrium shifts toward reactants. For an endothermic reaction, K increases with temperature. Temperature is the only factor that changes K."},{"id":"chem-130-26","front":"How does K change when you reverse a reaction, multiply it by n, or add reactions?","back":"Reverse: K becomes 1/K. Multiply all coefficients by n: K becomes K^n. Add two reactions: multiply their K values."},{"id":"chem-130-27","front":"How are Kp and Kc related?","back":"Kp = Kc(RT)^Δn, where Δn = moles of gaseous products − moles of gaseous reactants and R = 0.08206 L·atm/(mol·K)."},{"id":"chem-130-28","front":"Mini-problem: For A ⇌ B with K = 4.0, starting with 1.0 M A and no B, find equilibrium concentrations.","back":"ICE: [B] = x, [A] = 1.0 − x. x/(1.0 − x) = 4.0, so x = 0.80. At equilibrium [A] = 0.20 M and [B] = 0.80 M."},{"id":"chem-130-29","front":"What does a catalyst do to an equilibrium?","back":"Nothing to the position of equilibrium or K. It speeds up forward and reverse reactions equally, so equilibrium is reached faster."},{"id":"chem-130-30","front":"Electron configurations of Fe and Fe3+","back":"Fe is [Ar]4s2 3d6. Fe3+ is [Ar]3d5: transition metals lose their 4s electrons before 3d electrons when forming cations."},{"id":"chem-130-31","front":"Rank O2−, F−, Na+ and Mg2+ by size and explain.","back":"O2− > F− > Na+ > Mg2+. They are isoelectronic (10 electrons), so the ion with more protons pulls the same electrons in more tightly and is smaller."},{"id":"chem-130-32","front":"Why does MgO have a much larger lattice energy than NaCl?","back":"By Coulomb''s law, lattice energy grows with the product of ion charges and shrinks with distance. Mg2+ and O2− have double charges and are smaller than Na+ and Cl−."}],"quizzes":[],"seed":1,"look":{"color":"#DC2626","icon":"chem"}}'::jsonb);   -- https://prod.lsa.umich.edu/advising/plan-your-time-at-michigan/placement-and-credit.html
select pg_temp.sb_seed('seed:umich-edu:econ-101', 'umich.edu', 'ECON 101', 'ECON 101 Final Review: Consumer Choice, Market Structures, Labor, Inequality and Market Failures', '{"v":1,"app":"studyboard","type":"deck","name":"ECON 101 Final Review: Consumer Choice, Market Structures, Labor, Inequality and Market Failures","course":{"code":"ECON 101","name":"Principles of Economics I"},"cards":[{"id":"econ-101-1","front":"What is diminishing marginal utility?","back":"Each additional unit of a good consumed adds less extra satisfaction than the one before. It helps explain why demand curves slope downward."},{"id":"econ-101-2","front":"State the utility-maximizing rule for two goods.","back":"Spend your budget so that MU_x/P_x = MU_y/P_y: the last dollar spent on each good gives the same extra utility. If one ratio is higher, shift spending toward that good."},{"id":"econ-101-3","front":"What is the slope of a budget constraint with good X on the horizontal axis?","back":"−Px/Py, the rate at which the market lets you trade Y for X. A change in income shifts the line in parallel; a change in one price rotates it."},{"id":"econ-101-4","front":"Income effect vs substitution effect of a price drop","back":"Substitution effect: the good is now relatively cheaper, so you buy more of it. Income effect: your purchasing power rises, so you buy more if it is normal and less if it is inferior."},{"id":"econ-101-5","front":"What output rule maximizes profit for any firm?","back":"Produce where marginal revenue equals marginal cost (MR = MC), as long as price covers average variable cost."},{"id":"econ-101-6","front":"Key features of perfect competition, and why P = MR","back":"Many buyers and sellers, identical products, free entry and exit, full information. Each firm is a price taker, so selling one more unit always adds exactly the market price to revenue."},{"id":"econ-101-7","front":"When should a competitive firm shut down in the short run?","back":"When price falls below minimum average variable cost. Fixed costs must be paid either way, so the firm keeps producing as long as revenue covers variable costs."},{"id":"econ-101-8","front":"Describe long-run equilibrium in a perfectly competitive market.","back":"Economic profits attract entry and losses cause exit until P = minimum ATC. Firms earn zero economic profit and produce at the efficient scale."},{"id":"econ-101-9","front":"What is a sunk cost, and how should it affect decisions?","back":"A cost that has already been incurred and cannot be recovered. It should be ignored in decisions about what to do next, since only marginal costs and benefits matter."},{"id":"econ-101-10","front":"How does a monopolist choose price and quantity?","back":"It produces where MR = MC, then charges the highest price buyers will pay for that quantity (read from the demand curve). Because MR < P, it produces less than the efficient quantity, creating deadweight loss."},{"id":"econ-101-11","front":"Mini-problem: Demand is P = 100 − 2Q and MC = 20. Find the monopoly quantity and price.","back":"MR = 100 − 4Q. Set MR = MC: 100 − 4Q = 20, so Q = 20. Price from demand: P = 100 − 2(20) = 60."},{"id":"econ-101-12","front":"What is a natural monopoly?","back":"An industry where one firm can supply the whole market at lower average cost than two or more firms, typically due to large fixed costs, such as water or power distribution."},{"id":"econ-101-13","front":"What is perfect (first-degree) price discrimination and its welfare effect?","back":"Charging each buyer exactly their willingness to pay. Output reaches the efficient level, so there is no deadweight loss, but the firm captures all the surplus and consumer surplus is zero."},{"id":"econ-101-14","front":"Long-run equilibrium in monopolistic competition","back":"Entry drives economic profit to zero (P = ATC), but each firm''s demand slopes down, so P > MC and firms produce below efficient scale (excess capacity)."},{"id":"econ-101-15","front":"What is a Nash equilibrium?","back":"A set of strategies in which each player''s choice is the best response to the others'' choices, so no player can gain by changing strategy alone."},{"id":"econ-101-16","front":"What is a dominant strategy?","back":"A strategy that gives a player a better payoff than any alternative no matter what the other players do."},{"id":"econ-101-17","front":"Explain the prisoner''s dilemma and its link to oligopoly.","back":"Each player has a dominant strategy to defect, but mutual defection leaves both worse off than mutual cooperation. Oligopolists face the same pull to cut price or raise output rather than keep a collusive agreement."},{"id":"econ-101-18","front":"Why are cartels hard to sustain?","back":"Each member can profit by secretly producing more than its quota at the high cartel price. When many members cheat, output rises and price falls toward the competitive level."},{"id":"econ-101-19","front":"How does a competitive firm decide how many workers to hire?","back":"It hires until the wage equals the value of the marginal product of labor: W = VMPL = P × MPL. The VMPL curve is the firm''s labor demand curve."},{"id":"econ-101-20","front":"What is a compensating differential?","back":"A wage difference that offsets nonmonetary features of a job. Dangerous, unpleasant or night-shift jobs tend to pay more than otherwise similar jobs."},{"id":"econ-101-21","front":"What do the Lorenz curve and Gini coefficient measure?","back":"The Lorenz curve plots the cumulative share of income against the cumulative share of households. The Gini coefficient runs from 0 (perfect equality) to 1 (one household has everything); bigger gaps from the 45° line mean more inequality."},{"id":"econ-101-22","front":"Progressive vs regressive tax, and marginal vs average tax rate","back":"Progressive: higher-income people pay a larger share of income. Regressive: they pay a smaller share. The marginal rate applies to the next dollar earned; the average rate is total tax ÷ total income."},{"id":"econ-101-23","front":"Mini-problem: Tax is 10% on the first $10,000 of income and 20% on income above that. For $30,000, find total tax, average rate and marginal rate.","back":"Tax = $1,000 + 0.20 × $20,000 = $5,000. Average rate = 5,000/30,000 ≈ 16.7%. Marginal rate = 20%."},{"id":"econ-101-24","front":"Carbon tax vs cap-and-trade","back":"A carbon tax fixes the price of emissions and lets quantity adjust; cap-and-trade fixes the total quantity of permits and lets the permit price adjust. Both cut pollution at low cost because firms with cheap abatement cut the most."},{"id":"econ-101-25","front":"Positive externality: market outcome and policy fix","back":"When an activity benefits third parties (like vaccination or education), the market produces less than the social optimum. A subsidy equal to the external benefit can move output to the efficient level."},{"id":"econ-101-26","front":"Adverse selection vs moral hazard","back":"Adverse selection: hidden information before a transaction (people likely to get sick buy more insurance). Moral hazard: hidden action after a transaction (insured people take fewer precautions)."},{"id":"econ-101-27","front":"What is Pareto efficiency?","back":"An allocation where no one can be made better off without making someone else worse off. It says nothing about fairness, so an efficient outcome can be very unequal."},{"id":"econ-101-28","front":"Tariff vs import quota","back":"Both raise the domestic price, help domestic producers and hurt consumers with a deadweight loss. A tariff gives the government revenue; a quota gives the price difference to whoever holds the import licenses."},{"id":"econ-101-29","front":"When a country opens to trade and the world price is above its domestic price, who gains and who loses?","back":"The country exports. Domestic producers gain, domestic consumers lose because they now pay the higher world price, and total surplus rises."},{"id":"econ-101-30","front":"What is the efficiency-equity tradeoff?","back":"Policies that redistribute income, such as taxes and transfers, can reduce incentives to work and invest, shrinking total surplus. Societies balance a bigger pie against a fairer division of it."}],"quizzes":[],"seed":1,"look":{"color":"#16A34A","icon":"econ"}}'::jsonb);   -- https://graham.umich.edu/node/1844
select pg_temp.sb_seed('seed:umich-edu:math-115', 'umich.edu', 'MATH 115', 'MATH 115 Exam Review: Derivatives, Their Applications, and Introduction to Integration', '{"v":1,"app":"studyboard","type":"deck","name":"MATH 115 Exam Review: Derivatives, Their Applications, and Introduction to Integration","course":{"code":"MATH 115","name":"Calculus I"},"cards":[{"id":"math-115-1","front":"Average rate of change of f on [a, b]","back":"[f(b) − f(a)]/(b − a), which is the slope of the secant line through (a, f(a)) and (b, f(b))."},{"id":"math-115-2","front":"Limit definition of the derivative at x = a","back":"f''(a) = lim as h→0 of [f(a + h) − f(a)]/h, the instantaneous rate of change and the slope of the tangent line at x = a."},{"id":"math-115-3","front":"Interpret f''(5) = 3 if f(t) is gallons of water in a tank at t minutes.","back":"At t = 5 minutes, the amount of water is increasing at about 3 gallons per minute. Units of f'' are output units per input unit."},{"id":"math-115-4","front":"Exponential growth: compare P = P0·a^t and P = P0·e^(kt), and give the doubling time.","back":"Both describe exponential growth when a > 1 or k > 0, with a = e^k. Doubling time = ln 2 / k. If 0 < a < 1 or k < 0, it is exponential decay."},{"id":"math-115-5","front":"Power rule","back":"d/dx [x^n] = n·x^(n−1) for any real n. Example: d/dx [x^(1/2)] = (1/2)x^(−1/2)."},{"id":"math-115-6","front":"Derivatives of e^x, a^x and ln x","back":"d/dx [e^x] = e^x. d/dx [a^x] = (ln a)·a^x. d/dx [ln x] = 1/x for x > 0."},{"id":"math-115-7","front":"Derivatives of sin x, cos x and tan x","back":"d/dx [sin x] = cos x. d/dx [cos x] = −sin x. d/dx [tan x] = sec^2 x = 1/cos^2 x."},{"id":"math-115-8","front":"Product rule","back":"d/dx [f·g] = f''·g + f·g''. Example: d/dx [x^2 sin x] = 2x sin x + x^2 cos x."},{"id":"math-115-9","front":"Quotient rule","back":"d/dx [f/g] = (f''·g − f·g'')/g^2. A common error is reversing the order in the numerator."},{"id":"math-115-10","front":"Chain rule, with an example","back":"d/dx [f(g(x))] = f''(g(x))·g''(x). Example: d/dx [sin(x^2)] = cos(x^2)·2x."},{"id":"math-115-11","front":"Use implicit differentiation to find dy/dx for x^2 + y^2 = 25.","back":"Differentiate both sides: 2x + 2y·(dy/dx) = 0, so dy/dx = −x/y."},{"id":"math-115-12","front":"Derivative of arctan x","back":"d/dx [arctan x] = 1/(1 + x^2). It is found by implicitly differentiating tan y = x."},{"id":"math-115-13","front":"Tangent line (local linear) approximation","back":"Near x = a, f(x) ≈ f(a) + f''(a)(x − a). It overestimates when f is concave down and underestimates when f is concave up."},{"id":"math-115-14","front":"Mini-problem: Use a tangent line at x = 4 to approximate sqrt(4.1).","back":"f(x) = sqrt(x), f(4) = 2, f''(4) = 1/(2·sqrt 4) = 1/4. So sqrt(4.1) ≈ 2 + (1/4)(0.1) = 2.025."},{"id":"math-115-15","front":"What do the signs of f'' and f'''' tell you?","back":"f'' > 0: f increasing; f'' < 0: f decreasing. f'''' > 0: f concave up (f'' increasing); f'''' < 0: f concave down."},{"id":"math-115-16","front":"What is a critical point of f?","back":"A point in the domain where f''(x) = 0 or f''(x) does not exist. Local extrema of a function can only occur at critical points (or endpoints)."},{"id":"math-115-17","front":"First derivative test","back":"At a critical point, if f'' changes from positive to negative, f has a local maximum; from negative to positive, a local minimum; if the sign does not change, neither."},{"id":"math-115-18","front":"Second derivative test","back":"If f''(c) = 0 and f''''(c) > 0, f has a local minimum at c. If f''''(c) < 0, a local maximum. If f''''(c) = 0, the test is inconclusive."},{"id":"math-115-19","front":"What is an inflection point?","back":"A point on the graph where concavity changes (f'''' changes sign). f''''(x) = 0 alone is not enough: x^4 has f''''(0) = 0 but no inflection point."},{"id":"math-115-20","front":"How do you find the global maximum and minimum of a continuous f on a closed interval [a, b]?","back":"Evaluate f at every critical point inside the interval and at both endpoints; the largest value is the global max and the smallest is the global min (guaranteed by the Extreme Value Theorem)."},{"id":"math-115-21","front":"Mini-problem: A rectangle has perimeter 40. What dimensions maximize its area?","back":"With sides x and 20 − x, A = x(20 − x). A''(x) = 20 − 2x = 0 gives x = 10, so a 10 by 10 square with area 100."},{"id":"math-115-22","front":"Mini-problem: A circle''s radius grows at 2 cm/s. How fast is area changing when r = 5 cm?","back":"A = πr^2, so dA/dt = 2πr·(dr/dt) = 2π(5)(2) = 20π ≈ 62.8 cm^2/s."},{"id":"math-115-23","front":"Marginal analysis: when is profit maximized?","back":"Profit π = R − C is maximized where π'' = 0, that is, where marginal revenue equals marginal cost (R''(q) = C''(q)), with MC rising through MR."},{"id":"math-115-24","front":"State L''Hôpital''s rule.","back":"If lim f(x)/g(x) gives 0/0 or ∞/∞, then lim f(x)/g(x) = lim f''(x)/g''(x), if the latter exists. Example: lim as x→0 of sin x / x = lim cos x / 1 = 1."},{"id":"math-115-25","front":"Continuity vs differentiability","back":"If f is differentiable at a, it is continuous at a. The converse fails: |x| is continuous at 0 but not differentiable there because of the corner."},{"id":"math-115-26","front":"Left vs right Riemann sums for an increasing function","back":"For an increasing function, the left sum underestimates and the right sum overestimates the definite integral. For a decreasing function, the reverse is true."},{"id":"math-115-27","front":"What does the definite integral of f from a to b represent?","back":"The limit of Riemann sums as the number of subintervals goes to infinity: the net signed area between the graph and the x-axis (area above counts positive, area below counts negative)."},{"id":"math-115-28","front":"State the Fundamental Theorem of Calculus as total change.","back":"If F'' is continuous on [a, b], then the integral from a to b of F''(t) dt = F(b) − F(a): integrating a rate of change gives the total change."},{"id":"math-115-29","front":"If v(t) is velocity, what do the integral of v(t) and the integral of |v(t)| give?","back":"The integral of v(t) from a to b gives displacement (net change in position). The integral of |v(t)| gives total distance traveled."},{"id":"math-115-30","front":"Average value of f on [a, b]","back":"Average value = (1/(b − a)) × integral from a to b of f(x) dx."}],"quizzes":[],"seed":1,"look":{"color":"#3B6FE0","icon":"calc"}}'::jsonb);   -- https://prod.lsa.umich.edu/math/undergraduates/undergraduate-math-courses/courses-for-freshmen/standard-calc-sequence.html
select pg_temp.sb_seed('seed:utexas-edu:bio-311c', 'utexas.edu', 'BIO 311C', 'BIO 311C Exam Review: Cell Structure, Membranes, Photosynthesis, Cell Signaling and the Cell Cycle', '{"v":1,"app":"studyboard","type":"deck","name":"BIO 311C Exam Review: Cell Structure, Membranes, Photosynthesis, Cell Signaling and the Cell Cycle","course":{"code":"BIO 311C","name":"Introductory Biology I"},"cards":[{"id":"bio-311c-1","front":"Prokaryotic vs eukaryotic cells","back":"Prokaryotes (bacteria, archaea) lack a nucleus and membrane-bound organelles; their DNA sits in a nucleoid region. Eukaryotes have a nucleus and organelles such as mitochondria, ER and Golgi, and are usually much larger."},{"id":"bio-311c-2","front":"What evidence supports the endosymbiotic theory?","back":"Mitochondria and chloroplasts have double membranes, their own circular DNA, bacteria-like ribosomes, and divide by a process like binary fission, consistent with descent from engulfed prokaryotes."},{"id":"bio-311c-3","front":"Rough ER vs smooth ER","back":"Rough ER has ribosomes and makes secreted and membrane proteins. Smooth ER lacks ribosomes and makes lipids, detoxifies drugs, and stores calcium."},{"id":"bio-311c-4","front":"What does the Golgi apparatus do?","back":"It receives proteins from the ER at its cis face, modifies them (for example, adding or trimming sugars), sorts them, and ships them from the trans face in vesicles to their destinations."},{"id":"bio-311c-5","front":"What are lysosomes?","back":"Membrane-bound sacs with acidic interiors and hydrolytic enzymes that digest macromolecules, worn-out organelles (autophagy), and material taken in by phagocytosis."},{"id":"bio-311c-6","front":"Trace the path of a secreted protein from synthesis to export.","back":"Ribosome on rough ER, into the ER lumen, transport vesicle, Golgi (cis to trans), secretory vesicle, then fusion with the plasma membrane to release the protein (exocytosis)."},{"id":"bio-311c-7","front":"Three types of cytoskeletal fibers and their roles","back":"Microtubules (tubulin): tracks for transport, mitotic spindle, cilia and flagella. Microfilaments (actin): cell shape, muscle contraction, cytokinesis. Intermediate filaments: tension-bearing strength, such as anchoring the nucleus."},{"id":"bio-311c-8","front":"Why are cells small?","back":"As a cell grows, volume rises faster than surface area. A high surface area-to-volume ratio is needed so the membrane can exchange enough nutrients and wastes for the cell''s volume."},{"id":"bio-311c-9","front":"Describe the fluid mosaic model.","back":"The membrane is a phospholipid bilayer with hydrophobic tails inward and hydrophilic heads outward, with proteins embedded in or attached to it, and lipids and many proteins able to move laterally."},{"id":"bio-311c-10","front":"How does cholesterol affect membrane fluidity?","back":"It acts as a fluidity buffer: at high temperatures it restrains phospholipid movement, and at low temperatures it prevents tight packing that would make the membrane solidify."},{"id":"bio-311c-11","front":"Which molecules cross a lipid bilayer easily, and which need help?","back":"Small nonpolar molecules (O2, CO2) and lipid-soluble molecules diffuse through easily. Ions and large polar molecules (glucose) need channel or carrier proteins."},{"id":"bio-311c-12","front":"Simple diffusion vs facilitated diffusion vs active transport","back":"Simple diffusion: down a gradient directly through the bilayer. Facilitated diffusion: down a gradient through a protein, no energy needed. Active transport: against a gradient through a protein, requiring energy such as ATP."},{"id":"bio-311c-13","front":"What happens to animal and plant cells in a hypotonic solution?","back":"Water moves in by osmosis. An animal cell swells and may burst (lyse). A plant cell becomes turgid, which is its healthy state, because the cell wall resists bursting."},{"id":"bio-311c-14","front":"What does the sodium-potassium pump do?","back":"Using one ATP per cycle, it pumps 3 Na+ out of the cell and 2 K+ in, maintaining concentration gradients and contributing to the membrane potential."},{"id":"bio-311c-15","front":"What is cotransport (secondary active transport)?","back":"A protein uses the energy of one solute moving down its gradient (often Na+ or H+, set up by an ATP-driven pump) to move another solute against its gradient, as in the sodium-glucose symporter."},{"id":"bio-311c-16","front":"Phagocytosis vs pinocytosis vs receptor-mediated endocytosis","back":"Phagocytosis: engulfing large particles or cells. Pinocytosis: taking in droplets of extracellular fluid. Receptor-mediated endocytosis: specific molecules bind receptors in coated pits, as with LDL cholesterol uptake."},{"id":"bio-311c-17","front":"Overall equation for photosynthesis","back":"6 CO2 + 6 H2O + light energy → C6H12O6 + 6 O2."},{"id":"bio-311c-18","front":"Light reactions: where do they happen and what do they produce?","back":"In the thylakoid membranes. Light energy splits water (releasing O2) and drives electron flow through photosystems II and I, producing ATP and NADPH for the Calvin cycle."},{"id":"bio-311c-19","front":"Calvin cycle: where does it happen and what does it do?","back":"In the stroma. Rubisco fixes CO2 onto RuBP; ATP and NADPH from the light reactions reduce the products to G3P, a 3-carbon sugar used to build glucose and other molecules."},{"id":"bio-311c-20","front":"Where does the O2 released in photosynthesis come from?","back":"From water, split by photosystem II, not from CO2. Experiments with heavy-oxygen isotopes confirmed this."},{"id":"bio-311c-21","front":"What is photorespiration, and how do C4 and CAM plants reduce it?","back":"When CO2 is low (stomata closed on hot, dry days), rubisco binds O2 instead, wasting energy and releasing CO2. C4 plants fix CO2 in separate cells; CAM plants fix CO2 at night and open stomata only then."},{"id":"bio-311c-22","front":"Compare chemiosmosis in mitochondria and chloroplasts.","back":"Both use an electron transport chain to pump H+ and ATP synthase to make ATP. Mitochondria pump H+ into the intermembrane space; chloroplasts pump H+ into the thylakoid space. The electrons come from food vs from water."},{"id":"bio-311c-23","front":"Three stages of cell signaling","back":"Reception: a signal molecule binds a receptor. Transduction: a relay of molecules (often phosphorylation cascades and second messengers) carries the signal. Response: a cellular activity changes, such as gene expression or enzyme activity."},{"id":"bio-311c-24","front":"Outline a G protein-coupled receptor pathway using cAMP.","back":"Ligand binds the GPCR, which activates a G protein by swapping GDP for GTP. The G protein activates adenylyl cyclase, which makes cAMP from ATP. cAMP activates protein kinase A, which phosphorylates target proteins."},{"id":"bio-311c-25","front":"How do receptor tyrosine kinases work?","back":"Ligand binding causes two receptors to pair up and phosphorylate each other''s tyrosines. Relay proteins bind the phosphorylated sites, activating pathways such as Ras. Overactive RTKs or Ras contribute to many cancers."},{"id":"bio-311c-26","front":"How do steroid hormones signal differently from most protein hormones?","back":"Steroids are lipid-soluble, cross the plasma membrane, and bind intracellular receptors; the hormone-receptor complex acts as a transcription factor to change gene expression."},{"id":"bio-311c-27","front":"Why do signal transduction cascades amplify signals?","back":"Each activated enzyme in a cascade can activate many molecules of the next component, so one signal molecule can lead to thousands or millions of product molecules."},{"id":"bio-311c-28","front":"Phases of the cell cycle and the stages of mitosis","back":"Interphase: G1 (growth), S (DNA replication), G2 (preparation). M phase: prophase, prometaphase, metaphase, anaphase, telophase, then cytokinesis."},{"id":"bio-311c-29","front":"How are cell cycle checkpoints controlled?","back":"Cyclins bind and activate cyclin-dependent kinases (CDKs), which phosphorylate targets to push the cell into the next phase. Proteins such as p53 can halt the cycle at checkpoints if DNA is damaged."},{"id":"bio-311c-30","front":"Proto-oncogene vs tumor suppressor gene","back":"Proto-oncogenes promote cell division; gain-of-function mutations turn them into oncogenes (like Ras). Tumor suppressors inhibit division; loss-of-function mutations in both copies remove the brakes (like p53)."},{"id":"bio-311c-31","front":"Catabolic vs anabolic pathways","back":"Catabolic pathways break down complex molecules and release energy (cellular respiration). Anabolic pathways build complex molecules and consume energy (protein synthesis, photosynthesis)."}],"quizzes":[],"seed":1,"look":{"color":"#0D9488","icon":"bio"}}'::jsonb);   -- https://catalog.utexas.edu/general-information/coursesatoz/bio/
select pg_temp.sb_seed('seed:utexas-edu:ch-301', 'utexas.edu', 'CH 301', 'CH 301 Exam Review: Atomic Structure, Gases, Intermolecular Forces and Thermodynamics', '{"v":1,"app":"studyboard","type":"deck","name":"CH 301 Exam Review: Atomic Structure, Gases, Intermolecular Forces and Thermodynamics","course":{"code":"CH 301","name":"Principles of Chemistry I"},"cards":[{"id":"ch-301-1","front":"Rydberg equation for hydrogen emission lines","back":"1/λ = R_H(1/n_low^2 − 1/n_high^2), with R_H = 1.097×10^7 m^−1. Transitions down to n = 2 give the visible Balmer series."},{"id":"ch-301-2","front":"Energy levels of a particle in a 1-D box","back":"E_n = n^2·h^2/(8mL^2), n = 1, 2, 3, ... Energy is quantized, the lowest energy is not zero, and levels get closer together as the box length L or the mass m increases."},{"id":"ch-301-3","front":"How many radial and angular nodes does an orbital have?","back":"Angular nodes = l. Radial nodes = n − l − 1. Total nodes = n − 1. Example: a 3p orbital has 1 angular and 1 radial node."},{"id":"ch-301-4","front":"Shapes of s, p and d orbitals","back":"s orbitals are spherical. p orbitals are dumbbell-shaped along x, y or z. Most d orbitals are four-lobed (cloverleaf); d(z^2) has two lobes and a ring."},{"id":"ch-301-5","front":"Why is a 2s orbital lower in energy than a 2p orbital in multi-electron atoms?","back":"2s electrons penetrate closer to the nucleus, so they are less shielded and feel a higher effective nuclear charge. In hydrogen, with one electron, 2s and 2p have equal energy."},{"id":"ch-301-6","front":"Coulomb''s law and what it predicts for ionic attraction","back":"Potential energy E ∝ (q1·q2)/r. Larger ion charges and smaller distances between ions give stronger attraction and more energy released."},{"id":"ch-301-7","front":"How does bond order relate to bond length and bond strength?","back":"Higher bond order means shorter and stronger bonds. For carbon-carbon bonds: triple is shorter and stronger than double, which is shorter and stronger than single."},{"id":"ch-301-8","front":"N2 molecular orbital configuration and properties","back":"For B2, C2 and N2, the π2p orbitals lie below σ2p. N2 has bond order 3 and all electrons paired, so it is diamagnetic and very strongly bonded."},{"id":"ch-301-9","front":"Boyle''s, Charles''s and Avogadro''s laws","back":"Boyle: P1V1 = P2V2 at constant n and T. Charles: V1/T1 = V2/T2 at constant n and P. Avogadro: V/n is constant at constant P and T. All follow from PV = nRT."},{"id":"ch-301-10","front":"Density of an ideal gas","back":"d = PM/(RT), where M is molar mass. Heavier gases are denser at the same temperature and pressure."},{"id":"ch-301-11","front":"Mini-problem: How many moles of gas are in 2.00 L at 1.00 atm and 273 K?","back":"n = PV/(RT) = (1.00)(2.00)/(0.08206 × 273) ≈ 0.0893 mol."},{"id":"ch-301-12","front":"What do the a and b terms in the van der Waals equation correct for?","back":"(P + a·n^2/V^2)(V − n·b) = nRT. The a term corrects for intermolecular attractions, which lower the measured pressure; b corrects for the volume occupied by the molecules themselves."},{"id":"ch-301-13","front":"How does the Maxwell-Boltzmann speed distribution change with temperature and molar mass?","back":"Higher temperature or lower molar mass flattens and broadens the curve and shifts the most probable speed higher. Lower temperature or heavier gas gives a narrower, taller peak at lower speed."},{"id":"ch-301-14","front":"Four main types of intermolecular forces, weakest to strongest (typical)","back":"London dispersion forces (all molecules), dipole-dipole (polar molecules), hydrogen bonding (special strong dipole-dipole), and ion-dipole (ions in polar solvents)."},{"id":"ch-301-15","front":"When can hydrogen bonding occur?","back":"When H is covalently bonded to N, O or F and is attracted to a lone pair on another N, O or F atom."},{"id":"ch-301-16","front":"Why is F2 a gas, Br2 a liquid and I2 a solid at room temperature?","back":"All are nonpolar, so only dispersion forces act. Dispersion forces grow with the number of electrons and polarizability, so they increase from F2 to I2, raising melting and boiling points."},{"id":"ch-301-17","front":"Rank by boiling point: H2O, CH4, H2S. Explain.","back":"CH4 < H2S < H2O. CH4 has only dispersion forces; H2S adds dipole-dipole forces; H2O forms strong hydrogen bonds, giving it the highest boiling point despite its low mass."},{"id":"ch-301-18","front":"How do intermolecular forces affect vapor pressure and boiling point?","back":"Stronger IMFs mean fewer molecules escape to the gas phase, so vapor pressure is lower and boiling point is higher. A liquid boils when its vapor pressure equals the external pressure."},{"id":"ch-301-19","front":"Phase diagram: what are the triple point and critical point? What is odd about water''s?","back":"Triple point: the T and P where solid, liquid and gas coexist. Critical point: above it, liquid and gas are indistinguishable (supercritical fluid). Water''s solid-liquid line slopes negatively because ice is less dense than liquid water."},{"id":"ch-301-20","front":"First law of thermodynamics and the chemistry sign convention","back":"ΔU = q + w. q > 0 when heat flows into the system; w > 0 when work is done on the system. For expansion against constant external pressure, w = −P_ext·ΔV."},{"id":"ch-301-21","front":"What is a state function? Give examples and non-examples.","back":"A property that depends only on the current state, not the path taken. U, H, S, G, P, V and T are state functions; heat q and work w are not."},{"id":"ch-301-22","front":"How are ΔH and ΔU related for reactions involving gases?","back":"ΔH = ΔU + Δn_gas·RT, where Δn_gas is moles of gaseous products minus gaseous reactants. If Δn_gas = 0, ΔH ≈ ΔU."},{"id":"ch-301-23","front":"What is entropy at the molecular level, and what increases it?","back":"S = k ln W, where W is the number of microstates. Entropy increases on melting or vaporizing, when gas moles increase, with higher temperature, and when substances mix or (usually) dissolve."},{"id":"ch-301-24","front":"Second law of thermodynamics and entropy of the surroundings","back":"For any spontaneous process, ΔS_universe = ΔS_sys + ΔS_surr > 0. At constant T and P, ΔS_surr = −ΔH_sys/T, so exothermic reactions increase the entropy of the surroundings."},{"id":"ch-301-25","front":"Gibbs free energy: predict spontaneity from the signs of ΔH and ΔS.","back":"ΔG = ΔH − TΔS. ΔH < 0, ΔS > 0: spontaneous at all T. ΔH > 0, ΔS < 0: never spontaneous. ΔH < 0, ΔS < 0: spontaneous at low T. ΔH > 0, ΔS > 0: spontaneous at high T."},{"id":"ch-301-26","front":"Mini-problem: ΔH = +40.0 kJ/mol and ΔS = +100. J/(mol·K). Above what temperature is the process spontaneous?","back":"Set ΔG = 0: T = ΔH/ΔS = 40,000 J/mol ÷ 100 J/(mol·K) = 400 K. Above 400 K, ΔG < 0. Remember to convert kJ to J."},{"id":"ch-301-27","front":"Relationship between ΔG° and the equilibrium constant","back":"ΔG° = −RT ln K. If ΔG° < 0, K > 1 (products favored); if ΔG° > 0, K < 1 (reactants favored); if ΔG° = 0, K = 1."},{"id":"ch-301-28","front":"Why is temperature constant during a phase change on a heating curve?","back":"Added heat goes into overcoming intermolecular forces rather than increasing kinetic energy. The heat needed is q = n·ΔH_fus for melting or q = n·ΔH_vap for boiling."},{"id":"ch-301-29","front":"Entropy change for a phase transition at its transition temperature","back":"ΔS = ΔH_transition / T_transition, with T in kelvin. At the normal boiling point, liquid and gas are in equilibrium, so ΔG = 0."},{"id":"ch-301-30","front":"State the third law of thermodynamics.","back":"The entropy of a perfect crystal at absolute zero (0 K) is zero. This allows absolute standard molar entropies S° to be tabulated, unlike enthalpies."}],"quizzes":[],"seed":1,"look":{"color":"#EA580C","icon":"chem"}}'::jsonb);   -- https://catalog.utexas.edu/general-information/coursesatoz/ch/
select pg_temp.sb_seed('seed:utexas-edu:psy-301', 'utexas.edu', 'PSY 301', 'PSY 301 Exam Review: Memory, Thinking, Development, Social Psychology and Psychological Disorders', '{"v":1,"app":"studyboard","type":"deck","name":"PSY 301 Exam Review: Memory, Thinking, Development, Social Psychology and Psychological Disorders","course":{"code":"PSY 301","name":"Introduction to Psychology"},"cards":[{"id":"psy-301-1","front":"Describe the Atkinson-Shiffrin (multi-store) model of memory.","back":"Information passes from sensory memory (very brief) to short-term memory (limited, about 20-30 seconds without rehearsal) and, with encoding, into long-term memory (vast and relatively durable)."},{"id":"psy-301-2","front":"What is working memory, and what are Baddeley''s main components?","back":"An active short-term system for holding and manipulating information. Components: the phonological loop (verbal), the visuospatial sketchpad, the central executive (attention control), and the episodic buffer."},{"id":"psy-301-3","front":"What is the typical capacity of short-term memory, and how can chunking help?","back":"Miller estimated 7 ± 2 items; more recent estimates are about 4 chunks. Chunking groups items into meaningful units (like a phone number in parts) so more information fits."},{"id":"psy-301-4","front":"What is the levels of processing idea (Craik and Lockhart)?","back":"Deeper, meaning-based (semantic) processing produces better long-term memory than shallow processing of appearance or sound."},{"id":"psy-301-5","front":"Explicit vs implicit memory","back":"Explicit (declarative) memory is consciously recalled facts and events. Implicit (nondeclarative) memory shows up without conscious recall, such as skills (procedural memory), priming and classical conditioning."},{"id":"psy-301-6","front":"Episodic vs semantic memory","back":"Episodic memory stores personal experiences tied to a time and place (your last birthday). Semantic memory stores general facts and knowledge (the capital of Texas)."},{"id":"psy-301-7","front":"What is the serial position effect?","back":"In free recall of a list, the first items (primacy effect, from rehearsal into long-term memory) and the last items (recency effect, still in short-term memory) are remembered best."},{"id":"psy-301-8","front":"Proactive vs retroactive interference","back":"Proactive: old information disrupts recall of new information (your old locker combination blocks the new one). Retroactive: new information disrupts recall of old information."},{"id":"psy-301-9","front":"Anterograde vs retrograde amnesia, and what patient H.M. showed","back":"Anterograde: inability to form new memories after an injury. Retrograde: loss of memories from before it. After removal of his medial temporal lobes, including the hippocampus, H.M. had severe anterograde amnesia but could still learn new motor skills."},{"id":"psy-301-10","front":"What did Loftus and Palmer''s car crash study show?","back":"Wording such as ''smashed'' vs ''hit'' changed speed estimates and made people more likely to falsely recall broken glass, demonstrating the misinformation effect and the reconstructive nature of memory."},{"id":"psy-301-11","front":"What is encoding specificity (context-dependent memory)?","back":"Recall is better when the retrieval context or cues match those present at encoding, such as divers recalling words learned underwater better when tested underwater."},{"id":"psy-301-12","front":"Spacing effect and testing effect","back":"Spacing: study spread over time produces better long-term retention than cramming. Testing: practicing retrieval improves memory more than rereading the material."},{"id":"psy-301-13","front":"Availability vs representativeness heuristic","back":"Availability: judging likelihood by how easily examples come to mind (overestimating plane crashes). Representativeness: judging by how well something matches a prototype, often ignoring base rates."},{"id":"psy-301-14","front":"Confirmation bias vs framing effect","back":"Confirmation bias: seeking or favoring evidence that supports what you already believe. Framing: the same information leads to different choices depending on how it is presented (90% survive vs 10% die)."},{"id":"psy-301-15","front":"Piaget''s four stages of cognitive development","back":"Sensorimotor (0-2, object permanence develops), preoperational (2-7, egocentrism, lacks conservation), concrete operational (7-11, logical thinking about concrete events, conservation), formal operational (12+, abstract reasoning)."},{"id":"psy-301-16","front":"Define object permanence and conservation.","back":"Object permanence: knowing objects still exist when out of sight, developing in the sensorimotor stage. Conservation: understanding quantity stays the same despite changes in shape, mastered in the concrete operational stage."},{"id":"psy-301-17","front":"What did Harlow''s monkey studies show about attachment?","back":"Infant monkeys spent most of their time clinging to a soft cloth surrogate mother rather than a wire one that provided milk, showing that contact comfort, not just feeding, drives attachment."},{"id":"psy-301-18","front":"Ainsworth''s Strange Situation: describe secure and insecure attachment patterns.","back":"Secure infants explore with the caregiver present, become upset at separation and are comforted on reunion. Avoidant infants show little distress and ignore the caregiver on return; anxious-ambivalent (resistant) infants are very distressed and hard to soothe."},{"id":"psy-301-19","front":"What is the fundamental attribution error?","back":"The tendency to overestimate personality (dispositional) causes and underestimate situational causes when explaining other people''s behavior."},{"id":"psy-301-20","front":"What did Festinger and Carlsmith''s $1 vs $20 study show?","back":"Participants paid $1 to say a boring task was fun later rated it as more enjoyable than those paid $20. With little external justification, they reduced cognitive dissonance by changing their attitude."},{"id":"psy-301-21","front":"What did Asch''s line judgment studies show?","back":"Many participants conformed to a unanimous group''s obviously wrong answer on at least some trials. Conformity dropped sharply when even one other person gave the correct answer."},{"id":"psy-301-22","front":"What did Milgram''s obedience studies find?","back":"In the baseline version, about 65% of participants obeyed an experimenter''s instructions to deliver what they believed were 450-volt shocks. Obedience fell when the experimenter was absent or the victim was closer."},{"id":"psy-301-23","front":"What is the bystander effect, and why does it happen?","back":"People are less likely to help in an emergency when others are present, partly because of diffusion of responsibility and because others'' inaction makes the situation seem less serious."},{"id":"psy-301-24","front":"Social facilitation vs social loafing","back":"Social facilitation: the presence of others improves performance on simple or well-learned tasks but hurts it on hard or new ones. Social loafing: people exert less effort on group tasks when individual contributions are not identifiable."},{"id":"psy-301-25","front":"What are the Big Five personality traits?","back":"Openness to experience, conscientiousness, extraversion, agreeableness, and neuroticism (OCEAN). Each is a continuous dimension and fairly stable in adulthood."},{"id":"psy-301-26","front":"Fluid vs crystallized intelligence","back":"Fluid intelligence is the ability to reason quickly and solve new problems; it tends to decline in later adulthood. Crystallized intelligence is accumulated knowledge and vocabulary; it tends to hold steady or grow with age."},{"id":"psy-301-27","front":"Compare the James-Lange, Cannon-Bard and Schachter-Singer theories of emotion.","back":"James-Lange: physiological arousal comes first and we feel emotion from it. Cannon-Bard: arousal and emotion occur at the same time. Schachter-Singer two-factor: arousal plus a cognitive label creates the emotion."},{"id":"psy-301-28","front":"What is the Yerkes-Dodson law?","back":"Performance improves with arousal up to a moderate level, then declines. The optimal level is lower for difficult tasks and higher for easy ones."},{"id":"psy-301-29","front":"Major depressive disorder vs bipolar I disorder","back":"Major depressive disorder involves depressive episodes (at least two weeks of low mood or loss of interest) without mania. Bipolar I requires at least one manic episode, often with depressive episodes as well."},{"id":"psy-301-30","front":"Positive vs negative symptoms of schizophrenia","back":"Positive symptoms are added experiences or behaviors: hallucinations, delusions, disorganized speech. Negative symptoms are reductions of normal function: flat affect, social withdrawal, lack of motivation."},{"id":"psy-301-31","front":"Cognitive-behavioral therapy vs psychodynamic therapy","back":"CBT targets present maladaptive thoughts and behaviors with structured techniques like cognitive restructuring and exposure. Psychodynamic therapy explores unconscious conflicts and past experiences to build insight."}],"quizzes":[],"seed":1,"look":{"color":"#C026D3","icon":"psych"}}'::jsonb);   -- https://catalog.utexas.edu/general-information/coursesatoz/psy/
select pg_temp.sb_seed('seed:utexas-edu:m-408c', 'utexas.edu', 'M 408C', 'M 408C Exam Review: Limits, Continuity, Derivatives, Mean Value Theorem and Integration', '{"v":1,"app":"studyboard","type":"deck","name":"M 408C Exam Review: Limits, Continuity, Derivatives, Mean Value Theorem and Integration","course":{"code":"M 408C","name":"Differential and Integral Calculus"},"cards":[{"id":"m-408c-1","front":"When does lim as x→a of f(x) exist?","back":"When the left-hand limit and the right-hand limit both exist and are equal. The value of f(a) itself does not matter for the limit."},{"id":"m-408c-2","front":"Evaluate lim as x→2 of (x^2 − 4)/(x − 2).","back":"Factor: (x − 2)(x + 2)/(x − 2) = x + 2 for x ≠ 2, so the limit is 4."},{"id":"m-408c-3","front":"State the squeeze theorem and give its classic use.","back":"If g(x) ≤ f(x) ≤ h(x) near a and lim g = lim h = L, then lim f = L. It shows lim as x→0 of x^2 sin(1/x) = 0, since −x^2 ≤ x^2 sin(1/x) ≤ x^2."},{"id":"m-408c-4","front":"Two key trigonometric limits","back":"lim as x→0 of sin x / x = 1 (x in radians), and lim as x→0 of (1 − cos x)/x = 0."},{"id":"m-408c-5","front":"Three conditions for f to be continuous at x = a","back":"f(a) is defined, lim as x→a of f(x) exists, and the limit equals f(a)."},{"id":"m-408c-6","front":"State the Intermediate Value Theorem.","back":"If f is continuous on [a, b] and N is between f(a) and f(b), then f(c) = N for some c in (a, b). It is often used to show a root exists when f(a) and f(b) have opposite signs."},{"id":"m-408c-7","front":"Removable vs jump vs infinite discontinuity","back":"Removable: the limit exists but differs from f(a) or f(a) is undefined (a hole). Jump: the one-sided limits exist but differ. Infinite: f grows without bound near a (vertical asymptote)."},{"id":"m-408c-8","front":"Horizontal asymptotes of rational functions","back":"Compare degrees: if numerator degree < denominator degree, y = 0. If equal, y = ratio of leading coefficients. If numerator degree is larger, there is no horizontal asymptote."},{"id":"m-408c-9","front":"State the epsilon-delta definition of lim as x→a of f(x) = L.","back":"For every ε > 0 there is a δ > 0 such that if 0 < |x − a| < δ, then |f(x) − L| < ε."},{"id":"m-408c-10","front":"Evaluate lim as h→0 of [(2 + h)^3 − 8]/h without expanding.","back":"This is the definition of the derivative of x^3 at x = 2. Since d/dx [x^3] = 3x^2, the limit is 3(2)^2 = 12."},{"id":"m-408c-11","front":"Equation of the tangent line to y = f(x) at x = a","back":"y = f(a) + f''(a)(x − a). Example: for f(x) = x^2 at a = 3, y = 9 + 6(x − 3)."},{"id":"m-408c-12","front":"Differentiate e^(3x^2).","back":"By the chain rule: d/dx [e^(3x^2)] = e^(3x^2)·6x."},{"id":"m-408c-13","front":"Use logarithmic differentiation to find the derivative of y = x^x.","back":"ln y = x ln x. Differentiate: y''/y = ln x + 1. So y'' = x^x(ln x + 1)."},{"id":"m-408c-14","front":"Derivatives of ln|x| and log_b(x)","back":"d/dx [ln|x|] = 1/x for x ≠ 0. d/dx [log_b x] = 1/(x ln b)."},{"id":"m-408c-15","front":"Derivatives of arcsin x and arctan x","back":"d/dx [arcsin x] = 1/sqrt(1 − x^2) for |x| < 1. d/dx [arctan x] = 1/(1 + x^2)."},{"id":"m-408c-16","front":"State Rolle''s Theorem.","back":"If f is continuous on [a, b], differentiable on (a, b), and f(a) = f(b), then f''(c) = 0 for some c in (a, b)."},{"id":"m-408c-17","front":"State the Mean Value Theorem.","back":"If f is continuous on [a, b] and differentiable on (a, b), then for some c in (a, b), f''(c) = [f(b) − f(a)]/(b − a): the tangent slope equals the average slope somewhere."},{"id":"m-408c-18","front":"What important consequence follows from the Mean Value Theorem about f'' = 0?","back":"If f''(x) = 0 for all x in an interval, then f is constant there. So two functions with the same derivative on an interval differ by a constant."},{"id":"m-408c-19","front":"When can you use L''Hôpital''s rule?","back":"Only for indeterminate forms 0/0 or ∞/∞. Other forms like 0·∞, ∞ − ∞, 1^∞, 0^0 or ∞^0 must first be rewritten as a quotient (often using logarithms)."},{"id":"m-408c-20","front":"Evaluate lim as x→∞ of (ln x)/x.","back":"It is ∞/∞, so apply L''Hôpital: lim (1/x)/1 = 0. Polynomials grow faster than logarithms."},{"id":"m-408c-21","front":"Basic antiderivatives: x^n and 1/x","back":"∫ x^n dx = x^(n+1)/(n + 1) + C for n ≠ −1. ∫ (1/x) dx = ln|x| + C. Do not forget the constant of integration."},{"id":"m-408c-22","front":"Definite integral as a limit of Riemann sums","back":"The integral from a to b of f(x) dx = lim as n→∞ of the sum from i = 1 to n of f(x_i*)·Δx, where Δx = (b − a)/n and x_i* is a sample point in the i-th subinterval."},{"id":"m-408c-23","front":"Fundamental Theorem of Calculus, Part 1 (with chain rule)","back":"If F(x) = integral from a to x of f(t) dt with f continuous, then F''(x) = f(x). If the upper limit is g(x), the derivative is f(g(x))·g''(x)."},{"id":"m-408c-24","front":"Fundamental Theorem of Calculus, Part 2","back":"If F is any antiderivative of a continuous f on [a, b], then the integral from a to b of f(x) dx = F(b) − F(a)."},{"id":"m-408c-25","front":"Evaluate the integral of sin x from 0 to π.","back":"An antiderivative is −cos x, so the integral = −cos π − (−cos 0) = 1 + 1 = 2."},{"id":"m-408c-26","front":"Use u-substitution: ∫ 2x cos(x^2) dx","back":"Let u = x^2, so du = 2x dx. The integral becomes ∫ cos u du = sin u + C = sin(x^2) + C."},{"id":"m-408c-27","front":"How do you find the area between two curves?","back":"Area = integral from a to b of [top function − bottom function] dx, where a and b are usually the intersection points. If the curves cross, split the interval."},{"id":"m-408c-28","front":"Properties: reversing limits and splitting the interval of a definite integral","back":"The integral from b to a of f = −(the integral from a to b of f). The integral from a to c of f = (integral from a to b) + (integral from b to c)."},{"id":"m-408c-29","front":"Integrals of odd and even functions over [−a, a]","back":"If f is odd (f(−x) = −f(x)), the integral from −a to a is 0. If f is even (f(−x) = f(x)), it equals 2 × the integral from 0 to a."},{"id":"m-408c-30","front":"What is a differential, and how does it estimate change?","back":"dy = f''(x)·dx. For a small change dx in x, the actual change Δy is approximately dy, which is the change along the tangent line."}],"quizzes":[],"seed":1,"look":{"color":"#4F46E5","icon":"calc"}}'::jsonb);   -- https://catalog.utexas.edu/general-information/coursesatoz/m/
select pg_temp.sb_seed('seed:osu-edu:psych-1100', 'osu.edu', 'PSYCH 1100', 'PSYCH 1100 Midterm Review: Research Methods, Biopsychology, Learning and Memory', '{"v":1,"app":"studyboard","type":"deck","name":"PSYCH 1100 Midterm Review: Research Methods, Biopsychology, Learning and Memory","course":{"code":"PSYCH 1100","name":"Introduction to Psychology"},"cards":[{"id":"psych-1100-1","front":"What is the difference between an independent variable and a dependent variable?","back":"The independent variable is the factor the researcher manipulates; the dependent variable is the outcome measured to see whether it changed as a result."},{"id":"psych-1100-2","front":"Why can''t a correlational study establish cause and effect?","back":"A correlation may reflect reverse causation (B causes A) or a third variable that causes both, so only a controlled experiment with random assignment supports causal claims."},{"id":"psych-1100-3","front":"What does a correlation coefficient of r = -0.85 tell you?","back":"A strong negative linear relationship: as one variable increases, the other tends to decrease. The sign gives direction and the absolute value gives strength (0 to 1)."},{"id":"psych-1100-4","front":"Random sampling vs random assignment","back":"Random sampling picks participants from a population so results generalize (external validity). Random assignment places participants into conditions by chance so groups are equivalent (internal validity)."},{"id":"psych-1100-5","front":"What is a double-blind procedure and why is it used?","back":"Neither participants nor the researchers collecting data know who is in which condition. It reduces placebo effects and experimenter bias."},{"id":"psych-1100-6","front":"Operational definition","back":"A precise statement of how a variable will be measured or manipulated in a study, e.g. defining aggression as the number of times a child hits a doll in 10 minutes."},{"id":"psych-1100-7","front":"Reliability vs validity of a measure","back":"Reliability is consistency (same result on repeated measurement). Validity is accuracy (the measure assesses what it claims to). A measure can be reliable without being valid."},{"id":"psych-1100-8","front":"Name the main parts of a neuron and the direction a signal travels.","back":"Dendrites receive input, the cell body (soma) integrates it, the axon carries the action potential away, and axon terminals release neurotransmitter into the synapse."},{"id":"psych-1100-9","front":"What is the all-or-none principle of the action potential?","back":"A neuron either fires a full-strength action potential once the threshold is reached or does not fire at all; stimulus intensity is coded by firing rate, not spike size."},{"id":"psych-1100-10","front":"What does the myelin sheath do?","back":"It insulates the axon and speeds conduction, as the impulse jumps between gaps called nodes of Ranvier (saltatory conduction). Its breakdown occurs in multiple sclerosis."},{"id":"psych-1100-11","front":"Excitatory vs inhibitory neurotransmitters: give an example of each.","back":"Glutamate is the main excitatory neurotransmitter (makes firing more likely); GABA is the main inhibitory one (makes firing less likely)."},{"id":"psych-1100-12","front":"Which neurotransmitter is linked to reward and movement, and to Parkinson''s disease when depleted?","back":"Dopamine. Loss of dopamine-producing neurons in the substantia nigra leads to the motor symptoms of Parkinson''s disease."},{"id":"psych-1100-13","front":"Sympathetic vs parasympathetic nervous system","back":"Both are autonomic. Sympathetic arouses the body for fight or flight (raises heart rate, dilates pupils); parasympathetic calms it for rest and digest."},{"id":"psych-1100-14","front":"What are the functions of the four cerebral lobes?","back":"Frontal: planning, decision making, motor control. Parietal: touch and spatial processing. Temporal: hearing and language comprehension. Occipital: vision."},{"id":"psych-1100-15","front":"Broca''s area vs Wernicke''s area","back":"Broca''s area (left frontal lobe) supports speech production; damage gives halting speech. Wernicke''s area (left temporal lobe) supports comprehension; damage gives fluent but meaningless speech."},{"id":"psych-1100-16","front":"What role does the hippocampus play?","back":"It is crucial for forming new explicit (declarative) long-term memories; damage causes anterograde amnesia, as in patient H.M."},{"id":"psych-1100-17","front":"In Pavlov''s experiment, identify the US, UR, CS and CR.","back":"US: food. UR: salivation to food. CS: the tone (originally neutral). CR: salivation to the tone after repeated pairing."},{"id":"psych-1100-18","front":"Extinction vs spontaneous recovery in classical conditioning","back":"Extinction is the weakening of a CR when the CS is repeatedly presented without the US. Spontaneous recovery is the reappearance of the weakened CR after a rest period."},{"id":"psych-1100-19","front":"Negative reinforcement vs punishment","back":"Negative reinforcement removes an unpleasant stimulus to increase a behavior (taking aspirin removes a headache). Punishment decreases a behavior. Negative reinforcement is not punishment."},{"id":"psych-1100-20","front":"Which reinforcement schedule produces the highest, most extinction-resistant responding?","back":"Variable-ratio schedules (reward after an unpredictable number of responses, like slot machines) produce high, steady rates that resist extinction."},{"id":"psych-1100-21","front":"What did Bandura''s Bobo doll study show?","back":"Children who watched an adult model act aggressively toward a doll imitated that aggression, demonstrating observational learning without direct reinforcement."},{"id":"psych-1100-22","front":"Describe the three stages of the Atkinson-Shiffrin memory model.","back":"Sensory memory holds input very briefly; attended information enters short-term memory (limited capacity, seconds); rehearsed and encoded information moves to long-term memory."},{"id":"psych-1100-23","front":"What is the capacity of short-term memory, and how does chunking help?","back":"Classic estimate is about 7 plus or minus 2 items (modern estimates nearer 4). Chunking groups items into meaningful units so more information fits."},{"id":"psych-1100-24","front":"Explicit vs implicit memory","back":"Explicit (declarative) memory is consciously recalled facts and events. Implicit memory is unconscious, such as procedural skills like riding a bike and primed responses."},{"id":"psych-1100-25","front":"Proactive vs retroactive interference","back":"Proactive: old learning disrupts recall of new information. Retroactive: new learning disrupts recall of old information."},{"id":"psych-1100-26","front":"What is the serial position effect?","back":"When recalling a list, people remember the first items (primacy) and last items (recency) better than those in the middle."},{"id":"psych-1100-27","front":"What is the misinformation effect?","back":"Exposure to misleading information after an event distorts memory of it, as in Loftus and Palmer''s study where the verb ''smashed'' raised speed estimates."},{"id":"psych-1100-28","front":"Sensation vs perception","back":"Sensation is detecting physical energy with sense receptors; perception is the brain organizing and interpreting that input into meaningful experience."},{"id":"psych-1100-29","front":"What is transduction?","back":"The conversion of physical stimulus energy (light, sound waves) into neural signals the brain can interpret, e.g. by rods and cones in the retina."},{"id":"psych-1100-30","front":"Rods vs cones","back":"Rods are sensitive in dim light and detect black and white, concentrated in the periphery. Cones detect color and fine detail, concentrated in the fovea."}],"quizzes":[],"seed":1,"look":{"color":"#9A4FD1","icon":"psych"}}'::jsonb);   -- https://psychology.osu.edu/courses/psych-1100
select pg_temp.sb_seed('seed:osu-edu:chem-1210', 'osu.edu', 'CHEM 1210', 'CHEM 1210 Exam Review: Stoichiometry, Thermochemistry, Electron Configuration and Bonding', '{"v":1,"app":"studyboard","type":"deck","name":"CHEM 1210 Exam Review: Stoichiometry, Thermochemistry, Electron Configuration and Bonding","course":{"code":"CHEM 1210","name":"General Chemistry I"},"cards":[{"id":"chem-1210-1","front":"How many particles are in one mole?","back":"Avogadro''s number, 6.022 x 10^23 particles (atoms, molecules or formula units)."},{"id":"chem-1210-2","front":"Convert 36.0 g of water (molar mass 18.02 g/mol) to moles.","back":"n = mass / molar mass = 36.0 g / 18.02 g/mol = 2.00 mol H2O."},{"id":"chem-1210-3","front":"How do you find the limiting reactant?","back":"Convert each reactant to moles, divide by its coefficient in the balanced equation (or compute product each could form); the reactant giving the least product is limiting."},{"id":"chem-1210-4","front":"Percent yield formula","back":"Percent yield = (actual yield / theoretical yield) x 100%. Theoretical yield comes from stoichiometry using the limiting reactant."},{"id":"chem-1210-5","front":"Empirical formula vs molecular formula","back":"The empirical formula is the simplest whole-number ratio of atoms (CH2O); the molecular formula is the actual count, a whole-number multiple of it (C6H12O6)."},{"id":"chem-1210-6","front":"Define molarity and give its formula.","back":"Molarity M = moles of solute / liters of solution. Example: 0.50 mol NaCl in 0.250 L gives 2.0 M."},{"id":"chem-1210-7","front":"Dilution equation","back":"M1V1 = M2V2: initial concentration times initial volume equals final concentration times final volume, since moles of solute stay constant."},{"id":"chem-1210-8","front":"What is a net ionic equation?","back":"An equation showing only the species that actually react, with spectator ions (present unchanged on both sides) removed. E.g. Ag+(aq) + Cl-(aq) -> AgCl(s)."},{"id":"chem-1210-9","front":"In a redox reaction, what is oxidized and what is reduced?","back":"Oxidation is loss of electrons (oxidation number increases); reduction is gain of electrons (oxidation number decreases). Mnemonic: OIL RIG."},{"id":"chem-1210-10","front":"Ideal gas law: state it and define each symbol.","back":"PV = nRT. P pressure, V volume, n moles of gas, R gas constant (0.08206 L*atm/(mol*K)), T absolute temperature in kelvin."},{"id":"chem-1210-11","front":"A gas at 1.00 atm occupies 4.0 L. At constant T, what is its volume at 2.00 atm?","back":"Boyle''s law P1V1 = P2V2: V2 = (1.00 x 4.0)/2.00 = 2.0 L."},{"id":"chem-1210-12","front":"What is Dalton''s law of partial pressures?","back":"Total pressure of a gas mixture equals the sum of each gas''s partial pressure; each partial pressure equals its mole fraction times total pressure."},{"id":"chem-1210-13","front":"Endothermic vs exothermic","back":"Exothermic processes release heat to the surroundings (delta H < 0). Endothermic processes absorb heat (delta H > 0)."},{"id":"chem-1210-14","front":"Formula for heat absorbed by a substance, with symbols.","back":"q = m*c*delta T. m mass, c specific heat capacity, delta T = T_final - T_initial."},{"id":"chem-1210-15","front":"What does Hess''s law state?","back":"The enthalpy change of a reaction is the same whether it occurs in one step or many, so you can add the delta H values of steps that sum to the overall reaction."},{"id":"chem-1210-16","front":"How do you calculate delta H of reaction from standard enthalpies of formation?","back":"delta H rxn = sum of n*delta Hf(products) - sum of n*delta Hf(reactants). Elements in their standard states have delta Hf = 0."},{"id":"chem-1210-17","front":"Relationship between wavelength, frequency and energy of light","back":"c = lambda*nu and E = h*nu. Shorter wavelength means higher frequency and higher energy per photon."},{"id":"chem-1210-18","front":"What do the four quantum numbers n, l, ml and ms describe?","back":"n: energy level and size. l: subshell shape (0=s, 1=p, 2=d, 3=f). ml: orbital orientation (-l to +l). ms: electron spin (+1/2 or -1/2)."},{"id":"chem-1210-19","front":"Write the ground-state electron configuration of oxygen (Z = 8).","back":"1s2 2s2 2p4."},{"id":"chem-1210-20","front":"State the Pauli exclusion principle and Hund''s rule.","back":"Pauli: no two electrons in an atom share all four quantum numbers, so an orbital holds at most 2 with opposite spins. Hund: electrons fill degenerate orbitals singly before pairing."},{"id":"chem-1210-21","front":"Periodic trend for atomic radius","back":"Radius decreases across a period (higher effective nuclear charge) and increases down a group (more electron shells)."},{"id":"chem-1210-22","front":"Periodic trend for first ionization energy","back":"Increases across a period and decreases down a group; it is the energy needed to remove the outermost electron from a gaseous atom."},{"id":"chem-1210-23","front":"Ionic vs covalent bonds","back":"Ionic bonds form by electron transfer between a metal and nonmetal (large electronegativity difference). Covalent bonds form by sharing electrons, usually between nonmetals."},{"id":"chem-1210-24","front":"How do you calculate formal charge?","back":"Formal charge = valence electrons - nonbonding electrons - (bonding electrons / 2). The best Lewis structure minimizes formal charges."},{"id":"chem-1210-25","front":"What is resonance?","back":"When more than one valid Lewis structure can be drawn, the real molecule is an average (hybrid) of them, e.g. the equal N-O bonds in nitrate."},{"id":"chem-1210-26","front":"VSEPR: geometry of a molecule with 4 electron domains and 2 lone pairs (like H2O)?","back":"Electron geometry is tetrahedral; molecular shape is bent, with a bond angle a bit less than 109.5 degrees (about 104.5 degrees in water)."},{"id":"chem-1210-27","front":"Why is CO2 nonpolar though its C=O bonds are polar?","back":"It is linear, so the two bond dipoles point in opposite directions and cancel, giving no net dipole moment."},{"id":"chem-1210-28","front":"What hybridization does the central atom have with 3 electron domains?","back":"sp2, trigonal planar arrangement with about 120 degree angles. 2 domains is sp, 4 is sp3."},{"id":"chem-1210-29","front":"Rank intermolecular forces from weakest to strongest.","back":"London dispersion < dipole-dipole < hydrogen bonding (H bonded to N, O or F). Stronger forces give higher boiling points."},{"id":"chem-1210-30","front":"Sigma vs pi bonds","back":"A sigma bond forms from head-on orbital overlap; a pi bond from side-by-side p overlap. A single bond is 1 sigma, a double is 1 sigma + 1 pi, a triple is 1 sigma + 2 pi."}],"quizzes":[],"seed":1,"look":{"color":"#1E9E74","icon":"chem"}}'::jsonb);   -- https://chemistry.osu.edu/courses/chem-1210
select pg_temp.sb_seed('seed:osu-edu:stat-1450', 'osu.edu', 'STAT 1450', 'STAT 1450 Final Review: Sampling, Probability, Confidence Intervals and Regression', '{"v":1,"app":"studyboard","type":"deck","name":"STAT 1450 Final Review: Sampling, Probability, Confidence Intervals and Regression","course":{"code":"STAT 1450","name":"Introduction to the Practice of Statistics"},"cards":[{"id":"stat-1450-1","front":"Categorical vs quantitative variable","back":"Categorical variables place individuals into groups (eye color); quantitative variables take numerical values where arithmetic makes sense (height)."},{"id":"stat-1450-2","front":"Mean vs median: which is resistant to outliers?","back":"The median is resistant; the mean is pulled toward outliers and the long tail of a skewed distribution."},{"id":"stat-1450-3","front":"In a right-skewed distribution, how do the mean and median compare?","back":"The mean is typically greater than the median because the long right tail pulls the mean upward."},{"id":"stat-1450-4","front":"How is the IQR calculated and how is it used to flag outliers?","back":"IQR = Q3 - Q1. A value is a suspected outlier if it is below Q1 - 1.5*IQR or above Q3 + 1.5*IQR."},{"id":"stat-1450-5","front":"State the 68-95-99.7 rule.","back":"For a Normal distribution, about 68% of values lie within 1 standard deviation of the mean, 95% within 2, and 99.7% within 3."},{"id":"stat-1450-6","front":"Formula for a z-score and what it means","back":"z = (x - mu)/sigma. It tells how many standard deviations a value lies above (positive) or below (negative) the mean."},{"id":"stat-1450-7","front":"Exam scores are Normal with mean 70 and SD 10. What is the z-score of 85?","back":"z = (85 - 70)/10 = 1.5, so the score is 1.5 standard deviations above the mean."},{"id":"stat-1450-8","front":"Observational study vs experiment","back":"In an observational study researchers measure without intervening; in an experiment they impose treatments. Only well-designed experiments can show causation."},{"id":"stat-1450-9","front":"What is a confounding variable?","back":"A variable related to both the explanatory variable and the response, so its effect cannot be separated from the effect of the explanatory variable."},{"id":"stat-1450-10","front":"Three principles of experimental design","back":"Control (comparison group, reduce other variation), randomization (random assignment to treatments), and replication (enough subjects to see real effects)."},{"id":"stat-1450-11","front":"What is a simple random sample (SRS)?","back":"A sample of size n chosen so every possible set of n individuals has an equal chance of being selected."},{"id":"stat-1450-12","front":"Name two common sources of bias in sampling.","back":"Voluntary response bias (people choose to respond, often with strong opinions) and undercoverage (some groups left out of the sampling frame). Nonresponse bias is another."},{"id":"stat-1450-13","front":"Addition rule for P(A or B)","back":"P(A or B) = P(A) + P(B) - P(A and B). If A and B are disjoint, P(A and B) = 0."},{"id":"stat-1450-14","front":"When are two events independent, and what is the multiplication rule?","back":"A and B are independent if knowing one occurs doesn''t change the probability of the other. Then P(A and B) = P(A)*P(B)."},{"id":"stat-1450-15","front":"Conditional probability formula","back":"P(A | B) = P(A and B) / P(B): the probability of A given that B has occurred."},{"id":"stat-1450-16","front":"Conditions for a binomial setting","back":"Fixed number n of trials, each trial is success or failure, trials are independent, and the probability of success p is the same each trial."},{"id":"stat-1450-17","front":"Mean and SD of a binomial random variable","back":"mean = n*p and SD = sqrt(n*p*(1-p))."},{"id":"stat-1450-18","front":"What does the Central Limit Theorem say?","back":"For a large enough sample size, the sampling distribution of the sample mean is approximately Normal with mean mu and SD sigma/sqrt(n), whatever the population shape."},{"id":"stat-1450-19","front":"Parameter vs statistic","back":"A parameter describes a population (mu, p) and is usually unknown; a statistic is computed from a sample (x-bar, p-hat) and used to estimate the parameter."},{"id":"stat-1450-20","front":"Correct interpretation of a 95% confidence interval","back":"We are 95% confident the interval captures the true parameter; the method produces intervals that capture it in about 95% of repeated samples."},{"id":"stat-1450-21","front":"How does increasing sample size affect a confidence interval''s margin of error?","back":"Margin of error decreases (roughly by 1/sqrt(n)); quadrupling n halves it. Raising the confidence level widens the interval."},{"id":"stat-1450-22","front":"Formula for a confidence interval for a population proportion","back":"p-hat +/- z* * sqrt(p-hat*(1-p-hat)/n), where z* is 1.96 for 95% confidence."},{"id":"stat-1450-23","front":"What is a p-value?","back":"The probability, assuming the null hypothesis is true, of getting a result at least as extreme as the one observed. Small p-values are evidence against H0."},{"id":"stat-1450-24","front":"If p-value = 0.03 and alpha = 0.05, what do you conclude?","back":"Since 0.03 < 0.05, reject H0: the result is statistically significant at the 5% level. It does not prove H0 false or show a large effect."},{"id":"stat-1450-25","front":"Type I vs Type II error","back":"Type I: rejecting a true H0 (false positive); its probability is alpha. Type II: failing to reject a false H0 (false negative)."},{"id":"stat-1450-26","front":"When should you use a t procedure instead of z for a mean?","back":"When the population standard deviation is unknown and estimated by the sample SD s. The t distribution has heavier tails and degrees of freedom n - 1."},{"id":"stat-1450-27","front":"Interpret a regression slope b = 2.5 for predicting weight (lb) from height (in).","back":"For each additional inch of height, predicted weight increases by 2.5 lb on average."},{"id":"stat-1450-28","front":"What does r^2 represent in linear regression?","back":"The fraction of the variation in the response variable explained by the linear relationship with the explanatory variable."},{"id":"stat-1450-29","front":"What is a residual?","back":"Residual = observed y - predicted y-hat. A residual plot with no pattern suggests a linear model is appropriate."},{"id":"stat-1450-30","front":"Why is extrapolation risky?","back":"Using a regression line to predict far outside the range of observed x values assumes the pattern continues, which often isn''t true."}],"quizzes":[],"seed":1,"look":{"color":"#C79A12","icon":"stats"}}'::jsonb);   -- https://stat.osu.edu/courses/stat-1450
select pg_temp.sb_seed('seed:psu-edu:biol-110', 'psu.edu', 'BIOL 110', 'BIOL 110 Exam Review: Cells, Genetics, Evolution and Biodiversity', '{"v":1,"app":"studyboard","type":"deck","name":"BIOL 110 Exam Review: Cells, Genetics, Evolution and Biodiversity","course":{"code":"BIOL 110","name":"Biology: Basic Concepts and Biodiversity"},"cards":[{"id":"biol-110-1","front":"Prokaryotic vs eukaryotic cells","back":"Prokaryotes (bacteria, archaea) lack a nucleus and membrane-bound organelles. Eukaryotes (plants, animals, fungi, protists) have a nucleus and organelles like mitochondria."},{"id":"biol-110-2","front":"What is the function of the mitochondrion?","back":"It carries out cellular respiration, producing most of the cell''s ATP. It has its own DNA, supporting endosymbiotic origin."},{"id":"biol-110-3","front":"What is the endosymbiotic theory?","back":"Mitochondria and chloroplasts descend from free-living prokaryotes engulfed by an ancestral cell. Evidence: double membranes, own circular DNA and bacteria-like ribosomes."},{"id":"biol-110-4","front":"Describe the fluid mosaic model of the plasma membrane.","back":"The membrane is a phospholipid bilayer with hydrophobic tails inward, in which proteins, cholesterol and other molecules move laterally like a mosaic."},{"id":"biol-110-5","front":"Diffusion vs osmosis vs active transport","back":"Diffusion: solutes move down their concentration gradient. Osmosis: water moves across a selectively permeable membrane. Active transport uses energy (ATP) to move solutes against a gradient."},{"id":"biol-110-6","front":"What happens to an animal cell in a hypotonic solution?","back":"Water enters by osmosis because the outside has lower solute concentration; the cell swells and may lyse."},{"id":"biol-110-7","front":"How do enzymes speed up reactions?","back":"They lower the activation energy by binding substrates at the active site; they are not consumed and do not change the reaction''s overall delta G."},{"id":"biol-110-8","front":"Competitive vs noncompetitive inhibition","back":"A competitive inhibitor binds the active site and can be overcome by more substrate. A noncompetitive inhibitor binds elsewhere and changes enzyme shape, lowering activity."},{"id":"biol-110-9","front":"Overall equation for cellular respiration","back":"C6H12O6 + 6 O2 -> 6 CO2 + 6 H2O + energy (ATP and heat)."},{"id":"biol-110-10","front":"Stages of aerobic respiration and where they occur","back":"Glycolysis (cytoplasm), pyruvate oxidation and the citric acid cycle (mitochondrial matrix), oxidative phosphorylation (inner mitochondrial membrane)."},{"id":"biol-110-11","front":"Which stage of respiration makes the most ATP and how?","back":"Oxidative phosphorylation: the electron transport chain pumps H+ to build a gradient, and ATP synthase uses the H+ flow to make ATP (chemiosmosis). Oxygen is the final electron acceptor."},{"id":"biol-110-12","front":"Light reactions vs Calvin cycle in photosynthesis","back":"Light reactions (thylakoid membranes) split water, release O2 and make ATP and NADPH. The Calvin cycle (stroma) uses ATP and NADPH to fix CO2 into sugar."},{"id":"biol-110-13","front":"Mitosis vs meiosis","back":"Mitosis yields 2 genetically identical diploid cells for growth and repair. Meiosis yields 4 genetically different haploid gametes through two divisions."},{"id":"biol-110-14","front":"Name two sources of genetic variation generated in meiosis.","back":"Crossing over between homologous chromosomes in prophase I, and independent assortment of homologous pairs in metaphase I. Random fertilization adds more."},{"id":"biol-110-15","front":"Genotype vs phenotype","back":"Genotype is an organism''s genetic makeup (e.g. Aa); phenotype is its observable traits, produced by genotype and environment."},{"id":"biol-110-16","front":"Cross Aa x Aa. What are the expected genotype and phenotype ratios?","back":"Genotypes 1 AA : 2 Aa : 1 aa. With complete dominance, phenotypes are 3 dominant : 1 recessive."},{"id":"biol-110-17","front":"What is a test cross?","back":"Crossing an individual with the dominant phenotype to a homozygous recessive. If any offspring show the recessive trait, the unknown parent is heterozygous."},{"id":"biol-110-18","front":"Incomplete dominance vs codominance","back":"Incomplete dominance: heterozygote is intermediate (red x white gives pink). Codominance: both alleles fully expressed (AB blood type)."},{"id":"biol-110-19","front":"Why are X-linked recessive disorders more common in males?","back":"Males have one X chromosome, so a single recessive allele on it is expressed; females need two copies. Examples: hemophilia, red-green color blindness."},{"id":"biol-110-20","front":"State the central dogma of molecular biology.","back":"DNA is transcribed into mRNA, which is translated into protein. Transcription is in the nucleus in eukaryotes; translation is at ribosomes."},{"id":"biol-110-21","front":"Base pairing rules in DNA and RNA","back":"DNA: A with T, G with C. RNA has uracil in place of thymine, so A pairs with U."},{"id":"biol-110-22","front":"What is natural selection?","back":"Individuals with heritable traits that improve survival and reproduction in an environment leave more offspring, so those traits become more common over generations."},{"id":"biol-110-23","front":"Can an individual organism evolve? Explain.","back":"No. Populations evolve: evolution is a change in allele frequencies in a population over generations. Individuals do not change their genes in response to need."},{"id":"biol-110-24","front":"Name four mechanisms that change allele frequencies.","back":"Natural selection, genetic drift (chance, strongest in small populations), gene flow (migration), and mutation. Nonrandom mating changes genotype frequencies."},{"id":"biol-110-25","front":"Founder effect vs bottleneck effect","back":"Both are genetic drift. Founder: a few individuals start a new population. Bottleneck: a population is drastically reduced by a disaster. Either can cut genetic diversity."},{"id":"biol-110-26","front":"Homologous vs analogous structures","back":"Homologous structures share ancestry though function may differ (human arm, bat wing). Analogous structures share function by convergent evolution, not ancestry (bird and insect wings)."},{"id":"biol-110-27","front":"What is the biological species concept?","back":"A species is a group of populations that can interbreed in nature and produce fertile offspring, and is reproductively isolated from other groups."},{"id":"biol-110-28","front":"Allopatric vs sympatric speciation","back":"Allopatric: populations split by a geographic barrier diverge. Sympatric: new species arise in the same area, e.g. via polyploidy in plants or habitat differences."},{"id":"biol-110-29","front":"What are the three domains of life?","back":"Bacteria, Archaea and Eukarya. Archaea are prokaryotes but share some molecular features with eukaryotes."},{"id":"biol-110-30","front":"What does a phylogenetic tree show?","back":"Hypothesized evolutionary relationships; branch points (nodes) represent common ancestors, and sister taxa share the most recent common ancestor."}],"quizzes":[],"seed":1,"look":{"color":"#16A34A","icon":"bio"}}'::jsonb);   -- https://bulletins.psu.edu/university-course-descriptions/undergraduate/biol/
select pg_temp.sb_seed('seed:psu-edu:econ-102', 'psu.edu', 'ECON 102', 'ECON 102 Midterm Review: Supply and Demand, Elasticity, Costs and Market Structures', '{"v":1,"app":"studyboard","type":"deck","name":"ECON 102 Midterm Review: Supply and Demand, Elasticity, Costs and Market Structures","course":{"code":"ECON 102","name":"Introductory Microeconomic Analysis and Policy"},"cards":[{"id":"econ-102-1","front":"What is opportunity cost?","back":"The value of the next-best alternative given up when making a choice. Spending an evening studying costs the wages you could have earned working."},{"id":"econ-102-2","front":"Absolute vs comparative advantage","back":"Absolute advantage: producing more with the same resources. Comparative advantage: producing at a lower opportunity cost. Trade gains come from comparative advantage."},{"id":"econ-102-3","front":"What does a point inside the production possibilities frontier mean?","back":"Resources are unemployed or used inefficiently; more of one good could be made without giving up the other. Points outside are unattainable now."},{"id":"econ-102-4","front":"Change in quantity demanded vs change in demand","back":"A change in the good''s own price moves along the demand curve (quantity demanded). Other factors such as income, tastes or related prices shift the whole curve."},{"id":"econ-102-5","front":"List the main determinants that shift demand.","back":"Income, prices of related goods (substitutes, complements), tastes, expectations, and number of buyers."},{"id":"econ-102-6","front":"Normal vs inferior good","back":"For a normal good, demand rises when income rises. For an inferior good, demand falls when income rises (e.g. generic store brands for some consumers)."},{"id":"econ-102-7","front":"Substitutes vs complements","back":"Substitutes: a rise in one''s price increases demand for the other (coffee and tea). Complements: a rise in one''s price decreases demand for the other (cars and gasoline)."},{"id":"econ-102-8","front":"A frost destroys much of the orange crop. Effect on orange juice price and quantity?","back":"Supply shifts left: equilibrium price rises and equilibrium quantity falls."},{"id":"econ-102-9","front":"If both demand and supply increase, what happens to equilibrium price and quantity?","back":"Quantity definitely rises; the price change is ambiguous, depending on which shift is larger."},{"id":"econ-102-10","front":"Formula for price elasticity of demand (midpoint method)","back":"Ed = (% change in Qd)/(% change in P), with % changes computed as change divided by the average of start and end values. Use absolute value."},{"id":"econ-102-11","front":"If demand is elastic (|Ed| > 1), what happens to total revenue when price rises?","back":"Total revenue falls, because quantity demanded falls by a larger percentage than price rises. With inelastic demand, revenue rises."},{"id":"econ-102-12","front":"Factors that make demand more elastic","back":"Many close substitutes, the good is a luxury, it takes a large share of budget, a narrowly defined market, and a longer time horizon."},{"id":"econ-102-13","front":"What is the sign of cross-price elasticity for substitutes and for complements?","back":"Positive for substitutes and negative for complements."},{"id":"econ-102-14","front":"Consumer surplus vs producer surplus","back":"Consumer surplus is willingness to pay minus price paid (area below demand, above price). Producer surplus is price received minus cost (area above supply, below price)."},{"id":"econ-102-15","front":"Effect of a binding price ceiling (e.g. rent control)","back":"Set below equilibrium, it creates a shortage (Qd > Qs) and deadweight loss, and can lead to waiting lists and lower quality."},{"id":"econ-102-16","front":"Effect of a binding price floor (e.g. minimum wage)","back":"Set above equilibrium, it creates a surplus (Qs > Qd); in the labor market that surplus is unemployment."},{"id":"econ-102-17","front":"Does tax incidence depend on who legally pays the tax?","back":"No. The burden falls more on whichever side of the market is less elastic, regardless of whether buyers or sellers send the payment."},{"id":"econ-102-18","front":"What is deadweight loss?","back":"The loss of total surplus from transactions that would have been mutually beneficial but no longer happen, e.g. because of a tax or price control."},{"id":"econ-102-19","front":"Negative externality and its market outcome","back":"A cost imposed on third parties (pollution). The market overproduces relative to the efficient level; a Pigouvian tax equal to the external cost can correct it."},{"id":"econ-102-20","front":"Public goods: two defining characteristics","back":"Nonexcludable (can''t prevent people from using them) and nonrival (one person''s use doesn''t reduce another''s). Example: national defense. They face the free-rider problem."},{"id":"econ-102-21","front":"Fixed cost vs variable cost","back":"Fixed costs don''t change with output in the short run (rent); variable costs rise with output (raw materials). TC = FC + VC."},{"id":"econ-102-22","front":"What is marginal cost and why does it eventually rise?","back":"MC = change in TC / change in Q. It rises due to diminishing marginal returns: adding variable inputs to fixed capital adds less output each time."},{"id":"econ-102-23","front":"Why does the MC curve cross ATC at ATC''s minimum?","back":"When marginal cost is below average cost it pulls the average down; above it pulls the average up. So they meet at the lowest point of ATC."},{"id":"econ-102-24","front":"Profit-maximizing rule for any firm","back":"Produce the quantity where marginal revenue equals marginal cost (MR = MC)."},{"id":"econ-102-25","front":"When should a perfectly competitive firm shut down in the short run?","back":"When price falls below minimum average variable cost (P < AVC), since it cannot cover even variable costs. It loses only fixed costs by shutting down."},{"id":"econ-102-26","front":"Long-run outcome in perfect competition","back":"Free entry and exit drive economic profit to zero, so P = minimum ATC = MC, which is both productively and allocatively efficient."},{"id":"econ-102-27","front":"Accounting profit vs economic profit","back":"Accounting profit = revenue - explicit costs. Economic profit = revenue - explicit - implicit costs (opportunity costs such as the owner''s foregone salary)."},{"id":"econ-102-28","front":"How does a monopolist''s output and price compare with competition?","back":"The monopolist sets MR = MC and charges a price above MC from the demand curve, producing less at a higher price, which creates deadweight loss."},{"id":"econ-102-29","front":"What is a Nash equilibrium?","back":"An outcome where each player''s strategy is the best response to the others'' strategies, so no one can gain by changing strategy alone."},{"id":"econ-102-30","front":"Why do cartel members tend to cheat (prisoner''s dilemma)?","back":"Each firm earns more by producing beyond its quota if others comply, so cheating is a dominant strategy, even though all are worse off when everyone cheats."}],"quizzes":[],"seed":1,"look":{"color":"#E0673B","icon":"econ"}}'::jsonb);   -- https://bulletins.psu.edu/university-course-descriptions/undergraduate/econ/
select pg_temp.sb_seed('seed:psu-edu:math-140', 'psu.edu', 'MATH 140', 'MATH 140 Exam Review: Limits, Derivative Rules, Related Rates and Optimization', '{"v":1,"app":"studyboard","type":"deck","name":"MATH 140 Exam Review: Limits, Derivative Rules, Related Rates and Optimization","course":{"code":"MATH 140","name":"Calculus With Analytic Geometry I"},"cards":[{"id":"math-140-1","front":"Definition of the derivative as a limit","back":"f''(x) = lim as h -> 0 of [f(x+h) - f(x)] / h, the instantaneous rate of change and the slope of the tangent line."},{"id":"math-140-2","front":"Evaluate lim as x -> 3 of (x^2 - 9)/(x - 3).","back":"Factor: (x-3)(x+3)/(x-3) = x + 3, so the limit is 6."},{"id":"math-140-3","front":"lim as x -> 0 of sin(x)/x","back":"Equals 1 (x in radians). This is the key limit used to derive d/dx [sin x] = cos x."},{"id":"math-140-4","front":"Three conditions for f to be continuous at x = a","back":"f(a) is defined, lim as x -> a of f(x) exists, and the limit equals f(a)."},{"id":"math-140-5","front":"State the Intermediate Value Theorem.","back":"If f is continuous on [a, b] and N is between f(a) and f(b), then some c in (a, b) has f(c) = N. Often used to show a root exists."},{"id":"math-140-6","front":"How do you find horizontal asymptotes of a rational function?","back":"Compare degrees: numerator degree lower gives y = 0; equal degrees gives y = ratio of leading coefficients; numerator higher gives none."},{"id":"math-140-7","front":"Power rule","back":"d/dx [x^n] = n*x^(n-1) for any real n. Example: d/dx [x^5] = 5x^4."},{"id":"math-140-8","front":"Product rule","back":"d/dx [f*g] = f''*g + f*g''."},{"id":"math-140-9","front":"Quotient rule","back":"d/dx [f/g] = (f''*g - f*g'') / g^2. Mnemonic: low d-high minus high d-low, over low squared."},{"id":"math-140-10","front":"Chain rule","back":"d/dx [f(g(x))] = f''(g(x)) * g''(x). Example: d/dx [(3x+1)^4] = 4(3x+1)^3 * 3 = 12(3x+1)^3."},{"id":"math-140-11","front":"Derivatives of sin x, cos x and tan x","back":"d/dx [sin x] = cos x; d/dx [cos x] = -sin x; d/dx [tan x] = sec^2 x."},{"id":"math-140-12","front":"Derivatives of e^x and ln x","back":"d/dx [e^x] = e^x; d/dx [ln x] = 1/x for x > 0. More generally d/dx [a^x] = a^x * ln a."},{"id":"math-140-13","front":"Differentiate y = e^(x^2).","back":"By the chain rule, y'' = e^(x^2) * 2x = 2x*e^(x^2)."},{"id":"math-140-14","front":"Find the tangent line to y = x^2 at x = 3.","back":"y'' = 2x = 6 at x = 3 and y(3) = 9, so the tangent is y - 9 = 6(x - 3), i.e. y = 6x - 9."},{"id":"math-140-15","front":"What is implicit differentiation? Find dy/dx for x^2 + y^2 = 25.","back":"Differentiate both sides treating y as a function of x: 2x + 2y*dy/dx = 0, so dy/dx = -x/y."},{"id":"math-140-16","front":"Derivatives of inverse trig: arcsin x and arctan x","back":"d/dx [arcsin x] = 1/sqrt(1 - x^2); d/dx [arctan x] = 1/(1 + x^2)."},{"id":"math-140-17","front":"Steps for a related rates problem","back":"Draw and label, write an equation relating the quantities, differentiate with respect to time t, then substitute known values only after differentiating."},{"id":"math-140-18","front":"A circle''s radius grows at 2 cm/s. How fast is its area growing when r = 5 cm?","back":"A = pi*r^2, so dA/dt = 2*pi*r*dr/dt = 2*pi*5*2 = 20*pi cm^2/s."},{"id":"math-140-19","front":"What is a critical number?","back":"A value c in the domain of f where f''(c) = 0 or f''(c) does not exist. Local extrema can only occur there."},{"id":"math-140-20","front":"First derivative test","back":"If f'' changes from positive to negative at c, f has a local max; from negative to positive, a local min; no sign change, neither."},{"id":"math-140-21","front":"Second derivative test","back":"If f''(c) = 0 and f''''(c) > 0, local min (concave up); if f''''(c) < 0, local max. If f''''(c) = 0 the test is inconclusive."},{"id":"math-140-22","front":"What is an inflection point?","back":"A point on the graph where concavity changes (f'''' changes sign). f''''(c) = 0 alone is not enough."},{"id":"math-140-23","front":"Closed interval method for absolute extrema","back":"For continuous f on [a, b], evaluate f at the critical numbers inside and at the endpoints a and b; the largest is the absolute max and the smallest the absolute min."},{"id":"math-140-24","front":"State the Mean Value Theorem.","back":"If f is continuous on [a, b] and differentiable on (a, b), some c in (a, b) has f''(c) = [f(b) - f(a)] / (b - a)."},{"id":"math-140-25","front":"Maximize the area of a rectangle with perimeter 40.","back":"With 2x + 2y = 40, y = 20 - x and A = x(20 - x). A'' = 20 - 2x = 0 gives x = 10, so a 10 by 10 square with area 100."},{"id":"math-140-26","front":"L''Hopital''s rule: when can you use it?","back":"For limits of indeterminate form 0/0 or infinity/infinity, lim f/g = lim f''/g'' (if the latter exists). Differentiate top and bottom separately, not with the quotient rule."},{"id":"math-140-27","front":"Linear approximation formula","back":"L(x) = f(a) + f''(a)(x - a), the tangent line used to approximate f near a. Example: sqrt(4.1) is about 2 + (1/4)(0.1) = 2.025."},{"id":"math-140-28","front":"Position, velocity, acceleration relationship","back":"v(t) = s''(t) and a(t) = v''(t) = s''''(t). An object speeds up when v and a have the same sign."},{"id":"math-140-29","front":"Common pitfall: is d/dx [e^(2x)] = e^(2x)?","back":"No. By the chain rule it is 2e^(2x). Forgetting the inner derivative is a frequent error."},{"id":"math-140-30","front":"When is a function not differentiable at a point?","back":"At corners or cusps (like |x| at 0), vertical tangents, and discontinuities. Differentiable implies continuous, but not the reverse."}],"quizzes":[],"seed":1,"look":{"color":"#3B6FE0","icon":"calc"}}'::jsonb);   -- https://bulletins.psu.edu/university-course-descriptions/undergraduate/math/
select pg_temp.sb_seed('seed:ufl-edu:acg-2021', 'ufl.edu', 'ACG 2021', 'ACG 2021 Exam Review: Accounting Cycle, Inventory, Receivables and Financial Statements', '{"v":1,"app":"studyboard","type":"deck","name":"ACG 2021 Exam Review: Accounting Cycle, Inventory, Receivables and Financial Statements","course":{"code":"ACG 2021","name":"Introduction to Financial Accounting"},"cards":[{"id":"acg-2021-1","front":"State the basic accounting equation.","back":"Assets = Liabilities + Stockholders'' Equity. Every transaction keeps it in balance."},{"id":"acg-2021-2","front":"Normal balances of the account types","back":"Debit: assets, expenses, dividends. Credit: liabilities, equity (common stock, retained earnings) and revenues."},{"id":"acg-2021-3","front":"A company buys $5,000 of equipment on account. Journal entry?","back":"Debit Equipment 5,000; Credit Accounts Payable 5,000. Assets and liabilities both rise."},{"id":"acg-2021-4","front":"What does the revenue recognition principle require?","back":"Revenue is recognized when the performance obligation is satisfied (goods or services delivered), not necessarily when cash is received."},{"id":"acg-2021-5","front":"Accrual vs cash basis accounting","back":"Accrual basis records revenues when earned and expenses when incurred (required by GAAP). Cash basis records them only when cash changes hands."},{"id":"acg-2021-6","front":"What is the expense recognition (matching) principle?","back":"Expenses are recorded in the same period as the revenues they helped generate."},{"id":"acg-2021-7","front":"Four types of adjusting entries","back":"Prepaid expenses (deferral), unearned revenues (deferral), accrued revenues, and accrued expenses. Adjusting entries never involve cash."},{"id":"acg-2021-8","front":"Adjusting entry for $300 of supplies used during the period","back":"Debit Supplies Expense 300; Credit Supplies 300."},{"id":"acg-2021-9","front":"What type of account is Unearned Revenue?","back":"A liability: cash received before the service is performed. When earned, debit Unearned Revenue and credit Service Revenue."},{"id":"acg-2021-10","front":"What is accumulated depreciation?","back":"A contra-asset account with a credit balance subtracting total depreciation to date from an asset''s cost. Cost minus accumulated depreciation equals book value."},{"id":"acg-2021-11","front":"Order in which the financial statements are prepared, and why","back":"Income statement, then retained earnings statement (needs net income), then balance sheet (needs ending retained earnings), then statement of cash flows."},{"id":"acg-2021-12","front":"Retained earnings roll-forward formula","back":"Ending RE = Beginning RE + Net income - Dividends."},{"id":"acg-2021-13","front":"Which accounts are closed at period end?","back":"Temporary accounts (revenues, expenses, dividends) are closed to Retained Earnings. Permanent balance sheet accounts are not closed."},{"id":"acg-2021-14","front":"Straight-line depreciation formula","back":"(Cost - Salvage value) / Useful life. Example: (50,000 - 5,000)/9 years = 5,000 per year."},{"id":"acg-2021-15","front":"Double-declining-balance depreciation","back":"Rate = 2 / useful life, applied to beginning book value each year (ignore salvage in the rate, but don''t depreciate below salvage)."},{"id":"acg-2021-16","front":"Cost of goods sold formula (periodic)","back":"COGS = Beginning inventory + Purchases - Ending inventory."},{"id":"acg-2021-17","front":"In a period of rising prices, which method gives higher net income: FIFO or LIFO?","back":"FIFO, because older, cheaper costs go to COGS, leaving lower expenses and higher ending inventory. LIFO gives higher COGS and lower taxes."},{"id":"acg-2021-18","front":"Units: 10 at $4, then 10 at $6. 12 sold. COGS under FIFO?","back":"FIFO uses oldest first: 10 x $4 + 2 x $6 = $52."},{"id":"acg-2021-19","front":"What is the lower of cost and net realizable value rule?","back":"If inventory''s net realizable value falls below cost, write it down to NRV, recognizing a loss in the current period."},{"id":"acg-2021-20","front":"Allowance method for bad debts: entry to estimate uncollectible accounts","back":"Debit Bad Debt Expense; Credit Allowance for Doubtful Accounts. Net realizable value = Accounts Receivable - Allowance."},{"id":"acg-2021-21","front":"Under the allowance method, what entry writes off a specific bad account?","back":"Debit Allowance for Doubtful Accounts; Credit Accounts Receivable. It does not affect expense or net realizable value."},{"id":"acg-2021-22","front":"Gross profit and gross margin","back":"Gross profit = Net sales - COGS. Gross margin (gross profit rate) = Gross profit / Net sales."},{"id":"acg-2021-23","front":"What is a bank reconciliation, and name one item that adjusts the book side.","back":"It explains differences between the bank statement and the company''s cash balance. Book-side items include bank service charges, NSF checks and interest earned."},{"id":"acg-2021-24","front":"Name two key internal control principles.","back":"Segregation of duties (no one person handles a transaction from start to finish) and establishing responsibility; others include documentation and independent verification."},{"id":"acg-2021-25","front":"Bonds issued at a discount: what does it mean?","back":"The stated rate is below the market rate, so the bonds sell below face value. The discount is amortized, raising interest expense above cash interest."},{"id":"acg-2021-26","front":"What happens to equity in a 2-for-1 stock split?","back":"Shares outstanding double and par value per share halves; total equity and each account balance are unchanged."},{"id":"acg-2021-27","front":"Three sections of the statement of cash flows","back":"Operating activities (core business), investing activities (buying/selling long-term assets and investments), and financing activities (debt, stock, dividends)."},{"id":"acg-2021-28","front":"Under the indirect method, how is depreciation treated in operating cash flow?","back":"It is added back to net income because it reduced net income but used no cash."},{"id":"acg-2021-29","front":"Current ratio formula and meaning","back":"Current assets / Current liabilities; it measures short-term liquidity. A ratio above 1 means current assets exceed current liabilities."},{"id":"acg-2021-30","front":"Is paying dividends an expense?","back":"No. Dividends are a distribution of retained earnings to owners; they reduce equity but never appear on the income statement."}],"quizzes":[],"seed":1,"look":{"color":"#0D9488","icon":"acct"}}'::jsonb);   -- https://catalog.ufl.edu/UGRD/courses/accounting/
select pg_temp.sb_seed('seed:ufl-edu:eco-2013', 'ufl.edu', 'ECO 2013', 'ECO 2013 Final Review: GDP, Inflation, Unemployment, Money and Fiscal and Monetary Policy', '{"v":1,"app":"studyboard","type":"deck","name":"ECO 2013 Final Review: GDP, Inflation, Unemployment, Money and Fiscal and Monetary Policy","course":{"code":"ECO 2013","name":"Principles of Macroeconomics"},"cards":[{"id":"eco-2013-1","front":"Define GDP.","back":"The market value of all final goods and services produced within a country in a given period. Intermediate goods are excluded to avoid double counting."},{"id":"eco-2013-2","front":"Expenditure approach formula for GDP","back":"GDP = C + I + G + NX: consumption, investment, government purchases, and net exports (exports minus imports)."},{"id":"eco-2013-3","front":"Why aren''t transfer payments like Social Security counted in G?","back":"They are not payments for newly produced goods or services; they redistribute income."},{"id":"eco-2013-4","front":"Nominal vs real GDP","back":"Nominal GDP uses current prices; real GDP uses base-year prices, so it changes only when output changes. GDP deflator = (nominal/real) x 100."},{"id":"eco-2013-5","front":"Does buying a used car or a share of stock add to GDP?","back":"No. Used goods were counted when produced and stocks are financial transfers. A dealer''s commission on the sale is counted as a service."},{"id":"eco-2013-6","front":"How is the CPI inflation rate calculated?","back":"Inflation = (CPI this year - CPI last year) / CPI last year x 100%."},{"id":"eco-2013-7","front":"Name a bias that makes the CPI overstate inflation.","back":"Substitution bias (consumers switch to cheaper goods), plus quality changes and introduction of new goods."},{"id":"eco-2013-8","front":"How is the unemployment rate calculated?","back":"Unemployed / Labor force x 100, where the labor force = employed + unemployed (actively looking). Discouraged workers are not counted."},{"id":"eco-2013-9","front":"Frictional, structural and cyclical unemployment","back":"Frictional: between jobs or searching. Structural: skills mismatch or lack of jobs in a field. Cyclical: due to recessions. The natural rate = frictional + structural."},{"id":"eco-2013-10","front":"Real interest rate approximation (Fisher equation)","back":"Real interest rate = nominal interest rate - inflation rate."},{"id":"eco-2013-11","front":"Who is hurt by unexpected inflation?","back":"Lenders and savers with fixed nominal returns, and people on fixed incomes. Borrowers with fixed-rate loans benefit."},{"id":"eco-2013-12","front":"Why does aggregate demand slope downward?","back":"Because of the wealth effect, interest rate effect and exchange rate effect: a lower price level raises spending on C, I and NX."},{"id":"eco-2013-13","front":"What shifts aggregate demand to the right?","back":"Increases in consumer or business confidence, government spending, tax cuts, money supply growth (lower interest rates), or foreign demand for exports."},{"id":"eco-2013-14","front":"Long-run aggregate supply: shape and determinant","back":"Vertical at potential (full-employment) output, determined by labor, capital, natural resources and technology, not the price level."},{"id":"eco-2013-15","front":"Effect of a negative supply shock (e.g. oil price spike) in the AD-AS model","back":"Short-run aggregate supply shifts left: output falls and the price level rises, causing stagflation."},{"id":"eco-2013-16","front":"Simple spending multiplier formula","back":"Multiplier = 1/(1 - MPC) = 1/MPS. With MPC = 0.8, a $10 billion rise in spending can raise GDP by up to $50 billion."},{"id":"eco-2013-17","front":"Expansionary vs contractionary fiscal policy","back":"Expansionary: raise government spending or cut taxes to fight recession. Contractionary: cut spending or raise taxes to fight inflation."},{"id":"eco-2013-18","front":"Budget deficit vs national debt","back":"A deficit is the yearly shortfall of revenue relative to spending; the debt is the accumulated total of past deficits minus surpluses."},{"id":"eco-2013-19","front":"What is crowding out?","back":"Government borrowing to fund deficits raises interest rates, reducing private investment and offsetting part of the fiscal stimulus."},{"id":"eco-2013-20","front":"Automatic stabilizers: definition and example","back":"Features of the budget that counter the business cycle without new legislation, like progressive income taxes and unemployment insurance."},{"id":"eco-2013-21","front":"Three functions of money","back":"Medium of exchange, unit of account, and store of value."},{"id":"eco-2013-22","front":"Simple money multiplier formula","back":"Money multiplier = 1 / reserve requirement. With a 10% requirement, $1,000 of new reserves can support up to $10,000 of deposits."},{"id":"eco-2013-23","front":"Name the Fed''s main monetary policy tools.","back":"Interest on reserve balances, open market operations (buying and selling government securities), the discount rate, and (historically) reserve requirements."},{"id":"eco-2013-24","front":"How does the Fed conduct expansionary monetary policy?","back":"It lowers its federal funds rate target (e.g. by buying bonds or lowering interest on reserves), reducing interest rates and boosting investment and AD."},{"id":"eco-2013-25","front":"What is the federal funds rate?","back":"The interest rate banks charge each other for overnight loans of reserves; the Fed targets a range for it."},{"id":"eco-2013-26","front":"State the quantity theory of money.","back":"M x V = P x Y: money supply times velocity equals the price level times real output. With constant V and Y, faster money growth causes inflation."},{"id":"eco-2013-27","front":"Short-run Phillips curve","back":"An inverse short-run trade-off between inflation and unemployment. In the long run the curve is vertical at the natural rate of unemployment."},{"id":"eco-2013-28","front":"Sources of long-run economic growth","back":"Growth in physical capital, human capital (education, skills), technology and productivity, and institutions such as property rights."},{"id":"eco-2013-29","front":"What is the rule of 70?","back":"Years to double = 70 / growth rate (%). At 2% growth, real GDP per person doubles in about 35 years."},{"id":"eco-2013-30","front":"Effect of a stronger U.S. dollar on net exports","back":"U.S. exports become more expensive abroad and imports cheaper, so net exports tend to fall."}],"quizzes":[],"seed":1,"look":{"color":"#DC2626","icon":"econ"}}'::jsonb);   -- https://catalog.ufl.edu/UGRD/courses/economics/
select pg_temp.sb_seed('seed:ufl-edu:phy-2048', 'ufl.edu', 'PHY 2048', 'PHY 2048 Exam Review: Kinematics, Newton''s Laws, Energy, Momentum and Rotation', '{"v":1,"app":"studyboard","type":"deck","name":"PHY 2048 Exam Review: Kinematics, Newton''s Laws, Energy, Momentum and Rotation","course":{"code":"PHY 2048","name":"Physics with Calculus 1"},"cards":[{"id":"phy-2048-1","front":"Constant-acceleration kinematic equations","back":"v = v0 + a*t; x = x0 + v0*t + (1/2)a*t^2; v^2 = v0^2 + 2a(x - x0). They hold only when acceleration is constant."},{"id":"phy-2048-2","front":"A ball is dropped from rest. How far does it fall in 2.0 s? (g = 9.8 m/s^2)","back":"d = (1/2)g*t^2 = 0.5 x 9.8 x 4 = 19.6 m."},{"id":"phy-2048-3","front":"How are velocity and acceleration related to position using calculus?","back":"v(t) = dx/dt and a(t) = dv/dt = d^2x/dt^2. Displacement is the integral of velocity over time."},{"id":"phy-2048-4","front":"In projectile motion (no air resistance), what are the horizontal and vertical accelerations?","back":"Horizontal acceleration is zero (constant velocity); vertical acceleration is g = 9.8 m/s^2 downward."},{"id":"phy-2048-5","front":"Range of a projectile launched and landing at the same height","back":"R = v0^2 * sin(2*theta) / g, maximized at theta = 45 degrees."},{"id":"phy-2048-6","front":"Centripetal acceleration for uniform circular motion","back":"a_c = v^2 / r, directed toward the center of the circle."},{"id":"phy-2048-7","front":"State Newton''s three laws.","back":"1: An object keeps its velocity unless a net force acts (inertia). 2: F_net = m*a. 3: For every force, there is an equal and opposite force on the other object."},{"id":"phy-2048-8","front":"Common pitfall: do Newton''s third-law pairs cancel?","back":"No. The two forces act on different objects, so they never cancel in a single object''s free-body diagram."},{"id":"phy-2048-9","front":"Mass vs weight","back":"Mass is the amount of matter (kg), the same everywhere. Weight is the gravitational force W = m*g (newtons), which depends on location."},{"id":"phy-2048-10","front":"Normal force on a block resting on a 30 degree incline","back":"N = m*g*cos(30 degrees), perpendicular to the surface. The component along the incline is m*g*sin(30 degrees)."},{"id":"phy-2048-11","front":"Static vs kinetic friction","back":"Static friction prevents sliding and adjusts up to a maximum mu_s*N. Kinetic friction acts during sliding with magnitude mu_k*N; usually mu_k < mu_s."},{"id":"phy-2048-12","front":"Two blocks (2 kg and 3 kg) are pushed together on a frictionless floor by 10 N. Acceleration?","back":"a = F / total mass = 10 / 5 = 2 m/s^2."},{"id":"phy-2048-13","front":"Definition of work","back":"W = F*d*cos(theta), or the integral of F dot dx. Units: joules. A force perpendicular to motion does no work."},{"id":"phy-2048-14","front":"State the work-energy theorem.","back":"The net work done on an object equals its change in kinetic energy: W_net = (1/2)m*v_f^2 - (1/2)m*v_i^2."},{"id":"phy-2048-15","front":"Potential energy formulas for gravity and a spring","back":"Gravity near Earth: U = m*g*h. Spring: U = (1/2)k*x^2, where x is displacement from equilibrium."},{"id":"phy-2048-16","front":"When is mechanical energy conserved?","back":"When only conservative forces (gravity, spring) do work. Friction is nonconservative and converts mechanical energy into thermal energy."},{"id":"phy-2048-17","front":"A block slides from rest down a frictionless 5.0 m tall ramp. Speed at bottom?","back":"m*g*h = (1/2)m*v^2, so v = sqrt(2gh) = sqrt(2 x 9.8 x 5.0) = about 9.9 m/s."},{"id":"phy-2048-18","front":"Define power.","back":"P = dW/dt, the rate of doing work, in watts (J/s). For constant force, P = F*v."},{"id":"phy-2048-19","front":"Linear momentum and impulse","back":"p = m*v. Impulse J = integral of F dt = change in momentum."},{"id":"phy-2048-20","front":"When is total momentum conserved?","back":"When the net external force on the system is zero. It is conserved in all collisions if external forces are negligible."},{"id":"phy-2048-21","front":"Elastic vs perfectly inelastic collisions","back":"Both conserve momentum. Elastic collisions also conserve kinetic energy; in a perfectly inelastic collision the objects stick together and KE loss is maximal."},{"id":"phy-2048-22","front":"A 1 kg cart at 4 m/s hits and sticks to a stationary 1 kg cart. Final speed?","back":"Momentum conservation: 1 x 4 = 2 x v, so v = 2 m/s."},{"id":"phy-2048-23","front":"Relationship between linear and angular quantities","back":"v = r*omega and a_t = r*alpha, with omega in rad/s and alpha in rad/s^2."},{"id":"phy-2048-24","front":"Define torque.","back":"tau = r*F*sin(theta), the rotational effect of a force about an axis. Net torque = I*alpha, the rotational version of Newton''s second law."},{"id":"phy-2048-25","front":"What is moment of inertia?","back":"Rotational inertia, I = sum of m*r^2; it depends on how mass is distributed relative to the axis. Mass farther from the axis increases I."},{"id":"phy-2048-26","front":"Kinetic energy of a rolling object","back":"KE = (1/2)m*v^2 + (1/2)I*omega^2 (translational plus rotational). For rolling without slipping, v = R*omega."},{"id":"phy-2048-27","front":"Conservation of angular momentum example","back":"L = I*omega is conserved when net external torque is zero. A spinning skater pulls in her arms, lowering I, so omega increases."},{"id":"phy-2048-28","front":"Period of a mass-spring system and a simple pendulum","back":"Mass-spring: T = 2*pi*sqrt(m/k). Simple pendulum (small angles): T = 2*pi*sqrt(L/g), independent of mass."},{"id":"phy-2048-29","front":"Wave speed relationship","back":"v = f*lambda: wave speed equals frequency times wavelength. On a string, v = sqrt(T/mu) with tension T and linear mass density mu."},{"id":"phy-2048-30","front":"State Bernoulli''s equation.","back":"P + (1/2)rho*v^2 + rho*g*h = constant along a streamline for an ideal fluid. Faster flow means lower pressure at the same height."}],"quizzes":[],"seed":1,"look":{"color":"#4F46E5","icon":"phys"}}'::jsonb);   -- https://catalog.ufl.edu/UGRD/courses/physics/
select pg_temp.sb_seed('seed:asu-edu:bio-181', 'asu.edu', 'BIO 181', 'BIO 181 Exam Review: Macromolecules, Cells, Metabolism and Genetics', '{"v":1,"app":"studyboard","type":"deck","name":"BIO 181 Exam Review: Macromolecules, Cells, Metabolism and Genetics","course":{"code":"BIO 181","name":"General Biology I"},"cards":[{"id":"bio-181-1","front":"What are the four major classes of biological macromolecules?","back":"Carbohydrates, lipids, proteins and nucleic acids. All but lipids are true polymers built from repeating monomers."},{"id":"bio-181-2","front":"What type of reaction links monomers into polymers, and what reaction breaks them apart?","back":"Dehydration synthesis (condensation) joins monomers by removing a water molecule; hydrolysis breaks the bond by adding water."},{"id":"bio-181-3","front":"Name the four levels of protein structure.","back":"Primary: amino acid sequence. Secondary: alpha helices and beta sheets from backbone hydrogen bonds. Tertiary: overall 3D fold from R-group interactions. Quaternary: association of multiple polypeptide subunits."},{"id":"bio-181-4","front":"Saturated vs unsaturated fatty acids","back":"Saturated fatty acids have no C=C double bonds and pack tightly (solid at room temperature). Unsaturated fatty acids have one or more cis double bonds that create kinks, keeping them liquid."},{"id":"bio-181-5","front":"Why is water such a good solvent, and what gives it high cohesion?","back":"Water is polar, so it surrounds ions and polar molecules. Hydrogen bonds between water molecules produce cohesion, surface tension and a high specific heat."},{"id":"bio-181-6","front":"Prokaryotic vs eukaryotic cells","back":"Prokaryotes (bacteria, archaea) lack a nucleus and membrane-bound organelles and have 70S ribosomes. Eukaryotes have a nucleus, membrane-bound organelles and 80S cytoplasmic ribosomes."},{"id":"bio-181-7","front":"What does the endosymbiotic theory propose?","back":"Mitochondria and chloroplasts descended from free-living prokaryotes engulfed by an ancestral cell. Evidence: their own circular DNA, double membranes, 70S-like ribosomes and division by binary fission."},{"id":"bio-181-8","front":"Trace the path of a secreted protein through the endomembrane system.","back":"Synthesized by ribosomes on the rough ER, moved in vesicles to the Golgi for modification and sorting, then carried in secretory vesicles to the plasma membrane for exocytosis."},{"id":"bio-181-9","front":"What does the fluid mosaic model describe?","back":"The plasma membrane as a fluid phospholipid bilayer with proteins, cholesterol and carbohydrates embedded or attached that can move laterally."},{"id":"bio-181-10","front":"Diffusion vs facilitated diffusion vs active transport","back":"Diffusion: solutes cross the bilayer down their gradient with no protein. Facilitated diffusion: down the gradient through channel or carrier proteins, no ATP. Active transport: against the gradient using energy, such as ATP."},{"id":"bio-181-11","front":"A red blood cell is placed in a hypotonic solution. What happens?","back":"Water moves into the cell by osmosis because the outside has a lower solute concentration, so the cell swells and may lyse."},{"id":"bio-181-12","front":"What does the sodium-potassium pump do per ATP used?","back":"It pumps 3 Na+ out of the cell and 2 K+ into the cell, maintaining gradients and a negative membrane potential."},{"id":"bio-181-13","front":"How do enzymes speed up reactions?","back":"They lower the activation energy by stabilizing the transition state. They do not change delta G or the equilibrium position, and they are not consumed."},{"id":"bio-181-14","front":"Competitive vs noncompetitive inhibition","back":"A competitive inhibitor binds the active site and can be overcome by more substrate. A noncompetitive inhibitor binds elsewhere (allosteric site), changing the enzyme''s shape, so extra substrate does not overcome it."},{"id":"bio-181-15","front":"Exergonic vs endergonic reactions","back":"Exergonic reactions release free energy (delta G < 0) and are spontaneous. Endergonic reactions require energy (delta G > 0) and are often driven by coupling to ATP hydrolysis."},{"id":"bio-181-16","front":"Overall equation for cellular respiration","back":"C6H12O6 + 6 O2 -> 6 CO2 + 6 H2O + energy (ATP and heat)."},{"id":"bio-181-17","front":"Where do glycolysis, the citric acid cycle and the electron transport chain occur in eukaryotes?","back":"Glycolysis: cytosol. Pyruvate oxidation and the citric acid cycle: mitochondrial matrix. Electron transport chain and ATP synthase: inner mitochondrial membrane."},{"id":"bio-181-18","front":"What is chemiosmosis?","back":"Using energy from electron transport to pump H+ across a membrane, then letting H+ flow back down its gradient through ATP synthase to make ATP."},{"id":"bio-181-19","front":"What is the role of oxygen in aerobic respiration?","back":"Oxygen is the final electron acceptor of the electron transport chain; it combines with electrons and H+ to form water."},{"id":"bio-181-20","front":"What is the purpose of fermentation?","back":"To regenerate NAD+ from NADH so glycolysis can continue making ATP without oxygen. Products include lactate (animals) or ethanol and CO2 (yeast)."},{"id":"bio-181-21","front":"Light reactions vs Calvin cycle","back":"Light reactions (thylakoid membranes) use light to split water, release O2 and make ATP and NADPH. The Calvin cycle (stroma) uses that ATP and NADPH to fix CO2 into sugar via the enzyme rubisco."},{"id":"bio-181-22","front":"List the phases of mitosis in order.","back":"Prophase, prometaphase, metaphase, anaphase, telophase, usually followed by cytokinesis."},{"id":"bio-181-23","front":"Key differences between mitosis and meiosis","back":"Mitosis: one division producing 2 genetically identical diploid cells. Meiosis: two divisions producing 4 genetically different haploid cells, with crossing over and independent assortment."},{"id":"bio-181-24","front":"When does crossing over occur and why does it matter?","back":"During prophase I of meiosis, between homologous chromosomes. It exchanges DNA segments, creating new allele combinations."},{"id":"bio-181-25","front":"Cross Aa x Aa (A dominant). What are the expected genotype and phenotype ratios?","back":"Genotypes 1 AA : 2 Aa : 1 aa. Phenotypes 3 dominant : 1 recessive."},{"id":"bio-181-26","front":"State Mendel''s law of segregation and law of independent assortment.","back":"Segregation: the two alleles of a gene separate into different gametes. Independent assortment: alleles of genes on different chromosomes sort into gametes independently of each other."},{"id":"bio-181-27","front":"Describe the structure of DNA.","back":"A double helix of two antiparallel strands with a sugar-phosphate backbone. Bases pair by hydrogen bonds: A with T (2 bonds) and G with C (3 bonds)."},{"id":"bio-181-28","front":"Why is DNA replication called semiconservative?","back":"Each new double helix contains one original parental strand and one newly synthesized strand, as shown by the Meselson-Stahl experiment."},{"id":"bio-181-29","front":"Leading vs lagging strand in DNA replication","back":"DNA polymerase only adds nucleotides 5'' to 3''. The leading strand is made continuously toward the fork; the lagging strand is made in Okazaki fragments joined by DNA ligase."},{"id":"bio-181-30","front":"State the central dogma and where each step occurs in eukaryotes.","back":"DNA -> RNA -> protein. Transcription occurs in the nucleus; translation occurs at ribosomes in the cytoplasm."},{"id":"bio-181-31","front":"A codon reads 5''-AUG-3''. What does it code for?","back":"Methionine; AUG is also the start codon. The genetic code is read in triplets, and UAA, UAG and UGA are stop codons."}],"quizzes":[],"seed":1,"look":{"color":"#1E9E74","icon":"bio"}}'::jsonb);   -- https://catalog.apps.asu.edu/catalog/courses/courselist?catalogNbr=181&subject=BIO&term=2257
select pg_temp.sb_seed('seed:asu-edu:psy-101', 'asu.edu', 'PSY 101', 'PSY 101 Exam Review: Research Methods, Brain, Learning, Memory and Development', '{"v":1,"app":"studyboard","type":"deck","name":"PSY 101 Exam Review: Research Methods, Brain, Learning, Memory and Development","course":{"code":"PSY 101","name":"Introduction to Psychology"},"cards":[{"id":"psy-101-1","front":"Independent vs dependent variable","back":"The independent variable is what the researcher manipulates; the dependent variable is the outcome that is measured to see if it changed."},{"id":"psy-101-2","front":"Why can''t a correlational study establish causation?","back":"A third variable may cause both, or the direction may be reversed. Only a true experiment with random assignment and manipulation supports causal claims."},{"id":"psy-101-3","front":"Random sampling vs random assignment","back":"Random sampling picks participants from a population so results generalize. Random assignment places participants into conditions by chance so groups are equivalent, allowing causal conclusions."},{"id":"psy-101-4","front":"What does a correlation coefficient of r = -0.85 mean?","back":"A strong negative relationship: as one variable increases the other tends to decrease. The sign shows direction; the absolute value shows strength."},{"id":"psy-101-5","front":"What is a double-blind procedure and why use it?","back":"Neither participants nor the researchers who interact with them know who gets the treatment, reducing placebo effects and experimenter bias."},{"id":"psy-101-6","front":"What are the main parts of a neuron and their roles?","back":"Dendrites receive signals, the cell body (soma) integrates them, the axon carries the action potential, and axon terminals release neurotransmitters into the synapse. Myelin speeds conduction."},{"id":"psy-101-7","front":"What is the all-or-none principle?","back":"A neuron either fires a full-strength action potential when the threshold is reached or does not fire at all; stimulus intensity is coded by firing rate, not spike size."},{"id":"psy-101-8","front":"Match: dopamine, serotonin, acetylcholine","back":"Dopamine: reward, movement (low levels in Parkinson''s). Serotonin: mood, sleep, appetite (targeted by SSRIs). Acetylcholine: muscle contraction, memory (low in Alzheimer''s)."},{"id":"psy-101-9","front":"Sympathetic vs parasympathetic nervous system","back":"Sympathetic: fight or flight (raises heart rate, dilates pupils). Parasympathetic: rest and digest (calms the body and conserves energy)."},{"id":"psy-101-10","front":"Name the four cerebral lobes and a main function of each.","back":"Frontal: planning, decisions, motor control. Parietal: touch and spatial processing. Temporal: hearing and language comprehension. Occipital: vision."},{"id":"psy-101-11","front":"Broca''s area vs Wernicke''s area","back":"Broca''s area (left frontal lobe) supports speech production; damage gives halting speech. Wernicke''s area (left temporal lobe) supports comprehension; damage gives fluent but meaningless speech."},{"id":"psy-101-12","front":"What do the hippocampus and amygdala do?","back":"The hippocampus helps form new explicit memories. The amygdala processes emotions, especially fear."},{"id":"psy-101-13","front":"Sensation vs perception","back":"Sensation is detection of physical energy by sensory receptors; perception is the brain''s organization and interpretation of that input."},{"id":"psy-101-14","front":"What is an absolute threshold vs a difference threshold?","back":"Absolute threshold: the minimum stimulus detected 50 percent of the time. Difference threshold (JND): the smallest detectable change; by Weber''s law it is a constant proportion of the original stimulus."},{"id":"psy-101-15","front":"In Pavlov''s experiment, identify the US, UR, CS and CR.","back":"US: food. UR: salivation to food. CS: the tone, originally neutral, after pairing. CR: salivation to the tone alone."},{"id":"psy-101-16","front":"Extinction vs spontaneous recovery in classical conditioning","back":"Extinction: the CR weakens when the CS is repeatedly presented without the US. Spontaneous recovery: the extinguished CR reappears after a rest period."},{"id":"psy-101-17","front":"Positive vs negative reinforcement","back":"Both increase a behavior. Positive reinforcement adds a pleasant stimulus; negative reinforcement removes an unpleasant one (e.g., taking aspirin removes a headache)."},{"id":"psy-101-18","front":"Negative reinforcement vs punishment","back":"Negative reinforcement increases behavior by removing something aversive. Punishment decreases behavior, by adding something aversive (positive) or removing something pleasant (negative)."},{"id":"psy-101-19","front":"Which reinforcement schedule is most resistant to extinction?","back":"Variable-ratio schedules, where reinforcement comes after an unpredictable number of responses (as with slot machines)."},{"id":"psy-101-20","front":"What did Bandura''s Bobo doll study show?","back":"Children who watched an adult act aggressively toward a doll imitated that aggression, demonstrating observational learning."},{"id":"psy-101-21","front":"Describe the three stages of the Atkinson-Shiffrin memory model.","back":"Sensory memory (very brief), short-term or working memory (about 7 plus or minus 2 items, lasting seconds without rehearsal), and long-term memory (relatively permanent, large capacity)."},{"id":"psy-101-22","front":"Explicit vs implicit memory","back":"Explicit (declarative) memory is conscious recall of facts (semantic) and events (episodic). Implicit memory is unconscious, such as procedural skills and priming."},{"id":"psy-101-23","front":"Proactive vs retroactive interference","back":"Proactive: old learning disrupts recall of new information. Retroactive: new learning disrupts recall of old information."},{"id":"psy-101-24","front":"What is the serial position effect?","back":"Items at the beginning (primacy) and end (recency) of a list are recalled better than items in the middle."},{"id":"psy-101-25","front":"List Piaget''s four stages of cognitive development.","back":"Sensorimotor (0-2, object permanence), preoperational (2-7, egocentrism), concrete operational (7-11, conservation), formal operational (12+, abstract reasoning)."},{"id":"psy-101-26","front":"What did Harlow''s monkey studies show about attachment?","back":"Infant monkeys preferred a soft cloth mother over a wire mother that provided food, showing contact comfort matters more than feeding for attachment."},{"id":"psy-101-27","front":"What is the fundamental attribution error?","back":"The tendency to overemphasize personality traits and underestimate situational factors when explaining other people''s behavior."},{"id":"psy-101-28","front":"What did Milgram''s obedience study find?","back":"About two-thirds of participants obeyed an authority figure to deliver what they believed were maximum-voltage shocks, showing strong situational pressure to obey."},{"id":"psy-101-29","front":"What are the Big Five personality traits?","back":"Openness, conscientiousness, extraversion, agreeableness and neuroticism (OCEAN)."},{"id":"psy-101-30","front":"What is cognitive dissonance and how do people reduce it?","back":"When beliefs and actions conflict, people feel tension (dissonance) and reduce it by changing a belief, changing the behavior, or adding justifications."}],"quizzes":[],"seed":1,"look":{"color":"#9A4FD1","icon":"psych"}}'::jsonb);   -- https://catalog.apps.asu.edu/catalog/courses/courselist?catalogNbr=101&subject=PSY&term=2257
select pg_temp.sb_seed('seed:asu-edu:ecn-211', 'asu.edu', 'ECN 211', 'ECN 211 Exam Review: GDP, Inflation, Unemployment, Money and Policy', '{"v":1,"app":"studyboard","type":"deck","name":"ECN 211 Exam Review: GDP, Inflation, Unemployment, Money and Policy","course":{"code":"ECN 211","name":"Macroeconomic Principles"},"cards":[{"id":"ecn-211-1","front":"Define GDP.","back":"Gross domestic product is the market value of all final goods and services produced within a country in a given period."},{"id":"ecn-211-2","front":"Write the expenditure approach to GDP and define each term.","back":"Y = C + I + G + NX. C: consumption, I: business investment (including new housing and inventories), G: government purchases, NX: exports minus imports."},{"id":"ecn-211-3","front":"Why are intermediate goods excluded from GDP?","back":"Their value is already included in the price of the final good, so counting them would double count."},{"id":"ecn-211-4","front":"Are transfer payments like Social Security counted in G?","back":"No. Transfer payments are not purchases of goods or services, so they are excluded from government purchases in GDP."},{"id":"ecn-211-5","front":"Nominal vs real GDP","back":"Nominal GDP uses current prices. Real GDP uses constant base-year prices, so it changes only when output changes."},{"id":"ecn-211-6","front":"How is the GDP deflator calculated?","back":"GDP deflator = (nominal GDP / real GDP) x 100."},{"id":"ecn-211-7","front":"Nominal GDP is $1,200 billion and real GDP is $1,000 billion. What is the deflator?","back":"(1200 / 1000) x 100 = 120, meaning prices are 20 percent higher than in the base year."},{"id":"ecn-211-8","front":"How is the inflation rate computed from the CPI?","back":"Inflation rate = (CPI this year - CPI last year) / CPI last year x 100."},{"id":"ecn-211-9","front":"Name two biases that cause the CPI to overstate inflation.","back":"Substitution bias (consumers switch to cheaper goods), introduction of new goods, and unmeasured quality improvements."},{"id":"ecn-211-10","front":"Real interest rate formula (Fisher equation)","back":"Real interest rate is approximately the nominal interest rate minus the inflation rate."},{"id":"ecn-211-11","front":"How is the unemployment rate calculated?","back":"Unemployment rate = unemployed / labor force x 100, where the labor force = employed + unemployed people actively seeking work."},{"id":"ecn-211-12","front":"Frictional vs structural vs cyclical unemployment","back":"Frictional: short-term job searching. Structural: mismatch of skills or location with available jobs. Cyclical: caused by recessions. The natural rate includes frictional and structural only."},{"id":"ecn-211-13","front":"Why are discouraged workers a problem for the unemployment rate?","back":"They want work but stopped searching, so they are not counted in the labor force, making the official rate understate joblessness."},{"id":"ecn-211-14","front":"What are the three functions of money?","back":"Medium of exchange, unit of account and store of value."},{"id":"ecn-211-15","front":"M1 vs M2","back":"M1: currency in circulation, checkable deposits and other liquid deposits. M2: M1 plus less liquid assets such as small time deposits and retail money market funds."},{"id":"ecn-211-16","front":"What is the simple money multiplier?","back":"Money multiplier = 1 / reserve requirement. With a 10 percent ratio, the multiplier is 10."},{"id":"ecn-211-17","front":"Name the Federal Reserve''s main tools for conducting monetary policy today.","back":"Interest on reserve balances, open market operations (buying or selling government securities), the discount rate, and overnight reverse repurchase agreements."},{"id":"ecn-211-18","front":"What is expansionary monetary policy and its expected effect?","back":"The Fed lowers its interest rate target or buys securities, lowering interest rates, which boosts investment and spending, raising output in the short run."},{"id":"ecn-211-19","front":"What is fiscal policy?","back":"Government changes to spending and taxes to influence aggregate demand. Expansionary: raise spending or cut taxes. Contractionary: cut spending or raise taxes."},{"id":"ecn-211-20","front":"Spending multiplier formula","back":"Multiplier = 1 / (1 - MPC) = 1 / MPS. With MPC = 0.8, the multiplier is 5."},{"id":"ecn-211-21","front":"Why is the tax multiplier smaller than the spending multiplier?","back":"A tax cut is partly saved before it is spent, so the first-round change in spending is MPC times the tax change. Tax multiplier = -MPC / (1 - MPC)."},{"id":"ecn-211-22","front":"What is crowding out?","back":"Government borrowing raises interest rates, which reduces private investment and offsets part of the fiscal stimulus."},{"id":"ecn-211-23","front":"Budget deficit vs national debt","back":"A deficit is the shortfall in a single year (spending exceeds revenue). The debt is the accumulated total of past deficits minus surpluses."},{"id":"ecn-211-24","front":"What shifts aggregate demand to the right?","back":"Increases in consumption, investment, government purchases or net exports, for example from higher wealth, lower interest rates or more optimism."},{"id":"ecn-211-25","front":"Short-run vs long-run aggregate supply","back":"SRAS slopes upward because some prices and wages are sticky. LRAS is vertical at potential output, determined by labor, capital, resources and technology."},{"id":"ecn-211-26","front":"What is stagflation and what causes it?","back":"Rising inflation together with falling output and higher unemployment, typically caused by a negative supply shock that shifts SRAS left (such as an oil price spike)."},{"id":"ecn-211-27","front":"What is the Phillips curve?","back":"A short-run inverse relationship between inflation and unemployment. In the long run it is vertical at the natural rate of unemployment."},{"id":"ecn-211-28","front":"What are automatic stabilizers?","back":"Taxes and transfers that change with the economy without new legislation, such as unemployment benefits and progressive income taxes, cushioning recessions and booms."},{"id":"ecn-211-29","front":"What drives long-run economic growth across countries?","back":"Growth in productivity: physical capital, human capital, natural resources and technological knowledge, supported by institutions such as property rights and rule of law."},{"id":"ecn-211-30","front":"What is the rule of 70?","back":"Years for a variable to double is approximately 70 divided by its annual growth rate in percent. At 2 percent growth, about 35 years."}],"quizzes":[],"seed":1,"look":{"color":"#C79A12","icon":"econ"}}'::jsonb);   -- https://catalog.apps.asu.edu/catalog/courses/courselist?catalogNbr=211&subject=ECN&term=2257
select pg_temp.sb_seed('seed:tamu-edu:chem-119', 'tamu.edu', 'CHEM 119', 'CHEM 119 Exam Review: Atomic Structure, Bonding, Stoichiometry and Equilibrium', '{"v":1,"app":"studyboard","type":"deck","name":"CHEM 119 Exam Review: Atomic Structure, Bonding, Stoichiometry and Equilibrium","course":{"code":"CHEM 119","name":"Fundamentals of Chemistry I"},"cards":[{"id":"chem-119-1","front":"What do the atomic number and mass number represent?","back":"Atomic number (Z) is the number of protons. Mass number (A) is protons plus neutrons."},{"id":"chem-119-2","front":"Isotopes vs ions","back":"Isotopes have the same number of protons but different numbers of neutrons. Ions have gained or lost electrons and carry a net charge."},{"id":"chem-119-3","front":"Relationship between wavelength, frequency and energy of light","back":"c = lambda x nu and E = h x nu, where c is the speed of light, lambda the wavelength, nu the frequency, and h Planck''s constant. Shorter wavelength means higher energy."},{"id":"chem-119-4","front":"List the four quantum numbers and what each describes.","back":"n: energy level and size. l: subshell shape (0 = s, 1 = p, 2 = d, 3 = f). ml: orbital orientation (-l to +l). ms: electron spin (+1/2 or -1/2)."},{"id":"chem-119-5","front":"State the Pauli exclusion principle and Hund''s rule.","back":"Pauli: no two electrons in an atom share all four quantum numbers, so an orbital holds at most 2 electrons of opposite spin. Hund: electrons fill degenerate orbitals singly with parallel spins before pairing."},{"id":"chem-119-6","front":"Write the ground-state electron configuration of oxygen.","back":"1s2 2s2 2p4."},{"id":"chem-119-7","front":"How do atomic radius and first ionization energy trend on the periodic table?","back":"Atomic radius decreases across a period and increases down a group. Ionization energy increases across a period and decreases down a group."},{"id":"chem-119-8","front":"Why does atomic radius decrease across a period?","back":"Effective nuclear charge increases as protons are added while electrons enter the same shell, so electrons are pulled closer."},{"id":"chem-119-9","front":"Ionic vs covalent bonds","back":"Ionic bonds form from electrostatic attraction between ions after electron transfer (usually metal plus nonmetal). Covalent bonds share electron pairs between nonmetals."},{"id":"chem-119-10","front":"How do you calculate formal charge?","back":"Formal charge = valence electrons - nonbonding electrons - (bonding electrons / 2). The best Lewis structure minimizes formal charges."},{"id":"chem-119-11","front":"Give the VSEPR geometry for 4 electron domains with 0, 1 and 2 lone pairs.","back":"0 lone pairs: tetrahedral (CH4, 109.5 degrees). 1 lone pair: trigonal pyramidal (NH3). 2 lone pairs: bent (H2O)."},{"id":"chem-119-12","front":"Why is CO2 nonpolar even though C=O bonds are polar?","back":"CO2 is linear, so the two equal bond dipoles point in opposite directions and cancel."},{"id":"chem-119-13","front":"What hybridization goes with 2, 3 and 4 electron domains?","back":"2 domains: sp (linear). 3 domains: sp2 (trigonal planar). 4 domains: sp3 (tetrahedral)."},{"id":"chem-119-14","front":"Sigma vs pi bonds","back":"A sigma bond results from head-on orbital overlap; every single bond is one sigma. A pi bond results from side-by-side p-orbital overlap; a double bond is 1 sigma + 1 pi, a triple bond is 1 sigma + 2 pi."},{"id":"chem-119-15","front":"How many moles are in 36.0 g of water (molar mass 18.0 g/mol)?","back":"36.0 g / 18.0 g/mol = 2.00 mol."},{"id":"chem-119-16","front":"What is a limiting reactant?","back":"The reactant that is completely used up first, which determines the maximum amount of product that can form."},{"id":"chem-119-17","front":"How is percent yield calculated?","back":"Percent yield = (actual yield / theoretical yield) x 100."},{"id":"chem-119-18","front":"Define molarity and give a dilution formula.","back":"Molarity M = moles of solute / liters of solution. Dilution: M1V1 = M2V2."},{"id":"chem-119-19","front":"How much 6.0 M HCl is needed to make 500 mL of 1.5 M HCl?","back":"V1 = (1.5 M x 500 mL) / 6.0 M = 125 mL, diluted to 500 mL."},{"id":"chem-119-20","front":"Ideal gas law and the meaning of each symbol","back":"PV = nRT. P: pressure, V: volume, n: moles, R: gas constant (0.08206 L atm / mol K), T: temperature in kelvin."},{"id":"chem-119-21","front":"State Dalton''s law of partial pressures.","back":"The total pressure of a gas mixture equals the sum of the partial pressures of each gas; each partial pressure = mole fraction x total pressure."},{"id":"chem-119-22","front":"Rank the intermolecular forces from weakest to strongest (typical).","back":"London dispersion < dipole-dipole < hydrogen bonding. Ion-dipole forces are stronger still and occur in ionic solutions."},{"id":"chem-119-23","front":"What is required for hydrogen bonding?","back":"An H atom covalently bonded to N, O or F, attracted to a lone pair on another N, O or F."},{"id":"chem-119-24","front":"Write the equilibrium constant expression for aA + bB <-> cC + dD.","back":"K = [C]^c [D]^d / ([A]^a [B]^b). Pure solids and liquids are omitted."},{"id":"chem-119-25","front":"Q vs K: how do you predict the direction of a reaction?","back":"If Q < K the reaction shifts forward toward products. If Q > K it shifts toward reactants. If Q = K it is at equilibrium."},{"id":"chem-119-26","front":"State Le Chatelier''s principle with an example.","back":"A system at equilibrium shifts to counteract a disturbance. Adding a reactant shifts the equilibrium toward products."},{"id":"chem-119-27","front":"Bronsted-Lowry acid vs base","back":"An acid is a proton (H+) donor; a base is a proton acceptor. Removing H+ from an acid gives its conjugate base."},{"id":"chem-119-28","front":"What is the pH of a 0.010 M HCl solution?","back":"HCl is a strong acid, so [H+] = 0.010 M and pH = -log(0.010) = 2.00."},{"id":"chem-119-29","front":"Relationship between pH, pOH and Kw at 25 C","back":"Kw = [H+][OH-] = 1.0 x 10^-14, so pH + pOH = 14.00."},{"id":"chem-119-30","front":"Strong vs weak acids","back":"Strong acids (HCl, HBr, HI, HNO3, H2SO4, HClO4) ionize completely in water. Weak acids ionize only partially and are described by Ka."}],"quizzes":[],"seed":1,"look":{"color":"#E0673B","icon":"chem"}}'::jsonb);   -- https://catalog.tamu.edu/undergraduate/course-descriptions/chem/
select pg_temp.sb_seed('seed:tamu-edu:math-151', 'tamu.edu', 'MATH 151', 'MATH 151 Exam Review: Vectors, Limits, Derivatives and Integration', '{"v":1,"app":"studyboard","type":"deck","name":"MATH 151 Exam Review: Vectors, Limits, Derivatives and Integration","course":{"code":"MATH 151","name":"Engineering Mathematics I"},"cards":[{"id":"math-151-1","front":"Dot product of a = <a1, a2> and b = <b1, b2>, and its geometric meaning","back":"a . b = a1*b1 + a2*b2 = |a| |b| cos(theta), where theta is the angle between them. A dot product of 0 means the vectors are orthogonal."},{"id":"math-151-2","front":"Find the angle between <1, 0> and <1, 1>.","back":"cos(theta) = 1 / (1 * sqrt(2)), so theta = pi/4 (45 degrees)."},{"id":"math-151-3","front":"Formula for the scalar projection of b onto a","back":"comp_a b = (a . b) / |a|. The vector projection is ((a . b) / |a|^2) a."},{"id":"math-151-4","front":"Parametric equation of the line through point P0 in direction v","back":"r(t) = P0 + t*v, i.e. x = x0 + t*v1, y = y0 + t*v2."},{"id":"math-151-5","front":"What does lim x->a f(x) = L mean informally?","back":"f(x) gets arbitrarily close to L as x gets close to a (from both sides), regardless of the value of f at a."},{"id":"math-151-6","front":"Evaluate lim x->3 (x^2 - 9)/(x - 3).","back":"Factor: (x - 3)(x + 3)/(x - 3) = x + 3, so the limit is 6."},{"id":"math-151-7","front":"What are the two key special limits involving sin x?","back":"lim x->0 sin(x)/x = 1 and lim x->0 (1 - cos x)/x = 0."},{"id":"math-151-8","front":"Three conditions for f to be continuous at x = a","back":"f(a) is defined, lim x->a f(x) exists, and the limit equals f(a)."},{"id":"math-151-9","front":"State the Intermediate Value Theorem.","back":"If f is continuous on [a, b] and N is between f(a) and f(b), then there is some c in (a, b) with f(c) = N."},{"id":"math-151-10","front":"Limit definition of the derivative","back":"f''(x) = lim h->0 [f(x + h) - f(x)] / h, the slope of the tangent line at x."},{"id":"math-151-11","front":"How do you find horizontal asymptotes of a rational function?","back":"Compare degrees: if the numerator degree is lower, y = 0; if equal, y = ratio of leading coefficients; if higher, there is no horizontal asymptote."},{"id":"math-151-12","front":"Power rule, product rule and quotient rule","back":"d/dx [x^n] = n*x^(n-1). (fg)'' = f''g + fg''. (f/g)'' = (f''g - fg'') / g^2."},{"id":"math-151-13","front":"State the chain rule and differentiate sin(3x^2).","back":"d/dx f(g(x)) = f''(g(x)) * g''(x). So d/dx sin(3x^2) = cos(3x^2) * 6x."},{"id":"math-151-14","front":"Derivatives of sin x, cos x, tan x, e^x and ln x","back":"cos x, -sin x, sec^2 x, e^x, and 1/x."},{"id":"math-151-15","front":"Find dy/dx if x^2 + y^2 = 25.","back":"Implicit differentiation: 2x + 2y dy/dx = 0, so dy/dx = -x/y."},{"id":"math-151-16","front":"Velocity and acceleration from a position function s(t)","back":"Velocity v(t) = s''(t); acceleration a(t) = v''(t) = s''''(t). For a vector function r(t), speed is |r''(t)|."},{"id":"math-151-17","front":"Equation of the tangent line to y = f(x) at x = a","back":"y = f(a) + f''(a)(x - a)."},{"id":"math-151-18","front":"Approximate sqrt(4.1) using linearization.","back":"With f(x) = sqrt(x) at a = 4: L(x) = 2 + (1/4)(x - 4), so sqrt(4.1) is approximately 2 + 0.025 = 2.025."},{"id":"math-151-19","front":"General strategy for related rates problems","back":"Draw and label, write an equation relating the variables, differentiate both sides with respect to t, then substitute known values only after differentiating."},{"id":"math-151-20","front":"How do you find absolute extrema of a continuous f on [a, b]?","back":"Evaluate f at critical points (where f'' = 0 or is undefined) inside the interval and at the endpoints; the largest and smallest values are the absolute max and min."},{"id":"math-151-21","front":"First vs second derivative test","back":"First: a critical point is a max if f'' changes + to -, a min if - to +. Second: if f''(c) = 0 and f''''(c) > 0 it is a local min; if f''''(c) < 0 a local max; f''''(c) = 0 is inconclusive."},{"id":"math-151-22","front":"State the Mean Value Theorem.","back":"If f is continuous on [a, b] and differentiable on (a, b), there exists c in (a, b) with f''(c) = [f(b) - f(a)] / (b - a)."},{"id":"math-151-23","front":"When can you use L''Hopital''s rule?","back":"For limits of the indeterminate form 0/0 or infinity/infinity: lim f/g = lim f''/g'', provided the new limit exists."},{"id":"math-151-24","front":"What does an inflection point mean?","back":"A point where f is continuous and concavity changes (f'''' changes sign)."},{"id":"math-151-25","front":"Antiderivative of x^n (n not -1) and of 1/x","back":"Integral of x^n dx = x^(n+1)/(n+1) + C. Integral of 1/x dx = ln|x| + C."},{"id":"math-151-26","front":"State the Fundamental Theorem of Calculus (both parts).","back":"Part 1: if F(x) = integral from a to x of f(t) dt, then F''(x) = f(x). Part 2: integral from a to b of f(x) dx = F(b) - F(a), where F is any antiderivative of f."},{"id":"math-151-27","front":"Evaluate the integral from 0 to 2 of 3x^2 dx.","back":"Antiderivative x^3, so 2^3 - 0^3 = 8."},{"id":"math-151-28","front":"Integrate 2x*cos(x^2) dx using substitution.","back":"Let u = x^2, du = 2x dx, so the integral is sin(u) + C = sin(x^2) + C."},{"id":"math-151-29","front":"What does a Riemann sum approximate?","back":"The definite integral: the sum of f(x_i*) * delta x over n subintervals approximates the net signed area under f, becoming exact as n -> infinity."},{"id":"math-151-30","front":"Common pitfall: is d/dx [e^(2x)] equal to e^(2x)?","back":"No. By the chain rule it is 2*e^(2x)."}],"quizzes":[],"seed":1,"look":{"color":"#3B6FE0","icon":"calc"}}'::jsonb);   -- https://catalog.tamu.edu/undergraduate/course-descriptions/math/
select pg_temp.sb_seed('seed:tamu-edu:econ-202', 'tamu.edu', 'ECON 202', 'ECON 202 Exam Review: Supply and Demand, Elasticity, Costs and Market Structures', '{"v":1,"app":"studyboard","type":"deck","name":"ECON 202 Exam Review: Supply and Demand, Elasticity, Costs and Market Structures","course":{"code":"ECON 202","name":"Principles of Economics"},"cards":[{"id":"econ-202-1","front":"Define opportunity cost.","back":"The value of the next best alternative given up when making a choice."},{"id":"econ-202-2","front":"What does a production possibilities frontier show?","back":"The maximum combinations of two goods an economy can produce with its resources and technology. Points inside are inefficient; points outside are unattainable; a bowed-out shape reflects increasing opportunity cost."},{"id":"econ-202-3","front":"Absolute vs comparative advantage","back":"Absolute advantage: producing more with the same resources. Comparative advantage: producing at a lower opportunity cost. Gains from trade come from comparative advantage."},{"id":"econ-202-4","front":"Change in quantity demanded vs change in demand","back":"A change in the good''s own price moves along the demand curve (quantity demanded). Changes in income, tastes, related prices, expectations or number of buyers shift the whole curve (demand)."},{"id":"econ-202-5","front":"Normal vs inferior goods","back":"Demand for a normal good rises when income rises; demand for an inferior good falls when income rises."},{"id":"econ-202-6","front":"Substitutes vs complements","back":"If the price of a substitute rises, demand for the good increases. If the price of a complement rises, demand for the good decreases."},{"id":"econ-202-7","front":"Supply increases and demand stays the same. What happens to equilibrium price and quantity?","back":"Price falls and quantity rises."},{"id":"econ-202-8","front":"What is consumer surplus and producer surplus?","back":"Consumer surplus: buyers'' willingness to pay minus the price paid (area below demand, above price). Producer surplus: price received minus sellers'' cost (area above supply, below price)."},{"id":"econ-202-9","front":"Effect of a binding price ceiling","back":"Set below equilibrium, it causes a shortage (quantity demanded > quantity supplied) and deadweight loss. Example: rent control."},{"id":"econ-202-10","front":"Effect of a binding price floor","back":"Set above equilibrium, it causes a surplus (quantity supplied > quantity demanded). Example: a minimum wage above the market wage can create unemployment."},{"id":"econ-202-11","front":"Price elasticity of demand formula (midpoint method)","back":"Ed = (% change in Qd) / (% change in P), using percentage changes computed from the average of the starting and ending values. |Ed| > 1 elastic, < 1 inelastic, = 1 unit elastic."},{"id":"econ-202-12","front":"If demand is inelastic and price rises, what happens to total revenue?","back":"Total revenue increases, because quantity falls by a smaller percentage than price rises."},{"id":"econ-202-13","front":"What determines price elasticity of demand?","back":"Availability of substitutes, whether the good is a necessity or luxury, share of budget, how narrowly the market is defined, and time horizon (more elastic in the long run)."},{"id":"econ-202-14","front":"Who bears more of the burden of a tax?","back":"The side of the market that is less elastic (less able to adjust) bears more of the tax, regardless of who legally pays it."},{"id":"econ-202-15","front":"What is deadweight loss?","back":"The loss of total surplus from transactions that no longer occur because of a market distortion such as a tax, price control or monopoly."},{"id":"econ-202-16","front":"State the law of diminishing marginal returns.","back":"As more of a variable input is added to a fixed input, the additional output from each extra unit eventually decreases."},{"id":"econ-202-17","front":"Fixed vs variable costs","back":"Fixed costs do not change with output in the short run (rent). Variable costs change with output (materials, hourly labor). Total cost = FC + VC."},{"id":"econ-202-18","front":"How are marginal cost and average total cost related?","back":"MC crosses ATC at the minimum of ATC. When MC < ATC, ATC is falling; when MC > ATC, ATC is rising."},{"id":"econ-202-19","front":"Profit-maximizing rule for any firm","back":"Produce the quantity where marginal revenue equals marginal cost (MR = MC)."},{"id":"econ-202-20","front":"When should a perfectly competitive firm shut down in the short run?","back":"When price falls below minimum average variable cost (P < AVC)."},{"id":"econ-202-21","front":"Long-run outcome in perfect competition","back":"Free entry and exit drive economic profit to zero; firms produce at minimum ATC and P = MC = min ATC."},{"id":"econ-202-22","front":"Accounting profit vs economic profit","back":"Accounting profit = revenue - explicit costs. Economic profit = revenue - explicit costs - implicit costs (opportunity costs). Zero economic profit means a normal return."},{"id":"econ-202-23","front":"How does a monopoly differ from perfect competition in price and output?","back":"A monopolist faces downward-sloping demand, so MR < P; it sets MR = MC, producing less and charging more than a competitive market, creating deadweight loss."},{"id":"econ-202-24","front":"Key features of monopolistic competition","back":"Many firms, differentiated products, free entry. Firms have some price-setting power in the short run, but in the long run economic profit tends to zero."},{"id":"econ-202-25","front":"What is an oligopoly and why is game theory useful for it?","back":"A market with a few interdependent firms. Each firm''s best choice depends on rivals'' choices, which game theory models."},{"id":"econ-202-26","front":"Explain the prisoners'' dilemma.","back":"Each player has a dominant strategy to defect, so both defect, even though both would be better off if both cooperated. This explains why cartels are unstable."},{"id":"econ-202-27","front":"What is a Nash equilibrium?","back":"A set of strategies where no player can improve their payoff by changing strategy alone, given the others'' strategies."},{"id":"econ-202-28","front":"Negative externality and its market outcome","back":"A cost imposed on third parties (pollution). The market overproduces because private cost is below social cost. A corrective (Pigouvian) tax can fix it."},{"id":"econ-202-29","front":"Public goods: what two properties define them?","back":"Non-rival (one person''s use does not reduce another''s) and non-excludable (people cannot easily be prevented from using it), leading to the free-rider problem."},{"id":"econ-202-30","front":"What is a government failure?","back":"When a policy intervention reduces efficiency or creates new problems, for example from poor information, special-interest lobbying or unintended consequences."}],"quizzes":[],"seed":1,"look":{"color":"#0D9488","icon":"econ"}}'::jsonb);   -- https://catalog.tamu.edu/undergraduate/course-descriptions/econ/
select pg_temp.sb_seed('seed:ucf-edu:sta-2023', 'ucf.edu', 'STA 2023', 'STA 2023 Exam Review: Descriptive Stats, Probability, Sampling and Inference', '{"v":1,"app":"studyboard","type":"deck","name":"STA 2023 Exam Review: Descriptive Stats, Probability, Sampling and Inference","course":{"code":"STA 2023","name":"Statistical Methods I"},"cards":[{"id":"sta-2023-1","front":"Population vs sample; parameter vs statistic","back":"A population is the entire group of interest; a sample is a subset. A parameter describes a population (mu, sigma, p); a statistic describes a sample (x-bar, s, p-hat)."},{"id":"sta-2023-2","front":"Categorical vs quantitative variables","back":"Categorical variables place individuals into groups (eye color). Quantitative variables take numerical values where arithmetic makes sense (height)."},{"id":"sta-2023-3","front":"Mean vs median in a right-skewed distribution","back":"The mean is pulled toward the long right tail, so mean > median. The median is resistant to outliers."},{"id":"sta-2023-4","front":"How is the 1.5 x IQR rule used to flag outliers?","back":"IQR = Q3 - Q1. Values below Q1 - 1.5*IQR or above Q3 + 1.5*IQR are potential outliers."},{"id":"sta-2023-5","front":"What does the standard deviation measure?","back":"The typical distance of observations from the mean. It is the square root of the variance and is never negative."},{"id":"sta-2023-6","front":"State the empirical (68-95-99.7) rule.","back":"For a roughly normal distribution, about 68 percent of values fall within 1 SD of the mean, 95 percent within 2 SD and 99.7 percent within 3 SD."},{"id":"sta-2023-7","front":"Compute the z-score for x = 85 when mu = 70 and sigma = 10.","back":"z = (x - mu) / sigma = (85 - 70) / 10 = 1.5, so 85 is 1.5 SD above the mean."},{"id":"sta-2023-8","front":"Properties of the correlation coefficient r","back":"r ranges from -1 to 1, measures the strength and direction of a linear relationship, has no units, and is sensitive to outliers. Correlation does not imply causation."},{"id":"sta-2023-9","front":"Interpret the slope in y-hat = 20 + 3x.","back":"For each one-unit increase in x, the predicted y increases by 3 units on average."},{"id":"sta-2023-10","front":"What is a residual?","back":"Residual = observed y - predicted y-hat. The least-squares line minimizes the sum of squared residuals."},{"id":"sta-2023-11","front":"What does r^2 tell you?","back":"The proportion of variation in y explained by the linear relationship with x."},{"id":"sta-2023-12","front":"Observational study vs experiment","back":"In an observational study researchers measure without intervening. In an experiment they impose treatments, and with random assignment it can show cause and effect."},{"id":"sta-2023-13","front":"Name four probability sampling methods.","back":"Simple random sample, stratified sample (random within groups), cluster sample (randomly choose whole groups) and systematic sample (every kth individual)."},{"id":"sta-2023-14","front":"What is the complement rule and the addition rule?","back":"P(not A) = 1 - P(A). P(A or B) = P(A) + P(B) - P(A and B)."},{"id":"sta-2023-15","front":"When are events A and B independent?","back":"When P(A and B) = P(A) * P(B), equivalently P(A | B) = P(A). Knowing one occurred does not change the probability of the other."},{"id":"sta-2023-16","front":"Mutually exclusive vs independent","back":"Mutually exclusive events cannot both occur (P(A and B) = 0). Two events with positive probability that are mutually exclusive are never independent."},{"id":"sta-2023-17","front":"Conditional probability formula","back":"P(A | B) = P(A and B) / P(B)."},{"id":"sta-2023-18","front":"Conditions for a binomial setting and its mean and SD","back":"Fixed n trials, two outcomes, independent trials, constant p. Mean = n*p; SD = sqrt(n*p*(1 - p))."},{"id":"sta-2023-19","front":"State the Central Limit Theorem.","back":"For large n (often n >= 30), the sampling distribution of x-bar is approximately normal with mean mu and standard error sigma/sqrt(n), regardless of the population shape."},{"id":"sta-2023-20","front":"What happens to the standard error when sample size quadruples?","back":"It is cut in half, since SE = sigma / sqrt(n)."},{"id":"sta-2023-21","front":"Correct interpretation of a 95 percent confidence interval","back":"We are 95 percent confident the interval captures the true parameter; in repeated sampling, about 95 percent of such intervals would contain it."},{"id":"sta-2023-22","front":"How do confidence level and sample size affect margin of error?","back":"Higher confidence gives a wider margin of error. Larger sample size gives a smaller margin of error."},{"id":"sta-2023-23","front":"Formula for a confidence interval for a population proportion","back":"p-hat +/- z* x sqrt(p-hat(1 - p-hat)/n). For 95 percent confidence, z* = 1.96."},{"id":"sta-2023-24","front":"When do you use a t distribution instead of z for a mean?","back":"When the population standard deviation is unknown and estimated with s; degrees of freedom = n - 1."},{"id":"sta-2023-25","front":"Null vs alternative hypothesis","back":"H0 is the claim of no effect or no difference (e.g., mu = 50). Ha is what you seek evidence for (mu > 50, mu < 50, or mu not equal to 50)."},{"id":"sta-2023-26","front":"What is a p-value?","back":"The probability, assuming H0 is true, of getting a result at least as extreme as the one observed. Small p-values are evidence against H0."},{"id":"sta-2023-27","front":"Decision rule with significance level alpha = 0.05","back":"If p-value <= 0.05, reject H0. If p-value > 0.05, fail to reject H0 (never say ''accept H0'')."},{"id":"sta-2023-28","front":"Type I vs Type II error","back":"Type I: rejecting a true H0 (probability alpha). Type II: failing to reject a false H0 (probability beta). Power = 1 - beta."},{"id":"sta-2023-29","front":"Test statistic for a one-sample z test for a proportion","back":"z = (p-hat - p0) / sqrt(p0(1 - p0)/n), where p0 is the value in the null hypothesis."},{"id":"sta-2023-30","front":"Common pitfall: does a p-value of 0.03 mean a 3 percent chance H0 is true?","back":"No. It means a 3 percent chance of data this extreme if H0 were true; it is not the probability that H0 is true."}],"quizzes":[],"seed":1,"look":{"color":"#1D9BB8","icon":"stats"}}'::jsonb);   -- https://www.ucf.edu/catalog/undergraduate/#/courses/view/673622ff7d58719926cb04ab
select pg_temp.sb_seed('seed:ucf-edu:acg-2021', 'ucf.edu', 'ACG 2021', 'ACG 2021 Exam Review: Accounting Cycle, Financial Statements, Assets and Liabilities', '{"v":1,"app":"studyboard","type":"deck","name":"ACG 2021 Exam Review: Accounting Cycle, Financial Statements, Assets and Liabilities","course":{"code":"ACG 2021","name":"Principles of Financial Accounting"},"cards":[{"id":"acg-2021-1","front":"State the basic accounting equation.","back":"Assets = Liabilities + Equity. Every transaction keeps this equation in balance."},{"id":"acg-2021-2","front":"Expanded accounting equation for a corporation","back":"Assets = Liabilities + Common Stock + Retained Earnings, where retained earnings increase with revenues and decrease with expenses and dividends."},{"id":"acg-2021-3","front":"Normal balances: which accounts increase with a debit?","back":"Debits increase assets, expenses and dividends. Credits increase liabilities, equity (stock and retained earnings) and revenues."},{"id":"acg-2021-4","front":"Journal entry: company performs services for $500 on account.","back":"Debit Accounts Receivable $500; credit Service Revenue $500."},{"id":"acg-2021-5","front":"Journal entry: pays $1,200 cash for a one-year insurance policy in advance.","back":"Debit Prepaid Insurance $1,200; credit Cash $1,200. It is an asset until used."},{"id":"acg-2021-6","front":"List the steps of the accounting cycle in order.","back":"Analyze transactions, journalize, post to the ledger, prepare an unadjusted trial balance, make adjusting entries, prepare an adjusted trial balance, prepare financial statements, close temporary accounts, prepare a post-closing trial balance."},{"id":"acg-2021-7","front":"Revenue recognition principle vs expense recognition (matching) principle","back":"Revenue is recognized when the performance obligation is satisfied, not when cash is received. Expenses are recorded in the same period as the revenues they help generate."},{"id":"acg-2021-8","front":"Accrual vs cash basis accounting","back":"Accrual basis records revenues when earned and expenses when incurred (required by GAAP). Cash basis records them only when cash changes hands."},{"id":"acg-2021-9","front":"Name the four types of adjusting entries.","back":"Prepaid expenses (deferred expenses), unearned revenues (deferred revenues), accrued revenues and accrued expenses."},{"id":"acg-2021-10","front":"Adjusting entry: $300 of employee wages earned but not yet paid at year-end.","back":"Debit Wages Expense $300; credit Wages Payable $300."},{"id":"acg-2021-11","front":"Adjusting entry: $2,000 of previously collected unearned revenue is now earned.","back":"Debit Unearned Revenue $2,000; credit Service Revenue $2,000."},{"id":"acg-2021-12","front":"Which accounts are closed at period end and where do they go?","back":"Temporary accounts (revenues, expenses, dividends) are closed, ultimately to Retained Earnings. Balance sheet accounts are permanent and not closed."},{"id":"acg-2021-13","front":"In what order are the four main financial statements prepared, and why?","back":"Income statement, statement of retained earnings, balance sheet, statement of cash flows. Net income feeds retained earnings, which feeds the balance sheet."},{"id":"acg-2021-14","front":"Three sections of the statement of cash flows","back":"Operating activities (day-to-day business), investing activities (buying or selling long-term assets) and financing activities (debt, issuing stock, paying dividends)."},{"id":"acg-2021-15","front":"What is the difference between current and long-term assets?","back":"Current assets are expected to be converted to cash or used within one year or the operating cycle, whichever is longer; long-term assets last beyond that."},{"id":"acg-2021-16","front":"Allowance method: what is the entry to write off a specific uncollectible account?","back":"Debit Allowance for Doubtful Accounts; credit Accounts Receivable. It does not affect expense or net realizable value at write-off."},{"id":"acg-2021-17","front":"FIFO vs LIFO when prices are rising","back":"FIFO assigns older, cheaper costs to COGS, giving lower COGS and higher net income and ending inventory. LIFO gives higher COGS, lower net income and lower taxes."},{"id":"acg-2021-18","front":"Cost of goods sold formula","back":"COGS = Beginning Inventory + Purchases - Ending Inventory."},{"id":"acg-2021-19","front":"Gross profit vs net income","back":"Gross profit = Net Sales - Cost of Goods Sold. Net income = all revenues minus all expenses, including operating expenses, interest and taxes."},{"id":"acg-2021-20","front":"Straight-line depreciation formula","back":"Annual depreciation = (Cost - Salvage Value) / Useful Life."},{"id":"acg-2021-21","front":"Equipment costs $50,000, salvage $5,000, life 5 years. Straight-line depreciation?","back":"(50,000 - 5,000) / 5 = $9,000 per year."},{"id":"acg-2021-22","front":"What is book value of a long-term asset?","back":"Book (carrying) value = Cost - Accumulated Depreciation."},{"id":"acg-2021-23","front":"How is depreciation recorded?","back":"Debit Depreciation Expense; credit Accumulated Depreciation, a contra-asset account."},{"id":"acg-2021-24","front":"Bond issued at a discount vs premium","back":"Discount: the bond''s stated rate is below the market rate, so it sells below face value. Premium: the stated rate is above the market rate, so it sells above face value."},{"id":"acg-2021-25","front":"Simple interest formula for a note payable","back":"Interest = Principal x Annual Rate x Time (fraction of a year). A $10,000, 6 percent, 3-month note accrues 10,000 x 0.06 x 3/12 = $150."},{"id":"acg-2021-26","front":"Common stock vs preferred stock","back":"Common stock usually carries voting rights and residual claim. Preferred stock gets priority for dividends and in liquidation but usually no vote."},{"id":"acg-2021-27","front":"Effect of a cash dividend on the accounting equation","back":"On the declaration date, retained earnings decrease and dividends payable increase. On payment, cash and the liability both decrease."},{"id":"acg-2021-28","front":"Sole proprietorship vs corporation: key differences","back":"A proprietorship has one owner with unlimited liability, and income is taxed to the owner. A corporation is a separate legal entity with limited liability for shareholders and its own income tax."},{"id":"acg-2021-29","front":"Formula for the current ratio and what it measures","back":"Current ratio = Current Assets / Current Liabilities. It measures short-term liquidity."},{"id":"acg-2021-30","front":"Common pitfall: is a dividend an expense?","back":"No. Dividends are distributions of retained earnings to owners; they do not appear on the income statement."}],"quizzes":[],"seed":1,"look":{"color":"#16A34A","icon":"acct"}}'::jsonb);   -- https://www.ucf.edu/catalog/undergraduate/#/courses/view/63938f8e4acd58981cbea923
select pg_temp.sb_seed('seed:ucf-edu:syg-2000', 'ucf.edu', 'SYG 2000', 'SYG 2000 Exam Review: Theory, Culture, Socialization, Deviance and Inequality', '{"v":1,"app":"studyboard","type":"deck","name":"SYG 2000 Exam Review: Theory, Culture, Socialization, Deviance and Inequality","course":{"code":"SYG 2000","name":"Introduction to Sociology"},"cards":[{"id":"syg-2000-1","front":"What is the sociological imagination?","back":"C. Wright Mills''s term for seeing the connection between personal troubles and larger public issues and social structures."},{"id":"syg-2000-2","front":"Summarize the functionalist perspective.","back":"Society is a system of interrelated parts that work together to maintain stability; institutions have manifest (intended) and latent (unintended) functions. Linked to Durkheim, Parsons and Merton."},{"id":"syg-2000-3","front":"Summarize the conflict perspective.","back":"Society is shaped by inequality and competition over scarce resources; powerful groups maintain advantage. Rooted in Karl Marx."},{"id":"syg-2000-4","front":"Summarize symbolic interactionism.","back":"A micro-level view that society is created through everyday interaction and shared meanings of symbols. Associated with Mead, Cooley and Blumer."},{"id":"syg-2000-5","front":"Who coined the term sociology?","back":"Auguste Comte, who argued society could be studied scientifically (positivism)."},{"id":"syg-2000-6","front":"What did Durkheim''s study of suicide show?","back":"Suicide rates vary with social integration and regulation, showing that even an individual act has social causes."},{"id":"syg-2000-7","front":"Material vs nonmaterial culture","back":"Material culture: physical objects people make (tools, buildings). Nonmaterial culture: ideas such as values, beliefs, norms and language."},{"id":"syg-2000-8","front":"Folkways vs mores vs laws","back":"Folkways are casual norms (table manners). Mores are norms with strong moral weight (prohibitions on violence). Laws are norms formally enacted and enforced by the state."},{"id":"syg-2000-9","front":"Ethnocentrism vs cultural relativism","back":"Ethnocentrism judges other cultures by one''s own standards. Cultural relativism tries to understand a culture on its own terms."},{"id":"syg-2000-10","front":"Subculture vs counterculture","back":"A subculture shares the main culture but has distinctive traits. A counterculture actively rejects major values of the dominant culture."},{"id":"syg-2000-11","front":"What is Cooley''s looking-glass self?","back":"Self-concept forms by imagining how we appear to others, imagining their judgment, and developing feelings based on those judgments."},{"id":"syg-2000-12","front":"Describe Mead''s I and me.","back":"The ''I'' is the spontaneous, acting self; the ''me'' is the socialized self shaped by others'' expectations. Mead saw the self developing through play and game stages."},{"id":"syg-2000-13","front":"Name four major agents of socialization.","back":"Family, schools, peer groups and mass media; others include religion and the workplace."},{"id":"syg-2000-14","front":"What is resocialization and where does it often occur?","back":"Learning new norms and values while discarding old ones, often in total institutions such as prisons or military boot camp."},{"id":"syg-2000-15","front":"Ascribed vs achieved status","back":"Ascribed status is assigned at birth or involuntarily (race, age). Achieved status is earned or chosen (college graduate, doctor)."},{"id":"syg-2000-16","front":"Role strain vs role conflict","back":"Role strain: tension among demands within one role. Role conflict: incompatible demands between two or more roles (parent and employee)."},{"id":"syg-2000-17","front":"Primary vs secondary groups","back":"Primary groups are small, intimate and long-lasting (family, close friends). Secondary groups are larger, impersonal and goal-oriented (coworkers, a class)."},{"id":"syg-2000-18","front":"What is groupthink?","back":"A tendency in cohesive groups to prioritize agreement over critical evaluation, leading to poor decisions."},{"id":"syg-2000-19","front":"What are Weber''s main characteristics of bureaucracy?","back":"Division of labor, hierarchy of authority, written rules, impersonality, and hiring and promotion based on technical qualifications."},{"id":"syg-2000-20","front":"Merton''s strain theory of deviance","back":"Deviance arises when people cannot reach culturally approved goals through approved means. Adaptations: conformity, innovation, ritualism, retreatism and rebellion."},{"id":"syg-2000-21","front":"What does labeling theory say about deviance?","back":"Deviance results from others'' reactions; being labeled deviant can shape self-identity and lead to further (secondary) deviance."},{"id":"syg-2000-22","front":"Sutherland''s differential association theory","back":"Deviance is learned through interaction with others who define rule-breaking favorably."},{"id":"syg-2000-23","front":"What is social stratification?","back":"A system that ranks categories of people in a hierarchy, giving unequal access to wealth, power and prestige."},{"id":"syg-2000-24","front":"Open vs closed stratification systems","back":"Open (class) systems allow social mobility based on achievement. Closed (caste) systems fix status by birth, with little mobility."},{"id":"syg-2000-25","front":"Weber''s three dimensions of social stratification","back":"Class (economic position), status (social prestige) and party (power)."},{"id":"syg-2000-26","front":"Sex vs gender","back":"Sex refers to biological characteristics; gender refers to socially constructed roles, behaviors and identities associated with being female or male."},{"id":"syg-2000-27","front":"Race vs ethnicity","back":"Race is a socially constructed category based on perceived physical traits. Ethnicity is shared cultural heritage, such as language, ancestry or religion."},{"id":"syg-2000-28","front":"Prejudice vs discrimination","back":"Prejudice is a negative attitude toward a group. Discrimination is unequal treatment of people based on group membership."},{"id":"syg-2000-29","front":"What is institutional (structural) discrimination?","back":"Unequal treatment built into the normal operations of institutions such as schools, housing or the justice system, even without individual intent."},{"id":"syg-2000-30","front":"Describe the demographic transition model.","back":"Societies move from high birth and death rates, to falling death rates with high birth rates (rapid growth), to falling birth rates, and finally to low birth and death rates."},{"id":"syg-2000-31","front":"Quantitative vs qualitative research methods","back":"Quantitative methods use numerical data and statistics (surveys). Qualitative methods use non-numerical data for in-depth meaning (interviews, participant observation)."}],"quizzes":[],"seed":1,"look":{"color":"#D6386F","icon":"soc"}}'::jsonb);   -- https://www.ucf.edu/catalog/undergraduate/#/courses/view/65f2fcc94255750ed2116dd8
select pg_temp.sb_seed('seed:berkeley-edu:chem-1a', 'berkeley.edu', 'CHEM 1A', 'CHEM 1A Exam Review: Stoichiometry, Atomic Structure, Bonding, Gases and Equilibrium', '{"v":1,"app":"studyboard","type":"deck","name":"CHEM 1A Exam Review: Stoichiometry, Atomic Structure, Bonding, Gases and Equilibrium","course":{"code":"CHEM 1A","name":"General Chemistry"},"cards":[{"id":"chem-1a-1","front":"What is a mole?","back":"The amount of substance containing Avogadro''s number of particles, 6.022 x 10^23. The molar mass in g/mol equals the mass of one mole of that substance."},{"id":"chem-1a-2","front":"What is a limiting reactant?","back":"The reactant that is used up first, so it determines the maximum amount of product. Find it by converting each reactant to moles of product and taking the smallest."},{"id":"chem-1a-3","front":"Percent yield formula","back":"Percent yield = (actual yield / theoretical yield) x 100%. Theoretical yield comes from stoichiometry using the limiting reactant."},{"id":"chem-1a-4","front":"Mini-problem: How many moles are in 36.0 g of water (M = 18.0 g/mol)?","back":"n = m / M = 36.0 g / 18.0 g/mol = 2.00 mol."},{"id":"chem-1a-5","front":"Relationship between energy, frequency and wavelength of light","back":"E = h*nu and c = lambda*nu, so E = h*c/lambda. h = 6.626 x 10^-34 J*s, c = 3.00 x 10^8 m/s. Shorter wavelength means higher energy."},{"id":"chem-1a-6","front":"Bohr energy levels for hydrogen","back":"E_n = -2.18 x 10^-18 J / n^2 (about -13.6 eV / n^2). A photon is emitted when an electron drops from higher n to lower n; its energy equals the difference."},{"id":"chem-1a-7","front":"de Broglie wavelength","back":"lambda = h / (m*v). Any moving particle has wave character; it matters for tiny masses like electrons."},{"id":"chem-1a-8","front":"Heisenberg uncertainty principle","back":"Position and momentum cannot both be known exactly: delta_x * delta_p >= h/(4*pi). This is why electrons are described by orbitals (probability distributions), not orbits."},{"id":"chem-1a-9","front":"The four quantum numbers and their allowed values","back":"n = 1, 2, 3...; l = 0 to n-1 (s, p, d, f); m_l = -l to +l; m_s = +1/2 or -1/2. No two electrons in an atom share all four (Pauli exclusion)."},{"id":"chem-1a-10","front":"Hund''s rule","back":"In degenerate orbitals, electrons occupy separate orbitals with parallel spins before pairing up, which minimizes electron repulsion."},{"id":"chem-1a-11","front":"Electron configuration of Fe (Z = 26)","back":"1s2 2s2 2p6 3s2 3p6 4s2 3d6, or [Ar] 4s2 3d6."},{"id":"chem-1a-12","front":"Periodic trends: atomic radius and ionization energy","back":"Atomic radius decreases across a period (higher effective nuclear charge) and increases down a group. Ionization energy shows the opposite trend."},{"id":"chem-1a-13","front":"What is effective nuclear charge (Z_eff)?","back":"The net positive charge felt by an electron after shielding by other electrons, roughly Z minus the number of core electrons. It rises across a period."},{"id":"chem-1a-14","front":"Ionic vs covalent bonding","back":"Ionic bonds form by electron transfer between atoms with a large electronegativity difference (often metal plus nonmetal). Covalent bonds share electron pairs, usually between nonmetals."},{"id":"chem-1a-15","front":"How do you calculate formal charge?","back":"Formal charge = valence electrons - nonbonding electrons - (bonding electrons / 2). The best Lewis structure keeps formal charges near zero, with negative charge on the more electronegative atom."},{"id":"chem-1a-16","front":"VSEPR: geometry of a central atom with 4 electron domains and 1 lone pair","back":"Electron geometry is tetrahedral; molecular geometry is trigonal pyramidal (example: NH3), bond angle a bit less than 109.5 degrees."},{"id":"chem-1a-17","front":"What makes a molecule polar?","back":"It has polar bonds arranged so their dipoles do not cancel. CO2 is nonpolar (linear, dipoles cancel) while H2O is polar (bent)."},{"id":"chem-1a-18","front":"Hybridization for 2, 3 and 4 electron domains","back":"2 domains: sp (linear); 3 domains: sp2 (trigonal planar); 4 domains: sp3 (tetrahedral)."},{"id":"chem-1a-19","front":"Sigma vs pi bonds","back":"A single bond is one sigma bond; a double bond is one sigma plus one pi; a triple bond is one sigma plus two pi. Pi bonds form from side-on overlap of unhybridized p orbitals."},{"id":"chem-1a-20","front":"Ideal gas law and its symbols","back":"PV = nRT. P = pressure, V = volume, n = moles, T = temperature in kelvin, R = 0.08206 L*atm/(mol*K) or 8.314 J/(mol*K)."},{"id":"chem-1a-21","front":"When do real gases deviate most from ideal behavior?","back":"At high pressure (molecule volume matters) and low temperature (attractions matter). The van der Waals equation corrects with the a (attraction) and b (volume) terms."},{"id":"chem-1a-22","front":"Dalton''s law of partial pressures","back":"P_total = P_1 + P_2 + ...; each partial pressure P_i = x_i * P_total, where x_i is the mole fraction."},{"id":"chem-1a-23","front":"Hess''s law","back":"The enthalpy change for a reaction is the same whatever path is taken, so delta H values of steps can be added. Reversing a reaction flips the sign; multiplying it scales delta H."},{"id":"chem-1a-24","front":"Standard enthalpy of reaction from enthalpies of formation","back":"delta H_rxn = sum(n * delta H_f products) - sum(n * delta H_f reactants). delta H_f of an element in its standard state is zero."},{"id":"chem-1a-25","front":"Gibbs free energy and spontaneity","back":"delta G = delta H - T*delta S. A reaction is spontaneous when delta G < 0. With delta H < 0 and delta S > 0 it is spontaneous at all temperatures."},{"id":"chem-1a-26","front":"Link between delta G standard and K","back":"delta G standard = -R*T*ln K. If K > 1, delta G standard is negative and products are favored at equilibrium."},{"id":"chem-1a-27","front":"Reaction quotient Q vs K","back":"If Q < K the reaction shifts toward products; if Q > K it shifts toward reactants; if Q = K it is at equilibrium."},{"id":"chem-1a-28","front":"Le Chatelier''s principle: effect of adding heat to an exothermic reaction","back":"Heat acts like a product, so the equilibrium shifts toward reactants and K decreases. Temperature is the only change that alters the value of K."},{"id":"chem-1a-29","front":"pH, pOH and Kw at 25 C","back":"pH = -log[H3O+], pOH = -log[OH-], pH + pOH = 14, and Kw = [H3O+][OH-] = 1.0 x 10^-14."},{"id":"chem-1a-30","front":"Henderson-Hasselbalch equation","back":"pH = pKa + log([A-]/[HA]). It applies to buffers; when [A-] = [HA], pH = pKa."},{"id":"chem-1a-31","front":"Solubility product Ksp: write it for CaF2","back":"CaF2(s) <=> Ca2+ + 2F-, so Ksp = [Ca2+][F-]^2. If molar solubility is s, Ksp = s(2s)^2 = 4s^3."},{"id":"chem-1a-32","front":"Oxidation vs reduction","back":"Oxidation is loss of electrons (oxidation number rises); reduction is gain of electrons (oxidation number falls). The oxidizing agent is the species that gets reduced."},{"id":"chem-1a-33","front":"Rate law and reaction order","back":"Rate = k[A]^m[B]^n, where m and n are found from experiment, not from coefficients. The overall order is m + n."},{"id":"chem-1a-34","front":"First-order half-life","back":"t_1/2 = 0.693 / k, independent of starting concentration. Integrated law: ln[A] = ln[A]0 - k*t."},{"id":"chem-1a-35","front":"Arrhenius equation","back":"k = A * e^(-Ea/(R*T)). Raising T or lowering activation energy Ea (as a catalyst does) increases the rate constant."}],"quizzes":[],"seed":1,"look":{"color":"#1E9E74","icon":"chem"}}'::jsonb);   -- https://classes.berkeley.edu/content/2025-spring-chem-1a-001-lec-001
select pg_temp.sb_seed('seed:berkeley-edu:compsci-61a', 'berkeley.edu', 'COMPSCI 61A', 'COMPSCI 61A Midterm Review: Higher-Order Functions, Recursion, Objects and Interpreters', '{"v":1,"app":"studyboard","type":"deck","name":"COMPSCI 61A Midterm Review: Higher-Order Functions, Recursion, Objects and Interpreters","course":{"code":"COMPSCI 61A","name":"The Structure and Interpretation of Computer Programs"},"cards":[{"id":"compsci-61a-1","front":"What is abstraction in programming?","back":"Hiding the details of how something works behind a name or interface, so you can use it based only on what it does. Functions, data types and classes are all abstraction tools."},{"id":"compsci-61a-2","front":"What is a higher-order function?","back":"A function that takes another function as an argument, returns a function, or both. Examples: map, filter, and a function that builds and returns an adder."},{"id":"compsci-61a-3","front":"What does this return? def make_adder(n): return lambda x: x + n ... make_adder(3)(4)","back":"7. make_adder(3) returns a function that adds 3 to its argument, and calling it with 4 gives 7."},{"id":"compsci-61a-4","front":"What is an environment frame?","back":"A record of name-to-value bindings. Evaluating a name looks it up in the current frame, then each parent frame, ending at the global frame."},{"id":"compsci-61a-5","front":"Which frame is the parent of a new frame created by calling a function?","back":"The frame in which the function was defined (lexical scoping), not the frame from which it was called."},{"id":"compsci-61a-6","front":"What is a closure?","back":"A function together with the environment it was defined in, so it can still access names from that enclosing frame after the outer function has returned."},{"id":"compsci-61a-7","front":"What does the nonlocal statement do?","back":"It lets an inner function reassign a name bound in an enclosing (non-global) function''s frame instead of creating a new local binding."},{"id":"compsci-61a-8","front":"Two essential parts of a recursive function","back":"A base case that returns without recursing, and a recursive case that calls the function on a smaller problem moving toward the base case."},{"id":"compsci-61a-9","front":"Write factorial recursively in one line of logic","back":"def fact(n): return 1 if n == 0 else n * fact(n - 1). fact(4) = 4*3*2*1 = 24."},{"id":"compsci-61a-10","front":"What is tree recursion?","back":"Recursion where a call makes more than one recursive call, like fib(n) = fib(n-1) + fib(n-2) or counting partitions. Its call structure forms a tree."},{"id":"compsci-61a-11","front":"Counting partitions idea: count_partitions(n, m)","back":"Number of ways to write n as a sum of parts up to size m = ways using at least one m (count_partitions(n-m, m)) + ways using no m (count_partitions(n, m-1))."},{"id":"compsci-61a-12","front":"Pitfall: why can naive recursive Fibonacci be slow?","back":"It recomputes the same subproblems many times, giving exponential time. Memoization (caching results) makes it linear."},{"id":"compsci-61a-13","front":"Python list comprehension syntax","back":"[expression for x in iterable if condition]. Example: [x * x for x in range(5) if x % 2 == 0] gives [0, 4, 16]."},{"id":"compsci-61a-14","front":"Iterable vs iterator","back":"An iterable can produce an iterator through iter(). An iterator returns successive values through next() and raises StopIteration when it runs out; it can be used only once."},{"id":"compsci-61a-15","front":"What is a generator function?","back":"A function containing yield. Calling it returns a generator (a lazy iterator) that runs until each yield, pausing and resuming its state between next() calls."},{"id":"compsci-61a-16","front":"What does yield from do?","back":"It yields every value from another iterable or generator in turn, which is handy for recursive generators."},{"id":"compsci-61a-17","front":"What is a data abstraction barrier?","back":"A separation between code that uses a data type through its constructors and selectors and code that implements its representation. Violating it means relying on internal details."},{"id":"compsci-61a-18","front":"Mutable vs immutable values in Python","back":"Lists and dictionaries are mutable (can change in place). Integers, strings and tuples are immutable. Two names bound to the same list both see changes made through either name."},{"id":"compsci-61a-19","front":"is vs == in Python","back":"== tests whether two values are equal. is tests identity, that is, whether both names refer to the very same object."},{"id":"compsci-61a-20","front":"Class attribute vs instance attribute","back":"A class attribute is shared by all instances and stored on the class. An instance attribute is stored on one object, often set in __init__ through self."},{"id":"compsci-61a-21","front":"What is inheritance?","back":"A subclass reuses the attributes and methods of its base class and can override them. Attribute lookup checks the instance, then its class, then base classes."},{"id":"compsci-61a-22","front":"Bound method: what happens with obj.method(arg)?","back":"Python looks up method on the class and passes obj automatically as the first parameter, self, so it is the same as Class.method(obj, arg)."},{"id":"compsci-61a-23","front":"__str__ vs __repr__","back":"__str__ gives a readable string used by print and str(). __repr__ gives an unambiguous string, ideally valid code, shown by the interactive interpreter and repr()."},{"id":"compsci-61a-24","front":"What is a linked list?","back":"A recursive sequence where each node holds a first value and a rest, which is another linked list or empty. Access to the k-th element takes time proportional to k."},{"id":"compsci-61a-25","front":"What is a tree in 61A-style data abstraction?","back":"A value with a label and a list of branches, where each branch is itself a tree. A leaf has no branches."},{"id":"compsci-61a-26","front":"Order of growth: what is Theta(log n)?","back":"Time grows with the logarithm of input size, typical when each step halves the problem, as in binary search or repeated halving of n."},{"id":"compsci-61a-27","front":"Order of growth of a nested loop over n items for each of n items","back":"Theta(n^2), quadratic: doubling n roughly quadruples the work."},{"id":"compsci-61a-28","front":"Functional vs object-oriented vs declarative paradigms","back":"Functional: compose pure functions and avoid mutation. Object-oriented: bundle state and behavior in objects. Declarative: state what result you want (as in SQL) rather than how to compute it."},{"id":"compsci-61a-29","front":"In Scheme, what does (define (square x) (* x x)) do?","back":"It binds the name square to a procedure that multiplies its argument by itself. Scheme uses prefix notation with the operator first inside parentheses."},{"id":"compsci-61a-30","front":"What are the two core steps of an interpreter''s eval loop?","back":"Eval evaluates an expression: for a call it evaluates the operator and operands. Apply then calls the procedure on those argument values, often by evaluating its body in a new frame."},{"id":"compsci-61a-31","front":"Special form vs call expression in Scheme","back":"A call expression evaluates all operands first. Special forms such as if, define, lambda and and do not evaluate all subexpressions in the usual way."},{"id":"compsci-61a-32","front":"What is a macro?","back":"A procedure that operates on unevaluated code and returns new code, which is then evaluated in the caller''s environment. It lets you add new special forms to a language."},{"id":"compsci-61a-33","front":"What is tail recursion and why does it matter in Scheme?","back":"A call is in tail position when nothing remains to do after it returns. Scheme implementations must optimize tail calls, so tail-recursive procedures use constant space."}],"quizzes":[],"seed":1,"look":{"color":"#4F46E5","icon":"code"}}'::jsonb);   -- https://classes.berkeley.edu/content/2026-fall-compsci-61a-001-lec-001
select pg_temp.sb_seed('seed:berkeley-edu:econ-1', 'berkeley.edu', 'ECON 1', 'ECON 1 Final Review: Supply and Demand, Market Structures, GDP and Macro Policy', '{"v":1,"app":"studyboard","type":"deck","name":"ECON 1 Final Review: Supply and Demand, Market Structures, GDP and Macro Policy","course":{"code":"ECON 1","name":"Introduction to Economics"},"cards":[{"id":"econ-1-1","front":"Opportunity cost","back":"The value of the next best alternative given up when you make a choice. For example, the cost of college includes wages you could have earned."},{"id":"econ-1-2","front":"Absolute vs comparative advantage","back":"Absolute advantage: producing more with the same resources. Comparative advantage: producing at a lower opportunity cost. Trade gains come from comparative advantage."},{"id":"econ-1-3","front":"What does a production possibilities frontier (PPF) show?","back":"The maximum combinations of two goods an economy can produce with its resources. Points inside are inefficient, points outside unattainable; a bowed-out shape reflects increasing opportunity cost."},{"id":"econ-1-4","front":"Law of demand","back":"Other things equal, when the price of a good rises, the quantity demanded falls, so demand curves slope downward."},{"id":"econ-1-5","front":"Change in demand vs change in quantity demanded","back":"A price change moves you along the demand curve (quantity demanded). A change in income, tastes, related goods'' prices, expectations or number of buyers shifts the whole curve (demand)."},{"id":"econ-1-6","front":"Normal vs inferior good","back":"Demand for a normal good rises when income rises. Demand for an inferior good falls when income rises."},{"id":"econ-1-7","front":"Substitutes vs complements","back":"Substitutes: a price rise in one raises demand for the other (coffee and tea). Complements: a price rise in one lowers demand for the other (cars and gasoline)."},{"id":"econ-1-8","front":"Effect of a supply decrease on equilibrium","back":"Supply shifts left: equilibrium price rises and equilibrium quantity falls."},{"id":"econ-1-9","front":"Price elasticity of demand formula","back":"Elasticity = (% change in quantity demanded) / (% change in price), in absolute value. Greater than 1 is elastic, less than 1 is inelastic."},{"id":"econ-1-10","front":"How does a price increase affect total revenue for inelastic demand?","back":"Total revenue rises, because quantity falls by a smaller percentage than price rises. For elastic demand, revenue falls."},{"id":"econ-1-11","front":"Consumer surplus and producer surplus","back":"Consumer surplus: willingness to pay minus price paid (area under demand above price). Producer surplus: price received minus cost (area above supply below price)."},{"id":"econ-1-12","front":"What is deadweight loss?","back":"The loss of total surplus when output is not at the efficient level, for example from a tax, price ceiling, price floor or monopoly."},{"id":"econ-1-13","front":"Effect of a binding price ceiling","back":"Set below equilibrium, it causes a shortage: quantity demanded exceeds quantity supplied. Rent control is a standard example."},{"id":"econ-1-14","front":"Tax incidence rule","back":"The side of the market that is less elastic bears more of a tax burden, regardless of whether the tax is legally placed on buyers or sellers."},{"id":"econ-1-15","front":"Marginal cost and average total cost relationship","back":"MC crosses ATC at the minimum point of ATC. When MC is below ATC, ATC is falling; when MC is above ATC, ATC is rising."},{"id":"econ-1-16","front":"Profit-maximizing rule for any firm","back":"Produce the quantity where marginal revenue equals marginal cost (MR = MC)."},{"id":"econ-1-17","front":"Perfect competition in the long run","back":"Free entry and exit drive economic profit to zero, so price equals minimum average total cost and P = MC."},{"id":"econ-1-18","front":"How does a monopoly differ from a competitive firm?","back":"A monopolist faces the downward-sloping market demand, so MR < P. It sets MR = MC, producing less and charging more than a competitive market, creating deadweight loss."},{"id":"econ-1-19","front":"What is a negative externality and one fix?","back":"A cost imposed on third parties not reflected in price, such as pollution, leading to overproduction. A Pigouvian tax equal to the external cost can correct it."},{"id":"econ-1-20","front":"Public goods: two defining properties","back":"Non-rival (one person''s use does not reduce another''s) and non-excludable (people cannot be kept from using it). They suffer from the free-rider problem."},{"id":"econ-1-21","front":"Expenditure approach to GDP","back":"GDP = C + I + G + NX: consumption, investment, government purchases, and net exports (exports minus imports)."},{"id":"econ-1-22","front":"Nominal vs real GDP","back":"Nominal GDP uses current prices; real GDP uses constant base-year prices, so it measures changes in output alone. GDP deflator = (nominal / real) x 100."},{"id":"econ-1-23","front":"Unemployment rate formula and who counts","back":"Unemployment rate = unemployed / labor force x 100. The labor force is employed plus unemployed people actively seeking work; discouraged workers are excluded."},{"id":"econ-1-24","front":"Three types of unemployment","back":"Frictional (between jobs), structural (skill or location mismatch), and cyclical (due to recessions). The natural rate includes frictional and structural only."},{"id":"econ-1-25","front":"Mini-problem: CPI rises from 200 to 210. What is the inflation rate?","back":"(210 - 200) / 200 x 100 = 5%."},{"id":"econ-1-26","front":"Real interest rate (Fisher relation)","back":"Real interest rate is approximately nominal interest rate minus inflation. A 7% nominal rate with 3% inflation gives about a 4% real rate."},{"id":"econ-1-27","front":"Simple spending multiplier","back":"Multiplier = 1 / (1 - MPC), where MPC is the marginal propensity to consume. With MPC = 0.8, a change in spending is multiplied by 5."},{"id":"econ-1-28","front":"Aggregate demand and aggregate supply: effect of a negative demand shock in the short run","back":"AD shifts left: output falls, unemployment rises and the price level falls or rises more slowly."},{"id":"econ-1-29","front":"Expansionary fiscal policy vs expansionary monetary policy","back":"Fiscal: the government raises spending or cuts taxes. Monetary: the central bank lowers interest rates or expands the money supply. Both shift aggregate demand right."},{"id":"econ-1-30","front":"Quantity theory of money equation","back":"M*V = P*Y: money supply times velocity equals the price level times real output. With stable V and Y, faster money growth leads to inflation."}],"quizzes":[],"seed":1,"look":{"color":"#C79A12","icon":"econ"}}'::jsonb);   -- https://classes.berkeley.edu/content/2026-fall-econ-1-001-lec-001
select pg_temp.sb_seed('seed:usc-edu:psyc-100', 'usc.edu', 'PSYC 100', 'PSYC 100 Exam Review: Research Methods, Brain, Learning, Memory and Disorders', '{"v":1,"app":"studyboard","type":"deck","name":"PSYC 100 Exam Review: Research Methods, Brain, Learning, Memory and Disorders","course":{"code":"PSYC 100","name":"Introduction to Psychology"},"cards":[{"id":"psyc-100-1","front":"Correlation vs experiment","back":"A correlational study measures how variables relate without manipulating them, so it cannot show cause. An experiment manipulates an independent variable and uses random assignment to infer causation."},{"id":"psyc-100-2","front":"Independent vs dependent variable","back":"The independent variable is what the researcher manipulates. The dependent variable is the outcome that is measured."},{"id":"psyc-100-3","front":"Why use random assignment?","back":"It spreads participant differences evenly across conditions, so differences in the outcome can be attributed to the manipulation rather than preexisting differences."},{"id":"psyc-100-4","front":"What is a double-blind study?","back":"Neither participants nor the researchers interacting with them know who is in which condition, reducing placebo effects and experimenter bias."},{"id":"psyc-100-5","front":"Reliability vs validity","back":"Reliability is consistency of a measure across time or raters. Validity is whether it measures what it claims to measure. A measure can be reliable without being valid."},{"id":"psyc-100-6","front":"Parts of a neuron and the direction of signal flow","back":"Dendrites receive signals, the cell body integrates them, and the axon carries the action potential to the terminals, which release neurotransmitters into the synapse."},{"id":"psyc-100-7","front":"What is an action potential?","back":"An all-or-none electrical impulse along the axon, triggered when the membrane reaches threshold; sodium ions rush in, then potassium flows out to restore the charge."},{"id":"psyc-100-8","front":"Dopamine vs serotonin: main roles","back":"Dopamine is involved in reward, motivation and movement (low in Parkinson''s). Serotonin is involved in mood, sleep and appetite (targeted by SSRIs for depression)."},{"id":"psyc-100-9","front":"Functions of the frontal, parietal, temporal and occipital lobes","back":"Frontal: planning, decisions, motor control. Parietal: touch and spatial processing. Temporal: hearing and language comprehension. Occipital: vision."},{"id":"psyc-100-10","front":"Broca''s vs Wernicke''s area","back":"Damage to Broca''s area (frontal) impairs speech production. Damage to Wernicke''s area (temporal) impairs language comprehension, with fluent but meaningless speech."},{"id":"psyc-100-11","front":"Role of the hippocampus and amygdala","back":"The hippocampus helps form new explicit memories. The amygdala processes emotion, especially fear."},{"id":"psyc-100-12","front":"Sensation vs perception","back":"Sensation is detecting physical energy with sense receptors. Perception is the brain organizing and interpreting that input into meaningful experience."},{"id":"psyc-100-13","front":"Classical conditioning terms in Pavlov''s experiment","back":"Food is the unconditioned stimulus, salivation to food the unconditioned response. The bell becomes a conditioned stimulus, and salivation to the bell the conditioned response."},{"id":"psyc-100-14","front":"What is extinction in classical conditioning?","back":"The conditioned response weakens when the conditioned stimulus is repeatedly presented without the unconditioned stimulus. It can return later (spontaneous recovery)."},{"id":"psyc-100-15","front":"Positive vs negative reinforcement","back":"Both increase a behavior. Positive reinforcement adds something pleasant; negative reinforcement removes something unpleasant, like taking aspirin to remove a headache."},{"id":"psyc-100-16","front":"Negative reinforcement vs punishment","back":"Negative reinforcement increases behavior by removing an aversive stimulus. Punishment decreases behavior. They are often confused."},{"id":"psyc-100-17","front":"Which reinforcement schedule is most resistant to extinction?","back":"Variable-ratio, where reward comes after an unpredictable number of responses (like a slot machine)."},{"id":"psyc-100-18","front":"Bandura''s Bobo doll study showed what?","back":"Children who watched an adult act aggressively toward a doll imitated that aggression, demonstrating observational learning."},{"id":"psyc-100-19","front":"Stages of the multi-store (Atkinson-Shiffrin) memory model","back":"Sensory memory, then short-term (working) memory with limited capacity, then long-term memory. Attention moves information to short-term memory; encoding moves it to long-term."},{"id":"psyc-100-20","front":"Explicit vs implicit memory","back":"Explicit (declarative) memory is consciously recalled facts and events. Implicit memory includes skills and conditioned responses shown without conscious recall, like riding a bike."},{"id":"psyc-100-21","front":"Proactive vs retroactive interference","back":"Proactive: old learning disrupts recall of new information. Retroactive: new learning disrupts recall of old information."},{"id":"psyc-100-22","front":"Piaget''s four stages of cognitive development","back":"Sensorimotor (0-2, object permanence), preoperational (2-7, egocentrism), concrete operational (7-11, conservation), and formal operational (12+, abstract reasoning)."},{"id":"psyc-100-23","front":"Ainsworth''s Strange Situation identified which attachment styles?","back":"Secure, insecure-avoidant and insecure-resistant (ambivalent); later work added disorganized attachment."},{"id":"psyc-100-24","front":"The Big Five personality traits","back":"Openness, conscientiousness, extraversion, agreeableness and neuroticism (OCEAN)."},{"id":"psyc-100-25","front":"Fundamental attribution error","back":"Overestimating personal traits and underestimating situational factors when explaining other people''s behavior."},{"id":"psyc-100-26","front":"What did Milgram''s obedience study find?","back":"Most participants obeyed an authority figure''s instructions to give what they believed were severe electric shocks, showing the strong power of situational authority."},{"id":"psyc-100-27","front":"Cognitive dissonance","back":"Discomfort from holding conflicting beliefs or acting against one''s beliefs, which people often reduce by changing their attitudes."},{"id":"psyc-100-28","front":"Major depressive disorder vs bipolar disorder","back":"Major depression involves persistent low mood or loss of interest. Bipolar disorder involves depressive episodes plus manic or hypomanic episodes."},{"id":"psyc-100-29","front":"Key symptoms of schizophrenia","back":"Positive symptoms such as hallucinations and delusions, disorganized speech, and negative symptoms such as flat affect and reduced motivation."},{"id":"psyc-100-30","front":"Cognitive behavioral therapy (CBT) in one sentence","back":"A therapy that helps people identify and change distorted thoughts and maladaptive behaviors; it is well supported for depression and anxiety."},{"id":"psyc-100-31","front":"Stages of sleep and when vivid dreaming mostly occurs","back":"Sleep cycles through NREM stages 1-3 (stage 3 is deep slow-wave sleep) and REM sleep, about every 90 minutes. Vivid dreams occur mostly in REM."}],"quizzes":[],"seed":1,"look":{"color":"#9A4FD1","icon":"psych"}}'::jsonb);   -- https://classes.usc.edu/term-20263/course/psyc-100/
select pg_temp.sb_seed('seed:usc-edu:buad-280', 'usc.edu', 'BUAD 280', 'BUAD 280 Midterm Review: Accounting Equation, Financial Statements, Inventory and Receivables', '{"v":1,"app":"studyboard","type":"deck","name":"BUAD 280 Midterm Review: Accounting Equation, Financial Statements, Inventory and Receivables","course":{"code":"BUAD 280","name":"Introduction to Financial Accounting"},"cards":[{"id":"buad-280-1","front":"The basic accounting equation","back":"Assets = Liabilities + Stockholders'' Equity. Every transaction keeps it in balance."},{"id":"buad-280-2","front":"Expanded stockholders'' equity components","back":"Equity = Common Stock (contributed capital) + Retained Earnings. Retained earnings rise with net income and fall with net losses and dividends."},{"id":"buad-280-3","front":"Debit and credit rules for the five account types","back":"Assets, expenses and dividends increase with debits. Liabilities, equity and revenues increase with credits."},{"id":"buad-280-4","front":"What are the four main financial statements?","back":"Income statement, statement of retained earnings (or stockholders'' equity), balance sheet, and statement of cash flows."},{"id":"buad-280-5","front":"Income statement vs balance sheet","back":"The income statement reports revenues and expenses over a period. The balance sheet reports assets, liabilities and equity at a single point in time."},{"id":"buad-280-6","front":"Order in which the statements are prepared and why","back":"Income statement first (net income), then retained earnings (uses net income), then balance sheet (uses ending retained earnings), then cash flows."},{"id":"buad-280-7","front":"Accrual vs cash basis accounting","back":"Accrual accounting records revenue when earned and expenses when incurred, regardless of cash. Cash basis records them when cash changes hands. GAAP requires accrual."},{"id":"buad-280-8","front":"Revenue recognition principle","back":"Recognize revenue when the company satisfies its performance obligation by transferring goods or services to the customer, in the amount it expects to receive."},{"id":"buad-280-9","front":"Expense recognition (matching) principle","back":"Record expenses in the same period as the revenues they helped generate."},{"id":"buad-280-10","front":"Journal entry: company receives $5,000 cash for services to be performed next month","back":"Debit Cash 5,000; credit Unearned Revenue 5,000. Unearned revenue is a liability until the service is performed."},{"id":"buad-280-11","front":"Four types of adjusting entries","back":"Deferred revenues (unearned revenue earned), deferred expenses (prepaids used up), accrued revenues (earned but not billed) and accrued expenses (incurred but not paid)."},{"id":"buad-280-12","front":"Adjusting entry: $1,200 of prepaid insurance covers 12 months; one month has passed","back":"Debit Insurance Expense 100; credit Prepaid Insurance 100."},{"id":"buad-280-13","front":"What is depreciation?","back":"Allocating the cost of a long-term asset over its useful life. It is a cost allocation, not a measure of market value. Entry: debit Depreciation Expense, credit Accumulated Depreciation."},{"id":"buad-280-14","front":"Straight-line depreciation formula","back":"(Cost - Residual value) / Useful life. A $10,000 asset with $1,000 residual value and 3-year life gives $3,000 per year."},{"id":"buad-280-15","front":"What is a contra account? Give an example","back":"An account offsetting a related account, with the opposite normal balance. Accumulated Depreciation reduces equipment; Allowance for Doubtful Accounts reduces receivables."},{"id":"buad-280-16","front":"Which accounts are closed at period end?","back":"Temporary accounts: revenues, expenses and dividends are closed to Retained Earnings. Permanent balance sheet accounts carry forward."},{"id":"buad-280-17","front":"Gross profit formula","back":"Gross profit = Net sales - Cost of goods sold. Gross profit percentage = gross profit / net sales."},{"id":"buad-280-18","front":"Cost of goods sold formula (periodic)","back":"COGS = Beginning inventory + Purchases - Ending inventory."},{"id":"buad-280-19","front":"FIFO vs LIFO when costs are rising","back":"FIFO assigns older, cheaper costs to COGS, giving higher net income and higher ending inventory. LIFO gives higher COGS, lower income and lower taxes. IFRS does not allow LIFO."},{"id":"buad-280-20","front":"Perpetual vs periodic inventory systems","back":"Perpetual updates inventory and COGS with each sale. Periodic updates them only at the end of the period through a physical count."},{"id":"buad-280-21","front":"Lower of cost and net realizable value rule","back":"If inventory''s net realizable value falls below cost, write it down to NRV, recognizing a loss in that period."},{"id":"buad-280-22","front":"Allowance method for bad debts","back":"Estimate uncollectible accounts each period: debit Bad Debt Expense, credit Allowance for Doubtful Accounts. A write-off later debits the Allowance and credits Accounts Receivable, with no expense."},{"id":"buad-280-23","front":"Net realizable value of accounts receivable","back":"Accounts Receivable minus Allowance for Doubtful Accounts: the amount the company expects to collect."},{"id":"buad-280-24","front":"Three sections of the statement of cash flows","back":"Operating activities (core business), investing activities (buying or selling long-term assets and investments) and financing activities (debt, stock, dividends)."},{"id":"buad-280-25","front":"Under the indirect method, how is depreciation treated?","back":"It is added back to net income in operating activities, because it reduced net income without using cash."},{"id":"buad-280-26","front":"Current ratio formula and meaning","back":"Current ratio = current assets / current liabilities. It measures short-term liquidity; above 1 means current assets exceed current obligations."},{"id":"buad-280-27","front":"Debt-to-equity ratio","back":"Total liabilities / total stockholders'' equity. A higher ratio means more financing comes from creditors and more financial risk."},{"id":"buad-280-28","front":"Return on assets (ROA)","back":"Net income / average total assets. It measures how efficiently a company uses its assets to generate profit."},{"id":"buad-280-29","front":"Effect of declaring a cash dividend","back":"Retained earnings decrease and a dividends payable liability is created. Dividends are not an expense and do not appear on the income statement."},{"id":"buad-280-30","front":"Mini-problem: Assets $80,000 and liabilities $30,000. What is equity?","back":"Equity = Assets - Liabilities = 80,000 - 30,000 = $50,000."}],"quizzes":[],"seed":1,"look":{"color":"#0D9488","icon":"acct"}}'::jsonb);   -- https://classes.usc.edu/term-20263/course/buad-280/
select pg_temp.sb_seed('seed:usc-edu:math-125', 'usc.edu', 'MATH 125', 'MATH 125 Final Review: Limits, Derivatives, Applications and the Fundamental Theorem', '{"v":1,"app":"studyboard","type":"deck","name":"MATH 125 Final Review: Limits, Derivatives, Applications and the Fundamental Theorem","course":{"code":"MATH 125","name":"Calculus I"},"cards":[{"id":"math-125-1","front":"Informal meaning of lim x->a f(x) = L","back":"f(x) can be made as close to L as we like by taking x close enough to a, but not equal to a. The value f(a) itself does not matter."},{"id":"math-125-2","front":"When does a limit fail to exist?","back":"When the left and right limits differ, when f grows without bound, or when f oscillates without settling, as sin(1/x) does near 0."},{"id":"math-125-3","front":"Evaluate lim x->3 (x^2 - 9)/(x - 3)","back":"Factor: (x - 3)(x + 3)/(x - 3) = x + 3, so the limit is 6."},{"id":"math-125-4","front":"Key trig limit","back":"lim x->0 sin(x)/x = 1. Also lim x->0 (1 - cos x)/x = 0."},{"id":"math-125-5","front":"Three conditions for continuity at x = a","back":"f(a) is defined, lim x->a f(x) exists, and the limit equals f(a)."},{"id":"math-125-6","front":"Intermediate Value Theorem","back":"If f is continuous on [a, b] and N is between f(a) and f(b), then f(c) = N for some c in [a, b]. Used to show a root exists."},{"id":"math-125-7","front":"Limit definition of the derivative","back":"f''(x) = lim h->0 [f(x + h) - f(x)] / h: the slope of the tangent line, or instantaneous rate of change."},{"id":"math-125-8","front":"Pitfall: does differentiable imply continuous, and vice versa?","back":"Differentiable implies continuous, but continuous does not imply differentiable. |x| is continuous at 0 but has a corner there."},{"id":"math-125-9","front":"Power rule","back":"d/dx [x^n] = n*x^(n-1) for any real n. Example: d/dx [x^(1/2)] = (1/2)x^(-1/2)."},{"id":"math-125-10","front":"Product rule","back":"d/dx [f*g] = f''*g + f*g''."},{"id":"math-125-11","front":"Quotient rule","back":"d/dx [f/g] = (f''*g - f*g'') / g^2."},{"id":"math-125-12","front":"Chain rule","back":"d/dx [f(g(x))] = f''(g(x)) * g''(x). Example: d/dx [sin(x^2)] = cos(x^2) * 2x."},{"id":"math-125-13","front":"Derivatives of sin x, cos x and tan x","back":"d/dx sin x = cos x; d/dx cos x = -sin x; d/dx tan x = sec^2 x."},{"id":"math-125-14","front":"Derivatives of e^x and ln x","back":"d/dx e^x = e^x; d/dx ln x = 1/x for x > 0. Also d/dx a^x = a^x * ln a."},{"id":"math-125-15","front":"Implicit differentiation: find dy/dx for x^2 + y^2 = 25","back":"2x + 2y*(dy/dx) = 0, so dy/dx = -x/y."},{"id":"math-125-16","front":"Related rates strategy","back":"Write an equation linking the quantities, differentiate both sides with respect to time t, then substitute known values only after differentiating."},{"id":"math-125-17","front":"Equation of the tangent line at x = a","back":"y = f(a) + f''(a)(x - a). This is also the linear approximation of f near a."},{"id":"math-125-18","front":"What is a critical number?","back":"A number c in the domain where f''(c) = 0 or f''(c) does not exist. Local extrema can occur only at critical numbers."},{"id":"math-125-19","front":"First derivative test","back":"If f'' changes from positive to negative at c, f has a local max there; negative to positive gives a local min; no sign change gives neither."},{"id":"math-125-20","front":"Second derivative test and concavity","back":"f'''' > 0 means concave up; f'''' < 0 means concave down. If f''(c) = 0 and f''''(c) > 0, then c is a local min; if f''''(c) < 0, a local max."},{"id":"math-125-21","front":"What is an inflection point?","back":"A point on the graph where concavity changes, from up to down or down to up."},{"id":"math-125-22","front":"Mean Value Theorem","back":"If f is continuous on [a, b] and differentiable on (a, b), then f''(c) = [f(b) - f(a)] / (b - a) for some c in (a, b)."},{"id":"math-125-23","front":"Closed interval method for absolute extrema","back":"Evaluate f at critical numbers in [a, b] and at endpoints a and b. The largest value is the absolute max; the smallest is the absolute min."},{"id":"math-125-24","front":"L''Hopital''s rule","back":"If a limit gives 0/0 or infinity/infinity, then lim f/g = lim f''/g'' when the latter exists. Example: lim x->0 sin x / x = lim cos x / 1 = 1."},{"id":"math-125-25","front":"Antiderivative of x^n","back":"Integral of x^n dx = x^(n+1)/(n+1) + C for n not equal to -1. For n = -1 it is ln|x| + C."},{"id":"math-125-26","front":"Why is + C needed in an indefinite integral?","back":"Any two antiderivatives of the same function differ by a constant, so C represents the whole family."},{"id":"math-125-27","front":"Definite integral as a Riemann sum","back":"Integral from a to b of f(x) dx = limit as n -> infinity of the sum of f(x_i)*delta_x, with delta_x = (b - a)/n. It is signed area under the curve."},{"id":"math-125-28","front":"Fundamental Theorem of Calculus, Part 1","back":"If F(x) = integral from a to x of f(t) dt with f continuous, then F''(x) = f(x)."},{"id":"math-125-29","front":"Fundamental Theorem of Calculus, Part 2","back":"Integral from a to b of f(x) dx = F(b) - F(a), where F is any antiderivative of f."},{"id":"math-125-30","front":"Evaluate the integral from 0 to 2 of 3x^2 dx","back":"Antiderivative x^3; 2^3 - 0^3 = 8."},{"id":"math-125-31","front":"u-substitution: integral of 2x*cos(x^2) dx","back":"Let u = x^2, du = 2x dx, so the integral is integral of cos u du = sin(x^2) + C."}],"quizzes":[],"seed":1,"look":{"color":"#3B6FE0","icon":"calc"}}'::jsonb);   -- https://classes.usc.edu/term-20263/course/math-125/
select pg_temp.sb_seed('seed:uw-edu:biol-180', 'uw.edu', 'BIOL 180', 'BIOL 180 Exam Review: Mendelian Genetics, Evolution, Biodiversity and Ecology', '{"v":1,"app":"studyboard","type":"deck","name":"BIOL 180 Exam Review: Mendelian Genetics, Evolution, Biodiversity and Ecology","course":{"code":"BIOL 180","name":"Introductory Biology"},"cards":[{"id":"biol-180-1","front":"Mendel''s law of segregation","back":"Each individual has two alleles for a gene, which separate during gamete formation so each gamete carries only one."},{"id":"biol-180-2","front":"Mendel''s law of independent assortment","back":"Alleles of different genes assort into gametes independently of one another, as long as the genes are on different chromosomes or far apart on the same one."},{"id":"biol-180-3","front":"Genotype vs phenotype","back":"Genotype is the allele combination an organism carries. Phenotype is its observable trait, which results from genotype and environment."},{"id":"biol-180-4","front":"Expected ratios from a monohybrid cross Aa x Aa","back":"Genotypes 1 AA : 2 Aa : 1 aa; phenotypes 3 dominant : 1 recessive."},{"id":"biol-180-5","front":"Expected phenotype ratio from a dihybrid cross AaBb x AaBb","back":"9 : 3 : 3 : 1, assuming complete dominance and independent assortment."},{"id":"biol-180-6","front":"What is a testcross?","back":"Crossing an individual with the dominant phenotype to a homozygous recessive. If any offspring show the recessive phenotype, the parent was heterozygous."},{"id":"biol-180-7","front":"Incomplete dominance vs codominance","back":"Incomplete dominance: heterozygote is intermediate (red x white gives pink). Codominance: both alleles fully expressed (AB blood type)."},{"id":"biol-180-8","front":"Why are X-linked recessive traits more common in males?","back":"Males have one X chromosome, so a single recessive allele produces the trait; females need two copies."},{"id":"biol-180-9","front":"How does meiosis create genetic variation?","back":"Crossing over between homologous chromosomes in prophase I, independent assortment of homologs in metaphase I, and random fertilization."},{"id":"biol-180-10","front":"Mitosis vs meiosis outcome","back":"Mitosis gives two genetically identical diploid cells. Meiosis gives four genetically different haploid gametes."},{"id":"biol-180-11","front":"Linked genes and recombination frequency","back":"Genes close on a chromosome tend to be inherited together. Recombination frequency (recombinant offspring / total) estimates distance: 1% = 1 map unit."},{"id":"biol-180-12","front":"Darwin''s natural selection in four points","back":"Individuals vary, variation is heritable, more offspring are produced than survive, and individuals with advantageous traits leave more offspring, so those traits increase over generations."},{"id":"biol-180-13","front":"Fitness in evolutionary biology","back":"An individual''s relative reproductive success: how many offspring it contributes to the next generation compared with others."},{"id":"biol-180-14","front":"Hardy-Weinberg equations","back":"p + q = 1 for allele frequencies and p^2 + 2pq + q^2 = 1 for genotype frequencies (AA, Aa, aa)."},{"id":"biol-180-15","front":"Five Hardy-Weinberg assumptions","back":"No mutation, random mating, no natural selection, very large population (no drift) and no gene flow."},{"id":"biol-180-16","front":"Mini-problem: 16% of a population shows a recessive trait. What is q?","back":"q^2 = 0.16, so q = 0.4 and p = 0.6. Heterozygotes are 2pq = 0.48."},{"id":"biol-180-17","front":"Genetic drift, and the bottleneck vs founder effect","back":"Drift is random change in allele frequencies, strongest in small populations. Bottleneck: a population sharply shrinks. Founder effect: a few individuals start a new population."},{"id":"biol-180-18","front":"Directional, stabilizing and disruptive selection","back":"Directional favors one extreme; stabilizing favors intermediate phenotypes; disruptive favors both extremes over the middle."},{"id":"biol-180-19","front":"Biological species concept","back":"A species is a group of populations whose members can interbreed in nature and produce fertile offspring, and are reproductively isolated from other groups."},{"id":"biol-180-20","front":"Allopatric vs sympatric speciation","back":"Allopatric: populations are separated geographically and diverge. Sympatric: new species arise in the same area, for example through polyploidy in plants."},{"id":"biol-180-21","front":"Homologous vs analogous structures","back":"Homologous structures share common ancestry (human arm and whale flipper). Analogous structures have similar function from convergent evolution (bird and insect wings)."},{"id":"biol-180-22","front":"What is a monophyletic group (clade)?","back":"An ancestor and all of its descendants. Paraphyletic groups leave out some descendants, such as traditional reptiles without birds."},{"id":"biol-180-23","front":"The three domains of life","back":"Bacteria, Archaea and Eukarya. Bacteria and Archaea are prokaryotes; Archaea share some molecular features with eukaryotes."},{"id":"biol-180-24","front":"Population growth: exponential vs logistic","back":"Exponential: dN/dt = rN, a J-shaped curve with unlimited resources. Logistic: dN/dt = rN(K - N)/K, an S-shaped curve leveling off at carrying capacity K."},{"id":"biol-180-25","front":"r-selected vs K-selected species","back":"r-selected: many offspring, little care, fast maturity (often in unstable habitats). K-selected: few offspring, high parental care, near carrying capacity."},{"id":"biol-180-26","front":"Types of species interactions with their +/- effects","back":"Competition (-/-), predation and parasitism (+/-), mutualism (+/+), commensalism (+/0)."},{"id":"biol-180-27","front":"Competitive exclusion principle","back":"Two species competing for the exact same limiting resources cannot coexist indefinitely; one will outcompete the other or they will partition resources."},{"id":"biol-180-28","front":"What is a keystone species?","back":"A species whose effect on community structure is far larger than its abundance suggests, like sea otters controlling urchins and protecting kelp forests."},{"id":"biol-180-29","front":"Why is only about 10% of energy passed between trophic levels?","back":"Most energy is lost as heat in metabolism or remains in unconsumed or undigested material, which limits the length of food chains."},{"id":"biol-180-30","front":"Major threats to biodiversity","back":"Habitat loss and fragmentation, invasive species, overharvesting, pollution and climate change."},{"id":"biol-180-31","front":"Why does small population size threaten conservation?","back":"Small populations lose genetic diversity through drift and inbreeding, lowering fitness and adaptability, which can create an extinction vortex."}],"quizzes":[],"seed":1,"look":{"color":"#16A34A","icon":"bio"}}'::jsonb);   -- https://www.washington.edu/students/crscat/biology.html#biol180
select pg_temp.sb_seed('seed:uw-edu:stat-311', 'uw.edu', 'STAT 311', 'STAT 311 Final Review: Study Design, Probability, Confidence Intervals and Hypothesis Tests', '{"v":1,"app":"studyboard","type":"deck","name":"STAT 311 Final Review: Study Design, Probability, Confidence Intervals and Hypothesis Tests","course":{"code":"STAT 311","name":"Elements of Statistical Methods"},"cards":[{"id":"stat-311-1","front":"Observational study vs experiment","back":"An observational study records data without assigning treatments, so it shows association only. An experiment randomly assigns treatments, allowing cause-and-effect conclusions."},{"id":"stat-311-2","front":"What is a confounding variable?","back":"A variable related to both the explanatory variable and the response, making it impossible to separate their effects."},{"id":"stat-311-3","front":"Simple random sample vs stratified sample","back":"SRS: every group of n individuals is equally likely to be chosen. Stratified: divide the population into similar groups (strata) and take an SRS within each."},{"id":"stat-311-4","front":"Three principles of experimental design","back":"Control (comparison groups and holding variables constant), randomization, and replication (enough units). Blocking can also reduce variability."},{"id":"stat-311-5","front":"Mean vs median with a skewed distribution","back":"The mean is pulled toward the tail; the median is resistant. In right-skewed data the mean is usually greater than the median."},{"id":"stat-311-6","front":"Interquartile range and the 1.5 x IQR outlier rule","back":"IQR = Q3 - Q1. Values below Q1 - 1.5*IQR or above Q3 + 1.5*IQR are flagged as potential outliers."},{"id":"stat-311-7","front":"Standard deviation meaning","back":"Roughly the typical distance of observations from the mean. Sample formula: s = sqrt(sum((x - xbar)^2) / (n - 1))."},{"id":"stat-311-8","front":"Properties of the correlation r","back":"r ranges from -1 to 1 and measures the strength and direction of a linear relationship. It has no units, is unaffected by changes of scale, and is sensitive to outliers."},{"id":"stat-311-9","front":"Least-squares regression line formulas","back":"y-hat = b0 + b1*x, with slope b1 = r * (s_y / s_x) and intercept b0 = ybar - b1*xbar."},{"id":"stat-311-10","front":"Interpret r^2 in regression","back":"The proportion of variation in y explained by the linear relationship with x. r^2 = 0.64 means 64% of the variation is explained."},{"id":"stat-311-11","front":"What is a residual?","back":"Residual = observed y - predicted y-hat. A residual plot with no pattern supports a linear model."},{"id":"stat-311-12","front":"Pitfall: extrapolation","back":"Using a regression line to predict far outside the range of observed x values, which is unreliable because the relationship may not continue."},{"id":"stat-311-13","front":"Addition rule for probability","back":"P(A or B) = P(A) + P(B) - P(A and B). For disjoint events, P(A and B) = 0."},{"id":"stat-311-14","front":"Conditional probability and independence","back":"P(A | B) = P(A and B) / P(B). A and B are independent if P(A | B) = P(A), equivalently P(A and B) = P(A)*P(B)."},{"id":"stat-311-15","front":"Conditions for a binomial setting","back":"Fixed number of trials n, each trial success or failure, trials independent, and the same success probability p on each trial."},{"id":"stat-311-16","front":"Binomial mean and standard deviation","back":"Mean = n*p; SD = sqrt(n*p*(1 - p)). With n = 100 and p = 0.3, the mean is 30 and SD is about 4.58."},{"id":"stat-311-17","front":"The 68-95-99.7 rule","back":"In a normal distribution about 68% of values lie within 1 SD of the mean, 95% within 2 SD, and 99.7% within 3 SD."},{"id":"stat-311-18","front":"z-score formula","back":"z = (x - mu) / sigma: how many standard deviations x is above or below the mean."},{"id":"stat-311-19","front":"Central Limit Theorem","back":"For large n, the sampling distribution of the sample mean is approximately normal with mean mu and standard deviation sigma / sqrt(n), whatever the population shape."},{"id":"stat-311-20","front":"Standard error of a sample proportion","back":"SE = sqrt(p-hat * (1 - p-hat) / n). For a test, use the null value p0 in place of p-hat."},{"id":"stat-311-21","front":"General form of a confidence interval","back":"Estimate plus or minus (critical value x standard error). For a mean: xbar plus or minus t* * s / sqrt(n)."},{"id":"stat-311-22","front":"Correct interpretation of a 95% confidence interval","back":"If we repeated the sampling many times, about 95% of the intervals built this way would contain the true parameter. It is not a 95% chance this one interval contains it."},{"id":"stat-311-23","front":"How do sample size and confidence level affect interval width?","back":"Larger n gives a narrower interval (SE shrinks with sqrt(n)). Higher confidence gives a wider interval."},{"id":"stat-311-24","front":"What is a p-value?","back":"Assuming the null hypothesis is true, the probability of getting a result at least as extreme as the one observed. Small p-values are evidence against H0."},{"id":"stat-311-25","front":"Type I vs Type II error","back":"Type I: rejecting a true null hypothesis (probability alpha). Type II: failing to reject a false null hypothesis (probability beta). Power = 1 - beta."},{"id":"stat-311-26","front":"One-sample t statistic","back":"t = (xbar - mu0) / (s / sqrt(n)), with n - 1 degrees of freedom. Used when the population SD is unknown."},{"id":"stat-311-27","front":"Paired t-test vs two-sample t-test","back":"Paired: the same subjects measured twice or matched pairs, so analyze the differences. Two-sample: two independent groups, compare their means."},{"id":"stat-311-28","front":"Chi-square test statistic","back":"Chi-square = sum of (observed - expected)^2 / expected over all cells. Large values indicate the data differ from what H0 predicts."},{"id":"stat-311-29","front":"Expected count in a chi-square test of independence","back":"Expected = (row total x column total) / grand total. Each expected count should be at least about 5."},{"id":"stat-311-30","front":"Mini-problem: n = 25, xbar = 52, s = 10, testing mu0 = 50. Find t.","back":"SE = 10 / sqrt(25) = 2, so t = (52 - 50) / 2 = 1.0 with 24 degrees of freedom."},{"id":"stat-311-31","front":"Statistical significance vs practical importance","back":"With a very large sample, even a tiny, unimportant difference can give a small p-value. Always consider the size of the effect, for example through a confidence interval."}],"quizzes":[],"seed":1,"look":{"color":"#E0673B","icon":"stats"}}'::jsonb);   -- https://www.washington.edu/students/crscat/stat.html#stat311
select pg_temp.sb_seed('seed:uw-edu:phys-121', 'uw.edu', 'PHYS 121', 'PHYS 121 Exam Review: Kinematics, Newton''s Laws, Energy, Momentum and Rotation', '{"v":1,"app":"studyboard","type":"deck","name":"PHYS 121 Exam Review: Kinematics, Newton''s Laws, Energy, Momentum and Rotation","course":{"code":"PHYS 121","name":"Mechanics"},"cards":[{"id":"phys-121-1","front":"Displacement vs distance","back":"Displacement is the vector change in position (final minus initial). Distance is the total path length, a scalar that is never negative."},{"id":"phys-121-2","front":"Average velocity vs instantaneous velocity","back":"Average velocity = displacement / elapsed time. Instantaneous velocity is the derivative dx/dt, the slope of the position-time graph at an instant."},{"id":"phys-121-3","front":"Constant-acceleration kinematic equations","back":"v = v0 + a*t; x = x0 + v0*t + (1/2)*a*t^2; v^2 = v0^2 + 2*a*(x - x0)."},{"id":"phys-121-4","front":"Mini-problem: A ball is dropped from rest. How far does it fall in 2.0 s? (g = 9.8 m/s^2)","back":"d = (1/2)*g*t^2 = 0.5 * 9.8 * 4.0 = 19.6 m."},{"id":"phys-121-5","front":"Projectile motion key idea","back":"Horizontal and vertical motions are independent. Horizontal velocity is constant (no air resistance); vertical acceleration is -g."},{"id":"phys-121-6","front":"Range of a projectile launched and landing at the same height","back":"R = v0^2 * sin(2*theta) / g, which is greatest at 45 degrees."},{"id":"phys-121-7","front":"Uniform circular motion acceleration","back":"Centripetal acceleration a = v^2 / r, directed toward the center, even at constant speed."},{"id":"phys-121-8","front":"Newton''s first law","back":"An object stays at rest or moves at constant velocity unless a net external force acts on it (inertia)."},{"id":"phys-121-9","front":"Newton''s second law","back":"F_net = m*a, where F_net is the vector sum of all forces, m is mass in kg and a is acceleration in m/s^2."},{"id":"phys-121-10","front":"Newton''s third law and a common pitfall","back":"Forces come in equal and opposite pairs acting on different objects. The normal force and weight on a resting book are not a third-law pair; both act on the book."},{"id":"phys-121-11","front":"Mass vs weight","back":"Mass is the amount of matter (kg), the same everywhere. Weight is the gravitational force on it, W = m*g, measured in newtons."},{"id":"phys-121-12","front":"Static vs kinetic friction","back":"Static friction adjusts up to a maximum f_s <= mu_s*N to prevent sliding. Kinetic friction f_k = mu_k*N acts during sliding. Usually mu_k < mu_s."},{"id":"phys-121-13","front":"Block on a frictionless incline at angle theta: acceleration?","back":"a = g*sin(theta) down the slope; the normal force is m*g*cos(theta)."},{"id":"phys-121-14","front":"Atwood machine: two masses m1 > m2 over a frictionless pulley. Acceleration?","back":"a = (m1 - m2)*g / (m1 + m2)."},{"id":"phys-121-15","front":"Work done by a constant force","back":"W = F*d*cos(theta), where theta is the angle between force and displacement. Units: joules (N*m)."},{"id":"phys-121-16","front":"Work-energy theorem","back":"The net work done on an object equals its change in kinetic energy: W_net = delta KE, with KE = (1/2)*m*v^2."},{"id":"phys-121-17","front":"Gravitational and spring potential energy","back":"Near Earth, U_g = m*g*h. For a spring, U_s = (1/2)*k*x^2, where k is the spring constant and x the stretch or compression."},{"id":"phys-121-18","front":"Conservation of mechanical energy","back":"With only conservative forces doing work, KE + U is constant. Friction converts mechanical energy into thermal energy."},{"id":"phys-121-19","front":"Mini-problem: speed at the bottom of a frictionless 5.0 m drop starting from rest?","back":"v = sqrt(2*g*h) = sqrt(2 * 9.8 * 5.0), which is about 9.9 m/s."},{"id":"phys-121-20","front":"Power","back":"P = W / t = F*v, the rate of doing work, measured in watts (J/s)."},{"id":"phys-121-21","front":"Momentum and impulse","back":"Momentum p = m*v. Impulse J = F_avg * delta_t = delta p."},{"id":"phys-121-22","front":"When is total momentum conserved?","back":"When the net external force on the system is zero; internal forces in a collision do not change total momentum."},{"id":"phys-121-23","front":"Elastic vs perfectly inelastic collisions","back":"Both conserve momentum. Elastic collisions also conserve kinetic energy. In a perfectly inelastic collision the objects stick together and the most kinetic energy is lost."},{"id":"phys-121-24","front":"Mini-problem: 2 kg cart at 3 m/s sticks to a resting 1 kg cart. Final speed?","back":"Momentum conservation: 2*3 = (2 + 1)*v, so v = 2 m/s."},{"id":"phys-121-25","front":"Center of mass of a system of particles","back":"x_cm = sum(m_i * x_i) / sum(m_i). With no net external force, the center of mass moves at constant velocity."},{"id":"phys-121-26","front":"Rotational kinematics links between linear and angular quantities","back":"s = r*theta, v = r*omega, a_tangential = r*alpha, with angles in radians."},{"id":"phys-121-27","front":"Torque","back":"tau = r*F*sin(theta), the rotational effect of a force about an axis. Newton''s second law for rotation: tau_net = I*alpha."},{"id":"phys-121-28","front":"Moment of inertia and why it depends on shape","back":"I = sum(m_i * r_i^2): rotational inertia depends on how far mass sits from the axis. A hoop (I = M*R^2) is harder to spin than a solid disk (I = (1/2)*M*R^2)."},{"id":"phys-121-29","front":"Rotational kinetic energy and rolling without slipping","back":"KE_rot = (1/2)*I*omega^2. For rolling without slipping v = R*omega and total KE = (1/2)*m*v^2 + (1/2)*I*omega^2."},{"id":"phys-121-30","front":"Conservation of angular momentum","back":"L = I*omega is constant when net external torque is zero. A skater pulling in her arms lowers I, so omega increases."},{"id":"phys-121-31","front":"Conditions for static equilibrium","back":"Net force is zero and net torque about any axis is zero."},{"id":"phys-121-32","front":"Hooke''s law and simple harmonic motion period","back":"F = -k*x. A mass on a spring oscillates with period T = 2*pi*sqrt(m/k), independent of amplitude."}],"quizzes":[],"seed":1,"look":{"color":"#1D9BB8","icon":"phys"}}'::jsonb);   -- https://www.washington.edu/students/crscat/phys.html#phys121
select pg_temp.sb_seed('seed:nyu-edu:psych-ua-1', 'nyu.edu', 'PSYCH-UA 1', 'PSYCH-UA 1 Exam Review: Research Methods, Brain, Learning, Memory and Social Psychology', '{"v":1,"app":"studyboard","type":"deck","name":"PSYCH-UA 1 Exam Review: Research Methods, Brain, Learning, Memory and Social Psychology","course":{"code":"PSYCH-UA 1","name":"Introduction to Psychology"},"cards":[{"id":"psych-ua-1-1","front":"Independent variable vs dependent variable","back":"The independent variable is what the experimenter manipulates; the dependent variable is the outcome that is measured to see whether it changed as a result."},{"id":"psych-ua-1-2","front":"Why does random assignment matter in an experiment?","back":"It spreads participant differences evenly across conditions on average, so differences in the outcome can be attributed to the manipulation rather than to preexisting group differences."},{"id":"psych-ua-1-3","front":"Correlation vs causation: what are the two classic problems with inferring cause from a correlation?","back":"The directionality problem (A could cause B or B could cause A) and the third-variable problem (some other factor C could cause both)."},{"id":"psych-ua-1-4","front":"What does a correlation coefficient of r = -0.80 tell you?","back":"A strong negative linear relationship: as one variable increases, the other tends to decrease. The sign gives direction and the magnitude (0 to 1) gives strength."},{"id":"psych-ua-1-5","front":"Placebo effect and double-blind design","back":"A placebo effect is improvement caused by expectations rather than the treatment itself. In a double-blind study neither participants nor experimenters know who gets the real treatment, controlling for expectancy and experimenter bias."},{"id":"psych-ua-1-6","front":"Neuron basics: dendrites, axon, myelin, terminal buttons","back":"Dendrites receive signals, the axon carries the action potential away from the cell body, myelin insulates the axon to speed conduction, and terminal buttons release neurotransmitters into the synapse."},{"id":"psych-ua-1-7","front":"What is the all-or-none principle of the action potential?","back":"A neuron either fires a full-strength action potential once its threshold is reached or does not fire at all; stimulus intensity is coded by firing rate, not by spike size."},{"id":"psych-ua-1-8","front":"Sympathetic vs parasympathetic nervous system","back":"Sympathetic arouses the body for fight or flight (raises heart rate, dilates pupils); parasympathetic calms the body and supports rest and digest functions."},{"id":"psych-ua-1-9","front":"Functions of the frontal, parietal, temporal and occipital lobes","back":"Frontal: planning, decision making and motor control. Parietal: touch and spatial processing. Temporal: hearing and language comprehension. Occipital: vision."},{"id":"psych-ua-1-10","front":"Broca''s area vs Wernicke''s area","back":"Broca''s area (left frontal lobe) supports speech production; damage gives halting, effortful speech. Wernicke''s area (left temporal lobe) supports comprehension; damage gives fluent but meaningless speech."},{"id":"psych-ua-1-11","front":"Role of the hippocampus and amygdala","back":"The hippocampus is crucial for forming new explicit (declarative) memories; the amygdala processes emotion, especially fear, and emotional memory."},{"id":"psych-ua-1-12","front":"Sensation vs perception","back":"Sensation is the detection of physical energy by sense receptors; perception is the brain''s organization and interpretation of that input into meaningful experience."},{"id":"psych-ua-1-13","front":"Classical conditioning: define UCS, UCR, CS and CR using Pavlov''s dogs","back":"Food is the UCS, salivating to food is the UCR, the bell (after pairing) is the CS, and salivating to the bell alone is the CR."},{"id":"psych-ua-1-14","front":"Extinction vs spontaneous recovery in classical conditioning","back":"Extinction is the weakening of the CR when the CS is repeatedly presented without the UCS. Spontaneous recovery is the reappearance of the extinguished CR after a rest period."},{"id":"psych-ua-1-15","front":"Positive vs negative reinforcement","back":"Both increase a behavior. Positive reinforcement adds a pleasant stimulus; negative reinforcement removes an unpleasant one (for example, taking aspirin removes a headache)."},{"id":"psych-ua-1-16","front":"Negative reinforcement vs punishment: common pitfall","back":"Negative reinforcement increases a behavior by removing something aversive. Punishment decreases a behavior, either by adding something aversive or removing something pleasant."},{"id":"psych-ua-1-17","front":"Which reinforcement schedule produces behavior most resistant to extinction?","back":"Variable-ratio schedules (reward after an unpredictable number of responses, like a slot machine) produce high, steady responding that is very resistant to extinction."},{"id":"psych-ua-1-18","front":"Bandura''s Bobo doll study demonstrated what?","back":"Observational learning: children who watched an adult behave aggressively toward a doll were more likely to imitate that aggression, showing learning without direct reinforcement."},{"id":"psych-ua-1-19","front":"Three stages of the Atkinson-Shiffrin memory model","back":"Sensory memory (very brief, large capacity), short-term or working memory (about 7 plus or minus 2 items, roughly 20 seconds without rehearsal), and long-term memory (relatively permanent, vast capacity)."},{"id":"psych-ua-1-20","front":"Explicit vs implicit memory","back":"Explicit (declarative) memory is consciously recalled facts and events (semantic and episodic). Implicit memory shows up without awareness, such as skills (procedural memory) and priming."},{"id":"psych-ua-1-21","front":"Proactive vs retroactive interference","back":"Proactive: old learning interferes with recalling new information. Retroactive: new learning interferes with recalling old information."},{"id":"psych-ua-1-22","front":"Serial position effect","back":"Items at the start (primacy effect) and end (recency effect) of a list are recalled better than items in the middle."},{"id":"psych-ua-1-23","front":"Piaget''s four stages of cognitive development in order","back":"Sensorimotor (birth to 2, object permanence), preoperational (2 to 7, egocentrism), concrete operational (7 to 11, conservation), and formal operational (12 and up, abstract reasoning)."},{"id":"psych-ua-1-24","front":"Assimilation vs accommodation (Piaget)","back":"Assimilation fits new information into an existing schema; accommodation changes the schema to fit new information."},{"id":"psych-ua-1-25","front":"Big Five personality traits","back":"Openness, Conscientiousness, Extraversion, Agreeableness and Neuroticism (OCEAN)."},{"id":"psych-ua-1-26","front":"Fundamental attribution error","back":"The tendency to overestimate personality or disposition and underestimate the situation when explaining other people''s behavior."},{"id":"psych-ua-1-27","front":"What did Milgram''s obedience studies find?","back":"A large share of ordinary participants (about 65 percent in the classic version) continued to deliver what they believed were the maximum shocks when instructed by an authority figure."},{"id":"psych-ua-1-28","front":"Asch conformity studies","back":"Participants often went along with a clearly wrong group answer on a simple line-length judgment, showing the power of normative social pressure to conform."},{"id":"psych-ua-1-29","front":"Cognitive dissonance","back":"The discomfort felt when holding conflicting beliefs or when behavior conflicts with attitudes; people often reduce it by changing their attitudes to match their behavior."},{"id":"psych-ua-1-30","front":"Bystander effect","back":"People are less likely to help in an emergency when other people are present, partly due to diffusion of responsibility."}],"quizzes":[],"seed":1,"look":{"color":"#9A4FD1","icon":"psych"}}'::jsonb);   -- https://bulletins.nyu.edu/courses/psych_ua/
select pg_temp.sb_seed('seed:nyu-edu:econ-ua-1', 'nyu.edu', 'ECON-UA 1', 'ECON-UA 1 Exam Review: GDP, Inflation, Unemployment, Growth, Money and the Fed', '{"v":1,"app":"studyboard","type":"deck","name":"ECON-UA 1 Exam Review: GDP, Inflation, Unemployment, Growth, Money and the Fed","course":{"code":"ECON-UA 1","name":"Introduction to Macroeconomics"},"cards":[{"id":"econ-ua-1-1","front":"GDP definition","back":"Gross domestic product is the market value of all final goods and services produced within a country in a given period of time."},{"id":"econ-ua-1-2","front":"Expenditure approach to GDP","back":"Y = C + I + G + NX, where C is consumption, I is investment, G is government purchases and NX is net exports (exports minus imports)."},{"id":"econ-ua-1-3","front":"Why are intermediate goods excluded from GDP?","back":"Their value is already included in the price of the final good; counting them separately would double count."},{"id":"econ-ua-1-4","front":"Do transfer payments like Social Security count in G?","back":"No. G counts only government purchases of goods and services; transfers are excluded because nothing is produced in exchange."},{"id":"econ-ua-1-5","front":"Nominal vs real GDP","back":"Nominal GDP uses current-year prices; real GDP uses constant base-year prices, so it changes only when quantities produced change."},{"id":"econ-ua-1-6","front":"GDP deflator formula","back":"GDP deflator = (nominal GDP / real GDP) x 100. It measures the price level of all domestically produced goods and services."},{"id":"econ-ua-1-7","front":"Mini-problem: nominal GDP is 1,200 and real GDP is 1,000. What is the deflator?","back":"Deflator = (1,200 / 1,000) x 100 = 120, meaning prices are 20 percent higher than in the base year."},{"id":"econ-ua-1-8","front":"How is the inflation rate calculated from the CPI?","back":"Inflation rate = (CPI this year - CPI last year) / CPI last year x 100."},{"id":"econ-ua-1-9","front":"CPI vs GDP deflator","back":"The CPI tracks a fixed basket of goods bought by consumers, including imports; the deflator covers all domestically produced goods and uses current quantities."},{"id":"econ-ua-1-10","front":"Unemployment rate formula","back":"Unemployment rate = (number unemployed / labor force) x 100, where labor force = employed + unemployed."},{"id":"econ-ua-1-11","front":"Who is counted as unemployed?","back":"People without a job who are available for work and have actively looked for work in the past four weeks. Discouraged workers who stopped looking are not in the labor force."},{"id":"econ-ua-1-12","front":"Frictional vs structural vs cyclical unemployment","back":"Frictional: short-term job searching. Structural: mismatch between workers'' skills or location and available jobs. Cyclical: caused by recessions. The natural rate includes frictional and structural only."},{"id":"econ-ua-1-13","front":"Real interest rate (Fisher equation)","back":"Real interest rate is approximately nominal interest rate minus inflation rate (r = i - pi)."},{"id":"econ-ua-1-14","front":"Who is hurt by unexpectedly high inflation?","back":"Lenders and savers with fixed nominal returns, and people on fixed nominal incomes; borrowers with fixed-rate debt gain because they repay with less valuable money."},{"id":"econ-ua-1-15","front":"Main sources of long-run economic growth","back":"Growth in productivity, driven by physical capital per worker, human capital, natural resources and technological knowledge."},{"id":"econ-ua-1-16","front":"Rule of 70","back":"The number of years for a variable to double is about 70 divided by its annual percentage growth rate. At 2 percent growth, output doubles in about 35 years."},{"id":"econ-ua-1-17","front":"Catch-up (convergence) effect","back":"Countries that start with less capital tend to grow faster because of diminishing returns to capital: each additional unit of capital raises output more when capital is scarce."},{"id":"econ-ua-1-18","front":"Three functions of money","back":"Medium of exchange, unit of account and store of value."},{"id":"econ-ua-1-19","front":"Simple money multiplier","back":"Money multiplier = 1 / reserve ratio. With a 10 percent reserve ratio, each new dollar of reserves can support up to 10 dollars of deposits."},{"id":"econ-ua-1-20","front":"Main tools of the Federal Reserve","back":"Setting the target federal funds rate, paying interest on reserves, open market operations (buying or selling government bonds) and lending through the discount window."},{"id":"econ-ua-1-21","front":"Effect of the Fed buying government bonds","back":"It adds reserves to the banking system, increases the money supply and puts downward pressure on interest rates, which is expansionary."},{"id":"econ-ua-1-22","front":"Quantity theory of money","back":"M x V = P x Y. If velocity V and real output Y are stable, growth in the money supply M leads to proportional growth in the price level P in the long run."},{"id":"econ-ua-1-23","front":"Why does aggregate demand slope downward?","back":"A lower price level raises real wealth (wealth effect), lowers interest rates (interest rate effect) and makes domestic goods cheaper relative to foreign goods (exchange rate effect)."},{"id":"econ-ua-1-24","front":"Short-run vs long-run aggregate supply","back":"Long-run AS is vertical at potential output because it depends on resources and technology, not prices. Short-run AS slopes upward because some wages and prices are sticky."},{"id":"econ-ua-1-25","front":"Expansionary fiscal policy and its effect in the AD-AS model","back":"Increasing government spending or cutting taxes shifts AD right, raising output and the price level in the short run."},{"id":"econ-ua-1-26","front":"Spending multiplier formula","back":"Multiplier = 1 / (1 - MPC), where MPC is the marginal propensity to consume. With MPC = 0.8, the multiplier is 5."},{"id":"econ-ua-1-27","front":"Crowding out","back":"When government borrowing raises interest rates, private investment falls, offsetting part of the effect of expansionary fiscal policy."},{"id":"econ-ua-1-28","front":"Stagflation and what causes it","back":"Simultaneous high inflation and falling output or rising unemployment, typically caused by an adverse supply shock (such as an oil price spike) that shifts short-run AS left."},{"id":"econ-ua-1-29","front":"Recession definition (common rule of thumb)","back":"A significant, widespread decline in economic activity; a common rule of thumb is two consecutive quarters of falling real GDP, though the NBER uses a broader set of indicators."}],"quizzes":[],"seed":1,"look":{"color":"#1E9E74","icon":"econ"}}'::jsonb);   -- https://bulletins.nyu.edu/courses/econ_ua/
select pg_temp.sb_seed('seed:nyu-edu:math-ua-121', 'nyu.edu', 'MATH-UA 121', 'MATH-UA 121 Exam Review: Limits, Derivatives, Applications and Intro Integrals', '{"v":1,"app":"studyboard","type":"deck","name":"MATH-UA 121 Exam Review: Limits, Derivatives, Applications and Intro Integrals","course":{"code":"MATH-UA 121","name":"Calculus I"},"cards":[{"id":"math-ua-121-1","front":"Formal idea of lim x->a f(x) = L","back":"f(x) can be made as close as you like to L by taking x sufficiently close to a (but not equal to a). The value f(a) itself does not matter."},{"id":"math-ua-121-2","front":"When does a two-sided limit exist?","back":"Only when both one-sided limits exist and are equal: lim x->a- f(x) = lim x->a+ f(x)."},{"id":"math-ua-121-3","front":"Evaluate lim x->2 (x^2 - 4)/(x - 2)","back":"Factor: (x - 2)(x + 2)/(x - 2) = x + 2 for x not equal to 2, so the limit is 4."},{"id":"math-ua-121-4","front":"lim x->0 sin(x)/x","back":"1 (with x in radians). It is the key limit used to derive d/dx [sin x] = cos x."},{"id":"math-ua-121-5","front":"Three conditions for f to be continuous at x = a","back":"f(a) is defined, lim x->a f(x) exists, and lim x->a f(x) = f(a)."},{"id":"math-ua-121-6","front":"Intermediate Value Theorem","back":"If f is continuous on [a, b] and N is between f(a) and f(b), then there is some c in (a, b) with f(c) = N. Often used to show a root exists."},{"id":"math-ua-121-7","front":"Limit definition of the derivative","back":"f''(x) = lim h->0 [f(x + h) - f(x)] / h, the slope of the tangent line, or instantaneous rate of change."},{"id":"math-ua-121-8","front":"Differentiable vs continuous","back":"Differentiability at a point implies continuity there, but not the reverse. Example: f(x) = |x| is continuous at 0 but not differentiable (sharp corner)."},{"id":"math-ua-121-9","front":"Power rule","back":"d/dx [x^n] = n*x^(n-1) for any real constant n."},{"id":"math-ua-121-10","front":"Product rule","back":"d/dx [f*g] = f''*g + f*g''."},{"id":"math-ua-121-11","front":"Quotient rule","back":"d/dx [f/g] = (f''*g - f*g'') / g^2."},{"id":"math-ua-121-12","front":"Chain rule","back":"d/dx [f(g(x))] = f''(g(x)) * g''(x). Differentiate the outer function at the inner one, then multiply by the derivative of the inner function."},{"id":"math-ua-121-13","front":"Differentiate y = (3x^2 + 1)^5","back":"By the chain rule, y'' = 5(3x^2 + 1)^4 * 6x = 30x(3x^2 + 1)^4."},{"id":"math-ua-121-14","front":"Derivatives of sin x, cos x and tan x","back":"d/dx sin x = cos x; d/dx cos x = -sin x; d/dx tan x = sec^2 x."},{"id":"math-ua-121-15","front":"Derivatives of e^x and ln x","back":"d/dx e^x = e^x; d/dx ln x = 1/x for x > 0. More generally d/dx a^x = a^x * ln a."},{"id":"math-ua-121-16","front":"Implicit differentiation: find dy/dx for x^2 + y^2 = 25","back":"Differentiate both sides: 2x + 2y*(dy/dx) = 0, so dy/dx = -x/y."},{"id":"math-ua-121-17","front":"Strategy for related rates problems","back":"Draw and label a diagram, write an equation relating the quantities, differentiate both sides with respect to time t, then substitute known values only after differentiating."},{"id":"math-ua-121-18","front":"Linear approximation formula","back":"f(x) is approximately f(a) + f''(a)(x - a) for x near a; this is the tangent line at x = a."},{"id":"math-ua-121-19","front":"Critical number definition","back":"A number c in the domain of f where f''(c) = 0 or f''(c) does not exist. Local extrema can only occur at critical numbers."},{"id":"math-ua-121-20","front":"First derivative test","back":"If f'' changes from positive to negative at c, f has a local max at c; from negative to positive, a local min; no sign change means no local extremum."},{"id":"math-ua-121-21","front":"Second derivative test","back":"If f''(c) = 0 and f''''(c) > 0, local min at c; if f''''(c) < 0, local max; if f''''(c) = 0 the test is inconclusive."},{"id":"math-ua-121-22","front":"Concavity and inflection points","back":"f'''' > 0 means concave up and f'''' < 0 means concave down. An inflection point is where concavity changes."},{"id":"math-ua-121-23","front":"Closed interval method for absolute extrema","back":"For continuous f on [a, b], evaluate f at all critical numbers in (a, b) and at the endpoints a and b; the largest value is the absolute max and the smallest is the absolute min."},{"id":"math-ua-121-24","front":"Mean Value Theorem","back":"If f is continuous on [a, b] and differentiable on (a, b), there is some c in (a, b) with f''(c) = [f(b) - f(a)] / (b - a)."},{"id":"math-ua-121-25","front":"L''Hopital''s rule","back":"If lim f/g gives 0/0 or infinity/infinity, then lim f(x)/g(x) = lim f''(x)/g''(x), provided the latter limit exists. Do not use it for other forms without rewriting first."},{"id":"math-ua-121-26","front":"Horizontal asymptote of (3x^2 + 1)/(5x^2 - x)","back":"Degrees of numerator and denominator are equal, so the limit as x goes to infinity is the ratio of leading coefficients: y = 3/5."},{"id":"math-ua-121-27","front":"Antiderivative of x^n (n not -1)","back":"Integral of x^n dx = x^(n+1)/(n+1) + C. For n = -1, the integral of 1/x dx = ln|x| + C."},{"id":"math-ua-121-28","front":"Fundamental Theorem of Calculus, Part 2","back":"If F is an antiderivative of continuous f on [a, b], then the integral from a to b of f(x) dx = F(b) - F(a)."},{"id":"math-ua-121-29","front":"Compute the integral from 0 to 2 of 3x^2 dx","back":"An antiderivative is x^3, so the value is 2^3 - 0^3 = 8."},{"id":"math-ua-121-30","front":"Fundamental Theorem of Calculus, Part 1","back":"If g(x) = integral from a to x of f(t) dt with f continuous, then g''(x) = f(x)."}],"quizzes":[],"seed":1,"look":{"color":"#4F46E5","icon":"calc"}}'::jsonb);   -- https://bulletins.nyu.edu/courses/math_ua/
select pg_temp.sb_seed('seed:rutgers-edu:01-119-115', 'rutgers.edu', '01:119:115', '01:119:115 General Biology I Review: Cells, Metabolism, Genetics, Evolution and Ecology', '{"v":1,"app":"studyboard","type":"deck","name":"01:119:115 General Biology I Review: Cells, Metabolism, Genetics, Evolution and Ecology","course":{"code":"01:119:115","name":"General Biology"},"cards":[{"id":"01-119-115-1","front":"Four major classes of biological macromolecules and their monomers","back":"Carbohydrates (monosaccharides), proteins (amino acids), nucleic acids (nucleotides) and lipids (not true polymers; fats are built from glycerol and fatty acids)."},{"id":"01-119-115-2","front":"Dehydration synthesis vs hydrolysis","back":"Dehydration synthesis joins monomers by removing a water molecule; hydrolysis breaks polymers apart by adding water."},{"id":"01-119-115-3","front":"Four levels of protein structure","back":"Primary: amino acid sequence. Secondary: alpha helices and beta sheets from backbone hydrogen bonds. Tertiary: overall 3D fold from R-group interactions. Quaternary: multiple polypeptide subunits."},{"id":"01-119-115-4","front":"Prokaryotic vs eukaryotic cells","back":"Prokaryotes (bacteria and archaea) lack a nucleus and membrane-bound organelles; eukaryotes have a nucleus, membrane-bound organelles and usually larger cells."},{"id":"01-119-115-5","front":"Endosymbiotic theory and its evidence","back":"Mitochondria and chloroplasts descend from engulfed prokaryotes. Evidence: they have their own circular DNA, double membranes, bacteria-like ribosomes and divide by fission."},{"id":"01-119-115-6","front":"Fluid mosaic model","back":"The plasma membrane is a phospholipid bilayer with proteins embedded in or attached to it, and its components can move laterally."},{"id":"01-119-115-7","front":"Osmosis: what happens to an animal cell in a hypotonic solution?","back":"Water moves into the cell because the solution has a lower solute concentration than the cytoplasm, so the cell swells and may burst (lyse)."},{"id":"01-119-115-8","front":"Passive vs active transport","back":"Passive transport (diffusion, facilitated diffusion, osmosis) moves substances down their concentration gradient without energy input; active transport moves them against it using energy, usually ATP, as in the sodium-potassium pump."},{"id":"01-119-115-9","front":"How do enzymes speed up reactions?","back":"They lower the activation energy by binding substrates at the active site; they do not change the overall free energy change (delta G) of the reaction."},{"id":"01-119-115-10","front":"Competitive vs noncompetitive inhibition","back":"A competitive inhibitor binds the active site and can be outcompeted by more substrate. A noncompetitive inhibitor binds elsewhere and changes the enzyme''s shape, reducing activity regardless of substrate level."},{"id":"01-119-115-11","front":"Overall equation for cellular respiration","back":"C6H12O6 + 6 O2 -> 6 CO2 + 6 H2O + energy (ATP and heat)."},{"id":"01-119-115-12","front":"Stages of aerobic respiration and where they occur","back":"Glycolysis (cytosol), pyruvate oxidation and the citric acid cycle (mitochondrial matrix), and oxidative phosphorylation via the electron transport chain and chemiosmosis (inner mitochondrial membrane)."},{"id":"01-119-115-13","front":"Role of oxygen in cellular respiration","back":"Oxygen is the final electron acceptor of the electron transport chain, combining with electrons and H+ to form water."},{"id":"01-119-115-14","front":"Why does fermentation occur and what does it regenerate?","back":"Without oxygen, cells use fermentation to regenerate NAD+ from NADH so glycolysis can continue producing a small amount of ATP; products include lactate or ethanol plus CO2."},{"id":"01-119-115-15","front":"Light reactions vs Calvin cycle","back":"Light reactions (thylakoid membranes) split water, release O2 and make ATP and NADPH. The Calvin cycle (stroma) uses that ATP and NADPH to fix CO2 into sugar, with rubisco as the key enzyme."},{"id":"01-119-115-16","front":"Phases of mitosis in order","back":"Prophase, prometaphase, metaphase, anaphase and telophase, usually followed by cytokinesis."},{"id":"01-119-115-17","front":"Mitosis vs meiosis","back":"Mitosis produces two genetically identical diploid cells for growth and repair. Meiosis has two divisions and produces four genetically different haploid gametes."},{"id":"01-119-115-18","front":"Sources of genetic variation in meiosis","back":"Crossing over between homologous chromosomes in prophase I, independent assortment of homologs in metaphase I, and random fertilization."},{"id":"01-119-115-19","front":"Central dogma of molecular biology","back":"DNA is transcribed into mRNA, and mRNA is translated into protein by ribosomes."},{"id":"01-119-115-20","front":"Key features of DNA replication","back":"It is semiconservative; DNA polymerase adds nucleotides only in the 5'' to 3'' direction, so the leading strand is made continuously and the lagging strand in Okazaki fragments joined by ligase."},{"id":"01-119-115-21","front":"Role of tRNA in translation","back":"Each tRNA carries a specific amino acid and has an anticodon that base-pairs with a complementary mRNA codon in the ribosome."},{"id":"01-119-115-22","front":"The lac operon: what happens when lactose is present?","back":"Lactose (as allolactose) binds the repressor, releasing it from the operator so RNA polymerase can transcribe the genes for lactose metabolism."},{"id":"01-119-115-23","front":"Mendel''s law of segregation","back":"Each organism has two alleles for a gene, and they separate during gamete formation so each gamete carries only one allele."},{"id":"01-119-115-24","front":"Mini-problem: cross Aa x Aa. Expected genotype and phenotype ratios?","back":"Genotypes 1 AA : 2 Aa : 1 aa; phenotypes 3 dominant : 1 recessive."},{"id":"01-119-115-25","front":"Incomplete dominance vs codominance","back":"Incomplete dominance: heterozygote has an intermediate phenotype (red x white gives pink). Codominance: both alleles are fully expressed (AB blood type)."},{"id":"01-119-115-26","front":"Why are X-linked recessive disorders more common in males?","back":"Males have one X chromosome, so a single recessive allele on that X is expressed; females need two copies."},{"id":"01-119-115-27","front":"Hardy-Weinberg equations and what they assume","back":"p + q = 1 and p^2 + 2pq + q^2 = 1. Assumes no mutation, random mating, no natural selection, a very large population (no drift) and no gene flow."},{"id":"01-119-115-28","front":"Mini-problem: 16 percent of a population shows a recessive trait. What is the frequency of the recessive allele?","back":"q^2 = 0.16, so q = 0.4."},{"id":"01-119-115-29","front":"Natural selection: what conditions are required?","back":"Heritable variation among individuals, more offspring produced than can survive, and differential survival and reproduction based on traits."},{"id":"01-119-115-30","front":"Prezygotic vs postzygotic reproductive barriers","back":"Prezygotic barriers prevent mating or fertilization (habitat, behavioral, temporal, mechanical, gametic isolation). Postzygotic barriers act after fertilization (hybrid inviability, sterility or breakdown)."},{"id":"01-119-115-31","front":"Logistic vs exponential population growth","back":"Exponential growth is unlimited J-shaped growth (dN/dt = rN). Logistic growth slows as population nears carrying capacity K, producing an S-shaped curve (dN/dt = rN(K - N)/K)."},{"id":"01-119-115-32","front":"Roughly what fraction of energy passes from one trophic level to the next?","back":"About 10 percent; the rest is lost mainly as heat through metabolism, which limits the length of food chains."}],"quizzes":[],"seed":1,"look":{"color":"#16A34A","icon":"bio"}}'::jsonb);   -- https://biology.rutgers.edu/academics/undergraduate/courses/detail/28-biological-sciences-courses-3/52-01-119-115-116-general-biology
select pg_temp.sb_seed('seed:rutgers-edu:01-160-161', 'rutgers.edu', '01:160:161', '01:160:161 General Chemistry Review: Stoichiometry, Gases, Atomic Structure, Bonding and Thermochemistry', '{"v":1,"app":"studyboard","type":"deck","name":"01:160:161 General Chemistry Review: Stoichiometry, Gases, Atomic Structure, Bonding and Thermochemistry","course":{"code":"01:160:161","name":"General Chemistry"},"cards":[{"id":"01-160-161-1","front":"What is a mole?","back":"A mole is 6.022 x 10^23 particles (Avogadro''s number). The molar mass in grams per mole equals the formula mass in atomic mass units."},{"id":"01-160-161-2","front":"Mini-problem: how many moles are in 36.0 g of water (H2O, 18.0 g/mol)?","back":"36.0 g / 18.0 g/mol = 2.00 mol."},{"id":"01-160-161-3","front":"Limiting reactant","back":"The reactant that is completely used up first; it determines the maximum amount of product that can form (the theoretical yield)."},{"id":"01-160-161-4","front":"Percent yield formula","back":"Percent yield = (actual yield / theoretical yield) x 100."},{"id":"01-160-161-5","front":"Molarity definition","back":"M = moles of solute / liters of solution."},{"id":"01-160-161-6","front":"Dilution equation","back":"M1V1 = M2V2: moles of solute stay the same when a solution is diluted."},{"id":"01-160-161-7","front":"Empirical vs molecular formula","back":"The empirical formula is the simplest whole-number ratio of atoms (CH2O for glucose); the molecular formula is the actual number of each atom (C6H12O6)."},{"id":"01-160-161-8","front":"Oxidation vs reduction","back":"Oxidation is loss of electrons (oxidation number increases); reduction is gain of electrons (oxidation number decreases). Mnemonic: OIL RIG."},{"id":"01-160-161-9","front":"Ideal gas law with symbols","back":"PV = nRT: P pressure, V volume, n moles, R gas constant (0.08206 L atm / mol K), T temperature in kelvin."},{"id":"01-160-161-10","front":"Pitfall in gas law problems","back":"Temperature must be in kelvin (K = degrees C + 273.15); using Celsius gives wrong answers."},{"id":"01-160-161-11","front":"Dalton''s law of partial pressures","back":"The total pressure of a gas mixture equals the sum of the partial pressures of each gas; partial pressure of gas A = mole fraction of A x total pressure."},{"id":"01-160-161-12","front":"Kinetic molecular theory: what does average kinetic energy depend on?","back":"Only absolute temperature. At the same temperature, lighter gas molecules move faster on average than heavier ones."},{"id":"01-160-161-13","front":"Graham''s law of effusion","back":"rate1 / rate2 = square root of (M2 / M1): lighter gases effuse faster."},{"id":"01-160-161-14","front":"Relationship between wavelength, frequency and photon energy","back":"c = wavelength x frequency, and E = h x frequency, so shorter wavelength means higher frequency and higher energy photons."},{"id":"01-160-161-15","front":"Four quantum numbers","back":"n (principal: energy level and size), l (angular momentum: subshell shape, 0 to n - 1), ml (magnetic: orbital orientation) and ms (spin, +1/2 or -1/2)."},{"id":"01-160-161-16","front":"Pauli exclusion principle and Hund''s rule","back":"Pauli: no two electrons in an atom have the same four quantum numbers, so an orbital holds at most two electrons of opposite spin. Hund: electrons fill degenerate orbitals singly before pairing."},{"id":"01-160-161-17","front":"Electron configuration of oxygen (Z = 8)","back":"1s2 2s2 2p4."},{"id":"01-160-161-18","front":"Periodic trends in atomic radius","back":"Atomic radius decreases across a period (greater effective nuclear charge) and increases down a group (more electron shells)."},{"id":"01-160-161-19","front":"Periodic trends in ionization energy and electronegativity","back":"Both generally increase across a period and decrease down a group. Fluorine is the most electronegative element."},{"id":"01-160-161-20","front":"Ionic vs covalent bonds","back":"Ionic bonds form from electron transfer and electrostatic attraction between ions (often metal + nonmetal). Covalent bonds form from shared electron pairs (usually between nonmetals)."},{"id":"01-160-161-21","front":"Formal charge formula","back":"Formal charge = valence electrons - nonbonding electrons - (bonding electrons / 2). The best Lewis structure minimizes formal charges."},{"id":"01-160-161-22","front":"VSEPR: geometry of a molecule with 4 electron domains and 2 lone pairs (like H2O)","back":"Electron geometry is tetrahedral, molecular geometry is bent, with a bond angle slightly less than 109.5 degrees (about 104.5 for water)."},{"id":"01-160-161-23","front":"Hybridization for 2, 3 and 4 electron domains","back":"2 domains: sp (linear). 3 domains: sp2 (trigonal planar). 4 domains: sp3 (tetrahedral)."},{"id":"01-160-161-24","front":"Sigma vs pi bonds","back":"A single bond is one sigma bond; a double bond is one sigma and one pi; a triple bond is one sigma and two pi. Pi bonds come from side-by-side p orbital overlap."},{"id":"01-160-161-25","front":"How can a molecule with polar bonds be nonpolar? Give an example.","back":"If its geometry is symmetric, the bond dipoles cancel. CO2 is linear with two polar C=O bonds but no net dipole."},{"id":"01-160-161-26","front":"Rank the intermolecular forces from weakest to strongest","back":"London dispersion forces < dipole-dipole forces < hydrogen bonding (H bonded to N, O or F). Ion-dipole forces are stronger still."},{"id":"01-160-161-27","front":"Endothermic vs exothermic reactions","back":"Exothermic reactions release heat (delta H < 0); endothermic reactions absorb heat (delta H > 0)."},{"id":"01-160-161-28","front":"Heat equation q = m c delta T","back":"q is heat, m is mass, c is specific heat capacity and delta T is the temperature change. For water, c = 4.184 J/g C."},{"id":"01-160-161-29","front":"Hess''s law","back":"The enthalpy change of a reaction is the same regardless of path, so delta H values of steps can be added; reversing a reaction flips the sign and multiplying it scales delta H."},{"id":"01-160-161-30","front":"Enthalpy of reaction from enthalpies of formation","back":"Delta H rxn = sum of n x delta Hf(products) - sum of n x delta Hf(reactants). Elements in their standard states have delta Hf = 0."}],"quizzes":[],"seed":1,"look":{"color":"#E0673B","icon":"chem"}}'::jsonb);   -- https://chem.rutgers.edu/academics/undergraduate-program/undergraduate-course-descriptions/course-descriptions/1896-01-160-161-general-chemistry
select pg_temp.sb_seed('seed:rutgers-edu:01-920-101', 'rutgers.edu', '01:920:101', '01:920:101 Introduction to Sociology Review: Theory, Methods, Culture, Inequality and Institutions', '{"v":1,"app":"studyboard","type":"deck","name":"01:920:101 Introduction to Sociology Review: Theory, Methods, Culture, Inequality and Institutions","course":{"code":"01:920:101","name":"Introduction to Sociology"},"cards":[{"id":"01-920-101-1","front":"The sociological imagination (C. Wright Mills)","back":"The ability to see connections between personal experiences and larger social forces and history; for example, seeing one person''s job loss as part of a broader economic pattern."},{"id":"01-920-101-2","front":"Personal troubles vs public issues","back":"Personal troubles affect an individual and their immediate surroundings; public issues are problems of social structure that affect many people, such as mass unemployment."},{"id":"01-920-101-3","front":"Structural functionalism","back":"A macro perspective that views society as a system of interrelated parts, each serving a function that contributes to stability. Associated with Durkheim, Parsons and Merton."},{"id":"01-920-101-4","front":"Manifest vs latent functions (Merton)","back":"Manifest functions are intended and recognized consequences; latent functions are unintended and often unrecognized. College''s manifest function is education; a latent one is meeting future partners."},{"id":"01-920-101-5","front":"Conflict theory","back":"A macro perspective that views society as an arena of inequality and competition over scarce resources, where powerful groups maintain their advantage. Rooted in Marx."},{"id":"01-920-101-6","front":"Symbolic interactionism","back":"A micro perspective focused on how people create and interpret shared meanings through everyday interaction and symbols. Associated with Mead and Blumer."},{"id":"01-920-101-7","front":"Marx''s bourgeoisie vs proletariat","back":"The bourgeoisie own the means of production; the proletariat sell their labor for wages. Marx argued their opposed interests drive class conflict."},{"id":"01-920-101-8","front":"Durkheim''s study of suicide showed what?","back":"Suicide rates vary with social integration and regulation, so even a seemingly individual act is shaped by social forces."},{"id":"01-920-101-9","front":"Weber''s three dimensions of stratification","back":"Class (economic position), status (social prestige) and party (political power)."},{"id":"01-920-101-10","front":"Weber''s concept of verstehen","back":"Interpretive understanding: grasping the subjective meanings people attach to their actions."},{"id":"01-920-101-11","front":"Quantitative vs qualitative research","back":"Quantitative research uses numerical data and statistics (surveys, experiments); qualitative research uses non-numerical data such as interviews and participant observation to understand meaning."},{"id":"01-920-101-12","front":"Reliability vs validity","back":"Reliability is the consistency of a measure across repeated use; validity is whether it actually measures what it claims to measure."},{"id":"01-920-101-13","front":"Ethnography / participant observation","back":"A method in which the researcher spends extended time in a group''s natural setting, observing and often participating, to understand its culture from the inside."},{"id":"01-920-101-14","front":"Material vs nonmaterial culture","back":"Material culture is physical objects people create (tools, buildings); nonmaterial culture is ideas, values, beliefs, norms and language."},{"id":"01-920-101-15","front":"Folkways vs mores vs laws","back":"Folkways are informal everyday norms with mild sanctions; mores are norms with strong moral weight; laws are formal norms enforced by the state."},{"id":"01-920-101-16","front":"Ethnocentrism vs cultural relativism","back":"Ethnocentrism judges other cultures by the standards of one''s own; cultural relativism tries to understand a culture on its own terms."},{"id":"01-920-101-17","front":"Subculture vs counterculture","back":"A subculture shares many mainstream values but has distinctive features; a counterculture actively rejects and opposes key mainstream values."},{"id":"01-920-101-18","front":"Primary vs secondary socialization agents","back":"Primary socialization occurs early, mainly through family; secondary socialization continues through school, peers, media and workplaces."},{"id":"01-920-101-19","front":"Looking-glass self (Cooley)","back":"Our self-concept develops from how we imagine others see and judge us."},{"id":"01-920-101-20","front":"Mead''s I and me","back":"The me is the socialized self that reflects others'' expectations; the I is the spontaneous, active part of the self that responds."},{"id":"01-920-101-21","front":"Ascribed vs achieved status","back":"An ascribed status is assigned at birth or involuntarily (race, age); an achieved status is earned or chosen (college graduate, doctor)."},{"id":"01-920-101-22","front":"Role strain vs role conflict","back":"Role strain is tension among demands within one role (a student with too many assignments); role conflict is tension between two different roles (parent and employee)."},{"id":"01-920-101-23","front":"Primary vs secondary groups","back":"Primary groups are small, intimate and long-lasting (family, close friends); secondary groups are larger, impersonal and goal-oriented (a work team, a class)."},{"id":"01-920-101-24","front":"Labeling theory of deviance","back":"Deviance is not inherent in an act but results from others applying a deviant label; being labeled can push people toward further deviance."},{"id":"01-920-101-25","front":"Merton''s strain theory","back":"Deviance arises when people lack legitimate means to reach culturally approved goals; responses include conformity, innovation, ritualism, retreatism and rebellion."},{"id":"01-920-101-26","front":"Open vs closed stratification systems","back":"Open systems (class systems) allow movement between strata based on achievement; closed systems (caste systems) assign position at birth with little mobility."},{"id":"01-920-101-27","front":"Intergenerational vs intragenerational mobility","back":"Intergenerational mobility compares a person''s social position to their parents''; intragenerational mobility is change within one person''s lifetime."},{"id":"01-920-101-28","front":"Sex vs gender","back":"Sex refers to biological characteristics; gender refers to the socially constructed roles, behaviors and identities a society associates with being a man or woman."},{"id":"01-920-101-29","front":"Race as a social construction","back":"Racial categories are not fixed biological facts; they are created and given meaning by societies and change over time and place."},{"id":"01-920-101-30","front":"Prejudice vs discrimination vs institutional racism","back":"Prejudice is a biased attitude; discrimination is unequal treatment (behavior); institutional racism is inequality built into the policies and practices of organizations and systems."},{"id":"01-920-101-31","front":"Weber''s ideal type of bureaucracy","back":"A formal organization with hierarchy of authority, division of labor, written rules, impersonality and hiring based on technical qualifications."}],"quizzes":[],"seed":1,"look":{"color":"#D6386F","icon":"soc"}}'::jsonb);   -- https://sociology.rutgers.edu/academics/undergraduate/course-descriptions/course-descriptions/335-01920101-introduction-to-sociology
select pg_temp.sb_seed('seed:msu-edu:stt-200', 'msu.edu', 'STT 200', 'STT 200 Exam Review: Data Analysis, Probability, Confidence Intervals, Hypothesis Tests and Regression', '{"v":1,"app":"studyboard","type":"deck","name":"STT 200 Exam Review: Data Analysis, Probability, Confidence Intervals, Hypothesis Tests and Regression","course":{"code":"STT 200","name":"Statistical Methods"},"cards":[{"id":"stt-200-1","front":"Population vs sample; parameter vs statistic","back":"A population is the entire group of interest and a parameter describes it (mu, p). A sample is a subset actually measured and a statistic describes it (x-bar, p-hat)."},{"id":"stt-200-2","front":"Categorical vs quantitative variables","back":"Categorical variables place individuals into groups (major, eye color); quantitative variables take numerical values for which arithmetic makes sense (height, income)."},{"id":"stt-200-3","front":"Mean vs median when a distribution is right-skewed","back":"The mean is pulled toward the long right tail, so mean > median. The median is resistant to outliers and better describes the center of skewed data."},{"id":"stt-200-4","front":"IQR and the 1.5 x IQR outlier rule","back":"IQR = Q3 - Q1. A value is flagged as an outlier if it is below Q1 - 1.5 x IQR or above Q3 + 1.5 x IQR."},{"id":"stt-200-5","front":"Z-score formula and meaning","back":"z = (x - mean) / standard deviation. It tells how many standard deviations a value is above (positive) or below (negative) the mean."},{"id":"stt-200-6","front":"68-95-99.7 rule","back":"For a normal distribution, about 68 percent of values fall within 1 SD of the mean, 95 percent within 2 SD, and 99.7 percent within 3 SD."},{"id":"stt-200-7","front":"Observational study vs experiment","back":"In an observational study researchers measure without intervening; in an experiment they assign treatments. Only well-designed randomized experiments can establish cause and effect."},{"id":"stt-200-8","front":"Simple random sample and a common source of bias","back":"An SRS gives every possible sample of size n an equal chance of selection. Voluntary response samples are biased because people with strong opinions are more likely to respond."},{"id":"stt-200-9","front":"Addition rule for probability","back":"P(A or B) = P(A) + P(B) - P(A and B). If A and B are disjoint, P(A and B) = 0."},{"id":"stt-200-10","front":"Independent vs disjoint events: common pitfall","back":"Disjoint events cannot happen together. Independent events do not affect each other''s probabilities: P(A and B) = P(A) x P(B). Disjoint events with nonzero probabilities are never independent."},{"id":"stt-200-11","front":"Conditional probability formula","back":"P(A | B) = P(A and B) / P(B): the probability of A given that B has occurred."},{"id":"stt-200-12","front":"Expected value of a discrete random variable","back":"E(X) = sum of x x P(x), the long-run average value of X over many repetitions."},{"id":"stt-200-13","front":"Conditions for a binomial setting","back":"A fixed number n of trials, two outcomes (success or failure), independent trials, and the same probability of success p on each trial."},{"id":"stt-200-14","front":"Binomial mean and standard deviation","back":"Mean = n x p; standard deviation = square root of n x p x (1 - p)."},{"id":"stt-200-15","front":"Sampling distribution of the sample mean","back":"x-bar has mean mu and standard deviation sigma divided by square root of n. Larger samples give less variable sample means."},{"id":"stt-200-16","front":"Central Limit Theorem","back":"For a large enough sample size (a common guideline is n of at least 30), the sampling distribution of x-bar is approximately normal, regardless of the population''s shape."},{"id":"stt-200-17","front":"General form of a confidence interval","back":"Estimate plus or minus margin of error, where margin of error = critical value x standard error."},{"id":"stt-200-18","front":"Correct interpretation of a 95 percent confidence interval","back":"We are 95 percent confident the interval captures the true parameter; 95 percent of intervals built this way would contain it. It is not a 95 percent chance that the parameter is in this specific interval."},{"id":"stt-200-19","front":"How does sample size affect the margin of error?","back":"Margin of error shrinks as n grows, in proportion to 1 / square root of n; to cut it in half you need about four times the sample size."},{"id":"stt-200-20","front":"Confidence interval for a proportion","back":"p-hat plus or minus z* x square root of [p-hat(1 - p-hat) / n]. For 95 percent confidence, z* = 1.96."},{"id":"stt-200-21","front":"Null vs alternative hypothesis","back":"The null hypothesis H0 states no effect or no difference (parameter equals a specific value). The alternative Ha states what we are looking for evidence of (greater than, less than or not equal)."},{"id":"stt-200-22","front":"Definition of a p-value","back":"The probability, assuming H0 is true, of getting a test statistic at least as extreme as the one observed. A small p-value is evidence against H0."},{"id":"stt-200-23","front":"Decision rule using significance level alpha","back":"If p-value is at most alpha (often 0.05), reject H0; otherwise fail to reject H0. We never accept or prove H0."},{"id":"stt-200-24","front":"Type I vs Type II error","back":"Type I: rejecting H0 when it is actually true (probability alpha). Type II: failing to reject H0 when it is actually false (probability beta). Power = 1 - beta."},{"id":"stt-200-25","front":"When should you use a t procedure instead of z for a mean?","back":"When the population standard deviation sigma is unknown and estimated by the sample s; use a t distribution with n - 1 degrees of freedom."},{"id":"stt-200-26","front":"Correlation coefficient r: key properties","back":"r ranges from -1 to 1, measures the strength and direction of a linear relationship, has no units, and is not resistant to outliers."},{"id":"stt-200-27","front":"Least-squares regression line and slope interpretation","back":"y-hat = b0 + b1 x. The slope b1 is the predicted change in y for each one-unit increase in x."},{"id":"stt-200-28","front":"What is a residual?","back":"Residual = observed y - predicted y-hat. The least-squares line minimizes the sum of squared residuals."},{"id":"stt-200-29","front":"Meaning of r^2 in simple linear regression","back":"The fraction of the variation in y explained by the linear relationship with x. For r = 0.6, r^2 = 0.36, so 36 percent is explained."},{"id":"stt-200-30","front":"Extrapolation pitfall","back":"Using a regression line to predict far outside the range of observed x values is unreliable because the linear pattern may not continue."}],"quizzes":[],"seed":1,"look":{"color":"#1D9BB8","icon":"stats"}}'::jsonb);   -- https://reg.msu.edu/Courses/Request.aspx?SubjectCode=STT&CourseNumber=200
select pg_temp.sb_seed('seed:msu-edu:acc-201', 'msu.edu', 'ACC 201', 'ACC 201 Exam Review: Financial Statements, Transaction Analysis, Accruals, Inventory and Assets', '{"v":1,"app":"studyboard","type":"deck","name":"ACC 201 Exam Review: Financial Statements, Transaction Analysis, Accruals, Inventory and Assets","course":{"code":"ACC 201","name":"Principles of Financial Accounting"},"cards":[{"id":"acc-201-1","front":"The basic accounting equation","back":"Assets = Liabilities + Stockholders'' Equity. Every transaction keeps this equation in balance."},{"id":"acc-201-2","front":"Four main financial statements","back":"Income statement (revenues and expenses over a period), statement of stockholders'' equity (or retained earnings), balance sheet (assets, liabilities and equity at a point in time) and statement of cash flows."},{"id":"acc-201-3","front":"Normal balances: which accounts increase with a debit?","back":"Assets, expenses and dividends increase with debits. Liabilities, stockholders'' equity (including common stock and retained earnings) and revenues increase with credits."},{"id":"acc-201-4","front":"Journal entry: company borrows 10,000 cash from a bank","back":"Debit Cash 10,000; credit Notes Payable 10,000. Assets and liabilities both rise."},{"id":"acc-201-5","front":"Journal entry: company provides services on account for 2,000","back":"Debit Accounts Receivable 2,000; credit Service Revenue 2,000. Revenue is recognized when earned, not when cash is received."},{"id":"acc-201-6","front":"Revenue recognition principle","back":"Revenue is recognized when the company satisfies its performance obligation by transferring goods or services to the customer, regardless of when cash is collected."},{"id":"acc-201-7","front":"Expense recognition (matching) principle","back":"Expenses are recorded in the same period as the revenues they help generate."},{"id":"acc-201-8","front":"Accrual vs cash basis accounting","back":"Accrual basis records revenues when earned and expenses when incurred; cash basis records them only when cash changes hands. GAAP requires the accrual basis."},{"id":"acc-201-9","front":"Four types of adjusting entries","back":"Deferred (prepaid) expenses, deferred (unearned) revenues, accrued expenses and accrued revenues."},{"id":"acc-201-10","front":"Adjusting entry: 300 of prepaid insurance has expired","back":"Debit Insurance Expense 300; credit Prepaid Insurance 300."},{"id":"acc-201-11","front":"Adjusting entry: 500 of wages earned but unpaid at period end","back":"Debit Wages Expense 500; credit Wages Payable 500."},{"id":"acc-201-12","front":"Unearned revenue: what kind of account is it?","back":"A liability. The company has received cash but still owes goods or services; it becomes revenue as the obligation is fulfilled."},{"id":"acc-201-13","front":"Purpose of closing entries","back":"To reset temporary accounts (revenues, expenses, dividends) to zero and transfer their net balance to Retained Earnings at period end."},{"id":"acc-201-14","front":"Retained earnings roll-forward","back":"Ending retained earnings = beginning retained earnings + net income - dividends."},{"id":"acc-201-15","front":"Current vs noncurrent assets","back":"Current assets are expected to be converted to cash or used up within one year or the operating cycle (cash, receivables, inventory); noncurrent assets last longer (equipment, intangibles)."},{"id":"acc-201-16","front":"Allowance method for bad debts","back":"Estimated uncollectible accounts are recorded as Bad Debt Expense with a credit to Allowance for Doubtful Accounts, a contra-asset that reduces receivables to net realizable value."},{"id":"acc-201-17","front":"Writing off a specific uncollectible account under the allowance method","back":"Debit Allowance for Doubtful Accounts; credit Accounts Receivable. This entry does not affect net income or net receivables."},{"id":"acc-201-18","front":"Cost of goods sold formula","back":"COGS = beginning inventory + purchases - ending inventory."},{"id":"acc-201-19","front":"FIFO vs LIFO when prices are rising","back":"FIFO assigns the oldest (cheaper) costs to COGS, so it gives lower COGS, higher net income and higher ending inventory. LIFO gives higher COGS and lower net income. LIFO is not allowed under IFRS."},{"id":"acc-201-20","front":"Gross profit formula","back":"Gross profit = net sales - cost of goods sold."},{"id":"acc-201-21","front":"Straight-line depreciation formula","back":"Annual depreciation = (cost - residual value) / useful life in years."},{"id":"acc-201-22","front":"Mini-problem: equipment costs 50,000, residual value 5,000, useful life 5 years. Straight-line depreciation per year?","back":"(50,000 - 5,000) / 5 = 9,000 per year."},{"id":"acc-201-23","front":"Book value (carrying value) of a long-lived asset","back":"Cost minus accumulated depreciation. Accumulated depreciation is a contra-asset account."},{"id":"acc-201-24","front":"Capital expenditure vs revenue expenditure","back":"Capital expenditures add to an asset''s useful life or capacity and are capitalized; ordinary repairs and maintenance are expensed as incurred."},{"id":"acc-201-25","front":"Three sections of the statement of cash flows","back":"Operating activities (core business), investing activities (buying or selling long-term assets and investments) and financing activities (debt, issuing stock, paying dividends)."},{"id":"acc-201-26","front":"Where are dividends paid and interest paid classified under US GAAP?","back":"Dividends paid are financing activities; interest paid is an operating activity."},{"id":"acc-201-27","front":"Current ratio formula and meaning","back":"Current ratio = current assets / current liabilities. It measures short-term liquidity; higher means more ability to pay short-term obligations."},{"id":"acc-201-28","front":"Debt to assets ratio","back":"Total liabilities / total assets. It measures the share of assets financed with debt, an indicator of solvency risk."},{"id":"acc-201-29","front":"Historical cost principle","back":"Assets are generally recorded at their original cost when acquired, not at their later market value."},{"id":"acc-201-30","front":"GAAP vs IFRS: who sets each?","back":"In the US, GAAP is set by the Financial Accounting Standards Board (FASB). IFRS is set by the International Accounting Standards Board (IASB) and is used in many other countries."}],"quizzes":[],"seed":1,"look":{"color":"#C79A12","icon":"acct"}}'::jsonb);   -- https://reg.msu.edu/Courses/Request.aspx?SubjectCode=ACC&CourseNumber=201
select pg_temp.sb_seed('seed:msu-edu:cse-231', 'msu.edu', 'CSE 231', 'CSE 231 Exam Review: Python Fundamentals, Control Flow, Functions, Collections, Files and Classes', '{"v":1,"app":"studyboard","type":"deck","name":"CSE 231 Exam Review: Python Fundamentals, Control Flow, Functions, Collections, Files and Classes","course":{"code":"CSE 231","name":"Introduction to Programming I"},"cards":[{"id":"cse-231-1","front":"Result of 7 / 2, 7 // 2 and 7 % 2 in Python 3","back":"7 / 2 is 3.5 (true division, float); 7 // 2 is 3 (floor division); 7 % 2 is 1 (remainder)."},{"id":"cse-231-2","front":"What does int(''42'') + 1 return, and what does ''42'' + 1 do?","back":"int(''42'') + 1 returns 43. ''42'' + 1 raises a TypeError because you cannot add a str and an int."},{"id":"cse-231-3","front":"Mutable vs immutable types in Python","back":"Lists, dictionaries and sets are mutable (can change in place). Integers, floats, strings and tuples are immutable."},{"id":"cse-231-4","front":"What does ''python''[1:4] evaluate to?","back":"''yth''. Slicing includes the start index and excludes the stop index; indexing starts at 0."},{"id":"cse-231-5","front":"What does s[-1] return for a string s?","back":"The last character. Negative indexes count from the end, so s[-2] is the second-to-last."},{"id":"cse-231-6","front":"Why does s[0] = ''X'' fail for a string s?","back":"Strings are immutable, so item assignment raises a TypeError. Build a new string instead, for example ''X'' + s[1:]."},{"id":"cse-231-7","front":"What values does range(2, 10, 3) produce?","back":"2, 5, 8. The stop value 10 is excluded."},{"id":"cse-231-8","front":"for loop vs while loop","back":"A for loop iterates over each item of a sequence or iterable; a while loop repeats as long as a condition is True and is used when the number of iterations is not known in advance."},{"id":"cse-231-9","front":"break vs continue","back":"break exits the loop entirely; continue skips the rest of the current iteration and moves on to the next one."},{"id":"cse-231-10","front":"Common infinite loop pitfall in a while loop","back":"Forgetting to update the variable in the loop condition, so the condition never becomes False."},{"id":"cse-231-11","front":"Difference between = and ==","back":"= assigns a value to a variable; == compares two values and returns True or False."},{"id":"cse-231-12","front":"How does if / elif / else evaluate?","back":"Conditions are checked top to bottom; only the first True branch runs. else runs only if none of the conditions were True."},{"id":"cse-231-13","front":"Short-circuit evaluation of and / or","back":"With and, if the left side is False the right side is not evaluated; with or, if the left side is True the right side is not evaluated."},{"id":"cse-231-14","front":"print vs return in a function","back":"print displays a value on screen; return sends a value back to the caller. A function with no return statement returns None."},{"id":"cse-231-15","front":"Local vs global scope","back":"Variables assigned inside a function are local to it and disappear when it returns; globals are defined at the top level of the module. Use parameters and return values instead of modifying globals."},{"id":"cse-231-16","front":"Default parameter values","back":"def greet(name, greeting=''Hi''): lets callers omit greeting. Parameters with defaults must come after those without."},{"id":"cse-231-17","front":"Pitfall: using a mutable default argument like def f(x, items=[])","back":"The default list is created once when the function is defined and is shared across calls, so items accumulate unexpectedly. Use items=None and create a new list inside."},{"id":"cse-231-18","front":"lst.append(x) vs lst.extend(seq)","back":"append adds x as a single element at the end; extend adds each element of seq individually."},{"id":"cse-231-19","front":"Aliasing: after b = a where a is a list, what happens when you run b.append(5)?","back":"a also changes, because a and b refer to the same list object. Use b = a.copy() or a[:] for a separate copy."},{"id":"cse-231-20","front":"What does sorted(lst) do vs lst.sort()?","back":"sorted(lst) returns a new sorted list and leaves lst unchanged; lst.sort() sorts the list in place and returns None."},{"id":"cse-231-21","front":"List comprehension for the squares of 0 through 4","back":"[x**2 for x in range(5)] gives [0, 1, 4, 9, 16]."},{"id":"cse-231-22","front":"Tuple vs list","back":"Both are ordered sequences, but tuples are immutable and are written with parentheses; they can be used as dictionary keys if their contents are hashable."},{"id":"cse-231-23","front":"Dictionary basics: what are keys and values?","back":"A dict maps unique, immutable (hashable) keys to values. Access with d[key]; d[key] raises KeyError if missing, while d.get(key, default) returns the default instead."},{"id":"cse-231-24","front":"How do you loop over a dictionary''s keys and values together?","back":"for key, value in d.items(): ..."},{"id":"cse-231-25","front":"Counting occurrences of words with a dictionary","back":"for w in words: counts[w] = counts.get(w, 0) + 1"},{"id":"cse-231-26","front":"Why use ''with open(name) as f:'' to read a file?","back":"The with statement automatically closes the file when the block ends, even if an error occurs."},{"id":"cse-231-27","front":"File modes ''r'', ''w'' and ''a''","back":"''r'' reads (error if missing), ''w'' writes and erases existing contents (creates file if missing), ''a'' appends to the end."},{"id":"cse-231-28","front":"What does line.strip().split('','') do?","back":"strip removes leading and trailing whitespace including the newline; split('','') breaks the string into a list of substrings at each comma."},{"id":"cse-231-29","front":"try / except: purpose","back":"Code in try runs normally; if a matching exception is raised, control jumps to the except block instead of crashing, for example except ValueError when converting user input with int()."},{"id":"cse-231-30","front":"Class vs object, and the role of __init__","back":"A class is a blueprint; an object is an instance of it. __init__ is the initializer method that runs when an object is created and typically sets instance attributes."},{"id":"cse-231-31","front":"What is self in a Python method?","back":"self is the first parameter of an instance method and refers to the specific object the method was called on, giving access to its attributes."},{"id":"cse-231-32","front":"What does defining __str__ in a class do?","back":"It returns the string used when the object is printed or passed to str(), giving a readable representation."}],"quizzes":[],"seed":1,"look":{"color":"#334155","icon":"code"}}'::jsonb);   -- https://reg.msu.edu/Courses/Request.aspx?SubjectCode=CSE&CourseNumber=231
select pg_temp.sb_seed('seed:uiuc-edu:psyc-100', 'uiuc.edu', 'PSYC 100', 'PSYC 100 Exam Review: Research Methods, Brain, Learning, Memory and Personality', '{"v":1,"app":"studyboard","type":"deck","name":"PSYC 100 Exam Review: Research Methods, Brain, Learning, Memory and Personality","course":{"code":"PSYC 100","name":"Intro Psych"},"cards":[{"id":"psyc-100-1","front":"Independent variable vs dependent variable","back":"The independent variable is what the experimenter manipulates; the dependent variable is the outcome that is measured to see whether it changed."},{"id":"psyc-100-2","front":"Why does correlation not imply causation?","back":"Two correlated variables may both be driven by a third variable, or the causal direction may run the other way. Only a controlled experiment with random assignment supports causal claims."},{"id":"psyc-100-3","front":"Random sampling vs random assignment","back":"Random sampling picks participants from a population so results generalize. Random assignment places participants into conditions by chance so groups are equivalent and causal conclusions are possible."},{"id":"psyc-100-4","front":"What is a double-blind study and why use it?","back":"Neither participants nor the researchers collecting data know who is in which condition. It reduces placebo effects and experimenter bias."},{"id":"psyc-100-5","front":"What does a correlation coefficient of r = -0.80 tell you?","back":"A strong negative linear relationship: as one variable increases, the other tends to decrease. The sign gives direction and the absolute value gives strength."},{"id":"psyc-100-6","front":"Operational definition","back":"A precise statement of how a variable will be measured or manipulated in a study, e.g. defining aggression as the number of times a child hits a doll in 10 minutes."},{"id":"psyc-100-7","front":"Parts of a neuron and the direction a signal travels","back":"Dendrites receive signals, the cell body integrates them, the axon carries the action potential away, and axon terminals release neurotransmitter into the synapse."},{"id":"psyc-100-8","front":"What is an action potential?","back":"A brief all-or-none electrical impulse that travels down the axon when the neuron''s membrane reaches threshold, caused by sodium ions rushing in and potassium ions flowing out."},{"id":"psyc-100-9","front":"Role of the myelin sheath","back":"A fatty insulating layer around many axons that speeds signal conduction. Its breakdown is the hallmark of multiple sclerosis."},{"id":"psyc-100-10","front":"Dopamine vs serotonin: main associations","back":"Dopamine: reward, motivation and movement (low levels in Parkinson''s disease). Serotonin: mood, sleep and appetite (low levels linked to depression)."},{"id":"psyc-100-11","front":"Functions of the four cerebral lobes","back":"Frontal: planning, decision making and motor control. Parietal: touch and spatial processing. Temporal: hearing and language comprehension. Occipital: vision."},{"id":"psyc-100-12","front":"Broca''s area vs Wernicke''s area","back":"Broca''s area (left frontal lobe) supports speech production; damage gives halting, effortful speech. Wernicke''s area (left temporal lobe) supports comprehension; damage gives fluent but meaningless speech."},{"id":"psyc-100-13","front":"Functions of the hippocampus and amygdala","back":"The hippocampus is key for forming new explicit long-term memories. The amygdala processes emotion, especially fear."},{"id":"psyc-100-14","front":"Sympathetic vs parasympathetic nervous system","back":"Sympathetic: fight-or-flight arousal (faster heart rate, dilated pupils). Parasympathetic: rest-and-digest calming that conserves energy."},{"id":"psyc-100-15","front":"Sensation vs perception","back":"Sensation is detecting physical energy with sense receptors. Perception is the brain organizing and interpreting that input into meaningful experience."},{"id":"psyc-100-16","front":"Classical conditioning: define US, UR, CS and CR using Pavlov''s dogs","back":"US = food, UR = salivation to food, CS = the tone after pairing with food, CR = salivation to the tone alone."},{"id":"psyc-100-17","front":"Extinction vs spontaneous recovery","back":"Extinction is the weakening of a conditioned response when the CS is presented without the US. Spontaneous recovery is the return of the weakened CR after a rest period."},{"id":"psyc-100-18","front":"Negative reinforcement vs punishment","back":"Negative reinforcement removes an unpleasant stimulus to increase a behavior (taking aspirin to remove a headache). Punishment decreases a behavior. They are not the same."},{"id":"psyc-100-19","front":"Which reinforcement schedule produces the most extinction-resistant behavior?","back":"Variable-ratio schedules, where reinforcement comes after an unpredictable number of responses (like slot machines), produce high steady responding that resists extinction."},{"id":"psyc-100-20","front":"What did Bandura''s Bobo doll study show?","back":"Children who watched an adult act aggressively toward a doll were more likely to imitate that aggression, showing observational learning without direct reinforcement."},{"id":"psyc-100-21","front":"Three stages of the multi-store (Atkinson-Shiffrin) memory model","back":"Sensory memory (very brief), short-term or working memory (about 7 plus or minus 2 items, seconds without rehearsal), and long-term memory (large capacity, long lasting)."},{"id":"psyc-100-22","front":"Explicit vs implicit memory","back":"Explicit (declarative) memory is consciously recalled facts and events. Implicit (nondeclarative) memory is unconscious, such as skills, priming and conditioned responses."},{"id":"psyc-100-23","front":"Proactive vs retroactive interference","back":"Proactive: old learning disrupts recall of new information. Retroactive: new learning disrupts recall of old information."},{"id":"psyc-100-24","front":"Serial position effect","back":"Items at the beginning (primacy) and end (recency) of a list are recalled better than items in the middle."},{"id":"psyc-100-25","front":"Availability heuristic","back":"Judging how likely an event is by how easily examples come to mind, which can make vivid events like plane crashes seem more common than they are."},{"id":"psyc-100-26","front":"Confirmation bias","back":"The tendency to search for and favor information that supports what you already believe while ignoring evidence against it."},{"id":"psyc-100-27","front":"Reliability vs validity of a test","back":"Reliability is consistency of scores across time or forms. Validity is whether the test measures what it claims to measure. A test can be reliable without being valid."},{"id":"psyc-100-28","front":"Fluid vs crystallized intelligence","back":"Fluid intelligence is reasoning and solving novel problems quickly; it tends to decline with age. Crystallized intelligence is accumulated knowledge and vocabulary; it tends to hold steady or grow."},{"id":"psyc-100-29","front":"The Big Five personality traits","back":"Openness, Conscientiousness, Extraversion, Agreeableness and Neuroticism (OCEAN)."},{"id":"psyc-100-30","front":"James-Lange vs Cannon-Bard theory of emotion","back":"James-Lange: we feel emotion because we perceive our body''s physiological response. Cannon-Bard: physiological arousal and emotional experience occur at the same time, independently."},{"id":"psyc-100-31","front":"Fundamental attribution error","back":"Overestimating personality and underestimating the situation when explaining other people''s behavior."}],"quizzes":[],"seed":1,"look":{"color":"#9A4FD1","icon":"psych"}}'::jsonb);   -- https://catalog.illinois.edu/courses-of-instruction/psyc/
select pg_temp.sb_seed('seed:uiuc-edu:chem-102', 'uiuc.edu', 'CHEM 102', 'CHEM 102 Exam Review: Atomic Structure, Bonding, Stoichiometry, Gases and Equilibrium', '{"v":1,"app":"studyboard","type":"deck","name":"CHEM 102 Exam Review: Atomic Structure, Bonding, Stoichiometry, Gases and Equilibrium","course":{"code":"CHEM 102","name":"General Chemistry I"},"cards":[{"id":"chem-102-1","front":"Avogadro''s number and what it means","back":"6.022 x 10^23 particles per mole. One mole of any substance contains that many atoms, molecules or formula units."},{"id":"chem-102-2","front":"How do you convert grams to moles?","back":"Divide the mass by the molar mass: n = m / M. Example: 36.0 g of water / 18.0 g/mol = 2.00 mol."},{"id":"chem-102-3","front":"Limiting reactant","back":"The reactant that runs out first and therefore sets the maximum amount of product. Find it by converting each reactant to moles of product and taking the smallest amount."},{"id":"chem-102-4","front":"Percent yield formula","back":"Percent yield = (actual yield / theoretical yield) x 100%."},{"id":"chem-102-5","front":"Molarity definition and formula","back":"Molarity M = moles of solute / liters of solution. Dilution: M1*V1 = M2*V2."},{"id":"chem-102-6","front":"Mini-problem: how many grams of NaOH (40.0 g/mol) are in 250 mL of 0.200 M NaOH?","back":"moles = 0.200 mol/L x 0.250 L = 0.0500 mol; mass = 0.0500 x 40.0 = 2.00 g."},{"id":"chem-102-7","front":"Empirical vs molecular formula","back":"The empirical formula is the simplest whole-number ratio of atoms (CH2O). The molecular formula is the actual number of atoms (C6H12O6 for glucose), a whole-number multiple of the empirical formula."},{"id":"chem-102-8","front":"Relationship between energy, frequency and wavelength of light","back":"E = h*nu and c = lambda*nu, so E = h*c / lambda. h = 6.626 x 10^-34 J*s, c = 3.00 x 10^8 m/s. Shorter wavelength means higher energy."},{"id":"chem-102-9","front":"What do the four quantum numbers n, l, ml and ms describe?","back":"n: energy level and size. l: subshell shape (0 = s, 1 = p, 2 = d, 3 = f), from 0 to n-1. ml: orbital orientation, from -l to +l. ms: electron spin, +1/2 or -1/2."},{"id":"chem-102-10","front":"Pauli exclusion principle vs Hund''s rule","back":"Pauli: no two electrons in an atom share all four quantum numbers, so an orbital holds at most two electrons of opposite spin. Hund: electrons fill degenerate orbitals singly with parallel spins before pairing."},{"id":"chem-102-11","front":"Ground-state electron configuration of Fe (Z = 26)","back":"1s2 2s2 2p6 3s2 3p6 4s2 3d6, or [Ar] 4s2 3d6."},{"id":"chem-102-12","front":"Periodic trend: atomic radius","back":"Radius decreases left to right across a period (greater effective nuclear charge) and increases down a group (more electron shells)."},{"id":"chem-102-13","front":"Periodic trend: first ionization energy","back":"Increases left to right across a period and decreases down a group. Small exceptions: B is lower than Be, and O is lower than N."},{"id":"chem-102-14","front":"Electronegativity and bond polarity","back":"Electronegativity is an atom''s pull on shared electrons; F is highest. A large electronegativity difference gives a polar covalent bond; a very large one gives ionic bonding."},{"id":"chem-102-15","front":"How do you calculate formal charge?","back":"Formal charge = valence electrons - nonbonding electrons - (bonding electrons / 2). The best Lewis structure keeps formal charges near zero, with negative charge on the more electronegative atom."},{"id":"chem-102-16","front":"What is resonance?","back":"When more than one valid Lewis structure can be drawn, the real molecule is an average (hybrid) of them. In ozone or nitrate, all equivalent bonds have the same length."},{"id":"chem-102-17","front":"VSEPR: geometry for 4 electron domains with 0, 1 and 2 lone pairs","back":"0 lone pairs: tetrahedral (109.5 deg, CH4). 1 lone pair: trigonal pyramidal (NH3). 2 lone pairs: bent (H2O)."},{"id":"chem-102-18","front":"Hybridization for 2, 3 and 4 electron domains","back":"2 domains: sp (linear). 3 domains: sp2 (trigonal planar). 4 domains: sp3 (tetrahedral)."},{"id":"chem-102-19","front":"Sigma vs pi bonds","back":"A single bond is one sigma bond. A double bond is one sigma plus one pi. A triple bond is one sigma plus two pi. Pi bonds come from side-by-side p orbital overlap."},{"id":"chem-102-20","front":"Rank the intermolecular forces from weakest to strongest","back":"London dispersion forces < dipole-dipole < hydrogen bonding (H bonded to N, O or F). Stronger forces mean higher boiling points."},{"id":"chem-102-21","front":"Ideal gas law and its units","back":"PV = nRT. R = 0.08206 L*atm/(mol*K) or 8.314 J/(mol*K). Temperature must be in kelvin."},{"id":"chem-102-22","front":"Dalton''s law of partial pressures","back":"Total pressure is the sum of partial pressures: P_total = P_A + P_B + ... Each partial pressure P_A = X_A * P_total, where X_A is the mole fraction."},{"id":"chem-102-23","front":"Kinetic molecular theory: what does temperature measure?","back":"Temperature is proportional to the average kinetic energy of gas particles. At the same temperature, lighter gases move faster (rms speed = sqrt(3RT/M))."},{"id":"chem-102-24","front":"Equilibrium constant expression for aA + bB <=> cC + dD","back":"K = [C]^c [D]^d / ([A]^a [B]^b). Pure solids and liquids are left out."},{"id":"chem-102-25","front":"Q vs K: which way does the reaction shift?","back":"If Q < K the reaction goes forward toward products. If Q > K it goes in reverse toward reactants. If Q = K the system is at equilibrium."},{"id":"chem-102-26","front":"Le Chatelier: effect of adding reactant or raising pressure","back":"Adding reactant shifts toward products. Raising pressure by shrinking volume shifts toward the side with fewer moles of gas."},{"id":"chem-102-27","front":"Does a catalyst change K?","back":"No. A catalyst speeds up the forward and reverse reactions equally, so equilibrium is reached faster but its position and K are unchanged. Only temperature changes K."},{"id":"chem-102-28","front":"How do you relate Kp and Kc?","back":"Kp = Kc*(RT)^(delta n), where delta n = moles of gaseous products - moles of gaseous reactants."}],"quizzes":[],"seed":1,"look":{"color":"#1E9E74","icon":"chem"}}'::jsonb);   -- https://catalog.illinois.edu/courses-of-instruction/chem/
select pg_temp.sb_seed('seed:uiuc-edu:econ-102', 'uiuc.edu', 'ECON 102', 'ECON 102 Exam Review: Supply and Demand, Elasticity, Costs and Market Structures', '{"v":1,"app":"studyboard","type":"deck","name":"ECON 102 Exam Review: Supply and Demand, Elasticity, Costs and Market Structures","course":{"code":"ECON 102","name":"Microeconomic Principles"},"cards":[{"id":"econ-102-1","front":"Opportunity cost","back":"The value of the next best alternative you give up when making a choice."},{"id":"econ-102-2","front":"Comparative vs absolute advantage","back":"Absolute advantage: producing more with the same resources. Comparative advantage: producing at a lower opportunity cost. Trade gains come from comparative advantage."},{"id":"econ-102-3","front":"What does a production possibilities frontier show?","back":"The maximum combinations of two goods an economy can produce with its resources. Points inside are inefficient, points outside are unattainable, and a bowed-out shape reflects increasing opportunity cost."},{"id":"econ-102-4","front":"Change in quantity demanded vs change in demand","back":"A change in the good''s own price moves along the demand curve (change in quantity demanded). A change in income, tastes, related prices, expectations or number of buyers shifts the whole curve (change in demand)."},{"id":"econ-102-5","front":"Normal vs inferior goods","back":"Demand for a normal good rises when income rises. Demand for an inferior good falls when income rises."},{"id":"econ-102-6","front":"Substitutes vs complements","back":"Substitutes: a price rise in one raises demand for the other (coffee and tea). Complements: a price rise in one lowers demand for the other (cars and gasoline)."},{"id":"econ-102-7","front":"If supply increases and demand stays the same, what happens to equilibrium?","back":"Equilibrium price falls and equilibrium quantity rises."},{"id":"econ-102-8","front":"Price elasticity of demand formula","back":"Ed = (% change in quantity demanded) / (% change in price), usually reported as an absolute value. Above 1 is elastic, below 1 is inelastic, exactly 1 is unit elastic."},{"id":"econ-102-9","front":"Elasticity and total revenue","back":"If demand is elastic, a price cut raises total revenue. If demand is inelastic, a price increase raises total revenue. At unit elasticity revenue is maximized."},{"id":"econ-102-10","front":"What makes demand more elastic?","back":"Many close substitutes, a large share of the budget, the good being a luxury, a narrowly defined market, and a longer time horizon."},{"id":"econ-102-11","front":"Consumer surplus vs producer surplus","back":"Consumer surplus is willingness to pay minus the price paid (area below demand, above price). Producer surplus is the price received minus the cost to sell (area above supply, below price)."},{"id":"econ-102-12","front":"Effect of a binding price ceiling","back":"Set below equilibrium, it causes a shortage (quantity demanded exceeds quantity supplied) and deadweight loss. Rent control is the classic example."},{"id":"econ-102-13","front":"Effect of a binding price floor","back":"Set above equilibrium, it causes a surplus (quantity supplied exceeds quantity demanded). A minimum wage above the market wage is the classic example."},{"id":"econ-102-14","front":"Who bears more of a tax burden?","back":"The side of the market that is less elastic bears more of the tax, no matter who legally pays it."},{"id":"econ-102-15","front":"What is deadweight loss?","back":"The loss of total surplus from trades that would have benefited buyers and sellers but no longer happen, e.g. because of a tax, price control or monopoly."},{"id":"econ-102-16","front":"Negative externality and its fix","back":"A cost imposed on third parties (pollution), causing overproduction compared with the social optimum. A Pigouvian tax equal to the external cost can correct it."},{"id":"econ-102-17","front":"Public good characteristics","back":"Nonrival (one person''s use does not reduce another''s) and nonexcludable (people cannot be kept from using it). Leads to the free-rider problem; example: national defense."},{"id":"econ-102-18","front":"Marginal utility and the utility-maximizing rule","back":"Marginal utility is the extra satisfaction from one more unit. Consumers maximize utility when MU_x/P_x = MU_y/P_y."},{"id":"econ-102-19","front":"Fixed vs variable costs","back":"Fixed costs do not change with output in the short run (rent). Variable costs rise with output (materials, hourly labor). TC = FC + VC."},{"id":"econ-102-20","front":"Formulas for ATC, AVC and MC","back":"ATC = TC/Q, AVC = VC/Q, MC = change in TC / change in Q. MC crosses ATC and AVC at their minimum points."},{"id":"econ-102-21","front":"Law of diminishing marginal returns","back":"In the short run, adding more of a variable input to a fixed input eventually makes each additional unit of input add less output."},{"id":"econ-102-22","front":"Profit-maximizing rule for any firm","back":"Produce the quantity where marginal revenue equals marginal cost (MR = MC)."},{"id":"econ-102-23","front":"Short-run shutdown rule for a competitive firm","back":"Shut down if price falls below minimum average variable cost (P < AVC). Between AVC and ATC the firm operates at a loss to cover part of fixed cost."},{"id":"econ-102-24","front":"Long-run equilibrium in perfect competition","back":"Free entry and exit drive economic profit to zero, so P = MC = minimum ATC."},{"id":"econ-102-25","front":"Accounting profit vs economic profit","back":"Accounting profit = revenue - explicit costs. Economic profit = revenue - explicit costs - implicit costs (opportunity costs)."},{"id":"econ-102-26","front":"How does a monopoly differ from perfect competition?","back":"A monopoly faces downward-sloping demand, so MR < P. It sets MR = MC, charges a price above MC, produces less and creates deadweight loss."},{"id":"econ-102-27","front":"Monopolistic competition in the long run","back":"Many firms sell differentiated products. Entry pushes economic profit to zero, but P > MC and firms produce with excess capacity (not at minimum ATC)."},{"id":"econ-102-28","front":"Oligopoly and the prisoner''s dilemma","back":"Few interdependent firms. Each firm''s dominant strategy may be to cheat on collusion, so they end up at a worse outcome for both than if they cooperated."},{"id":"econ-102-29","front":"Nash equilibrium","back":"A set of strategies where no player can do better by changing their own strategy, given what the others are doing."}],"quizzes":[],"seed":1,"look":{"color":"#C79A12","icon":"econ"}}'::jsonb);   -- https://catalog.illinois.edu/courses-of-instruction/econ/
select pg_temp.sb_seed('seed:wisc-edu:math-221', 'wisc.edu', 'MATH 221', 'MATH 221 Exam Review: Limits, Derivatives, Applications and Integrals', '{"v":1,"app":"studyboard","type":"deck","name":"MATH 221 Exam Review: Limits, Derivatives, Applications and Integrals","course":{"code":"MATH 221","name":"Calculus and Analytic Geometry 1"},"cards":[{"id":"math-221-1","front":"Formal idea of lim x->a f(x) = L","back":"f(x) can be made as close to L as we like by taking x close enough to a (but not equal to a). The value f(a) itself does not matter."},{"id":"math-221-2","front":"When does a limit fail to exist?","back":"When the left-hand and right-hand limits differ, when the function grows without bound, or when it oscillates without settling down."},{"id":"math-221-3","front":"lim x->0 of sin(x)/x","back":"1 (with x in radians)."},{"id":"math-221-4","front":"Evaluate lim x->2 of (x^2 - 4)/(x - 2)","back":"Factor: (x - 2)(x + 2)/(x - 2) = x + 2, so the limit is 4."},{"id":"math-221-5","front":"Three conditions for f to be continuous at x = a","back":"f(a) is defined, lim x->a f(x) exists, and the limit equals f(a)."},{"id":"math-221-6","front":"Intermediate Value Theorem","back":"If f is continuous on [a, b] and N is between f(a) and f(b), then there is a c in (a, b) with f(c) = N. Often used to show a root exists."},{"id":"math-221-7","front":"Limit definition of the derivative","back":"f''(x) = lim h->0 of [f(x + h) - f(x)] / h. It gives the slope of the tangent line and the instantaneous rate of change."},{"id":"math-221-8","front":"Does differentiable imply continuous? Does continuous imply differentiable?","back":"Differentiable implies continuous. Continuous does not imply differentiable; f(x) = |x| is continuous at 0 but has a corner there."},{"id":"math-221-9","front":"Power rule","back":"d/dx [x^n] = n*x^(n-1) for any real n."},{"id":"math-221-10","front":"Product rule and quotient rule","back":"(fg)'' = f''g + fg''. (f/g)'' = (f''g - fg'') / g^2."},{"id":"math-221-11","front":"Chain rule","back":"d/dx [f(g(x))] = f''(g(x)) * g''(x). Example: d/dx [sin(x^2)] = cos(x^2) * 2x."},{"id":"math-221-12","front":"Derivatives of sin x, cos x and tan x","back":"d/dx sin x = cos x, d/dx cos x = -sin x, d/dx tan x = sec^2 x."},{"id":"math-221-13","front":"Derivatives of e^x, a^x and ln x","back":"d/dx e^x = e^x, d/dx a^x = a^x * ln a, d/dx ln x = 1/x for x > 0."},{"id":"math-221-14","front":"Derivatives of arcsin x and arctan x","back":"d/dx arcsin x = 1/sqrt(1 - x^2). d/dx arctan x = 1/(1 + x^2)."},{"id":"math-221-15","front":"Implicit differentiation: find dy/dx for x^2 + y^2 = 25","back":"2x + 2y*(dy/dx) = 0, so dy/dx = -x/y."},{"id":"math-221-16","front":"Steps for a related rates problem","back":"Draw and label variables, write an equation relating them, differentiate both sides with respect to time t, then substitute the known values only after differentiating."},{"id":"math-221-17","front":"Linear approximation of f near x = a","back":"L(x) = f(a) + f''(a)(x - a). Example: sqrt(4.1) is about 2 + (1/4)(0.1) = 2.025."},{"id":"math-221-18","front":"Mean Value Theorem","back":"If f is continuous on [a, b] and differentiable on (a, b), some c in (a, b) has f''(c) = [f(b) - f(a)] / (b - a)."},{"id":"math-221-19","front":"First derivative test for local extrema","back":"At a critical point, if f'' changes from + to - there is a local max; from - to + a local min; no sign change means neither."},{"id":"math-221-20","front":"Second derivative: concavity and the second derivative test","back":"f'''' > 0 means concave up, f'''' < 0 means concave down. At a critical point c, f''''(c) > 0 gives a local min and f''''(c) < 0 gives a local max; f''''(c) = 0 is inconclusive."},{"id":"math-221-21","front":"How to find absolute extrema on a closed interval [a, b]","back":"Evaluate f at every critical point in (a, b) and at both endpoints. The largest value is the absolute max and the smallest is the absolute min."},{"id":"math-221-22","front":"L''Hopital''s rule","back":"If lim f/g gives 0/0 or infinity/infinity, then lim f/g = lim f''/g'' (if that limit exists). Differentiate top and bottom separately, not as a quotient."},{"id":"math-221-23","front":"Fundamental Theorem of Calculus, Part 1","back":"If F(x) = integral from a to x of f(t) dt and f is continuous, then F''(x) = f(x)."},{"id":"math-221-24","front":"Fundamental Theorem of Calculus, Part 2","back":"If F is any antiderivative of continuous f, then the integral from a to b of f(x) dx = F(b) - F(a)."},{"id":"math-221-25","front":"Antiderivative of x^n and of 1/x","back":"Integral of x^n dx = x^(n+1)/(n+1) + C for n not equal to -1. Integral of 1/x dx = ln|x| + C."},{"id":"math-221-26","front":"u-substitution: integrate 2x*cos(x^2) dx","back":"Let u = x^2, du = 2x dx. Integral of cos u du = sin u + C = sin(x^2) + C."},{"id":"math-221-27","front":"Riemann sum and the definite integral","back":"Sum of f(x_i)*delta x over n subintervals. As n goes to infinity the sum approaches the definite integral, the signed area under the curve."},{"id":"math-221-28","front":"Average value of f on [a, b]","back":"f_avg = [1/(b - a)] * integral from a to b of f(x) dx."},{"id":"math-221-29","front":"Area between curves y = f(x) and y = g(x) where f >= g on [a, b]","back":"Area = integral from a to b of [f(x) - g(x)] dx."},{"id":"math-221-30","front":"Solution of the differential equation dy/dt = k*y","back":"y(t) = y0 * e^(k*t). k > 0 gives exponential growth, k < 0 gives decay."}],"quizzes":[],"seed":1,"look":{"color":"#3B6FE0","icon":"calc"}}'::jsonb);   -- https://guide.wisc.edu/courses/math/
select pg_temp.sb_seed('seed:wisc-edu:econ-102', 'wisc.edu', 'ECON 102', 'ECON 102 Exam Review: GDP, Inflation, Unemployment, AD-AS and Fiscal and Monetary Policy', '{"v":1,"app":"studyboard","type":"deck","name":"ECON 102 Exam Review: GDP, Inflation, Unemployment, AD-AS and Fiscal and Monetary Policy","course":{"code":"ECON 102","name":"Principles of Macroeconomics"},"cards":[{"id":"econ-102-1","front":"GDP definition","back":"The market value of all final goods and services produced within a country in a given period. Intermediate goods and used goods are not counted."},{"id":"econ-102-2","front":"Expenditure approach to GDP","back":"GDP = C + I + G + NX: consumption, investment, government purchases, and net exports (exports - imports)."},{"id":"econ-102-3","front":"Do transfer payments count in G?","back":"No. Social Security and unemployment benefits are transfers, not purchases of goods or services, so they are excluded from G and GDP."},{"id":"econ-102-4","front":"Nominal vs real GDP","back":"Nominal GDP uses current prices. Real GDP uses base-year prices, so it changes only when output changes."},{"id":"econ-102-5","front":"GDP deflator formula","back":"GDP deflator = (nominal GDP / real GDP) x 100."},{"id":"econ-102-6","front":"How is the inflation rate computed from the CPI?","back":"Inflation = (CPI this year - CPI last year) / CPI last year x 100%."},{"id":"econ-102-7","front":"Three biases that make the CPI overstate inflation","back":"Substitution bias, introduction of new goods, and unmeasured quality change."},{"id":"econ-102-8","front":"Unemployment rate formula and who counts as unemployed","back":"Unemployment rate = unemployed / labor force x 100. Unemployed means without a job but actively looking in the past four weeks; labor force = employed + unemployed."},{"id":"econ-102-9","front":"Frictional, structural and cyclical unemployment","back":"Frictional: short spells while job searching. Structural: mismatch of skills or location with available jobs. Cyclical: caused by recessions. Natural rate = frictional + structural."},{"id":"econ-102-10","front":"Why does a discouraged worker lower the measured unemployment rate?","back":"They have stopped looking for work, so they leave the labor force and are no longer counted as unemployed."},{"id":"econ-102-11","front":"Fisher equation","back":"Real interest rate is approximately the nominal interest rate minus the inflation rate."},{"id":"econ-102-12","front":"Who is hurt by unexpected inflation?","back":"Lenders and savers with fixed nominal returns, and people on fixed incomes. Borrowers with fixed-rate loans benefit."},{"id":"econ-102-13","front":"Rule of 70","back":"The number of years for a variable to double is about 70 divided by its annual growth rate in percent. At 2% growth, output doubles in about 35 years."},{"id":"econ-102-14","front":"Sources of long-run economic growth","back":"Growth in physical capital, human capital, natural resources and especially technology (productivity)."},{"id":"econ-102-15","front":"Why does the aggregate demand curve slope downward?","back":"A lower price level raises real wealth (wealth effect), lowers interest rates (interest rate effect) and makes exports cheaper (exchange rate effect)."},{"id":"econ-102-16","front":"Short-run vs long-run aggregate supply","back":"SRAS slopes upward because some wages and prices are sticky. LRAS is vertical at potential output, determined by resources and technology, not the price level."},{"id":"econ-102-17","front":"Effect of a negative supply shock such as an oil price spike","back":"SRAS shifts left: output falls and the price level rises at the same time (stagflation)."},{"id":"econ-102-18","front":"Recessionary gap and how the economy self-corrects","back":"Output is below potential and unemployment is above natural. Over time wages and prices fall, shifting SRAS right and returning output to potential."},{"id":"econ-102-19","front":"Marginal propensity to consume and the spending multiplier","back":"MPC = change in consumption / change in disposable income. Spending multiplier = 1 / (1 - MPC). With MPC = 0.8, the multiplier is 5."},{"id":"econ-102-20","front":"Expansionary vs contractionary fiscal policy","back":"Expansionary: raise government purchases or cut taxes to shift AD right in a recession. Contractionary: cut spending or raise taxes to cool inflation."},{"id":"econ-102-21","front":"Crowding out","back":"Government borrowing to finance deficits can raise interest rates and reduce private investment, weakening the effect of expansionary fiscal policy."},{"id":"econ-102-22","front":"Budget deficit vs national debt","back":"The deficit is the one-year gap when spending exceeds tax revenue. The debt is the accumulated total of past deficits minus surpluses."},{"id":"econ-102-23","front":"Automatic stabilizers","back":"Policies that change fiscal stance without new legislation, like progressive income taxes and unemployment insurance, which soften booms and busts."},{"id":"econ-102-24","front":"Three functions of money","back":"Medium of exchange, unit of account and store of value."},{"id":"econ-102-25","front":"Simple money multiplier","back":"Money multiplier = 1 / reserve requirement ratio. With a 10% requirement, each new dollar of reserves can support up to $10 of deposits."},{"id":"econ-102-26","front":"Tools of the Federal Reserve","back":"Setting the federal funds rate target, mainly through interest on reserve balances, plus open market operations, the discount rate and, historically, reserve requirements."},{"id":"econ-102-27","front":"Effect of expansionary monetary policy","back":"The Fed lowers interest rates (for example by buying bonds), which raises investment and consumption, shifting AD right."},{"id":"econ-102-28","front":"Short-run Phillips curve","back":"A short-run tradeoff: lower unemployment comes with higher inflation. In the long run the Phillips curve is vertical at the natural rate of unemployment."},{"id":"econ-102-29","front":"Quantity theory of money","back":"M*V = P*Y. If velocity V and real output Y are stable, growth in the money supply M leads to proportional growth in the price level P."}],"quizzes":[],"seed":1,"look":{"color":"#EA580C","icon":"econ"}}'::jsonb);   -- https://guide.wisc.edu/courses/econ/
select pg_temp.sb_seed('seed:wisc-edu:stat-301', 'wisc.edu', 'STAT 301', 'STAT 301 Exam Review: Descriptive Stats, Normal Distribution, Inference and Regression', '{"v":1,"app":"studyboard","type":"deck","name":"STAT 301 Exam Review: Descriptive Stats, Normal Distribution, Inference and Regression","course":{"code":"STAT 301","name":"Introduction to Statistical Methods"},"cards":[{"id":"stat-301-1","front":"Mean vs median in a right-skewed distribution","back":"The mean is pulled toward the long right tail, so mean > median. The median is resistant to outliers."},{"id":"stat-301-2","front":"Sample standard deviation formula","back":"s = sqrt( sum of (x_i - xbar)^2 / (n - 1) ). It measures typical spread around the mean."},{"id":"stat-301-3","front":"Why divide by n - 1 in the sample variance?","back":"Using n - 1 (degrees of freedom) makes the sample variance an unbiased estimator of the population variance."},{"id":"stat-301-4","front":"Interquartile range and the 1.5 x IQR outlier rule","back":"IQR = Q3 - Q1. A value is a suspected outlier if it is below Q1 - 1.5*IQR or above Q3 + 1.5*IQR."},{"id":"stat-301-5","front":"Z-score formula and meaning","back":"z = (x - mu) / sigma. It tells how many standard deviations a value lies above or below the mean."},{"id":"stat-301-6","front":"The 68-95-99.7 rule","back":"For a normal distribution, about 68% of values fall within 1 SD of the mean, 95% within 2 SD, and 99.7% within 3 SD."},{"id":"stat-301-7","front":"Mini-problem: scores are normal with mean 70 and SD 10. About what percent score above 90?","back":"90 is z = 2. About 95% lie within 2 SD, so about 2.5% lie above 90."},{"id":"stat-301-8","front":"Standard error of the sample mean","back":"SE = sigma / sqrt(n), estimated by s / sqrt(n). Quadrupling n halves the standard error."},{"id":"stat-301-9","front":"Central Limit Theorem","back":"For a large enough sample size, the sampling distribution of the sample mean is approximately normal with mean mu and SD sigma/sqrt(n), whatever the population''s shape."},{"id":"stat-301-10","front":"Parameter vs statistic","back":"A parameter describes a population (mu, sigma, p) and is usually unknown. A statistic is computed from a sample (xbar, s, p-hat) and estimates the parameter."},{"id":"stat-301-11","front":"General form of a confidence interval","back":"Estimate plus or minus (critical value) x (standard error). For a mean: xbar plus or minus t* x s/sqrt(n)."},{"id":"stat-301-12","front":"Correct interpretation of a 95% confidence interval","back":"If we repeated the sampling many times, about 95% of the intervals built this way would contain the true parameter. It is not a 95% probability that this one interval contains it."},{"id":"stat-301-13","front":"What makes a confidence interval narrower?","back":"A larger sample size, a lower confidence level, or less variability in the data."},{"id":"stat-301-14","front":"When do you use t instead of z for a mean?","back":"When the population standard deviation is unknown and estimated by s. The t distribution has heavier tails and depends on degrees of freedom (n - 1 for one sample)."},{"id":"stat-301-15","front":"Null vs alternative hypothesis","back":"H0 is the no-effect or no-difference claim (e.g. mu = 50). Ha is what we seek evidence for (mu > 50, mu < 50 or mu not equal to 50)."},{"id":"stat-301-16","front":"Definition of a p-value","back":"The probability, assuming H0 is true, of getting a test statistic at least as extreme as the one observed. Small p-values are evidence against H0."},{"id":"stat-301-17","front":"Decision rule with significance level alpha","back":"Reject H0 if p-value <= alpha (often 0.05). Otherwise fail to reject H0; we never accept or prove H0."},{"id":"stat-301-18","front":"Type I vs Type II error","back":"Type I: rejecting a true H0 (probability alpha). Type II: failing to reject a false H0 (probability beta). Power = 1 - beta."},{"id":"stat-301-19","front":"One-sample t statistic","back":"t = (xbar - mu0) / (s / sqrt(n)), with n - 1 degrees of freedom."},{"id":"stat-301-20","front":"Paired t-test vs two-sample t-test","back":"Paired: two measurements on the same subjects (before and after); analyze the differences. Two-sample: two independent groups; compare the two means."},{"id":"stat-301-21","front":"Assumptions of t procedures","back":"Random sample or randomized experiment, independent observations, and a roughly normal population or a large enough sample. They are sensitive to strong skew and outliers in small samples."},{"id":"stat-301-22","front":"What does one-way ANOVA test?","back":"Whether three or more group means are all equal. F = (between-group variability) / (within-group variability); a large F suggests at least one mean differs."},{"id":"stat-301-23","front":"Least squares regression line","back":"y-hat = b0 + b1*x, chosen to minimize the sum of squared residuals. Slope b1 = r*(sy/sx), and the line passes through (xbar, ybar)."},{"id":"stat-301-24","front":"Interpreting a slope of b1 = 2.5 for y = exam score and x = hours studied","back":"Each additional hour of study is associated with a predicted increase of 2.5 points in exam score, on average."},{"id":"stat-301-25","front":"Residual","back":"Residual = observed y - predicted y-hat. A residual plot with no pattern supports a linear model."},{"id":"stat-301-26","front":"What does r^2 mean?","back":"The fraction of variation in y explained by the linear regression on x. r = 0.6 gives r^2 = 0.36, so 36% of variation is explained."},{"id":"stat-301-27","front":"Properties of the correlation r","back":"Between -1 and 1, unitless, measures only linear association, and is strongly affected by outliers."},{"id":"stat-301-28","front":"Extrapolation","back":"Using a regression line to predict far outside the range of observed x values. It is unreliable because the relationship may not continue."},{"id":"stat-301-29","front":"Observational study vs experiment","back":"An observational study measures without intervening and cannot prove causation. An experiment imposes treatments, ideally with random assignment and a control group, allowing causal conclusions."},{"id":"stat-301-30","front":"Blocking in experimental design","back":"Grouping similar experimental units (e.g. by age) and randomizing treatments within each block to reduce variability from that factor."}],"quizzes":[],"seed":1,"look":{"color":"#1D9BB8","icon":"stats"}}'::jsonb);   -- https://guide.wisc.edu/courses/stat/
